insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 8, '''ഓ നബിയേ, അല്ലാഹു അങ്ങേക്ക് അനുവദനീയമാക്കിയത് അവിടന്ന് എന്തിനാണ് നിഷിദ്ധമാക്കുന്നത്'' എന്ന സൂക്തം', 'بَابٌ: تَأْوِيلُ قَوْلِهِ عَزَّ وَ جَلَّ: {يَاأَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللهُ لَكَ}', 153 from books where volume_id=3 and book_no=3 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 9, 'വിവാഹമോചിത പുനർവിവാഹം ചെയ്യപ്പെട്ടാൽ ഭർത്താവുമായി ബന്ധപ്പെടാതെ ആദി ഭർത്താവിലേക്ക് മടങ്ങാനാവില്ല', 'بَابٌ: فِي الرَّجُلِ يُطَلِّقُ امْرَأَتَهُ فَتَزَوَّجَ غَيْرَهُ وَلَا يَدْخُلُ بِهَا فَلَيْسَ لَهَا أَنْ تَرْجِعَ الَى الْأَوَّلِ', 155 from books where volume_id=3 and book_no=3 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 10, 'ബന്ധപ്പെടുന്നതിന് മുമ്പ് മൊഴിചൊല്ലപ്പെട്ട സ്ത്രീയുടെ മകളെ വിവാഹം ചെയ്യാൻ പറ്റുമോ?', 'بَابٌ: مَاجَاءَ فِيمَنْ يَتَزَوَّجُ الْمَرْأَةَ ثُمَّ يُطَلِّقُهَا قَبْلَ أَنْ يَدْخُلَ بِهَا هَلْ يَتَزَوَّجُ ابْنَتَهَا أَوْ لَا', 156 from books where volume_id=3 and book_no=3 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
