insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 24, 'യഥാർത്ഥമല്ലാത്ത അർത്ഥം ഉദ്ദേശിക്കപ്പെടുന്ന വ്യക്തമായ വാക്കുകൾ ഒന്നും നിർബന്ധമാക്കുന്നില്ല', 'بَابٌ: الْإِبَانَةُ وَالْإِفْصَاحُ بِالْكَلِمَةِ الْمَلْفُوظِ بِهَا إِذَا قُصِدَ بِهَا لِمَا لَا يَحْتَمِلُ مَعْنَاهَا لَمْ تُوجِبْ شَيْئًا', 166 from books where volume_id=3 and book_no=3 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
