insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ مِنَّا مَنْ خَبَّبَ امْرَأَةً عَلَى زَوْجِهَا، أَوْ عَبْدًا عَلَى سَيِّدِهِ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഭാര്യയെ ഭർത്താവിനെതിരെയും, അടിമയെ യജമാനനെതിരിരെയും രോഷാകുലനാക്കി വിടുന്നവൻ നമ്മിൽ പെട്ടവനല്ല." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 147, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي هُرَيْرَةَ بْنِ دِثَارٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَسْأَلِ الْمَرْأَةُ طَلَاقَ أُخْتِهَا لِتَسْتَفْرِغَ صَحْفَتَهَا، فَإِنَّمَا لَهَا مَا قُدِّرَ لَهَا". (ق,د,ت,ن)', 'അബൂഹുറൈറതുബ്നു ദിസാർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു സ്ത്രീ തന്റെ തളിക വിശാലമാകാൻ വേണ്ടി തന്റെ സഹോദരിയുടെ വിവാഹമോചനം ആവശ്യപ്പെടരുത്. അവൾക്ക് വിധിക്കപ്പെട്ടതേ അവൾക്കുള്ളൂ." (ബു,മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ بْنِ دِثَارٍ', 'അബൂഹുറൈറതുബ്നു ദിസാർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 147, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ مُحَارِبِ بْنِ دِثَارٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا أَحَلَّ اللهُ شَيْئًا أَبْغَضَ إِلَيْهِ مِنَ الطَّلَاقِ". [مرسل] (د)', 'മുഹാരിബുബ്നു ദിസാർ(റ): റസൂൽ(സ) പറഞ്ഞു: "വിവാഹമോചനത്തേക്കാൾ ദേഷ്യമുള്ള ഒന്നും അല്ലാഹു അനുവദനീയമാക്കിയിട്ടില്ല." (ഹദീസ് മുർസലാണ്) (ദ)', 'مُحَارِبِ بْنِ دِثَارٍ', 'മുഹാരിബുബ്നു ദിസാർ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'مرسل', null, 147, 147, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: طَلَّقْتُ امْرَأَتِي فِي حَيَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهِيَ حَائِضٌ، فَذَكَرَ ذَلِكَ عُمَرُ رَضِيَ اللهُ عَنْهُ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَتَغَيَّظَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي ذَلِكَ، فَقَالَ: "لِيُرَاجِعْهَا، ثُمَّ يُمْسِكْهَا حَتَّى تَحِيضَ حَيْضَةً وَتَطْهُرَ، فَإِنْ بَدَا لَهُ أَنْ يُطَلِّقَهَا طَاهِرًا قَبْلَ أَنْ يَمَسَّهَا، فَذَاكَ الطَّلَاقُ لِلْعِدَّةِ كَمَا أَنْزَلَ اللهُ عَزَّ وَجَلَّ". قَالَ عَبْدُ اللهِ بْنُ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: فَرَاجَعْتُهَا، وَحَسَبْتُ لَهَا التَّطْلِيقَةَ الَّتِي طَلَّقْتُهَا. (ق,ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ)യുടെ കാലത്ത്, എന്റെ ഭാര്യ ആർത്തവകാരിയായിരിക്കെ ഞാനവളെ മൊഴിചൊല്ലി. ഉമർ(റ) ഇക്കാര്യം റസൂൽ(സ)യോട് പറഞ്ഞു. ഇത് കാരണം റസൂൽ(സ) കോപിഷ്ഠനായി. അവിടന്ന് പറഞ്ഞു: അവൻ അവളെ തിരിച്ചെടുക്കുക. ഒരാർത്തവം കഴിഞ്ഞ് ശുദ്ധിയാകുന്നത് വരെ, അവൻ അവളെ നിലനിർത്തട്ടെ. അവളെ ബന്ധപ്പെടുന്നതിന് മുമ്പ് ശുദ്ധിയുള്ളവളായിരിക്കുമ്പോൾ അവളെ മൊഴിചൊല്ലാൻ അവന് തോന്നിയാൽ ഈ സമയത്തുള്ള ത്വലാഖ് അല്ലാഹു അവതരിപ്പിച്ചത് പോലെയാണ്." അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) പറയുന്നു: അങ്ങനെ ഞാനവളെ തിരിച്ചെടുത്തു. ഞാൻ ചൊല്ലിയ ഒരു ത്വലാഖ് പരിഗണിക്കപ്പെട്ടു. (ബു,മു,തു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 147, 148, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فِي قَوْلِهِ عَزَّ وَجَلَّ {يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ} [الطلاق : ١] قَالَ ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: قُبُلِ عِدَّتِهِنَّ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ''നിങ്ങൾ ഭാര്യമാരെ വിവാഹമോചനം നടത്തുമ്പോൾ അവരുടെ സമയങ്ങളിൽ വിവാഹമോചനം നടത്തുക'' (ത്വലാഖ്:1) എന്ന സൂക്തത്തെക്കുറിച്ച് ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: അവരുടെ ഇദ്ദയുടെ ആദ്യ സമയത്ത് എന്നാണതിനർത്ഥം. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الطلاق : ١', null, 148, 148, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ نَافِعٍ رَضِيَ اللهُ عَنْهُ: أَنَّ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ، فَسَأَلَ عُمَرُ رَضِيَ اللهُ عَنْهُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَهُ أَنْ يُرَاجِعَهَا ثُمَّ يُمْهِلَهَا حَتَّى تَحِيضَ حَيْضَةً أُخْرَى، ثُمَّ يُمْهِلَهَا حَتَّى تَطْهُرَ، ثُمَّ يُطَلِّقَهَا قَبْلَ أَنْ يَمَسَّهَا، فَتِلْكَ الْعِدَّةُ الَّتِي أَمَرَ اللهُ أَنْ يُطَلَّقَ لَهَا النِّسَاءُ. قَالَ: فَكَانَ ابْنُ عُمَرَ رَضِيَ اللهُ عَنْهُمَا إِذَا سُئِلَ عَنِ الرَّجُلِ يُطَلِّقُ امْرَأَتَهُ وَهِيَ حَائِضٌ يَقُولُ: أَمَّا أَنْتَ طَلَّقْتَهَا وَاحِدَةً أَوِ اثْنَتَيْنِ، إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَهُ أَنْ يَرْجِعَهَا ثُمَّ يُمْهِلَهَا حَتَّى تَحِيضَ حَيْضَةً أُخْرَى، ثُمَّ يُمْهِلَهَا حَتَّى تَطْهُرَ، ثُمَّ يُطَلِّقَهَا قَبْلَ أَنْ يَمَسَّهَا. وَأَمَّا أَنْتَ طَلَّقْتَهَا ثَلَاثًا، فَقَدْ عَصَيْتَ رَبَّكَ فِيمَا أَمَرَكَ بِهِ مِنْ طَلَاقِ امْرَأَتِكَ، وَبَانَتْ مِنْكَ. (م)', 'നാഫിഅ്(റ): തന്റെ ഭാര്യ ആർത്തവകാരിയായിരിക്കെ ഇബ്നുഉമർ(റ) അവരെ ത്വലാഖ് ചൊല്ലി. അപ്പോൾ ഉമർ(റ) ഇക്കാര്യം നബി(സ)യോട് ചോദിച്ചു. അവിടന്ന് ഇബ്നുഉമർ(റ)വിനോട് തന്റെ ഭാര്യയെ തിരിച്ചെടുക്കാനും ഒരാർത്തവം ഉണ്ടാകുന്നത് വരെ കാത്തിരിക്കാനും ശുദ്ധിയാകുന്നത് വരെ ത്വലാഖ് പിന്തിപ്പിക്കാനും ശേഷം അവളുമായി ബന്ധപ്പെടുന്നതിന് മുമ്പ് മൊഴിചൊല്ലാനും കൽപിച്ചു. ഇതാണ് ഭാര്യമാരെ ത്വലാഖ് ചൊല്ലാൻ അല്ലാഹു പറഞ്ഞ സമയം. നിവേദകൻ പറയുന്നു: തന്റെ ഭാര്യയെ ആർത്തവകാരിയായിരിക്കെ ത്വലാഖ് ചൊല്ലിയവനെ സംബന്ധിച്ച് ഇബ്നുഉമർ(റ)വിനോട് ചോദിച്ചാൽ അദ്ദേഹം പറയും: നീ അവളെ ഒന്നോ രണ്ടോ ത്വലാഖാണോ ചൊല്ലിയത്, (എങ്കിൽ) റസൂൽ(സ) അദ്ദേഹത്തോട് ഭാര്യയെ തിരിച്ചെടുക്കാനും പിന്നെ ഒരാർത്തവം ഉണ്ടാകുന്നത് വരെ കാത്തിരിക്കുവാനും ശുദ്ധിയാകുന്നത് വരെ വീണ്ടും കാത്തിരിക്കാനും ബന്ധപ്പെടുന്നതിന് മുമ്പ് അവരെ മൊഴിചൊല്ലാനും കൽപിച്ചു. നിങ്ങളവളെ മൂന്ന് ത്വലാഖ് ചൊല്ലിയിരിക്കുന്നുവെങ്കിൽ നിന്റെ ഭാര്യയെ വിവാഹമോചനം നടത്തുന്നതിൽ നിന്റെ രക്ഷിതാവ് നിന്നോട് കൽപിച്ച വിഷയത്തിൽ നീ അവനെ ധിക്കരിച്ചിരിക്കുന്നു. നിന്റെ ഭാര്യയെ വേർപ്പിരിയുകയും ചെയ്തിരിക്കുന്നു. (മു)', 'نَافِعٍ', 'നാഫിഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 148, 148, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنِ ابْنِ سِيرِينَ رَضِيَ اللهُ عَنْهُ قَالَ: مَكَثْتُ عِشْرِينَ سَنَةً يُحَدِّثُنِي مَنْ لَا أَتَّهِمُ: أَنَّ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا طَلَّقَ امْرَأَتَهُ ثَلَاثًا وَهِيَ حَائِضٌ، فَأُمِرَ أَنْ يُرَاجِعَهَا، فَجَعَلْتُ لَا أَتَّهِمُهُمْ وَلَا أَعْرِفُ الْحَدِيثَ، حَتَّى لَقِيتُ أَبَا غَلَّابٍ يُونُسُ بْنُ جُبَيْرٍ الْبَاهِلِيَّ، وَكَانَ ذَا ثَبَتٍ، فَحَدَّثَنِي أَنَّهُ سَأَلَ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا فَحَدَّثَهُ: أَنَّهُ طَلَّقَ امْرَأَتَهُ تَطْلِيقَةً وَهِيَ حَائِضٌ فَأُمِرَ أَنْ يَرْجِعَهَا، قَالَ: قُلْتُ: أَفَحُسِبَتْ عَلَيْهِ؟ قَالَ: فَمَهْ، أَوْ إِنْ عَجَزَ وَاسْتَحْمَقَ؟ (ق,ت)', 'ഇബ്നുസീരീൻ(റ): ഇബ്നുഉമർ(റ) തന്റെ ഭാര്യ ആർത്തവകാരിയായിരിക്കെ അവളെ മൂന്ന്മൊഴിയും ചൊല്ലിയെന്നും അപ്പോഴവളെ മടക്കിയെടുക്കാൻ അദ്ദേഹം കൽപിക്കപ്പെട്ടുവെന്നും വിശ്വസ്തരായ ആളുകൾ പറയുന്നത് ഇരുപത് വർഷത്തോളം ഞാൻ കേട്ടു. അന്നേരം ഞാൻ അവരെ തെറ്റിദ്ധരിച്ചില്ല. അപ്പറഞ്ഞ കാര്യം എനിക്ക് ബോധ്യമായിരുന്നുമില്ല. അങ്ങനെയിരിക്കെ ഞാനൊരിക്കൽ അബൂഗല്ലാബ് യൂനുസ് ബിൻ ജുബൈറിനിൽ ബാഹിലി(റ)വിനെ കണ്ടു. അദ്ദേഹം വിശ്വസ്തനായിരുന്നു. അദ്ദേഹം എന്നോട് പറഞ്ഞു: അദ്ദേഹം ഈ കാര്യം ഇബ്നുഉമർ(റ)വിനോട് ചോദിച്ചു. അപ്പോൾ ഇബ്നുഉമർ(റ) പറഞ്ഞു: അദ്ദേഹം തന്റെ ഭാര്യയെ ആർത്തവമുള്ള അവസരത്തിൽ ഒരു പ്രാവശ്യം വിവാഹമോചനം ചെയ്യുകയും അപ്പോഴവളെ മടക്കിയെടുക്കാൻ അദ്ദേഹം കൽപിക്കപ്പെടുകയും ചെയ്തു. അതൊരു വിവാഹമോചനമായി കണക്കാക്കുന്നുണ്ടോയെന്ന് ഞാൻ ചോദിച്ചപ്പോൾ ശരിക്ക് വിവാഹമോചനം ചെയ്യാൻ പഠിക്കാതെ വിഡ്ഢിത്തം ചെയ്തതാണെങ്കിലും അത് വിവാഹമോചനമായി കണക്കാക്കാതിരിക്കുകയില്ല എന്നാണ് അദ്ദേഹം പറഞ്ഞത്. (ബു,മു,തു)', 'ابْنِ سِيرِينَ', 'ഇബ്നുസീരീൻ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 148, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ طَلَّقَ امْرَأَتَهُ فِي الْحَيْضِ، فَسَأَلَ عُمَرُ رَضِيَ اللهُ عَنْهُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مُرْهُ فَلْيُرَاجِعْهَا، ثُمَّ لِيُطَلِّقْهَا طَاهِرًا أَوْ حَامِلًا". حسن صحيح. (ق,ت)', 'ഇബ്നുഉമർ(റ): തന്റെ ഭാര്യ ആർത്തവകാരിയായിരിക്കെ ഇബ്നുഉമർ(റ) അവളെ വിവാഹമോചനം ചെയ്തു. അപ്പോൾ ഉമർ(റ) ആ കാര്യം നബി(സ)യോട് പറഞ്ഞു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അവളെ മടക്കിയെടുക്കുവാൻ അവനോട് കൽപ്പിക്കുക. പിന്നീട് ശുദ്ധിയായ നിലയിൽ അല്ലെങ്കിൽ ഗർഭിണിയായ നിലയിൽ അവനവളെ വിവാഹമോചനം ചെയ്തു കൊള്ളട്ടെ." (ബു,മു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 149, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، أَنَّهُ قَالَ طَلَاقُ السُّنَّةِ تَطْلِيقَةً وَهِيَ طَاهِرٌ – وَفِي رِوَايَةٍ:أَنْ يُطَلِّقَهَاطَاهِرًا – فِي غَيْرِ جِمَاعٍ، فَإِذَا حَاضَتْ وَطَهُرَتْ طَلَّقَهَا أُخْرَى، فَإِذَا حَاضَتْ وَطَهُرَتْ طَلَّقَهَا أُخْرَى. ثُمَّ تَعْتَدُّ بَعْدَ ذَلِكَ بِحَيْضَةٍ. (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ശുദ്ധിയുള്ളപ്പോൾ ഭാര്യയുമായി ബന്ധപ്പെടാതെ ഒരു ത്വലാഖ് ചൊല്ലലാണ് - ഒരു നിവേദന പ്രകാരം: ശുദ്ധിയുള്ളപ്പോൾ അവളെ ത്വലാഖ് ചൊല്ലലാണ്. - സുന്നത്തിലെ (നബിചര്യ) ത്വലാഖ്. അവൾക്ക് അശുദ്ധിയുണ്ടാവുകയും പിന്നെ ശുദ്ധിയുണ്ടാവുകയും ചെയ്താൽ അവളെ രണ്ടാം ത്വലാഖ് ചൊല്ലണം. അവൾക്ക് അശുദ്ധിയുണ്ടാവുകയും പിന്നെ ശുദ്ധിയുണ്ടാവുകയും ചെയ്താൽ അവളെ മൂന്നാം ത്വലാഖ് ചൊല്ലണം. അതിന് ശേഷം ഒരു അശുദ്ധിയുടെ സമയം അവൾ ഇദ്ദ ഇരിക്കണം. (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 149, 149, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=9), 1, 'وَفِي رِوَايَةٍ:أَنْ يُطَلِّقَهَاطَاهِرًا – فِي غَيْرِ جِمَاعٍ، فَإِذَا حَاضَتْ وَطَهُرَتْ طَلَّقَهَا أُخْرَى، فَإِذَا حَاضَتْ وَطَهُرَتْ طَلَّقَهَا أُخْرَى. ثُمَّ تَعْتَدُّ بَعْدَ ذَلِكَ بِحَيْضَةٍ. (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَبِي حَسَنٍ مَوْلَى بَنِي نَوْفَلٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ اسْتَفْتَى ابْنَ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فِي مَمْلُوكٍ كَانَتْ تَحْتَهُ مَمْلُوكَةٌ، فَطَلَّقَهَا تَطْلِيقَتَيْنِ، ثُمَّ عُتِقَا بَعْدَ ذَلِكَ: هَلْ يَصْلُحُ لَهُ أَنْ يَخْطُبَهَا؟ قَالَ: نَعَمْ، قَضَى بِذَلِكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ .وفي رواية: بَقِيَتْ لَكَ وَاحِدَةٌ، قَضَى بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ . (د,ن,جه)', 'ബനൂനൗഫലിന്റെ അടിമയായ അബൂഹസൻ(റ): ഒരടിമ അടിമസ്ത്രീയായ തന്റെ ഭാര്യയെ രണ്ട് ത്വലാഖ് ചൊല്ലുകയും പിന്നീട് അവർ രണ്ടുപേരും മോചിപ്പിക്കപ്പെടുകയും ചെയ്താൽ അടിമക്ക് വീണ്ടുമവളെ വിവാഹം നടത്താൻ പറ്റുമോയെന്ന് അദ്ദേഹം ഇബ്നുഅബ്ബാസ്(റ)വിനോട് നിയമോപദേശം തേടി. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അതെ. ഇതാണ് റസൂൽ(സ) വിധിച്ചതും. മറ്റൊരു നിവേദനം: ഒരു ത്വലാഖ് നിനക്ക് ബാക്കിയുണ്ട്. അതാണ് റസൂൽ(സ) വിധിച്ചത്. (ദ,ന,ജ)', 'أَبِي حَسَنٍ مَوْلَى بَنِي نَوْفَلٍ', 'ബനൂനൗഫലിന്റെ അടിമയായ അബൂഹസൻ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 149, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=10), 1, 'وَفِي رِوَايَةٍ: بَقِيَتْ لَكَ وَاحِدَةٌ، قَضَى بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ . (د,ن,جه)', 'മറ്റൊരു നിവേദനം: ഒരു ത്വലാഖ് നിനക്ക് ബാക്കിയുണ്ട്. അതാണ് റസൂൽ(സ) വിധിച്ചത്. (ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "طَلَاقُ الْأَمَةِ تَطْلِيقَتَانِ، وَقُرْؤُهَا – وفي رِوَايَةٍ: عِدَّتُهَا – حَيْضَتَانِ". (د,ت,جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "അടിമസ്ത്രീയുടെ ത്വലാഖ് രണ്ട് ത്വലാഖാണ്. അവളുടെ ഇദ്ദയുടെ സമയം രണ്ട് ആർത്തവത്തിന്റെ സമയമാണ്." (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 150, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=11), 1, 'وَفِي رِوَايَةٍ: عِدَّتُهَا – حَيْضَتَانِ". (د,ت,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ الطَّلَاقُ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ وَسَنَتَيْنِ مِنْ خِلَافَةِ عُمَرَ رَضِيَ اللهُ عَنْهُ طَلَاقُ الثَّلَاثِ وَاحِدَةً، فَقَالَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ: إِنَّ النَّاسَ قَدِ اسْتَعْجَلُوا فِي أَمْرٍ قَدْ كَانَتْ لَهُمْ فِيهِ أَنَاةٌ، فَلَوْ أَمْضَيْنَاهُ عَلَيْهِمْ؟ فَأَمْضَاهُ عَلَيْهِمْ. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)യുടെയും അബൂബക്കർ(റ)വിന്റെയും ഉമർ(റ)വിന്റെ ഭരണകാലത്തെ രണ്ട് വർഷവും മൂന്ന് പ്രാവശ്യം ഒന്നിച്ച് ചെയ്യുന്ന വിവാഹമോചനം ഒന്നായിട്ടാണ് കണക്കാക്കപ്പെട്ടിരുന്നത്. ശേഷം ഉമറുബ്നുൽ ഖത്താബ്(റ) പറഞ്ഞു: സാവധാനത്തിൽ ചെയ്യേണ്ട ഒരു കാര്യം ജനങ്ങൾ ധൃതിയിൽ ചെയ്യുന്നു. അതുകൊണ്ട് അതൊരു നിയമമാക്കി നടപ്പിൽ വരുത്തുകയാണെങ്കിൽ നന്നായിരിക്കും എന്നെനിക്ക് തോന്നുകയാണ്. ശേഷം ഉമർ(റ) അത് നിയമമാക്കി നടപ്പിൽ വരുത്തുകയും ചെയ്തു. (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 150, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ امْرَأَةَ رِفَاعَةَ الْقُرَظِيِّ، جَاءَتْ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللهِ إِنَّ رِفَاعَةَ طَلَّقَنِي، فَبَتَّ طَلَاقِي وَإِنِّي نَكَحْتُ بَعْدَهُ عَبْدَالرَّحْمَنِ بْنَ الزَّبِيرِ الْقُرَظِيَّ وَإِنَّمَا مَعَهُ مِثْلُ الْهُدْبَةِ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَعَلَّكِ تُرِيدِينَ أَنْ تَرْجِعِي إِلَى رِفَاعَةَ؟ لَا، حَتَّى يَذُوقَ عُسَيْلَتَكِ وَتَذُوقِي عُسَيْلَتَهُ". (ق,ن)', 'ആഇശ(റ): രിഫാഅതുൽ ഖുറളി(റ)വിന്റെ ഭാര്യ നബി(സ)യുടെ അടുക്കൽ വന്നുകൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, രിഫാഅത്ത് ഞാനുമായുള്ള വിവാഹബന്ധം വേർപ്പെടുത്തി. അദ്ദേഹം എന്റെ ത്വലാഖ് പൂർണ്ണമായും ചൊല്ലി. പിന്നീട് ഞാൻ അബ്ദുറഹ്മാനുബ്നു സുബൈർ(റ)വിനെയാണ് വിവാഹം കഴിച്ചത്. വസ്ത്രത്തിന്റെ അറ്റത്തെ പൊടിപ്പു പോലെയൊന്നേ അദ്ദേഹത്തിനുള്ളു. റസൂൽ(സ) ചോദിച്ചു: "നീ രിഫാഅയുടെ അടുത്തേക്ക് തിരിച്ചു പോകാൻ ആഗ്രഹിക്കുന്നുണ്ടാകുമല്ലേ? പക്ഷേ, നിന്റെ ചെറുതേൻ ഇബ്നുസുബൈറും അദ്ദേഹത്തിന്റെ ചെറുതേൻ നീയും രുചിനോക്കുംവരെ അത് പാടില്ല." (ബു,മു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 150, 150, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: طَلَّقَ عَبْدُ يَزِيدَ – أَبُو رُكَانَةَ – أُمَّ رُكَانَةَ، وَنَكَحَ امْرَأَةً مِنْ مُزَيْنَةَ، فَجَاءَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: مَا يُغْنِي عَنِّي إِلَّا كَمَا تُغْنِي هَذِهِ الشَّعْرَةُ – لِشَعْرَةٍ أَخَذَتْهَا مِنْ رَأْسِهَا – فَفَرِّقْ بَيْنِي وَبَيْنَهُ. فَأَخَذَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَمِيَّةٌ، فَدَعَا بِرُكَانَةَ وَإِخْوَتِهِ، ثُمَّ قَالَ لِجُلَسَائِهِ: "أَتَرَوْنَ فُلَانًا يُشْبِهُ مِنْهُ كَذَا وَكَذَا – مِنْ عَبْدِ يَزِيدَ – وَفُلَانًا يُشْبِهُ مِنْهُ كَذَا وَكَذَا". قَالُوا: نَعَمْ، قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِعَبْدِ يَزِيدَ: "طَلِّقْهَا". فَفَعَلَ، ثُمَّ قَالَ: "رَاجِعِ امْرَأَتَكَ أُمَّ رُكَانَةَ". قَالَ: إِنِّي طَلَّقْتُهَا ثَلَاثًا يَا رَسُولَ اللهِ، قَالَ: "قَدْ عَلِمْتُ، رَاجِعْهَا". وَتَلَا: {يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ} [الطلاق: ١]. قَالَ أَبُودَاوُدَ: وَحَدِيثُ أَنَّ رُكَانَةَ طَلَّقَ امْرَأَتَهُ الْبَتَّةَ فَرَدَّهَا إِلَيْهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَصَحُّ، إِنَّ رُكَانَةَ إِنَّمَا طَلَّقَ امْرَأَتَهُ الْبَتَّةَ، فَجَعَلَهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَاحِدَةً. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): റുകാനയുടെ പിതാവായ അബ്ദുയസീദ്(റ) ഉമ്മുറുകാനയെ വിവാഹമോചനം ചെയ്തു. അദ്ദേഹം മുസൈനയിലെ ഒരു സ്ത്രീയെ വിവാഹംകഴിച്ചു . അവർ നബി(സ)യുടെ അടുത്ത് വന്ന് തന്റെ തലയിൽ നിന്ന് ഒരു മുടിയെടുത്ത് പറഞ്ഞു: ഈ മുടിയുടെ ഉപയോഗമല്ലാതെ അദ്ദേഹത്തെ കൊണ്ടൊരുപയോഗവുമില്ല. അതിനാൽ അവിടന്ന് എന്നെ അദ്ദേഹത്തിന്റെയടുത്ത് നിന്ന് വേർപ്പെടുത്തിയാലും. അപ്പോൾ നബി(സ)ക്ക് ദേഷ്യം പിടിച്ചു. അവിടന്ന് റുകാനയെയും അവന്റെ സഹോദരന്മാരെയും വിളിച്ചുവരുത്തി. പിന്നെ റസൂൽ(സ) ചുറ്റും ഇരിക്കുന്നവരോടായി പറഞ്ഞു: "ഇന്നാലിന്നവനോട് - അബ്ദുയസീദിനോട് - ഇന്നാലിന്നവന് സാദൃശ്യമുള്ളത് നിങ്ങൾ കാണുന്നില്ലേ?" അപ്പോൾ അവർ പറഞ്ഞു: അതെ. നബി(സ) അബ്ദുയസീദ്(റ) വിനോട് പറഞ്ഞു: "നീ അവളെ വിവാഹമോചനം ചെയ്യുക." അപ്പോൾ അദ്ദേഹം അപ്രകാരം ചെയ്തു. പിന്നെ നബി(സ) പറഞ്ഞു: "നിന്റെ ഭാര്യ ഉമ്മുറുകാനയെ നീ തിരിച്ചെടുക്കുക." അബ്ദുയസീദ്(റ) പറഞ്ഞു: അള്ളാഹുവിന്റെ റസൂലേ, ഞാനവളെ മൂന്ന് ത്വലാഖും ചൊല്ലിയിട്ടുണ്ട്. നബി(സ) പറഞ്ഞു: "ഞാൻ അറിഞ്ഞിട്ടുണ്ട്, നിങ്ങൾ അവളെ തിരിച്ചെടുക്കുക." പിന്നെ അവിടന്ന് ഓതിക്കേൾപ്പിച്ചു: ''ഓ നബിയേ, അങ്ങ് ഭാര്യമാരെ ത്വലാഖ് ചെല്ലുകയാണെങ്കിൽ അവരുടെ ഇദ്ദകാലത്ത് നിങ്ങൾ ത്വലാഖ് ചൊല്ലുക'' (ത്വലാഖ്:1).
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَمَا قَالَتْ: طَلَّقَنِي زَوْجِي ثَلَاثًا، وَهُوَ خَارِجٌ إِلَى الْيَمَنِ، فَأَجَازَ ذَلِكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,د,ت,ن,جه)', 'ഫാത്വിമതു ബിൻതുഖൈസ്(റ): എന്റെ ഭർത്താവ് യമനിലേക്ക് പുറപ്പെടുമ്പോൾ എന്നെ മൂന്ന് ത്വലാഖും ചൊല്ലി. അങ്ങനെ റസൂൽ(സ) അത് നടപ്പിലാക്കി. (മു,ദ,തു,ന,ജ)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമതു ബിൻതുഖൈസ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 151, 151, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ مَحْمُودِ بْنِ لَبِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُخْبِرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ رَجُلٍ طَلَّقَ امْرَأَتَهُ ثَلَاثَ تَطْلِيقَاتٍ جَمِيعًا، فَقَامَ غَضْبَانًا، ثُمَّ قَالَ: "أَيُلْعَبُ بِكِتَابِ اللهِ وَأَنَا بَيْنَ أَظْهُرِكُمْ". حَتَّى قَامَ رَجُلٌ وَقَالَ: يَا رَسُولَ اللهِ، أَلَا أَقْتُلُهُ. (ن)', 'മുഹമ്മദുബ്നു ലബീദ്(റ): തന്റെ ഭാര്യയെ മൂന്ന് ത്വലാഖും ചൊല്ലിയ ഒരാളെക്കുറിച്ച് റസൂൽ(സ)യോട് പറയപ്പെട്ടു. അപ്പോൾ അവിടന്ന് ദേഷ്യപ്പെട്ടുകൊണ്ട് എണീറ്റു, എന്നിട്ട് പറഞ്ഞു: "ഞാൻ നിങ്ങൾക്കിടയിലുണ്ടായിരിക്കെ അല്ലാഹുവിന്റെ കിതാബ് കൊണ്ട് കളിക്കുകയോ?" അപ്പോൾ ഒരാൾ എണീറ്റ്കൊണ്ട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ അവനെ കൊല്ലട്ടെയോ? (ന)', 'مَحْمُودِ بْنِ لَبِيدٍ', 'മുഹമ്മദുബ്നു ലബീദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 151, 151, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ عُوَيْمِرًا الْعَجْلَانِيَّ جَاءَ إِلَى عَاصِمِ بْنِ عَدِيٍّ فَقَالَ: أَرَأَيْتَ يَا عَاصِمُ، لَوْ أَنَّ رَجُلًا وَجَدَ مَعَ امْرَأَتِهِ رَجُلًا، أَيَقْتُلُهُ فَيَقْتُلُونَهُ، أَمْ كَيْفَ يَفْعَلُ؟ سَلْ لِي يَا عَاصِمُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ. فَسَأَلَ عَاصِمٌ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَكَرِهَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَسَائِلَ وَعَابَهَا، حَتَّى كَبُرَ عَلَى عَاصِمٍ مَا سَمِعَ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا رَجَعَ عَاصِمٌ إِلَى أَهْلِهِ جَاءَهُ عُوَيْمِرٌ فَقَالَ: يَا عَاصِمُ، مَاذَا قَالَ لَكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ عَاصِمٌ لِعُوَيْمِرٍ: لَمْ تَأْتِنِي بِخَيْرٍ، قَدْ كَرِهَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَسْأَلَةَ الَّتِي سَأَلْتُ عَنْهَا. فَقَالَ عُوَيْمِرٌ: وَاللهِ لَا أَنْتَهِي حَتَّى أَسْأَلَ عَنْهَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَأَقْبَلَ عُوَيْمِرٌ حَتَّى أَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَسْطَ النَّاسِ فَقَالَ: يَا رَسُولَ اللهِ، أَرَأَيْتَ رَجُلًا وَجَدَ مَعَ امْرَأَتِهِ رَجُلًا، أَيَقْتُلُهُ فَتَقْتُلُونَهُ، أَمْ كَيْفَ يَفْعَلُ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "قَدْ نَزَلَ فِيكَ وَفِي صَاحِبَتِكَ، فَاذْهَبْ فَأْتِ بِهَا". قَالَ سَهْلٌ: فَتَلَاعَنَا وَأَنَا مَعَ النَّاسِ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا فَرَغَ عُوَيْمِرٌ قَالَ: كَذَبْتُ عَلَيْهَا يَا رَسُولَ اللهِ إِنْ أَمْسَكْتُهَا، فَطَلَّقَهَا ثَلَاثًا قَبْلَ أَنْ يَأْمُرَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദി(റ): ആസിമുബ്നു അദിയ്യ്(റ)വിന്റെ അടുത്ത് വന്ന് ഉവൈമിറുൽ അജ്ലാനി ചോദിച്ചു: ഓ ആസിം, ഒരാൾ തന്റെ ഭാര്യയുടെ കൂടെ വേറൊരുത്തനെ കണ്ടാൽ അവന് അയാളെ കൊല്ലാൻ പറ്റുമോ? അപ്പോൾ ജനങ്ങൾ അവനെയും കൊല്ലില്ലേ? അല്ലെങ്കിൽ എന്താണ് അവൻ ചെയ്യേണ്ടത്? ആസിമേ, എനിക്ക് വേണ്ടി ഇത് നീ റസൂൽ(സ)യോട് ചോദിക്കുക. അങ്ങനെ ആസിം റസൂൽ(സ)യോട് ചോദിച്ചു. ചോദ്യങ്ങൾ റസൂൽ(സ) വെറുക്കുകയും അവയെ ആക്ഷേപിക്കുകയും ചെയ്തു. ആസിം(റ)വിന് റസൂൽ(സ)യിൽ നിന്ന് കേട്ടത് വലിയ വിഷമമുണ്ടാക്കി. അദ്ദേഹം തന്റെ കുടുംബത്തിലേക്ക് മടങ്ങിയെത്തിയപ്പോൾ ഉവൈമിർ(റ) വന്ന് കൊണ്ട് അദ്ദേഹത്തോട് ചോദിച്ചു: ഓ ആസിം, നിന്നോട് എന്താണ് നബി(സ) പറഞ്ഞത്? അപ്പോൾ ആസിം(റ) ഉവൈമിർ(റ)വിനോട് പറഞ്ഞു: നിങ്ങളെനിക്ക് നന്മ ചെയ്തില്ല. നിങ്ങൾ ചോദിച്ച ചോദ്യം റസൂൽ(സ) വെറുത്തു. അപ്പോൾ ഉവൈമിർ(റ) പറഞ്ഞു: അതിനെക്കുറിച്ച് ഞാൻ റസൂൽ(സ)യോട് ചോദിക്കുന്നത് വരെ, അല്ലാഹുതന്നെ സത്യം, ഞാൻ പിന്തിരിയില്ല. ഉവൈമിർ(റ) മുന്നോട്ട് നടന്നു. അങ്ങനെ അദ്ദേഹം, ജനങ്ങൾക്കിടയിൽ നിൽക്കുകയായിരുന്ന റസൂൽ(സ)യുടെ അടുത്തെത്തി. അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഒരാൾ തന്റെ ഭാര്യയുടെ കൂടെ വേറൊരാളെ കണ്ടാൽ അവനെ കൊല്ലാൻ പറ്റുമോ, അപ്പോൾ നിങ്ങൾ അവനെയും കൊല്ലുമല്ലോ? അല്ലെങ്കിൽ അവൻ എന്താണ് ചെയ്യേത്? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ വിഷയത്തിലും നിന്റെ ഭാര്യയുടെ വിഷയത്തിലും ആയത്തിറങ്ങിയിരിക്കുന്നു. നീ പോയി അവളുമായി തിരിച്ച് വരിക." സഹ്ൽ(റ) പറഞ്ഞു: അങ്ങനെ റസൂൽ(സ)യുടെ അടുത്ത് വെച്ച് ജനങ്ങളോടൊപ്പം ഞങ്ങൾ പരസ്പരം ലിആൻ ചെയ്തു. ലിആൻ പൂർത്തിയായപ്പോൾ ഉവൈമിർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവളെ ഞാൻ നിലനിർത്തുകയാണെങ്കിൽ, ഞാനവളുടെ മേൽ കളവ് പറഞ്ഞെന്ന് വരും. റസൂൽ(സ) അദ്ദേഹത്തോട് കൽപിക്കുന്നതിന് മുമ്പ് അദ്ദേഹം അവളെ മൂന്ന് ത്വലാഖും ചൊല്ലി. (ന)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 151, 152, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّاسُ، وَالرَّجُلُ يُطَلِّقُ امْرَأَتَهُ مَا شَاءَ أَنْ يُطَلِّقَهَا، وَهِيَ امْرَأَتُهُ إِذَا ارْتَجَعَهَا وَهِيَ فِي الْعِدَّةِ، وَإِنْ طَلَّقَهَا مِائَةَ مَرَّةٍ أَوْ أَكْثَرَ، حَتَّى قَالَ رَجُلٌ لِامْرَأَتِهِ: وَاللهِ لَا أُطَلِّقُكِ فَتَبِينِي مِنِّي، وَلَا آوِيكِ أَبَدًا. قَالَتْ: وَكَيْفَ ذَاكَ؟ قَالَ: أُطَلِّقُكِ، فَكُلَّمَا هَمَّتْ عِدَّتُكِ أَنْ تَنْقَضِيَ رَاجَعْتُكِ. فَذَهَبَتِ الْمَرْأَةُ حَتَّى دَخَلَتْ عَلَى عَائِشَةَ فَأَخْبَرَتْهَا، فَسَكَتَتْ عَائِشَةُ حَتَّى جَاءَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَتْهُ، فَسَكَتَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى نَزَلَ الْقُرْآنُ: {الطَّلَاقُ مَرَّتَانِ فَإِمْسَاكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسَانٍ} [البقرة: ٢٢٩]. قَالَتْ عَائِشَةُ: فَاسْتَأْنَفَ النَّاسُ الطَّلَاقَ مُسْتَقْبَلًا، مَنْ كَانَ طَلَّقَ وَمَنْ لَمْ يَكُنْ طَلَّقَ. (ت)', 'ആയിശ(റ): പുരുഷന്മാർ ഉദ്ദേശിക്കുന്നയത്ര തങ്ങളുടെ ഭാര്യമാരെ ത്വലാഖ് ചൊല്ലുമായിരുന്നു. അവൾ ഇദ്ദയിൽ ഇരിക്കുമ്പോൾതന്നെ മടക്കി എടുക്കുകയാണെങ്കിൽ അവൾ അവന്റെ ഭാര്യതന്നെയായിരിക്കും. നൂറ് പ്രാവശ്യവും അതിലധികവും അവളെ ത്വലാഖ് ചൊല്ലിയാലും ശരി. അങ്ങനെ ഒരാൾ തന്റെ ഭാര്യയോട് പറഞ്ഞു: അള്ളാഹു തന്നെ സത്യം, നീ എന്നിൽനിന്ന് വേർപെടും വിധം ഞാൻ നിന്നെ ത്വലാഖ് ചൊല്ലുകയില്ല, എന്നാൽ ഒരിക്കലും ഞാൻ നിന്നെ അടുപ്പിക്കുകയുമില്ല. അവൾ ചോദിച്ചു: അത് എങ്ങനെയാണ്? അവൻ പറഞ്ഞു: ഞാൻ നിന്നെ ത്വലാഖ് ചൊല്ലും. നിന്റെ ഇദ്ദ കഴിയാനടുക്കുമ്പോഴെല്ലാം ഞാൻ നിന്നെ മടക്കി എടുക്കും. അപ്പോൾ ആ സ്ത്രീ പോയി ആയിശ(റ)യുടെ അടുക്കൽ ചെന്ന് കാര്യം പറഞ്ഞു. ആയിശ(റ) നബി(സ) വരുന്നത് വരെ മിണ്ടാതിരുന്നു. വന്നപ്പോൾ തിരുമേനി(സ)യോട് വിവരം പറഞ്ഞു. ''റദ്ദാക്കാവുന്ന വിവാഹമോചനം രണ്ടു പ്രാവശ്യമാണ്. പിന്നെ ഒന്നുകിൽ മര്യാദ അനുസരിച്ച് കൂടെ നിർത്തുക. അല്ലെങ്കിൽ നല്ല നിലയിൽ പിരിച്ചയക്കുക'' (അൽ ബഖറ: 229) എന്ന ഖുർആൻ സൂക്തം അവതരിക്കുന്നത് വരെ നബി(സ) ഒന്നും പറഞ്ഞില്ല. ആഇശ(റ) പറഞ്ഞു: ജനങ്ങൾ ത്വലാഖിലെ പുതിയ നിയമം സ്വീകരിച്ചു, മുമ്പ് ത്വലാഖ് ചൊല്ലിയവനും ചൊല്ലിയിട്ടില്ലാത്തവനും. (തു)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ت']::text[], array['തു']::text[], 'البقرة: ٢٢٩', null, 152, 153, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِذَا حَرَّمَ الرَّجُلُ عَلَيْهِ امْرَأَتَهُ فَهُوَ يَمِينٌ يُكَفِّرُهَا، وَلَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللهِ أُسْوَةٌ حَسَنَةً. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു മനുഷ്യൻ തന്റെ ഭാര്യയെ തനിക്ക് നിഷിദ്ധമാക്കിയാൽ അത് ഒരു സത്യംചെയ്യലാണ്. അതിന് അവൻ പ്രായശ്ചിത്തം നൽകണം. നിങ്ങൾക്ക് അല്ലാഹുവിന്റെ റസൂലിൽ ഉത്തമമായ മാതൃകയുണ്ട്. (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 153, 153, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَمْكُثُ عِنْدَ زَيْنَبَ بِنْتِ جَحْشٍ رَضِيَ اللهُ عَنْهَا فَيَشْرَبُ عِنْدَهَا عَسَلًا، قَالَتْ: فَتَوَاطَيْتُ أَنَا وَحَفْصَةُ رَضِيَ اللهُ عَنْهَا: أَنَّ أَيَّتَنَا مَا دَخَلَ عَلَيْهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلْتَقُلْ: إِنِّي أَجِدُ مِنْكَ رِيحَ مَغَافِيرَ، أَكَلْتَ مَغَافِيرَ؟ فَدَخَلَ عَلَى إِحْدَاهُمَا فَقَالَتْ ذَلِكَ لَهُ. فَقَالَ: "بَلْ شَرِبْتُ عَسَلًا عِنْدَ زَيْنَبَ بِنْتِ جَحْشٍ، وَلَنْ أَعُودَ لَهُ" فَنَزَلَ: {لِمَ تُحَرِّمُ مَا أَحَلَّ اللهُ لَكَ} إِلَى قَوْلِهِ تعالَى: {إِنْ تَتُوبَا} لِعَائِشَةَ وَحَفْصَةَ رَضِيَ اللهُ عَنْهُمَا {وَإِذْ أَسَرَّ النَّبِيُّ إِلَى بَعْضِ أَزْوَاجِهِ حَدِيثًا} [التحريم : ٣-١] لِقَوْلِهِ: "بَلْ شَرِبْتُ عَسَلًا". (م)', 'ആഇശ(റ): നബി(സ) സൈനബ് ബിൻത് ജഹ്ശ്(റ)യുടെ കൂടെ താമസിക്കുകയും അവിടെ നിന്ന് തേൻ കുടിക്കുകയും ചെയ്യുമായിരുന്നു. അന്നേരം ഞാനും ഹഫ്സ(റ)യും തിരുമേനി(സ) ഞങ്ങളിൽ ആരുടെ അടുത്ത് വന്നാലും, അങ്ങയിൽ നിന്ന് മഗാഫീറിന്റെ ദുർഗന്ധം വമിക്കുന്നു, അങ്ങ് മഗാഫീർ ഭക്ഷിച്ചിട്ടുണ്ടോ? എന്ന് ചോദിക്കാൻ തീരുമാനിച്ചു. അങ്ങനെ നബി(സ) അവരിൽ ഒരാളുടെ അടുക്കൽ ചെന്നപ്പോൾ അവർ അങ്ങനെ ചോദിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഞാൻ സൈനബ് ബിൻത് ജഹ്ശിന്റെ അടുക്കൽ നിന്ന് തേനാണ് കഴിച്ചത്. ഇനി ഞാനത് ആവർത്തിക്കില്ല." അന്നേരമാണ് ''അല്ലാഹു താങ്കൾക്ക് അനുവദനീയമാക്കിയത് താങ്കൾ എന്തിന് നിഷിദ്ധമാക്കുന്നു'' എന്നത് മുതൽ ആഇശ(റ)യോടും ഹഫ്സ(റ)യോടും, ''നിങ്ങൾ രണ്ടു പേരും പശ്ചാത്തപിക്കുന്ന പക്ഷം'' "ഞാൻ തേൻ കുടിച്ചു" എന്ന് പറഞ്ഞതിനെക്കുറിച്ച് ''നബി(സ) അവിടത്തെ ഭാര്യമാരിൽ ചിലരോട് ഒരു കാര്യം രഹസ്യമായി പറഞ്ഞ സന്ദർഭം ഓർക്കുക'' (തഹ്രീം: 1-3) എന്നിങ്ങനെയുള്ള ഖുർആൻ വാക്യം അവതരിച്ചത്. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], 'التحريم : ٣-١', null, 153, 153, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُحِبُّ الْحَلْوَاءَ وَالْعَسَلَ، فَكَانَ إِذَا صَلَّى الْعَصْرَ دَارَ عَلَى نِسَائِهِ فَيَدْنُو مِنْهُنَّ، فَدَخَلَ عَلَى حَفْصَةَ رَضِيَ اللهُ عَنْهَا فَاحْتَبَسَ عِنْدَهَا أَكْثَرَ مِمَّا كَانَ يَحْتَبِسُ، فَسَأَلْتُ عَنْ ذَلِكَ فَقِيلَ لِي: أَهْدَتْ لَهَا امْرَأَةٌ مِنْ قَوْمِهَا عُكَّةً مِنْ عَسَلٍ، فَسَقَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْهُ شَرْبَةً. فَقُلْتُ: أَمَا وَاللَّهِ لَنَحْتَالَنَّ لَهُ، فَذَكَرْتُ ذَلِكَ لِسَوْدَةَ رَضِيَ اللهُ عَنْهَا، وَقُلْتُ: إِذَا دَخَلَ عَلَيْكِ فَإِنَّهُ سَيَدْنُو مِنْكِ، فَقُولِي لَهُ: يَا رَسُولَ اللهِ، أَكَلْتَ مَغَافِيرَ؟ فَإِنَّهُ سَيَقُولُ لَكِ: لَا، فَقُولِي لَهُ: مَا هَذِهِ الرِّيحُ؟ وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَشْتَدُّ عَلَيْهِ أَنْ يُوجَدَ مِنْهُ الرِّيحُ، فَإِنَّهُ سَيَقُولُ لَكِ: سَقَتْنِي حَفْصَةُ شَرْبَةَ عَسَلٍ، فَقُولِي لَهُ: جَرَسَتْ نَحْلُهُ الْعُرْفُطَ، وَسَأَقُولُ ذَلِكَ لَهُ، وَقُولِيهِ أَنْتِ يَا صَفِيَّةُ، فَلَمَّا دَخَلَ عَلَى سَوْدَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: - تَقُولُ سَوْدَةُ رَضِيَ اللهُ عَنْهَا: وَالَّذِي لَا إِلَهَ إِلَّا هُوَ، لَقَدْ كِدْتُ أَنْ أُبَادِئَهُ بِالَّذِي قُلْتِ [لِي] وَإِنَّهُ لَعَلَى الْبَابِ، فَرَقًا مِنْكِ - فَلَمَّا دَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: يَا رَسُولَ اللهِ أَكَلْتَ مَغَافِيرَ؟ قَالَ: "لَا". قَالَتْ: فَمَا هَذِهِ الرِّيحُ؟ قَالَ: "سَقَتْنِي حَفْصَةُ شَرْبَةَ عَسَلٍ". قَالَتْ: جَرَسَتْ نَحْلُهُ الْعُرْفُطُ. فَلَمَّا دَخَلَ عَلَيَّ قُلْتُ لَهُ مِثْلَ ذَلِكَ، ثُمَّ دَخَلَ عَلَى صَفِيَّةَ فَقَالَتْ بِمِثْلِ ذَلِكَ، فَلَمَّا دَخَلَ عَلَى حَفْصَةَ رَضِيَ اللهُ عَنْهُ قَالَتْ: يَا رَسُولَ اللهِ أَلَا أَسْقِيكَ مِنْهُ؟ قَالَ: "لَا حَاجَةَ لِي بِهِ". قَالَتْ: تَقُولُ سَوْدَةُ رَضِيَ اللهُ عَنْهَا: سُبْحَانَ اللهِ، وَاللهِ لَقَدْ حَرَمْنَاهُ. قَالَتْ: قُلْتُ لَهَا: اسْكُتِي. (ق)', 'ആഇശ(റ): നബി(സ)ക്ക് ഹൽവയും തേനും ഇഷ്ടമായിരുന്നു. അവിടന്ന് അസർ നമസ്കാരാനന്തരം എല്ലാ ഭാര്യമാരുടെയും അടുക്കൽ ചെല്ലുകയും അവരിൽ ഒരാളുടെ കൂടെ താമസിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. അങ്ങനെ അവിടന്ന് ഒരു ദിവസം ഹഫ്സ(റ)യുടെ അടുക്കൽ ചെല്ലുകയും സാധാരണ ചെലവഴിക്കുന്നതിനെക്കാൾ കൂടുതൽ അവരുടെ അടുത്ത് കഴിച്ചുകൂട്ടുകയും ചെയ്തു. അതിനെക്കുറിച്ച് ഞാൻ അന്വേഷിച്ചപ്പോൾ അവരുടെ കുടുംബത്തിൽപെട്ട ഒരു സ്ത്രീ ഒരു പാത്രം തേൻ അവർക്ക് പാരിതോഷികമായി നൽകിയിരുന്നുവെന്നും അവർ അതിൽ നിന്നും തിരുമേനി(സ)ക്ക് കുടിക്കാൻ കൊടുത്തുവെന്നും എനിക്ക് മറുപടി ലഭിച്ചു. അന്നേരം ഞാൻ മനസ്സിൽ വിചാരിച്ചു: അല്ലാഹുവാണ് സത്യം, ഞങ്ങൾ തിരുമേനി(സ)യോട് ഒരു സൂത്രം പ്രയോഗിക്കും. അനന്തരം ഞാനീ സംഭവം സൗദ(റ)യെ അറിയിച്ചു. ഞാൻ അവരോട് പറഞ്ഞു: നബി(സ) ഇപ്പോൾ നിങ്ങളുടെ അടുത്ത് വരും. വരുമ്പോൾ നിങ്ങൾ ഇപ്രകാരം ചോദിക്കണം: അല്ലാഹുവിന്റെ ദൂതരേ, അങ്ങ് മഗാഫീർ കഴിച്ചിട്ടുണ്ടോ? അന്നേരം അവിടന്ന് ''ഇല്ല'' എന്ന് പറയും. അപ്പോൾ എന്താണ് ഈ ദുർഗന്ധമെന്ന് നിങ്ങൾ ചോദിക്കണം. നബി(സ)യിൽ നിന്ന് എന്തെങ്കിലും ദുർഗന്ധം വമിക്കുകയെന്നത് അവിടത്തേക്ക് ഒരിക്കലും സഹിക്കുവാൻ കഴിയുകയില്ലായിരുന്നു. അന്നേരം അവിടന്ന് നിന്നോട് പറയും: എനിക്ക് ഹഫ്സ അൽപം തേൻ കുടിക്കാൻ തന്നിരുന്നു. അപ്പോൾ നീ പറയണം: എന്നാൽ ആ തേനീച്ച ഉർഫുത് എടുക്കുന്ന മരത്തിൽ നിന്ന് ഭക്ഷിച്ചിട്ടുണ്ടായിരിക്കും, നിശ്ചയമായും ഞാനും തിരുമേനി(സ)യോട് ഇങ്ങനെത്തന്നെ പറയുന്നതാണ്. ഹേ സ്വഫിയ്യാ, നീയും ഇങ്ങനെ പറയണം. - ആഇശ(റ) പറയുന്നു: സൗദ(റ) പറയുമായിരുന്നു: അല്ലാഹുവാണ് സത്യം, നിന്നോടുള്ള ഭയം നിമിത്തം നബി(സ) വാതിൽക്കൽ എത്തിയപ്പോൾതന്നെ ഞാൻ നീ പറഞ്ഞപ്രകാരം പറയാൻ തുനിഞ്ഞു. - അങ്ങനെ അവിടന്ന് അടുത്ത് വന്നപ്പോൾ സൗദ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് ''മഗാഫീർ'' ഭക്ഷിച്ചിട്ടുണ്ടോ? അവിടന്ന് പറഞ്ഞു: "ഇല്ല." മഹതി ചോദിച്ചു: എന്നാൽ എന്താണീ ദുർഗന്ധം? അവിടന്ന് പറഞ്ഞു: "ഹഫ്സ എനിക്കൽപം തേൻ കുടിക്കാൻ തന്നിരുന്നു." അവർ പറഞ്ഞു: ആ തേനീച്ച ഉർഫുത് ഭക്ഷിച്ചിരുന്നു. ശേഷം അവിടന്ന് എന്റെയടുക്കൽ വന്നപ്പോൾ ഞാനും അവിടത്തോട് അതുപോലെ പറഞ്ഞു. ശേഷം അവിടന്ന് സ്വഫിയ്യ(റ)യുടെ അടുക്കൽ ചെന്നു. അപ്പോൾ മഹതിയും അപ്രകാരം പറഞ്ഞു. അനന്തരം അവിടന്ന് ഹഫ്സ(റ)യുടെ അടുക്കൽ ചെന്നപ്പോൾ അവർ പറഞ്ഞു: ഞാൻ അങ്ങേക്ക് അതിൽ നിന്ന് അൽപം കുടിക്കാൻ തരട്ടെയോ? അവിടന്നരുളി: "എനിക്ക് അതാവശ്യമില്ല." ആഇശ(റ) പറയുന്നു: അന്നേരം സൗദ(റ) പറഞ്ഞു: സുബ്ഹാനല്ലാഹ്, അല്ലാഹു തന്നെ സത്യം, നിശ്ചയമായും നാം തിരുമേനി(സ)ക്ക് അത് നിഷിദ്ധമാക്കി. ആഇശ(റ) പറയുന്നു: ഞാൻ സൗദ(റ)യോട് പറഞ്ഞു: നീ മിണ്ടാതിരിക്കുക. (ബു,മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], 'لِي', null, 153, 155, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَتَاهُ رَجُلٌ فَقَالَ: إِنِّي جَعَلْتُ امْرَأَتِي عَلَيَّ حَرَامًا؟ قَالَ: كَذَبْتَ، لَيْسَتْ عَلَيْكَ بِحَرَامٍ، ثُمَّ تَلَا هَذِهِ الْآيَةَ {يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللهُ لَكَ} [التحريم: ٤] عَلَيْكَ أَغْلَظُ الْكَفَّارَةِ عِتْقُ رَقَبَةٍ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അദ്ദേഹത്തിന്റെയടുത്ത് ഒരാൾ വന്നു കൊണ്ട് പറഞ്ഞു: ഞാനെന്റെ ഭാര്യയെ എനിക്ക് നിഷിദ്ധമാക്കിയിരിക്കുന്നു. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: നീ കളവാണ് പറഞ്ഞത്. അവൾ നിനക്ക് നിഷിദ്ധമാകുന്നില്ല. പിന്നെ അവിടന്ന് ഈ സൂക്തം ഓതിക്കേൾപ്പിച്ചു: ''അങ്ങേക്ക് അല്ലാഹു അനവദനീയമാക്കിയത് എന്തിനാണ് അവിടന്ന് നിഷിദ്ധമാക്കുന്നത്.'' ഒരു അടിമയെ മോചിപ്പിക്കണമെന്ന കടുത്ത പ്രായശ്ചിത്തം നിനക്ക് നിർബന്ധമായിരിക്കുന്നു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'التحريم: ٤', null, 155, 155, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَخْبَرَتْهُ أَنَّ رِفَاعَةَ الْقُرَظِيَّ رَضِيَ اللهُ عَنْهُ طَلَّقَ امْرَأَتَهُ فَبَتَّ طَلَاقَهَا، فَتَزَوَّجَتْ بَعْدَهُ عَبْدَ الرَّحْمَنِ بْنَ الزَّبِيرِ رَضِيَ اللهُ عَنْهُ، فَجَاءَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللهِ إِنَّهَا كَانَتْ تَحْتَ رِفَاعَةَ، فَطَلَّقَهَا آخِرَ ثَلَاثِ تَطْلِيقَاتٍ، فَتَزَوَّجَتْ بَعْدَهُ عَبْدَ الرَّحْمَنِ بْنَ الزَّبِيرِ، وَإِنَّهُ وَاللهِ مَا مَعَهُ إِلَّا مِثْلُ الْهُدْبَةِ. وَأَخَذَتْ بِهُدْبَةٍ مِنْ جِلْبَابِهَا، قَالَ: فَتَبَسَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ضَاحِكًا، فَقَالَ: "لَعَلَّكِ تُرِيدِينَ أَنْ تَرْجِعِي إِلَى رِفَاعَةَ؟ لَا، حَتَّى يَذُوقَ عُسَيْلَتَكِ، وَتَذُوقِي عُسَيْلَتَهُ". وَأَبُو بَكْرٍ الصِّدِّيقُ رَضِيَ اللهُ عَنْهُ جَالِسٌ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَخَالِدُ بْنُ سَعِيدِ بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُ جَالِسٌ بِبَابِ الْحُجْرَةِ لَمْ يُؤْذَنْ لَهُ، قَالَ: فَطَفِقَ خَالِدٌ رَضِيَ اللهُ عَنْهُ يُنَادِي: أَبَا بَكْرٍ، أَلَا تَزْجُرُ هَذِهِ عَمَّا تَجْهَرُ بِهِ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ (ق)', 'നബി(സ)യുടെ പത്നിയായ ആഇശ(റ): രിഫാഅത്തൽ ഖുറദി(റ) തന്റെ ഭാര്യയുടെ ത്വലാഖ് പൂർണ്ണമായും ചൊല്ലി. അവർ (ഭാര്യ) അതിനുശേഷം അബ്ദുർറഹ്മാനുബ്നു സുബൈർ(റ)വിനെ വിവാഹം കഴിച്ചു. അവർ നബി(സ)യുടെ അടുത്ത് വന്നുകൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവൾ രിഫാഅയുടെ ഭാര്യയായിരുന്നു. അദ്ദേഹം അവളെ മൂന്ന് ത്വലാഖും ചൊല്ലി. അതിന് ശേഷം ഞാൻ അബ്ദുർറഹ്മാനുബ്നു സുബൈറിനെ വിവാഹം കഴിച്ചു. അദ്ദേഹത്തിന്റെയടുത്ത് തുണിക്കോന്തലക്ക് സമാനമായതേയുള്ളൂ. അവൾ തന്റെ വസ്ത്രത്തിന്റെ കോന്തല പിടിച്ചു. അപ്പോൾ റസൂൽ(സ) പുഞ്ചിരിച്ചു. അവിടന്ന് പറഞ്ഞു: "നീ രിഫാഅയുടെ അടുത്തേക്ക് മടങ്ങാൻ ഉദ്ദേശിക്കുന്നുണ്ടാകും. പക്ഷേ, നിന്റെ തേൻതുള്ളി അദ്ദേഹവും (അബ്ദുർറഹ്മാനുബ്നു സുബൈർ) അദ്ദേഹത്തിന്റെ തേൻതുള്ളി നീയും കുടിക്കുന്നതു വരെ അത് പറ്റില്ല." അപ്പോൾ അബൂബക്കർ(റ) റസൂൽ(സ)യുടെ അടുത്ത് ഇരിക്കുന്നുണ്ടായിരുന്നു. ഖാലിദുബ്നു സഈദുബ്നുൽ ആസ്(റ) റൂമിന്റെ വാതിൽക്കലും ഇരിക്കുന്നുണ്ട്. അദ്ദേഹത്തിന് അകത്തുവരാൻ സമ്മതം കിട്ടിയിട്ടില്ല. അപ്പോൾ ഖാലിദ്(റ) വിളിച്ചുപറയാൻ തുടങ്ങി: ഓ അബൂബക്കർ, ഇവൾ റസൂൽ(സ)യുടെയടുത്ത് ഉറക്കെ വിളിച്ചു പറയുന്നത് നിങ്ങൾ തടയുന്നില്ലേ? (ബു,മു)', 'عَائِشَةَ', 'നബി(സ)യുടെ പത്നിയായ ആഇശ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 155, 155, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ رَجُلٍ طَلَّقَ امْرَأَتَهُ - يَعْنِي ثَلَاثًا - فَتَزَوَّجَتْ زَوْجًا غَيْرَهُ، فَدَخَلَ بِهَا، ثُمَّ طَلَّقَهَا قَبْلَ أَنْ يُوَاقِعَهَا، أَتَحِلُّ لِزَوْجِهَا الْأَوَّلِ؟ قَالَتْ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَحِلُّ لِلْأَوَّلِ حَتَّى تَذُوقَ عُسَيْلَةَ الْآخَرِ وَيَذُوقَ عُسَيْلَتَهَا". (ق,د,ت,ن,جه)', 'ആഇശ(റ): തന്റെ ഭാര്യയെ ത്വലാഖ് ചൊല്ലിയ - മൂന്ന് പ്രാവശ്യമാണുദ്ദേശിക്കപ്പെടുന്നത് - ഒരാളെക്കുറിച്ച് റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു. അങ്ങനെ അവൾ മറ്റൊരു ഭർത്താവിനെ വിവാഹം ചെയ്യുകയും അവൻ അവളുമായി വീട് കൂടുകയും ബന്ധപ്പെടുംമുമ്പേ അവളെ ത്വലാഖ് ചൊല്ലുകയും ചെയ്തു. എന്നാൽ, അവളുടെ ഒന്നാം ഭർത്താവിന് അവൾ അനുവദനീയമാവുമോ? മഹതി പറഞ്ഞു: നബി(സ) പറഞ്ഞു: "മറ്റവന്റെ മധു ഇവളും ഇവളുടെ മധു അവനും രുചിക്കുന്നത് വരെ (അവരിരുവരും ബന്ധപ്പെടുന്നത് വരെ) ഒന്നാമത്തെയാൾക്ക് അവൾ അനുവദനീയമാകുകയില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 156, 156, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَيُّمَا رَجُلٍ نَكَحَ امْرَأَةً فَدَخَلَ بِهَا فَلَا يَحِلُّ لَهُ نِكَاحُ ابْنَتِهَا، وَإِنْ لَمْ يَكُنْ دَخَلَ بِهَا فَلْيَنْكِحِ ابْنَتَهَا. وَأَيُّمَا رَجُلٍ نَكَحَ امْرَأَةً - فَدَخَلَ بِهَا أَوْ لَمْ يَدْخُلْ بِهَا - فَلَا يَحِلُّ لَهُ نِكَاحُ أُمِّهَا". (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറയുന്നു: "ഒരാൾ ഒരു സ്ത്രീയെ വിവാഹം കഴിച്ച് അവളെ ബന്ധപ്പെട്ടാൽ അവന് അവളുടെ മകളെ വിവാഹം കഴിക്കൽ അനുവദനീയമല്ല. ഭാര്യയെ ബന്ധപ്പെട്ടിട്ടില്ലെങ്കിൽ അവന് അവളുടെ മകളെ വിവാഹം കഴിക്കാം. ഒരാൾ ഒരു സ്ത്രീയെ വിവാഹം കഴിച്ച് അവളെ ബന്ധപ്പെട്ടാലും ഇല്ലെങ്കിലും അവന് അവളുടെ മാതാവിനെ വിവാഹം കഴിക്കാൻ പറ്റുകയില്ല." (തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 156, 156, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ، أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ طَلَّقَ حَفْصَةَ رَضِيَ اللهُ عَنْهَا ثُمَّ رَاجَعَهَا. (د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഉമർ(റ) പറയുന്നു: നബി(സ) ഹഫ്സ(റ)യെ വിവാഹമോചനം നടത്തിയിരുന്നു. പിന്നെ അവിടന്ന് അവരെ തിരിച്ചെടുത്തു. (ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 156, 156, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ عِمْرَانَ بْنِ الْحُصَيْنِ رَضِيَ اللهُ عَنْهُمَا: سُئِلَ عَنِ الرَّجُلِ يُطَلِّقُ امْرَأَتَهُ ثُمَّ يَقَعُ بِهَا، وَلَمْ يُشْهِدْ عَلَى طَلَاقِهَا وَلَا عَلَى رَجْعَتِهَا، فَقَالَ طَلَّقْتَ بِغَيْرِ سُنَّةٍ، وَرَاجَعْتَ بِغَيْرِ سُنَّةٍ، أَشْهِدْ عَلَى طَلَاقِهَا وَعَلَى رَجْعَتِهَا. (د,جه)', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ): തന്റെ ഭാര്യയെ വിവാഹമോചനം ചെയ്യുകയും പിന്നെ അവളുമായി വേഴ്ചയിലേർപ്പെടുകയും ചെയ്യുന്ന ഒരാളെക്കുറിച്ച് അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. അവളെ വിവാഹമോചനം നടത്തിയതിനോ തിരിച്ചെടുത്തതിനോ ഒരു സാക്ഷിയുമില്ല. അപ്പോൾ ഇംറാൻ(റ) പറഞ്ഞു: നീ തിരുചര്യക്കെതിരായാണ് വിവാഹമോചനം ചെയ്തത്. തിരുചര്യക്കെതിരായാണ് നീ തിരിച്ചെടുക്കുകയും ചെയ്തത്. അവളെ വിവാഹമോചനം ചെയ്തതിനും തിരിച്ചെടുത്തതിനും നീ സാക്ഷിയെ കൊണ്ടുവരിക. (ദ,ജ)', 'عِمْرَانَ بْنِ الْحُصَيْنِ', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 156, 156, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثٌ جِدُّهُنَّ جِدٌّ، وَهَزْلُهُنَّ جِدٌّ: النِّكَاحُ وَالطَّلَاقُ وَالرَّجْعَةُ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്നു കാര്യങ്ങൾ അവയുടെ കാര്യവും കാര്യമാണ്, തമാശയും കാര്യമാണ്. വിവാഹം, വിവാഹമോചനം, തിരിച്ചെടുക്കൽ." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ قَالَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 157, 157, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا بَالُ أَقْوَامٍ يَلْعَبُونَ بِحُدُودِ اللهِ، يَقُولُ أَحَدُهُمْ: قَدْ طَلَّقْتُكِ، قَدْ رَاجَعْتُكِ، قَدْ طَلَّقْتُكِ". (جه)', 'അബൂമൂസ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിന്നെ ഞാൻ ത്വലാഖ് ചൊല്ലി, നിന്നെ ഞാൻ തിരിച്ചെടുത്തു, നിന്നെ ഞാൻ ത്വലാഖ് ചൊല്ലി എന്നിങ്ങനെ പറഞ്ഞ് അല്ലാഹുവിന്റെ വിധികൾ കൊണ്ട് കളിക്കുന്ന ആളുകളുടെ അവസ്ഥയെന്താണ്." (ജ)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 157, 157, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فِي قَوْلِهِ: {مَا نَنْسَخْ مِنْ آيَةٍ أَوْ نُنْسِهَا نَأْتِ بِخَيْرٍ مِنْهَا أَوْ مِثْلِهَا} [البقرة: ١٠٦] وَقَالَ: {وَإِذَا بَدَّلْنَا آيَةً مَكَانَ آيَةٍ وَاللهُ أَعْلَمُ بِمَا يُنَزِّلُ} [النحل: ١٠١] الآيَةِ، وَقَالَ: {يَمْحُو اللهُ مَا يَشَاءُ وَيُثْبِتُ وَعِنْدَهُ أُمُّ الْكِتَابِ} [الرّعد: ٣٩] فَأَوَّلُ مَا نُسِخَ مِنَ الْقُرْآنِ الْقِبْلَةُ. وَقَالَ: {وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ وَلَا يَحِلُّ لَهُنَّ أَنْ يَكْتُمْنَ مَا خَلَقَ اللهُ فِي أَرْحَامِهِنَّ} إِلَى قَوْلِهِ: {إِنْ أَرَادُوا إِصْلَاحًا} وَذَلِكَ بِأَنَّ الرَّجُلَ كَانَ إِذَا طَلَّقَ امْرَأَتَهُ فَهُوَ أَحَقُّ بِرَجْعَتِهَا وَإِنْ طَلَّقَهَا ثَلَاثًا، فَنُسِخَ ذَلِكَ وَقَالَ: {الطَّلَاقُ مَرَّتَانِ فَإِمْسَاكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسَانٍ} [البقرة: ٢٢٩] (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ''നാമൊരു സൂക്തം ദുർബലപ്പെടുത്തുകയോ മരവിപ്പിക്കുകയോ ചെയ്യുമ്പോൾ അതിലും ഉത്തമമായതോ അതുപോലോത്തതോ നാം കൊണ്ടുവരുന്നതാണ്'' (അൽ ബഖറ: 106). ''ഒരു സൂക്തത്തിന് പകരമായി വേറൊരു സൂക്തം നാം കൊണ്ടുവന്നാൽ അള്ളാഹു താൻ അവതരിപ്പിക്കുന്നത് നന്നായി അറിയുന്നവനാണ്'' (അന്നഹ്ല്: 101). ''അള്ളാഹു ഉദ്ദേശിക്കുന്നത് മായ്ച്ച് കളയുകയും സ്ഥിരപ്പെടുത്തുകയും ചെയ്യും. അവന്റെയടുത്താണ് ഉമ്മുൽകിതാബ്'' (അർറഅ്ദ്:39). ഖുർആനിൽ നിന്ന് ആദ്യമായി ദുർബലമാക്കപ്പെട്ടത് ഖിബ്ലയാണ്. ''വിവാഹമോചനം ചെയ്യപ്പെട്ടവർ മൂന്ന് ശുദ്ധിയുടെ സമയം കാത്തിരിക്കണം. അള്ളാഹു അവരുടെ ഗർഭപാത്രങ്ങളിൽ സൃഷ്ടിച്ചത് മറച്ചുവെക്കൽ അവർക്ക് അനുവദനീയമല്ല.'' എന്നത് മുതൽ ''അവർ നന്നാക്കൽ ആഗ്രഹിക്കുന്നവരെങ്കിൽ'' എന്നത്വരെയുള്ള സൂക്തം അവതരിക്കാൻ കാരണം, ഒരാൾ തന്റെ ഭാര്യയെ ത്വലാഖ് ചൊല്ലിയാൽ അവൻ അവളെ മൂന്ന് പ്രാവശ്യം ചൊല്ലിയുട്ടുണ്ടെങ്കിലും അവന് അവളെ തിരിച്ചെടുക്കാമായിരുന്നു. അങ്ങനെ അള്ളാഹു ഇത് ദുർബലമാക്കി. അള്ളാഹു പറയുന്നു: ''വിവാഹമോചനം രണ്ട് പ്രാവശ്യമാണ്. അതിന് ശേഷം നല്ല രീതിയിൽ നിർത്തുകയോ നല്ല രീതിയിൽ വേർപ്പിരിക്കുകയോ ചെയ്യലാണ്.'' (അൽ ബഖറ: 229) (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'البقرة: ٢٢٩', null, 157, 157, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ مُجَاهِدٍ قَالَ: كُنْتُ عِنْدَ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، فَجَاءَهُ رَجُلٌ فَقَالَ: إِنَّهُ طَلَّقَ امْرَأَتَهُ ثَلَاثًا، قَالَ: فَسَكَتَ حَتَّى ظَنَنْتُ أَنَّهُ رَادُّهَا إِلَيْهِ، ثُمَّ قَالَ: يَنْطَلِقُ أَحَدُكُمْ فَيَرْكَبُ الْحُمُوقَةَ ثُمَّ يَقُولُ: يَا ابْنَ عَبَّاسٍ، يَا ابْنَ عَبَّاسٍ، وَإِنَّ اللهَ قَالَ: {وَمَنْ يَتَّقِ اللهَ يَجْعَلْ لَهُ مَخْرَجًا} [الطّلاق: ٢] وَإِنَّكَ لَمْ تَتَّقِ اللهَ فَلَمْ أَجِدْ لَكَ مَخْرَجًا، عَصَيْتَ رَبَّكَ، وَبَانَتْ مِنْكَ امْرَأَتُكَ، وَإِنَّ اللهَ قَالَ: {يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ} [الطّلاق: ١] فِي قُبُلِ عِدَّتِهِنَّ. (د)', 'മുജാഹിദ്(റ): ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)വിന്റെ കൂടെയായിരുന്നു. അപ്പോൾ ഒരാൾ വന്ന് അയാൾ തന്റെ ഭാര്യയെ മൂന്ന് ത്വലാഖ് ചൊല്ലിയെന്ന് പറഞ്ഞു. നിവേദകൻ പറയുന്നു: ഇബ്നുഅബ്ബാസ്(റ) മൗനമവലംബിച്ചു. ഭാര്യയെ അവന് തിരിച്ചു നൽകുമെന്ന് ഞാൻ വിചാരിച്ചു. പിന്നെ അദ്ദേഹം പറഞ്ഞു: നിങ്ങൾ പോയി വല്ല വിഡ്ഢിത്തവും ചെയ്ത് പിന്നെ ഇബ്നുഅബ്ബാസേ, ഇബ്നുഅബ്ബാസേ എന്ന് പറഞ്ഞുവരും. അള്ളാഹു പറഞ്ഞിട്ടുണ്ട്: ''ആരെങ്കിലും അള്ളാഹുവിനെ സൂക്ഷിച്ചാൽ അള്ളാഹു അവന് മാർഗമുണ്ടാക്കിക്കൊടുക്കും'' (ത്വലാഖ്: 2). നിങ്ങൾ അള്ളാഹുവിനെ സൂക്ഷിച്ചില്ല. അതിനാൽ ഞാൻ നിങ്ങൾക്കൊരു പഴുതും കാണുന്നില്ല. നിന്റെ നാഥനെ നീ ധിക്കരിച്ചിരിക്കുന്നു, നിന്റെ ഭാര്യ നിന്നെ വേർപ്പിരിഞ്ഞിരിക്കുന്നു. അള്ളാഹു പറയുന്നു: ''ഓ, നബിയെ, അവിടന്ന് ഭാര്യമാരെ വിവാഹമോചനം ചെയ്യുമ്പോൾ അവർക്ക് (ഇദ്ദ ഇരിക്കാവുന്ന വേളകളിൽ) നിങ്ങളവരെ വിവാഹമോചനം ചെയ്യുക.'' (ത്വലാഖ്: 1) അതായത് ഇദ്ദയുടെ ആദ്യസമയത്ത്. (ദ)', 'مُجَاهِدٍ قَالَ', 'മുജാഹിദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'الطّلاق: ١', null, 157, 158, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنِ ابْنِ عَبَّاسٍ وَأَبِي هُرَيْرَةَ وَعَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُمْ: سُئِلُوا عَنِ الْبِكْرِ يُطَلِّقُهَا زَوْجُهَا ثَلَاثًا؟ فَكُلُّهُمْ قَالُوا: لَا تَحِلُّ لَهُ حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ), അബുഹുറൈറ(റ), അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽആസ്(റ): ഭർത്താവ് മൂന്നുപ്രാവശ്യം മൊഴിചൊല്ലിയ കന്യകയെക്കുറിച്ച് ഇവരോട് ചോദിക്കപ്പെട്ടു. അവർ എല്ലാവരും പറഞ്ഞു: അവൾ വേറെയൊരു ഭർത്താവിനെ വിവാഹം കഴിക്കുന്നത് വരെ അവൾ അവന് ഹലാലാകില്ല. (ദ)', 'ابْنِ عَبَّاسٍ وَأَبِي هُرَيْرَةَ وَعَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 158, 158, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ طَاوُسٍ: أَنَّ رَجُلًا يُقَالُ لَهُ أَبُو الصَّهْبَاءِ كَانَ كَثِيرَ السُّؤَالِ لِابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، قَالَ: أَمَا عَلِمْتَ أَنَّ الرَّجُلَ كَانَ إِذَا طَلَّقَ امْرَأَتَهُ ثَلَاثًا قَبْلَ أَنْ يَدْخُلَ بِهَا جَعَلُوهَا وَاحِدَةً، عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ وَصَدْرًا مِنْ إِمَارَةِ عُمَرَ؟ قَالَ ابْنُ عَبَّاسٍ: بَلَى، كَانَ الرَّجُلُ إِذَا طَلَّقَ امْرَأَتَهُ قَبْلَ أَنْ يَدْخُلَ بِهَا جَعَلُوهَا وَاحِدَةً عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ وَصَدْرًا مِنْ إِمَارَةِ عُمَرَ، فَلَمَّا رَأَى النَّاسَ قَدْ تَتَابَعُوا فِيهَا قَالَ: أَجِيزُوهُنَّ عَلَيْهِمْ. وَفِي رِوَايَةٍ: أَنَّ أَبَا الصَّهْبَاءِ قَالَ لِابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَتَعْلَمُ أَنَّمَا كَانَتِ الثَّلَاثُ تُجْعَلُ وَاحِدَةً عَلَى عَهْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ وَثَلَاثًا مِنْ إِمَارَةِ عُمَرَ؟ قَالَ ابْنُ عَبَّاسٍ: نَعَمْ. (م,د,ن)', 'ത്വാഊസ്(റ): അബുസഹ്ബാഅ് എന്ന് പേരുള്ള ഒരാൾ ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ധാരാളം ചോദ്യങ്ങൾ ചോദിക്കുമായിരുന്നു, അദ്ദേഹം ചോദിച്ചു: റസൂൽ(സ)യുടെയും അബൂബകർ(റ)വിന്റെയും കാലത്തും ഉമർ(റ)വിന്റെ ആദ്യകാലത്തും ഒരാൾ തന്റെ ഭാര്യയെ ബന്ധപ്പെടുന്നതിന് മുമ്പ് മൂന്ന് ത്വലാഖും ചൊല്ലിയാൽ അവർ അത് ഒന്നായി പരിഗണിച്ചിരുന്നുവെന്ന് താങ്കൾക്കറിയില്ലേ? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അതെ, റസൂൽ(സ)യുടെയും അബൂബകർ(റ)വിന്റെയും കാലത്തും ഉമർ(റ)വിന്റെ ഭരണകാലത്തിന്റെ ആദ്യഘട്ടത്തിലും ഒരാൾ തന്റെ ഭാര്യയെ ബന്ധപ്പെടുന്നതിന്ന് മുമ്പ് മൂന്ന് ത്വലാഖ് ചൊല്ലിയാൽ അത് ഒന്നായാണ് പരിഗണിച്ചിരുന്നത്. ജനങ്ങൾ അതിൽ തുടർന്നുകൊണ്ടേയിരുന്നപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അവ സ്ത്രീകൾക്ക് മേൽ നടപ്പാക്കുക. മറ്റൊരു നിവേദനം: അബുസ്വഹ്ബാഅ് ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ചോദിച്ചു: നബി(സ)യുടെയും അബൂബകർ(റ)വിന്റെയും കാലത്തും ഉമർ(റ)വിന്റെ ഭരണകാലത്തിന്റെ മൂന്ന് വർഷവും മൂന്ന് ത്വലാഖ് ഒന്നായി ഗണിച്ചിരുന്നത് താങ്കൾക്കറിയില്ലേ. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അതെ. (മു,ദ,ന)', 'طَاوُسٍ', 'ത്വാഊസ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 158, 158, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=33), 1, 'وَفِي رِوَايَةٍ: أَنَّ أَبَا الصَّهْبَاءِ قَالَ لِابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَتَعْلَمُ أَنَّمَا كَانَتِ الثَّلَاثُ تُجْعَلُ وَاحِدَةً عَلَى عَهْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ وَثَلَاثًا مِنْ إِمَارَةِ عُمَرَ؟ قَالَ ابْنُ عَبَّاسٍ: نَعَمْ. (م,د,ن)', 'മറ്റൊരു നിവേദനം: അബുസ്വഹ്ബാഅ് ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ചോദിച്ചു: നബി(സ)യുടെയും അബൂബകർ(റ)വിന്റെയും കാലത്തും ഉമർ(റ)വിന്റെ ഭരണകാലത്തിന്റെ മൂന്ന് വർഷവും മൂന്ന് ത്വലാഖ് ഒന്നായി ഗണിച്ചിരുന്നത് താങ്കൾക്കറിയില്ലേ. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അതെ. (മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا أَوِ امْرَأَةٍ يَتَزَوَّجُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ". (ق,د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "കർമ്മങ്ങൾ ഉദ്ദേശങ്ങൾ കൊണ്ടാണ് പരിഗണിക്കപ്പെടുന്നത്. ഓരോ മനുഷ്യനും അവനുദ്ദേശിച്ചതേയുള്ളൂ. ആരുടെയെങ്കിലും ഹിജ്റ അല്ലാഹുവിലേക്കും അവന്റെ റസൂലിലേക്കുമാണെങ്കിൽ അവന്റെ ഹിജ്റ അല്ലാഹുവിലേക്കും അവന്റെ റസൂലിലേക്കുമാണ്. ഒരാളുടെ ഹിജ്റ താൻ സമ്പാദിക്കുന്ന ദുൻയാവിന് വേണ്ടിയോ, താൻ വിവാഹം ചെയ്യുന്ന ഭാര്യക്ക് വേണ്ടിയോ ആണെങ്കിൽ അവന്റെ ഹിജ്റ അവൻ ഹിജ്റ പോയതിലേക്കാണ്." (ബു,മു,ദ,തു,ന,ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 159, 159, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ عَبْدِ اللهِ بْنِ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا - وَكَانَ قَائِدَ كَعْبٍ مِنْ بَنِيهِ حِينَ عَمِيَ - قَالَ: سَمِعْتُ كَعْبَ بْنَ مَالِكٍ - فَسَاقَ قِصَّتَهُ فِي تَبُوكَ - قَالَ: حَتَّى إِذَا مَضَتْ أَرْبَعُونَ مِنَ الْخَمْسِينَ إِذَا رَسُولُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْتِي، فَقَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكَ أَنْ تَعْتَزِلَ امْرَأَتَكَ. قَالَ: فَقُلْتُ: أُطَلِّقُهَا أَمْ مَاذَا أَفْعَلُ؟ قَالَ: لَا، بَلِ اعْتَزِلْهَا فَلَا تَقْرَبَنَّهَا. فَقُلْتُ لِامْرَأَتِي: الْحَقِي بِأَهْلِكِ، فَكُونِي عِنْدَهُمْ حَتَّى يَقْضِيَ اللهُ سُبْحَانَهُ فِي هَذَا الْأَمْرِ. (ق,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു കഅ്ബുബ്നു മാലിക്(റ): കഅ്ബ്(റ) അന്ധനായപ്പോൾ തന്റെ മക്കളിൽ അദ്ദേഹമായിരുന്നു കഅ്ബ്(റ)വിന് വഴികാണിച്ചുകൊടുത്തിരുന്നത്. അദ്ദേഹം പറയുന്നു: ഞാൻ കഅ്ബുബ്നു മാലിക്(റ) പറയുന്നത് കേട്ടു: അദ്ദേഹം തബൂക്കിലെ തന്റെ സംഭവം വിവരിച്ചു. അങ്ങനെ അമ്പതു ദിവസത്തിൽ നാൽപ്പത് ദിവസം കഴിഞ്ഞപ്പോൾ റസൂൽ(സ)യുടെ ദൂതൻ വന്നുകൊണ്ട് പറഞ്ഞു: റസൂൽ(സ) നിങ്ങളോട് നിങ്ങളുടെ ഭാര്യയെ വേർപിരിഞ്ഞ് നിൽക്കാൻ കൽപ്പിക്കുന്നു. ഞാൻ ചോദിച്ചു: അവളെ ഞാൻ ത്വലാഖ് ചൊല്ലണോ, അല്ലെങ്കിൽ ഞാൻ എന്താണ് ചെയ്യേണ്ടത്. ദൂതൻ പറഞ്ഞു: അല്ല. നിങ്ങളവളിൽ നിന്ന് അകന്ന് നിൽക്കുക. നിങ്ങളൊരിക്കലും അവളോടടുക്കരുത്. അപ്പോൾ ഞാനെന്റെ ഭാര്യയോട് പറഞ്ഞു: നീ നിന്റെ കുടുംബത്തിലേക്ക് പോകുക. ഈ കാര്യത്തിൽ അല്ലാഹു വിധിക്കുന്നത് വരെ നീ അവരുടെ കൂടെ നിൽക്കുക. (ബു,മു,ദ,തു,ന)', 'عَبْدِ اللهِ بْنِ كَعْبِ بْنِ مَالِكٍ', 'അബ്ദുല്ലാഹിബ്നു കഅ്ബുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 159, 159, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: أَنَا بِنْتُ آلِ خَالِدٍ، وَإِنَّ زَوْجِي فُلَانًا، أَرْسَلَ إِلَيَّ بِطَلَاقِي، وَإِنِّي سَأَلْتُ أَهْلَهُ النَّفَقَةَ وَالسُّكْنَى فَأَبَوْا عَلَيَّ. قَالُوا: يَا رَسُولَ اللهِ، إِنَّهُ قَدْ أَرْسَلَ إِلَيْهَا بِثَلَاثِ تَطْلِيقَاتٍ. قَالَتْ: فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا النَّفَقَةُ وَالسُّكْنَى لِلْمَرْأَةِ إِذَا كَانَ لِزَوْجِهَا عَلَيْهَا الرَّجْعَةُ". (ن)', 'ഫാത്വിമതു ബിൻത് ഖൈസ്(റ): ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: ഞാൻ ഖാലിദ് കുടുംബത്തിലെ പുത്രിയാണ്. എന്റെ ഭർത്താവ് ഇന്നാലിന്നയാളാണ്. അദ്ദേഹം എന്റെ ത്വലാഖുമായി എന്റെയുടത്തേക്ക് ആളെ അയച്ചിരിക്കുന്നു. ഞാനദ്ദേഹത്തിന്റെ കുടുംബത്തോട് താമസവും ചെലവും ചോദിച്ചു. അപ്പോൾ അവർ എനിക്ക് നൽകാൻ വിസമ്മതിച്ചു. അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവൻ അവളുടെയടുത്തേക്ക് മൂന്ന് ത്വലാഖുമായി ആളെ അയച്ചിരിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഭർത്താവിന് ഭാര്യയെ തിരിച്ചെടുക്കാൻ പറ്റുമെങ്കിലാണ് സ്ത്രീക്ക് ചെലവും, താമസവുമൊക്കെ നൽകേണ്ടത്." (ന)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമതു ബിൻത് ഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 159, 159, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمُطَلَّقَةُ ثَلَاثًا لَيْسَ لَهَا سُكْنَى وَلَا نَفَقَةٌ". (ن)', 'ഫാത്വിമതു ബിൻത് ഖൈസ്(റ): നബി(സ) പറഞ്ഞു: "മൂന്ന് ത്വലാഖും ചൊല്ലപ്പെട്ടവർക്ക് താമസമോ ചെലവോ ഇല്ല." (ന)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമതു ബിൻത് ഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 160, 160, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا: أَنَّ أَبَا عَمْرِو بْنَ حَفْصٍ الْمَخْزُومِيَّ طَلَّقَهَا ثَلَاثًا، فَانْطَلَقَ خَالِدُ بْنُ الْوَلِيدِ فِي نَفَرٍ مِنْ بَنِي مَخْزُومٍ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "يَا رَسُولَ اللهِ، إِنَّ أَبَا عَمْرِو بْنَ حَفْصٍ طَلَّقَ فَاطِمَةَ ثَلَاثًا، فَهَلْ لَهَا نَفَقَةٌ؟ فَقَالَ: "لَيْسَ لَهَا نَفَقَةٌ وَلَا سُكْنَى". (ن)', 'ഫാത്വിമതു ബിൻത് ഖൈസ്(റ): അബൂഅംറിബ്നി ഹഫ്സുൽ മഖ്സൂമി(റ) അവരെ മൂന്ന് ത്വലാഖും ചൊല്ലി. ബനൂ മഖ്സൂമിന്റെ യാത്രാ സംഘത്തിൽ ഖാലിദുബ്നു വലീദ്(റ) റസൂൽ(സ)യുടെ അടുത്ത് വന്നു. ഖാലിദ്(റ) റസൂൽ(സ)യോട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അബൂഅംറുബ്നു ഹഫ്സ് ഫാത്വിമയെ മൂന്ന് ത്വലാഖും ചൊല്ലയിരിക്കുന്നു. അവൾക്ക് വല്ലതും ചെലവിന് നൽകേണ്ടതുണ്ടോ. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവൾക്ക് ചെലവോ താമസമോ ഇല്ല." (ന)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമതു ബിൻത് ഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 160, 160, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ الْغُمَيْصَاءَ - أَوِ الرُّمَيْصَاءَ - أَتَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَشْتَكِي زَوْجَهَا أَنَّهُ لَا يَصِلُ إِلَيْهَا، فَلَمْ يَلْبَثْ أَنْ جَاءَ زَوْجُهَا فَقَالَ: يَا رَسُولَ اللهِ، هِيَ كَاذِبَةٌ، وَهُوَ يَصِلُ إِلَيْهَا، وَلَكِنَّهَا تُرِيدُ أَنْ تَرْجِعَ إِلَى زَوْجِهَا الْأَوَّلِ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ ذَلِكَ حَتَّى تَذُوقِي عُسَيْلَتَهُ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): ഗുമൈസാഅ് - അല്ലെങ്കിൽ റുമൈസാഅ് - (റ) നബി(സ)യുടെ അടുത്ത് വന്ന് തന്റെ ഭർത്താവ് തന്നോട് ബന്ധം പുലർത്തുന്നില്ലെന്ന് വേവലാതി പറഞ്ഞു. താമസിയാതെ അവളുടെ ഭർത്താവ് വന്നു. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവൾ കളവ് പറയുകയാണ്. അദ്ദേഹം അവളോട് ബന്ധം പുലർത്തുന്നുണ്ട്. പക്ഷേ, അവൾ തന്റെ ആദ്യ ഭർത്താവിലേക്ക് മടങ്ങാൻ ആഗ്രഹിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവന്റെ മധു നീ രുചിക്കുന്നത് വരെ ഇത് പാടില്ല." (ന)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 160, 160, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: فِي الرَّجُلِ تَكُونُ لَهُ الْمَرْأَةُ يُطَلِّقُهَا، ثُمَّ يَتَزَوَّجُهَا رَجُلٌ آخَرُ فَيُطَلِّقُهَا قَبْلَ أَنْ يَدْخُلَ بِهَا، فَتَرْجِعَ إِلَى زَوْجِهَا الْأَوَّلِ؟ قَالَ: "لَا، حَتَّى تَذُوقَ الْعُسَيْلَةَ". وَفِي رِوَايَةٍ قَالَ: سُئِلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الرَّجُلِ: يُطَلِّقُ امْرَأَتَهُ ثَلَاثًا، فَيَتَزَوَّجُهَا الرَّجُلُ فَيُغْلِقُ الْبَابَ وَيُرْخِي السِّتْرَ، ثُمَّ يُطَلِّقُهَا قَبْلَ أَنْ يَدْخُلَ بِهَا؟ قَالَ: "لَا تَحِلُّ لِلْأَوَّلِ حَتَّى يُجَامِعَهَا الْآخَرُ". (ن)', 'ഇബ്നുഉമർ(റ): ഒരു സ്ത്രീയെ ഒരാൾ വിവാഹമോചനം നടത്തുകയും പിന്നീട് അവളെ വേറൊരാൾ വിവാഹം കഴിക്കുകയും അവളുമായി ബന്ധപ്പെടുന്നതിന് മുമ്പ് അദ്ദേഹം അവളെ വിവാഹമോചനം നടത്തുകയും ചെയ്താൽ അവൾക്ക് ആദ്യ ഭർത്താവിലേക്ക് മടങ്ങാൻ പറ്റുമോ എന്നതിനെക്കുറിച്ച് റസൂൽ(സ) പറയുന്നു: "ഇല്ല, അവൾ തേൻതുള്ളി രുചിക്കുന്നത് വരെ." മറ്റൊരു നിവേദനം: ഇബ്നുഉമർ(റ) പറയുന്നു: ഒരാൾ തന്റെ ഭാര്യയുടെ മൂന്ന് ത്വലാഖ് ചൊല്ലുകയും പിന്നെ അവളെ വേറൊരാൾ വിവാഹം കഴിക്കുകയും വാതിലടക്കുകയും വിരി താഴ്ത്തുകയും, പിന്നീട് ബന്ധപ്പെടുന്നതിന് മുമ്പ് അവളെ വിവാഹമോചനം നടത്തുകയും ചെയ്യുന്നതിനെക്കുറിച്ച് ചോദിച്ചപ്പോൾ അവിടന്ന് പറഞ്ഞു: "രണ്ടാമത്തെ ഭർത്താവ് ബന്ധപ്പെടുന്നത് വരെ ആദ്യ ഭർത്താവിന് അവൾ ഹലാലാകില്ല." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 160, 160, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=40), 1, 'وَفِي رِوَايَةٍ قَالَ: سُئِلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الرَّجُلِ: يُطَلِّقُ امْرَأَتَهُ ثَلَاثًا، فَيَتَزَوَّجُهَا الرَّجُلُ فَيُغْلِقُ الْبَابَ وَيُرْخِي السِّتْرَ، ثُمَّ يُطَلِّقُهَا قَبْلَ أَنْ يَدْخُلَ بِهَا؟ قَالَ: "لَا تَحِلُّ لِلْأَوَّلِ حَتَّى يُجَامِعَهَا الْآخَرُ". (ن)', 'മറ്റൊരു നിവേദനം: ഇബ്നുഉമർ(റ) പറയുന്നു: ഒരാൾ തന്റെ ഭാര്യയുടെ മൂന്ന് ത്വലാഖ് ചൊല്ലുകയും പിന്നെ അവളെ വേറൊരാൾ വിവാഹം കഴിക്കുകയും വാതിലടക്കുകയും വിരി താഴ്ത്തുകയും, പിന്നീട് ബന്ധപ്പെടുന്നതിന് മുമ്പ് അവളെ വിവാഹമോചനം നടത്തുകയും ചെയ്യുന്നതിനെക്കുറിച്ച് ചോദിച്ചപ്പോൾ അവിടന്ന് പറഞ്ഞു: "രണ്ടാമത്തെ ഭർത്താവ് ബന്ധപ്പെടുന്നത് വരെ ആദ്യ ഭർത്താവിന് അവൾ ഹലാലാകില്ല." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَعَنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْوَاشِمَةَ وَالْمُوتَشِمَةَ، وَالْوَاصِلَةَ وَالْمَوْصُولَةَ، وَآكِلَ الرِّبَا وَمُوكِلَهُ، وَالْمُحَلِّلَ وَالْمُحَلَّلَ لَهُ. (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): കൊത്തിവെക്കുന്നവനെയും കൊത്തിവെച്ച് കൊടുക്കുന്നവനെയും കൃത്രിമ മുടി വെക്കുന്നവനെയും കൃത്രിമ മുടി വെച്ചുകൊടുക്കുന്നവനെയും, പലിശ ഭക്ഷിക്കുന്നവനെയും, അത് ഭക്ഷിപ്പിക്കുന്നവനെയും, ഭാര്യയുടെ മൂന്ന് ത്വലാഖ് ചൊല്ലിയവന് അവളെ അനുവദനീയമാക്കിക്കൊടുക്കുന്നവനെയും, ആർക്ക് വേണ്ടിയാണോ അനുവദനീയമാക്കുന്നത് അവനെയും റസൂൽ(സ) ശപിച്ചിരിക്കുന്നു. (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 161, 161, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أُخْبِرُكُمْ بِالتَّيْسِ الْمُسْتَعَارِ". قَالُوا: بَلَى يَا رَسُولَ اللهِ. قَالَ: "هُوَ الْمُحَلِّلُ لَعَنَ اللهُ الْمُحَلِّلَ وَالْمُحَلَّلَ لَهُ". [ز: فيه راوٍ مختلف فيه] (جه)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "വാടകക്ക് കൊടുക്കപ്പെടുന്ന ആടിനെക്കുറിച്ച് നിങ്ങൾക്ക് ഞാൻ പറഞ്ഞുതരട്ടെയോ? അവർ പറഞ്ഞു: അതെ, അല്ലാഹുവിന്റെ റസൂലേ. റസൂൽ(സ) പറഞ്ഞു: "ഭാര്യയെ മൂന്ന് ത്വലാഖ് ചൊല്ലിയവന് അവളെ അനുവദനീയമാക്കിക്കൊടുക്കുന്നവനാണവൻ. അനുവദനീയമാക്കിക്കൊടുക്കുന്നവനെയും ആർക്ക് വേണ്ടിയാണോ അനുവദനീയമാക്കുന്നത് അവനെയും അല്ലാഹു ശപിച്ചിരിക്കുന്നു." (ജ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فيه راوٍ مختلف فيه', null, 161, 161, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: دَخَلَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ يَسْتَأْذِنُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَوَجَدَ النَّاسَ جُلُوسًا بِبَابِهِ، لَمْ يُؤْذَنْ لِأَحَدٍ مِنْهُمْ. قَالَ: فَأُذِنَ لِأَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ فَدَخَلَ، ثُمَّ أَقْبَلَ عُمَرُ رَضِيَ اللهُ عَنْهُ فَاسْتَأْذَنَ فَأُذِنَ لَهُ، فَوَجَدَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَالِسًا حَوْلَهُ نِسَاؤُهُ وَاجِمًا سَاكِتًا. قَالَ: فَقَالَ: لَأَقُولَنَّ شَيْئًا أُضْحِكُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ: يَا رَسُولَ اللهِ، لَوْ رَأَيْتَ بِنْتَ خَارِجَةَ سَأَلَتْنِي النَّفَقَةَ، فَقُمْتُ إِلَيْهَا فَوَجَأْتُ عُنُقَهَا. فَضَحِكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "هُنَّ حَوْلِي كَمَا تَرَى يَسْأَلْنَنِي النَّفَقَةَ". فَقَامَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ إِلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا يَجَأُ عُنُقَهَا، فَقَامَ عُمَرُ رَضِيَ اللهُ عَنْهُ إِلَى حَفْصَةَ رَضِيَ اللهُ عَنْهَا يَجَأُ عُنُقَهَا، كِلَاهُمَا يَقُولُ: تَسْأَلْنَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَا لَيْسَ عِنْدَهُ؟ فَقُلْنَ: وَاللهِ لَا نَسْأَلُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَيْئًا أَبَدًا لَيْسَ عِنْدَهُ، ثُمَّ اعْتَزَلَهُنَّ شَهْرًا أَوْ تِسْعًا وَعِشْرِينَ، ثُمَّ نَزَلَتْ عَلَيْهِ هَذِهِ الْآيَةُ: {يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ} حَتَّى بَلَغَ {لِلْمُحْسِنَاتِ مِنْكُنَّ أَجْرًا عَظِيمًا} [الأحزاب: ٢٨-٢٩]. قَالَ: فَبَدَأَ بِعَائِشَةَ رَضِيَ اللهُ عَنْهَا فَقَالَ: "يَا عَائِشَةُ، إِنِّي أُرِيدُ أَنْ أَعْرِضَ عَلَيْكِ أَمْرًا، أُحِبُّ أَنْ لَا تَعْجَلِي فِيهِ حَتَّى تَسْتَشِيرِي أَبَوَيْكِ". قَالَتْ: وَمَا هُوَ يَا رَسُولَ اللهِ؟ فَتَلَا عَلَيْهَا الْآيَةَ. قَالَتْ: أَفِيكَ يَا رَسُولَ اللهِ أَسْتَشِيرُ أَبَوَيَّ؟ بَلْ أَخْتَارُ اللهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ، وَأَسْأَلُكَ أَنْ لَا تُخْبِرَ امْرَأَةً مِنْ نِسَائِكَ بِالَّذِي قُلْتُ. قَالَ: "لَا تَسْأَلُنِي امْرَأَةٌ مِنْهُنَّ إِلَّا أَخْبَرْتُهَا، إِنَّ اللهَ لَمْ يَبْعَثْنِي مُعَنِّتًا وَلَا مُتَعَنِّتًا، وَلَكِنْ بَعَثَنِي مُعَلِّمًا مُيَسِّرًا". (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): അബൂബക്കർ(റ) നബി(സ)യുടെ അടുത്ത് പ്രവേശിക്കാൻ അനുമതി ആവശ്യപ്പെട്ടുകൊണ്ട് വന്നു. അപ്പോൾ ജനങ്ങളെല്ലാം അവിടത്തെ വാതിൽക്കൽ ഇരിക്കുന്നത് അദ്ദേഹം കണ്ടു. അവരിൽ ഒരാൾക്കും തിരുമേനി(സ)യുടെ അടുത്ത് പ്രവേശിക്കുവാൻ അനുമതി ലഭിച്ചിട്ടില്ല. നിവേദകൻ പറയുന്നു: എന്നാൽ അബൂബക്കർ(റ)വിന് അനുവാദം കിട്ടി. ഉടനെ അദ്ദേഹം പ്രവേശിക്കുകയും ചെയ്തു. പിന്നെ ഉമർ(റ) വന്ന് സമ്മതം ചോദിച്ചു. അപ്പോൾ അദ്ദേഹത്തിനും അവിടന്ന് സമ്മതം കൊടുത്തു. അങ്ങനെ അകത്ത് ചെന്നപ്പോൾ ദുഃഖാധികൃത്താൽ നിശ്ശബ്ദനായിരിക്കുന്ന നബി(സ)യെയും ചുറ്റുഭാഗത്തും അവിടുത്തെ ഭാര്യമാരെയും ഉമർ(റ) കണ്ടു. അന്നേരം നബി(സ)യെ ചിരിപ്പിക്കാൻ പറ്റുന്ന ഏതെങ്കിലും ഒരു കാര്യം ഞാനിപ്പോൾ പറയും എന്ന് പറഞ്ഞുകൊണ്ട് അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഖാരിജയുടെ മകൾ (ഉമർ(റ)വിന്റെ ഭാര്യ) എന്നോട് ചെലവിന് പണം ആവശ്യപ്പെട്ടപ്പോൾ ഞാനെഴുന്നേറ്റ് അവളുടെ കരണക്കുറ്റിക്ക് ഒരു അടികൊടുത്തു. അപ്പോൾ നബി(സ) ചിരിക്കുകയും "നീ കാണുന്നില്ലേ? അപ്രകാരം ഇവരും എന്റെ ചുറ്റുഭാഗത്തും വന്നിരുന്ന് എന്നോട് ചെലവിന് ചോദിക്കുകയാണ്" എന്ന് പറയുകയും ചെയ്തു. ഉടനെ നിങ്ങൾ നബി(സ)യുടെ അടുത്ത് ഇല്ലാത്തത് അവിടത്തോട് ആവശ്യപ്പെടുകയാണോ? എന്ന് ചോദിച്ചു കൊണ്ട് അബൂബക്കർ(റ) ആഇശ(റ)യുടെ കരണക്കുറ്റിക്ക് അടിക്കുവാനും ഉമർ(റ) ഹഫ്സ(റ)യുടെ കരണക്കുറ്റിക്ക് അടിക്കുവാനുമായി അവരുടെ അടുക്കലേക്ക് എഴുന്നേറ്റ് ചെന്നു. അപ്പോൾ അല്ലാഹുവാണ് സത്യം, തിരുമേനി(സ)യുടെ അടുത്ത് ഇല്ലാത്തത് ഇനിയൊരിക്കലും അവടിത്തോട് ചോദിക്കുകയില്ല എന്നവർ സത്യം ചെയ്തു പറഞ്ഞു. അനന്തരം തിരുമേനി(സ) ഒരു മാസം അല്ലെങ്കിൽ ഇരുപത്തി ഒമ്പത് ദിവസം അവരിൽ നിന്നും വിട്ടുനിന്ന് ജീവിച്ചു. അപ്പോൾ ''ഓ നബിയേ, അങ്ങ് അവിടത്തെ ഭാര്യമാരോട് പറയുക'' എന്നത് മുതൽ ''നിങ്ങളിലെ നന്മചെയ്യുന്നവർക്ക് അല്ലാഹു മഹനീയ പ്രതിഫലം തയ്യാർ ചെയ്ത് വെച്ചിരിക്കുന്നു.'' (അഹ്സാബ്: 28-29) എന്ന് വരെയുള്ള ഖുർആൻ സൂക്തങ്ങൾ അവിടത്തേക്ക് അവതരിച്ചു. ശേഷം അവിടന്ന് ആദ്യം ആഇശ(റ)യോട് പറഞ്ഞു: "ഓ ആഇശ, ഞാൻ നിന്റെ മുന്നിൽ ഒരു സുപ്രധാന കാര്യം അവതരിപ്പിക്കാനുദ്ദേശിക്കുന്നു. ഈ കാര്യത്തിൽ നീ നിന്റെ മാതാപിതാക്കളോട് ആലോചിച്ചതിന് ശേഷം ഉത്തരം പറയുന്നതാണ് ഞാൻ ഇഷ്ടപ്പെടുന്നത്." ആഇശ(റ) ചോദിച്ചു: അതെന്താണ്, റസൂലേ. അപ്പോൾ അവിടന്ന് ഖുർആൻ സൂക്തം ഓതിക്കേൾപ്പിച്ചു. അപ്പോൾ ആഇശ(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങയുടെ കാര്യത്തിലാണോ ഞാനെന്റെ മാതാപിതാക്കളോട് ആലോചന നടത്തുന്നത്? അതിന്റെയൊരാവശ്യവുമില്ല. ഞാനിതാ, അല്ലാഹുവിനെയും അവന്റെ ദൂതരെയും പാരത്രിക ഭവനത്തെയും തെരഞ്ഞെടുക്കുന്നു. ഞാൻ പറഞ്ഞത് അങ്ങയുടെ മറ്റു ഭാര്യമാരോട് പറയരുതെന്ന് ഞാൻ അങ്ങയോട് അപേക്ഷിക്കുന്നു. നബി(സ) പറഞ്ഞു: "അവരിൽ നിന്ന് ആര് ചോദിച്ചാലും ഞാൻ ഈ കാര്യം പറയാതിരിക്കുകയില്ല. കാരണം ആളുകളെ വിഷമമുള്ള കാര്യങ്ങൾ ചെയ്യുവാൻ നിർബന്ധിക്കുവാനും അവരെ ബുദ്ധിമുട്ടാക്കുവാനുമല്ല അല്ലാഹു എന്നെ നിയോഗിച്ചിട്ടുള്ളത്. മറിച്ച് ജനങ്ങൾക്ക് ആവശ്യമുള്ളത് പഠിപ്പിച്ച് കൊടുക്കുവാനും സൗകര്യമുണ്ടാക്കിക്കൊടുക്കുവാനുമാണ് എന്നെ അല്ലാഹു നിയോഗിച്ചിട്ടുള്ളത്." (മു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], 'الأحزاب: ٢٨-٢٩', null, 161, 162, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ مَسْرُوقٍ قَالَ: مَا أُبَالِي خَيَّرْتُ امْرَأَتِي وَاحِدَةً أَوْ مِائَةً أَوْ أَلْفًا، بَعْدَ أَنْ تَخْتَارَنِي، وَلَقَدْ سَأَلْتُ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، فَقَالَتْ: قَدْ خَيَّرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، أَفَكَانَ طَلَاقًا؟ (م)', 'മസ്റൂഖ്(റ): എന്റെ ഭാര്യ എന്റെയടുത്ത് ജീവിക്കാൻ ഇഷ്ടപ്പെട്ട് തീരുമാനിച്ച ശേഷം എന്റെ കൂടെ ജീവിക്കണമോ എന്ന് തീരുമാനിക്കുവാൻ അവൾക്ക് ഒരു പ്രാവശ്യമോ, നൂറ് പ്രാവശ്യമോ, ആയിരം പ്രാവശ്യമോ സ്വാതന്ത്ര്യം കൊടുക്കുന്നത് ഞാൻ ഒരു പരിഗണനീയമായ കാര്യമായി കാണുന്നില്ല. ഇത് സംബന്ധിച്ച് ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചപ്പോൾ, ഞങ്ങൾക്ക് തിരുമേനി(സ) അപ്രകാരം തെരഞ്ഞെടുക്കുവാനുള്ള സ്വാതന്ത്ര്യം നൽകിയിരുന്നു. അത് വിവാഹമോചനമായിരുന്നോ? എന്ന് ചോദിക്കുകയാണ് അവർ ചെയ്തത്. (മു)', 'مَسْرُوقٍ قَالَ', 'മസ്റൂഖ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 162, 162, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهُ قَالَتْ: خَيَّرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاخْتَرْنَاهُ، فَهَلْ كَانَ طَلَاقًا. وَفِي رِوَايَةٍ قَالَتْ: قَدْ خَيَّرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نِسَاءَهُ، فَلَمْ يَكُنْ طَلَاقًا. وَفِي رِوَايَةٍ: فَلَمْ يَعُدَّهَا عَلَيْنَا شَيْئًا. وَفِي رِوَايَةٍ: فَلَمْ يَعُدَّ ذَلِكَ شَيْئًا. (ق,د,ت,ن,جه)', 'ആഇശ(റ): റസൂൽ(സ) ഞങ്ങളോട് ഇഷ്ടാനുസരണം പ്രവർത്തിക്കാൻ പറഞ്ഞു. അങ്ങനെ ഞങ്ങൾ അവിടത്തെ തെരഞ്ഞെടുത്തു. അത് ത്വലാഖായിരുന്നോ. മറ്റൊരു നിവേദനം: ആഇശ(റ) പറയുന്നു: റസൂൽ(സ) അവിടത്തെ ഭാര്യമാരോട് ഇഷ്ടാനുസരണം ചെയ്തോളാൻ പറഞ്ഞു. അത് ത്വലാഖ് ആകില്ല. മറ്റൊരു നിവേദനം: അവിടന്ന് അത് ഞങ്ങളുടെ മേൽ ഒന്നും തന്നെയായി കണക്കാക്കിയിട്ടില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 162, 163, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=45), 1, 'وَفِي رِوَايَةٍ قَالَتْ: قَدْ خَيَّرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نِسَاءَهُ، فَلَمْ يَكُنْ طَلَاقًا.', 'മറ്റൊരു നിവേദനം: ആഇശ(റ) പറയുന്നു: റസൂൽ(സ) അവിടത്തെ ഭാര്യമാരോട് ഇഷ്ടാനുസരണം ചെയ്തോളാൻ പറഞ്ഞു. അത് ത്വലാഖ് ആകില്ല.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=45), 2, 'وَفِي رِوَايَةٍ: فَلَمْ يَعُدَّهَا عَلَيْنَا شَيْئًا.', 'മറ്റൊരു നിവേദനം: അവിടന്ന് അത് ഞങ്ങളുടെ മേൽ ഒന്നും തന്നെയായി കണക്കാക്കിയിട്ടില്ല. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=45), 3, 'وَفِي رِوَايَةٍ: فَلَمْ يَعُدَّ ذَلِكَ شَيْئًا. (ق,د,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهُ قَالَتْ: لَمَّا أُمِرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِتَخْيِيرِ أَزْوَاجِهِ بَدَأَ بِي فَقَالَ: "إِنِّي ذَاكِرٌ لَكِ أَمْرًا، فَلَا عَلَيْكِ أَنْ لَا تُعَجِّلِي حَتَّى تَسْتَأْمِرِي أَبَوَيْكِ". قَالَتْ: قَدْ عَلِمَ أَنَّ أَبَوَايَ لَمْ يَكُونَا لِيَأْمُرَانِي بِفِرَاقِهِ، قَالَتْ: ثُمَّ تَلَا هَذِهِ الْآيَةَ: {يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ إِنْ كُنْتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا} إِلَى قَوْلِهِ: {جَمِيلًا}. فَقُلْتُ: أَفِي هَذَا أَسْتَأْمِرُ أَبَوَيَّ، فَإِنِّي أُرِيدُ اللهَ عَزَّ وَجَلَّ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ. قَالَتْ عَائِشَةُ: ثُمَّ فَعَلَ أَزْوَاجُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِثْلَ مَا فَعَلْتُ، وَلَمْ يَكُنْ ذَلِكَ حِينَ قَالَ لَهُنَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَاخْتَرْنَهُ طَلَاقًا، مِنْ أَجْلِ أَنَّهُنَّ اخْتَرْنَهُ. (ن)', 'ആഇശ(റ): ഭാര്യമാർക്ക് ഇഷ്ടാനുസൃതം ചെയ്യാൻ അവസരം നൽകുക എന്ന് റസൂൽ(സ)യോട് കൽപിക്കപ്പെട്ടപ്പോൾ എന്നിൽ നിന്നാണ് തുടങ്ങിയത്. അവിടന്ന് പറഞ്ഞു: "ഞാൻ നിന്നോടൊരു കാര്യം പറയുന്നുണ്ട്. നിന്റെ മാതാപിതാക്കളോട് തീരുമാനമാരായുന്നത് വരെ നീ ധൃതിപിടിക്കരുത്." ആഇശ(റ) പറയുന്നു: എന്റെ മാതാപിതാക്കൾ നബി(സ)യോട് വേർപിരിയാൻ എന്നോട് കൽപിക്കില്ലെന്ന് അവിടത്തേക്ക് അറിയാം. പിന്നെ അവിടന്ന് ഈ സൂക്തം ഓതിക്കേൾപ്പിച്ചു. ''പ്രവാചകരേ, അങ്ങ് അവിടത്തെ ഭാര്യമാരോട് പറയുക, നിങ്ങൾ ഭൗതിക ജീവിതം ആഗ്രഹിക്കുന്നുവെങ്കിൽ'' എന്നത് മുതൽ ''ഭംഗിയായി'' എന്നതുവരെ. അപ്പോൾ ഞാൻ ചോദിച്ചു: ഈ വിഷയത്തിലാണോ, എന്റെ മാതാപിതാക്കളോട് ഞാൻ തീരുമാനമാരായേണ്ടത്. ഞാൻ അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും പരലോകത്തെയുമാണ് ആഗ്രഹിക്കുന്നത്. ആഇശ(റ) പറയുന്നു: പിന്നെ പ്രവാചക പത്നിമാരെല്ലാം ഞാൻ ചെയ്തത് പോലെ ചെയ്തു. നബി(സ) അവരോട് ഇഷ്ടാനുസരണം ചെയ്യാൻ പറയുകയും, അപ്പോൾ അവർ നബി(സ)യെ തെരഞ്ഞെടുക്കുകയും ചെയ്തു. അവർ നബി(സ)യെ തെരഞ്ഞെടുത്തത് കാരണം അത് ത്വലാഖാകുന്നില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 163, 163, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّ بَرِيرَةَ أُعْتِقَتْ وَهِيَ عِنْدَ مُغِيثٍ – عَبْدٍ لِآلِ أَبِي أَحْمَدَ – فَخَيَّرَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَالَ لَهَا: "إِنْ قَرِبَكِ فَلَا خِيَارَ لَكِ". (د)', 'ആഇശ(റ): ബരീറ(റ), അബൂഅഹ്മദ് കുടുംബത്തിന്റെ അടിമയായ മുഗീസിന്റെ ഭാര്യയായിരിക്കെ മോചിപ്പിക്കപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) അവരോട് ഇഷ്ടാനുസരണം പ്രവർത്തിക്കാൻ പറഞ്ഞു. അവിടന്ന് അവളോട് പറഞ്ഞു: "അവൻ നീയുമായി ബന്ധപ്പെട്ടിട്ടുണ്ടെങ്കിൽ നിനക്ക് ഇഷ്ടാനുസരണം പ്രവർത്തിക്കാൻ പറ്റില്ല." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 163, 163, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا أَرَادَتْ أَنْ تَعْتِقَ مَمْلُوكَيْنِ لَهَا، زَوْجٌ، قَالَ: فَسَأَلَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ، فَأَمَرَهَا أَنْ تَبْدَأَ بِالرَّجُلِ قَبْلَ الْمَرْأَةِ. (د,ن,جه)', 'ആഇശ(റ): അവർ അവരുടെ രണ്ട് അടിമകളെ മോചിപ്പിക്കാൻ ഉദ്ദേശിച്ചു. അപ്പോൾ അവർ നബി(സ)യോട് അതേക്കുറിച്ച് ചോദിച്ചു. തിരുമേനി(സ) സ്ത്രീക്കുമുമ്പ് പുരുഷനിൽ നിന്ന് തുടങ്ങാൻ അവരോട് കൽപിച്ചു. (ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 163, 164, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنِ الْقَاسِمِ بْنِ مُحَمَّدٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ لِعَائِشَةَ رَضِيَ اللهُ عَنْهَا غُلَامٌ وَجَارِيَةٌ، قَالَتْ: فَأَرَدْتُ أَنْ أُعْتِقَهُمَا، فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "ابْدَئِي بِالْغُلَامِ قَبْلَ الْجَارِيَةِ". (ن)', 'ഖാസിമുബ്നു മുഹമ്മദ്(റ): ആഇശ(റ)ക്ക് ഒരു അടിമയും, ഒരു അടിമസ്ത്രീയുമുണ്ടായിരുന്നു. ആഇശ(റ) പറയുന്നു. ഞാനവരെ മോചിപ്പിക്കാനുദ്ദേശിച്ചു. ഞാനത് റസൂൽ(സ)യോട് പറഞ്ഞു: അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അടിമസ്ത്രീക്ക് മുമ്പ്, നീ അടിമയിൽ നിന്ന് തുടങ്ങുക." (ന)', 'الْقَاسِمِ بْنِ مُحَمَّدٍ', 'ഖാസിമുബ്നു മുഹമ്മദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 164, 164, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ حَمَّادِ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ لِأَيُّوبَ: هَلْ عَلِمْتَ أَحَدًا قَالَ – فِي: أَمْرُكِ بِيَدِكِ – إِنَّهَا ثَلَاثٌ، إِلَّا الْحَسَنَ؟ فَقَالَ: لَا، إِلَّا الْحَسَنَ. ثُمَّ قَالَ: اللَّهُمَّ غَفْرًا، إِلَّا مَا حَدَّثَنِي قَتَادَةُ عَنْ كَثِيرٍ مَوْلَى ابْنِ سَمُرَةَ، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ثَلَاثٌ". قَالَ أَيُّوبُ: فَلَقِيتُ كَثِيرًا مَوْلَى بَنِي سَمُرَةَ، فَسَأَلْتُهُ فَلَمْ يَعْرِفْهُ، فَرَجَعْتُ إِلَى قَتَادَةَ فَأَخْبَرْتُهُ فَقَالَ: نَسِيَ. (د,ت,ن)', 'ഹമ്മാദുബ്നു സൈദ്(റ): ഞാൻ അയ്യൂബ്(റ)വിനോട് ചോദിച്ചു: നിന്റെ തീരുമാനം നിന്റെ കയ്യിലാണ്, എന്ന വിഷയത്തിൽ അത് മൂന്ന് ത്വലാഖായി പരിഗണിക്കണമെന്ന്, ഹസൻ(റ)വിന് പുറമെ ആരെങ്കിലും പറഞ്ഞതായി താങ്കളറിഞ്ഞിട്ടുണ്ടോ? അയ്യൂബ്(റ) പറഞ്ഞു: ഹസൻ(റ) ഒഴികെ ആരെയുമറിയില്ല. പിന്നെ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവേ പൊറുക്കണേ. നബി(സ)യിൽ നിന്ന് അബൂഹുറൈറ(റ)വും അദ്ദേഹത്തിൽ നിന്ന് അബൂസലമ(റ)വും അദ്ദേഹത്തിൽ നിന്ന് ഇബ്നുസമുറയുടെ അടിമയായ കസീർ(റ)വും അദ്ദേഹത്തിൽ നിന്ന് ഖതാദ(റ)വും എനിക്ക് പറഞ്ഞുതന്നിട്ടുണ്ട്: "അത് മൂന്ന് ത്വലാഖായി ഗണിക്കും." അയ്യൂബ്(റ) പറഞ്ഞു: ഞാൻ ഇബ്നുസമുറ(റ)യുടെ അടിമയായ കസീർ(റ)വിനെ കണ്ടു. അദ്ദേഹത്തോട് ഞാൻ ചോദിച്ചു. അപ്പോൾ അദ്ദേഹത്തിനതറിയില്ല. അങ്ങനെ ഞാൻ ഖതാദ(റ)വിന്റെ അടുത്ത് ചെന്നു. അദ്ദേഹത്തോട് ഞാൻ വിവരം പറഞ്ഞു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: കസീർ(റ) മറന്നതാണ്. (ദ,തു,ന)', 'حَمَّادِ بْنِ زَيْدٍ', 'ഹമ്മാദുബ്നു സൈദ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 164, 164, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ عَزَّ وَجَلَّ تَجَاوَزَ لِأُمَّتِي مَا وَسْوَسَتْ بِهِ وَحَدَّثَتْ – وَفِي رِوَايَةٍ: عَمَّا حَدَّثَتْ – بِهِ أَنْفُسَهَا، مَا لَمْ تَعْمَلْ أَوْ تَتَكَلَّمْ بِهِ". (ق,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "സംസാരിക്കുകയോ പ്രവർത്തിക്കുകയോ ചെയ്യാത്ത പക്ഷം മനസ്സിൽ തോന്നുകയോ വിചാരിക്കുകയോ ചെയ്യുന്നത് അല്ലാഹു എന്റെ സമൂഹത്തിന് പൊറുത്ത് നൽകിയിരിക്കുന്നു." (ബു,മു,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 164, 164, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=51), 1, 'وَفِي رِوَايَةٍ: عَمَّا حَدَّثَتْ – بِهِ أَنْفُسَهَا، مَا لَمْ تَعْمَلْ أَوْ تَتَكَلَّمْ بِهِ". (ق,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَتْ تَحْتِي امْرَأَةٌ أُحِبُّهَا، وَكَانَ أَبِي يَكْرَهُهَا، فَأَمَرَنِي أَبِي أَنْ أُطَلِّقَهَا فَأَبَيْتُ، فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "يَا عَبْدَ اللهِ بْنَ عُمَرَ، طَلِّقِ امْرَأَتَكَ". حسن صحيح. (د,ت,جه)', 'ഇബ്നുഉമർ(റ): എനിക്ക് ഞാൻ ഇഷ്ടപ്പെടുന്ന ഒരു ഭാര്യയുണ്ടായിരുന്നു. എന്റെ പിതാവിന് അവളെ വെറുപ്പായിരുന്നു. എന്റെ പിതാവ് എന്നോട് അവളെ ത്വലാഖ് ചൊല്ലാൻ പറഞ്ഞു. ഞാൻ വഴങ്ങിയില്ല. അപ്പോൾ ഞാനത് റസൂൽ(സ)യോട് പറഞ്ഞു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ഓ, അബ്ദുല്ലാഹിബ്നു ഉമർ, നീ നിന്റെ ഭാര്യയെ ത്വലാഖ് ചൊല്ലുക." (ദ,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 164, 165, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَتْ تَحْتِي امْرَأَةٌ، وَكُنْتُ أُحِبُّهَا، وَكَانَ أَبِي يُبْغِضُهَا، فَذَكَرَ ذَلِكَ عُمَرُ رَضِيَ اللهُ عَنْهُ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَنِي أَنْ أُطَلِّقَهَا، فَطَلَّقْتُهَا. (د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): എനിക്കൊരു ഭാര്യയുണ്ടായിരുന്നു. എനിക്കവളെ ഇഷ്ടമായിരുന്നു. എന്നാൽ, എന്റെ പിതാവിന് അവളോട് ദേഷ്യമായിരുന്നു. ഉമർ(റ) ഇത് നബി(സ)യോട് പറഞ്ഞു. അപ്പോൾ അവിടന്ന് എന്നോട് അവളെ വിവാഹമോചനം ചെയ്യാൻ പറഞ്ഞു. അങ്ങനെ ഞാനവളെ വിവാഹമോചനം ചെയ്തു. (ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 165, 165, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللهِ بْنِ حَبِيبٍ السُّلَمِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا أَمَرَهُ أَبُوهُ – أَوْ أُمُّهُ – أَنْ يُطَلِّقَ امْرَأَتَهُ، فَجَعَلَ عَلَيْهِ مِائَةَ مُحَرَّرٍ. فَأَتَى أَبَا الدَّرْدَاءِ، فَإِذَا هُوَ يُصَلِّي الضُّحَى وَيُطِيلُهَا، وَصَلَّى مَا بَيْنَ الظُّهْرِ وَالْعَصْرِ. فَسَأَلَهُ، فَقَالَ أَبُو الدَّرْدَاءِ: أَوْفِ بِنَذْرِكَ، وَبِرَّ وَالِدَيْكَ. وَقَالَ أَبُو الدَّرْدَاءِ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْوَالِدُ أَوْسَطُ أَبْوَابِ الْجَنَّةِ، فَحَافِظْ عَلَى وَالِدَيْكَ، أَوِ اتْرُكْ". (ت,جه)', 'അബൂഅബ്ദിർറഹ്മാൻ അബ്ദുല്ലാഹിബ്നു ഹബീബുസ്സലമി(റ): ഒരാളോട് തന്റെ പിതാവ് - അല്ലെങ്കിൽ മാതാവ് - അയാളുടെ ഭാര്യയെ വിവാഹമോചനം ചെയ്യാൻ പറഞ്ഞു. അപ്പോൾ അദ്ദേഹം നൂറടിമയെ മോചിപ്പിക്കാൻ തീർച്ചപ്പെടുത്തി. അങ്ങനെ അദ്ദേഹം അബുദ്ദർദാഅ്(റ)വിന്റെ അടുത്ത് ചെന്നു. അപ്പോൾ അദ്ദേഹം ളുഹാ ദീർഘിപ്പിച്ച് നിസ്കരിക്കുകയാണ്. അദ്ദേഹം ളുഹ്റിന്റെയും അസറിന്റെയും ഇടയിലുള്ള സമയവും നിസ്കരിച്ചു. അദ്ദേഹത്തോട് വിഷയം ചോദിച്ചു. അപ്പോൾ അബുദ്ദർദാഅ്(റ) പറഞ്ഞു: നിന്റെ നേർച്ച പൂർത്തിയാക്കുക, മാതാപിതാക്കളെ അനുസരിക്കുകയും ചെയ്യുക. അബുദ്ദർദാഅ്(റ) പറഞ്ഞു: ഞാൻ റസൂൽ(സ) പറയുന്നത് കേട്ടിട്ടുണ്ട്: "സ്വർഗ്ഗക്കവാടങ്ങളിൽ ഏറ്റവും ഉത്തമമായത് മാതാപിതാക്കളാണ്." അത്കൊണ്ട് നിന്റെ മാതാപിതാക്കളെ സംരക്ഷിക്കുകയോ ഉപേക്ഷിക്കുകയോ ചെയ്യുക." (തു,ജ)', 'أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللهِ بْنِ حَبِيبٍ السُّلَمِيِّ', 'അബൂഅബ്ദിർറഹ്മാൻ അബ്ദുല്ലാഹിബ്നു ഹബീബുസ്സലമി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 165, 165, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ رُكَانَةَ بْنِ عَبْدِ يَزِيدَ رَضِيَ اللهُ عَنْهُ: طَلَّقَ امْرَأَتَهُ سُهَيْمَةَ الْبَتَّةَ، فَأَخْبَرَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِذَلِكَ، وَقَالَ: وَاللهِ مَا أَرَدْتُ إِلَّا وَاحِدَةً. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَاللهِ مَا أَرَدْتَ إِلَّا وَاحِدَةً". فَقَالَ رُكَانَةُ: وَاللهِ مَا أَرَدْتُ إِلَّا وَاحِدَةً، فَرَدَّهَا إِلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَطَلَّقَهَا الثَّانِيَةَ فِي زَمَانِ عُمَرَ رَضِيَ اللهُ عَنْهُ وَالثَّالِثَةَ فِي زَمَانِ عُثْمَانَ رَضِيَ اللهُ عَنْهُ. وَفِي رِوَايَةٍ: أَنَّهُ طَلَّقَ امْرَأَتَهُ الْبَتَّةَ، فَأَتَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "مَا أَرَدْتَ". قَالَ: وَاحِدَةً. قَالَ: "آللَّهِ". قَالَ: آللهِ. قَالَ: "هُوَ عَلَى مَا أَرَدْتَ". (د,ت,جه)', 'റുകാനതുബ്നു അബ്ദി യസീദ്(റ): അദ്ദേഹം തന്റെ ഭാര്യ സുഹൈമ(റ)യെ സമ്പൂർണ്ണ വിവാഹമോചനം നടത്തി. അദ്ദേഹം ഈ വിവരം നബി(സ)യോട് പറഞ്ഞു. റുകാന(റ) പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, ഞാനൊരു ത്വലാഖ് മാത്രമേ ഉദ്ദേശിച്ചിട്ടുള്ളു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "അല്ലാഹുവാണ് സത്യം, നീയൊരു ത്വലാഖ് മാത്രമാണോ ഉദ്ദേശിച്ചത്." അപ്പോൾ റുകാന(റ) പറഞ്ഞു. അല്ലാഹുവാണ് സത്യം. ഞാനൊന്ന് മാത്രമേ ഉദ്ദേശിച്ചിട്ടുള്ളു. അപ്പോൾ റസൂൽ(സ) ഭാര്യയെ അദ്ദേഹത്തിന് തിരിച്ചു നൽകി. ഉമർ(റ)വിന്റെ കാലത്ത് റുകാന(റ) തന്റെ ഭാര്യയെ രണ്ടാം വിവാഹമോചനവും, ഉസ്മാൻ(റ)വിന്റെ കാലത്ത് മൂന്നാം വിവാഹമോചനവും ചെയ്തു. മറ്റൊരു നിവേദനം: റുകാന(റ) തന്റെ ഭാര്യയെ സമ്പൂർണ്ണ വിവാഹമോചനം നടത്തി. അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് ചെന്നു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "നീ എന്താണ് ഉദ്ദേശിച്ചത്?" റുകാന(റ) പറഞ്ഞു: ഒന്നേ ഉദ്ദേശിച്ചിട്ടുള്ളൂ. റസൂൽ(സ) ചോദിച്ചു: "അല്ലാഹു തന്നെ സത്യം?" അദ്ദേഹം പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം. നബി(സ) പറഞ്ഞു: "അത് നീ ഉദ്ദേശിച്ചത് പോലെയാണ്." (ദ,തു,ജ)', 'رُكَانَةَ بْنِ عَبْدِ يَزِيدَ', 'റുകാനതുബ്നു അബ്ദി യസീദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 165, 165, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=55), 1, 'وَفِي رِوَايَةٍ: أَنَّهُ طَلَّقَ امْرَأَتَهُ الْبَتَّةَ، فَأَتَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "مَا أَرَدْتَ". قَالَ: وَاحِدَةً. قَالَ: "آللَّهِ". قَالَ: آللهِ. قَالَ: "هُوَ عَلَى مَا أَرَدْتَ". (د,ت,جه)', 'മറ്റൊരു നിവേദനം: റുകാന(റ) തന്റെ ഭാര്യയെ സമ്പൂർണ്ണ വിവാഹമോചനം നടത്തി. അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് ചെന്നു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "നീ എന്താണ് ഉദ്ദേശിച്ചത്?" റുകാന(റ) പറഞ്ഞു: ഒന്നേ ഉദ്ദേശിച്ചിട്ടുള്ളൂ. റസൂൽ(സ) ചോദിച്ചു: "അല്ലാഹു തന്നെ സത്യം?" അദ്ദേഹം പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം. നബി(സ) പറഞ്ഞു: "അത് നീ ഉദ്ദേശിച്ചത് പോലെയാണ്." (ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا طَلَاقَ وَلَا عَتَاقَ فِي غِلَاقٍ". (د,جه)', 'ആഇശ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "കോപത്തിന്റെ സമയത്ത് വിവാഹമോചനമോ അടിമമോചനമോ പാടില്ല." (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 166, 166, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَارٌ فَارِسِيٌّ طَيِّبُ الْمَرَقَةِ، فَأَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ وَعِنْدَهُ عَائِشَةُ رَضِيَ اللهُ عَنْهَا، فَأَوْمَأَ إِلَيْهِ بِيَدِهِ: أَنْ تَعَالَ، وَأَوْمَأَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَيْ وَهَذِهِ؟ فَأَوْمَأَ إِلَيْهِ الْآخَرُ هَكَذَا بِيَدِهِ: أَنْ لَا، مَرَّتَيْنِ أَوْ ثَلَاثًا. (ن)', 'അനസ്(റ): റസൂൽ(സ)ക്ക്, നന്നായി കറി വെക്കുന്ന ഒരു പേർഷ്യക്കാരൻ അയൽവാസിയുണ്ടായിരുന്നു. അദ്ദേഹം ഒരു ദിവസം റസൂൽ(സ)യുടെ അടുത്ത് വന്നു. റസൂൽ(സ)യുടെ അടുത്ത് ആഇശ(റ) ഉണ്ട്. അദ്ദേഹം നബി(സ)യോട് വരാൻ ആംഗ്യം കാണിച്ചു. റസൂൽ(സ) ആഇശ(റ)വിലേക്ക്, ഇവളും വന്നോട്ടെ? എന്ന അർത്ഥത്തിൽ ആംഗ്യം കാണിച്ചു. അപ്പോൾ അദ്ദേഹം തന്റെ കൈകൊണ്ട് നബി(സ)ക്ക് ഇത് പോലെ രണ്ടോ മൂന്നോ പ്രാവശ്യം വേണ്ട എന്ന അർത്ഥത്തിൽ ആംഗ്യം കാണിച്ചു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 166, 166, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، يُحَدِّثُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "انْظُرُوا كَيْفَ يَصْرِفُ اللهُ عَنِّي شَتْمَ قُرَيْشٍ وَلَعْنَهُمْ، إِنَّهُمْ يَشْتِمُونَ مُذَمَّمًا وَيَلْعَنُونَ مُذَمَّمًا، وَأَنَا مُحَمَّدٌ". (خ,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖുറൈശികളുടെ ആക്ഷേപവും ശാപവും അല്ലാഹു എന്നിൽ നിന്ന് എങ്ങനെയാണ് അകറ്റുന്നത് എന്ന് നിങ്ങൾ നോക്കുക. അവർ ആക്ഷേപിക്കുന്നത് ഒരു നീചനെയാണ്, അവർ ശപിക്കുന്നതും ഒരു നീചനെയാണ്. ഞാനോ മുഹമ്മദാണ് (സ്തുതിക്കപ്പെട്ടവൻ)." (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 166, 166, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رُفِعَ الْقَلَمُ عَنْ ثَلَاثَةٍ: عَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ، وَعَنِ الصَّغِيرِ حَتَّى يَكْبَرَ، وَعَنِ الْمَجْنُونِ حَتَّى يَعْقِلَ". أَوْ: يُفِيقَ". وَفِي رِوَايَةٍ: "وَعَنِ الْمُبْتَلَى حَتَّى يَبْرَأَ". (د,ت,ن,جه)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്നാളുകളിൽ നിന്ന് പേന ഉയർത്തപ്പെട്ടിരിക്കുന്നു: ഉറങ്ങുന്നവൻ ഉണരുന്നത് വരെ, കുട്ടി വളരുന്നത് വരെ, ഭ്രാന്തന് ബുദ്ധിവെക്കുന്നത് വരെ, അല്ലെങ്കിൽ ബുദ്ധി തെളിയുന്നത് വരെ." മറ്റൊരു നിവേദനം: "രോഗി സുഖമാകുന്നത് വരെ." (ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 166, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=59), 1, 'وَفِي رِوَايَةٍ: "وَعَنِ الْمُبْتَلَى حَتَّى يَبْرَأَ". (د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: "രോഗി സുഖമാകുന്നത് വരെ." (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُلُّ طَلَاقٍ جَائِزٌ، إِلَّا طَلَاقَ الْمَعْتُوهِ الْمَغْلُوبِ عَلَى عَقْلِهِ". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ശക്തമായി ഭ്രാന്തുള്ളവന്റേതല്ലാത്ത എല്ലാ വിവാഹമോചനവും സാധുവാണ്." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 167, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللهَ وَضَعَ عَنْ أُمَّتِي الْخَطَأَ، وَالنِّسْيَانَ، وَمَا اسْتُكْرِهُوا عَلَيْهِ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു എന്റെ സമൂഹത്തിന് പിഴവും മറവിയും ബലാൽക്കാര വിധേയനായി ചെയ്യുന്നതും പൊറുത്ത് നൽകിയിരിക്കുന്നു." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 167, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ كَثِيرِ بْنِ السَّائِبِ رَضِيَ اللهُ عَنْهُ قَالَ: حَدَّثَنِي ابْنَا قُرَيْظَةَ: أَنَّهُمْ عُرِضُوا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ قُرَيْظَةَ، فَمَنْ كَانَ مُحْتَلِمًا أَوْ نَبَتَتْ عَانَتُهُ قُتِلَ، وَمَنْ لَمْ يَكُنْ مُحْتَلِمًا أَوْ لَمْ تَنْبُتْ عَانَتُهُ تُرِكَ. (ن)', 'കസീറുബ്നു സാഇബ്(റ): ബനൂഖുറൈളയുടെ രണ്ട് പുത്രന്മാർ എന്നോട് പറഞ്ഞു: ഖുറൈളാ ദിനത്തിൽ അവരെ റസൂൽ(സ)യുടെ മുന്നിൽ കൊണ്ടുവന്നു. പ്രായപൂർത്തിയായവരും ഗുഹ്യരോമം മുളച്ചവരും വധിക്കപ്പെട്ടു, പ്രായപൂർത്തിയാകാത്തവരെയും, ഗുഹ്യരോമം മുളക്കാത്തവരെയും വെറുതെ വിട്ടു. (ന)', 'كَثِيرِ بْنِ السَّائِبِ', 'കസീറുബ്നു സാഇബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 167, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ عَطِيَّةَ الْقُرَظِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ يَوْمَ حُكْمِ سَعْدٍ فِي بَنِي قُرَيْظَةَ غُلَامًا، فَشَكُّوا فِيَّ فَلَمْ يَجِدُونِي أَنْبَتُّ، فَاسْتُبْقِيتُ، فَهَا أَنَا ذَا بَيْنَ أَظْهُرِكُمْ. (ن)', 'അതിയ്യതുൽ ഖുറളി(റ): ബനൂഖുറൈദയിൽ സഅ്ദ്(റ) വിധി നടപ്പാക്കിയ ദിവസം ഞാനൊരു കുട്ടിയായിരുന്നു. എന്നിൽ അവർക്ക് സംശയം തോന്നി. എന്റെ ഗുഹ്യരോമം മുളച്ചതായി അവർ കണ്ടില്ല. അങ്ങനെ ഞാൻ ശേഷിച്ചു. ഇപ്പോൾ ഞാനിതാ നിങ്ങൾക്ക് മുന്നിൽ. (ന)', 'عَطِيَّةَ الْقُرَظِيِّ', 'അതിയ്യതുൽ ഖുറളി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 167, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَرَضَهُ يَوْمَ أُحُدٍ وَهُوَ ابْنُ أَرْبَعَ عَشْرَةَ سَنَةً فَلَمْ يُجِزْهُ، وَعَرَضَهُ يَوْمَ الْخَنْدَقِ وَهُوَ ابْنُ خَمْسَ عَشْرَةَ سَنَةً، فَأَجَازَهُ. (ن)', 'ഇബ്നുഉമർ(റ): ഉഹ്ദ് ദിനത്തിൽ, ഇബ്നുഉമർ(റ)വിന് പതിനാല് വയസ്സുള്ളപ്പോൾ അദ്ദേഹത്തെ റസൂൽ(സ) ഹാജറാക്കി. അവിടന്ന് ഇബ്നുഉമർ(റ)വിന് യുദ്ധം ചെയ്യാൻ അനുമതി നൽകിയില്ല. ഖൻദഖ് ദിനത്തിൽ, ഇബ്നുഉമർ(റ)വിന് പതിനഞ്ച് വയസ്സുള്ളപ്പോൾ അദ്ദേഹത്തെ റസൂൽ(സ) വീണ്ടും ഹാജറാക്കി. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തിന് അനുമതി നൽകി. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 167, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ مُغِيثًا كَانَ عَبْدًا، فَقَالَ: يَا رَسُولَ اللهِ، اشْفَعْ لِي إِلَيْهَا، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا بَرِيرَةُ، اتَّقِي اللهَ، فَإِنَّهُ زَوْجُكِ وَأَبُو وَلَدِكِ". فَقَالَتْ: يَا رَسُولَ اللهِ، أَتَأْمُرُنِي بِذَلِكَ؟ قَالَ: "لَا، إِنَّمَا أَنَا شَافِعٌ". فَكَأَنَّ دُمُوعَهُ تَسِيلُ عَلَى خَدِّهِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلْعَبَّاسِ: "أَلَا تَعْجَبُ مِنْ حُبِّ مُغِيثٍ بَرِيرَةَ وَبُغْضِهَا إِيَّاهُ". (خ,د)', 'ഇബ്നുഅബ്ബാസ്(റ): മുഗീസ്(റ) ഒരു അടിമയായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് എനിക്ക് വേണ്ടി അവളോട് ശുപാർശ ചെയ്താലും. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഓ ബരീറ, നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുക. മുഗീസ് നിന്റെ ഭർത്താവും, നിന്റെ മകന്റെ പിതാവുമാണ്." അപ്പോൾ ബരീറ(റ) ചോദിച്ചു: "അല്ലാഹുവിന്റെ റസൂലേ, അവിടുന്ന് ഇക്കാര്യം എന്നോട് കൽപ്പിക്കുകയാണോ? തിരുമേനി(സ) പറഞ്ഞു: "അല്ല, ഞാൻ ശുപാർശ ചെയ്യുന്നേയുള്ളൂ." മുഗീസ്(റ)വിന്റെ കണ്ണുനീർ അദ്ദേഹത്തിന്റെ കവിളിലൂടെ ഒഴുകുന്നത് പോലെയുണ്ട്. അപ്പോൾ റസൂൽ(സ) അബ്ബാസ്(റ)വിനോട് പറഞ്ഞു: "മുഗീസിന് ബരീറയോടുള്ള സ്നേഹവും അവൾക്ക് അദ്ദേഹത്തോടുള്ള വെറുപ്പും കണ്ട് നിനക്കത്ഭുതം തോന്നുന്നില്ലേ." (ബു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 167, 168, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ زَوْجَ بَرِيرَةَ كَانَ عَبْدًا أَسْوَدَ يُسَمَّى مُغِيثًا، فَخَيَّرَهَا - يَعْنِي النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - وَأَمَرَهَا أَنْ تَعْتَدَّ. (د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ബരീറ(റ)യുടെ ഭർത്താവ് മുഗീസ്(റ) എന്ന് പേരുള്ള കറുത്ത ഒരു അടിമയാണ്. ബരീറ(റ)യോട് റസൂൽ(സ) ഇഷ്ടാനുസരണം പ്രവർത്തിക്കാൻ പറഞ്ഞു: അവരോട് ഇദ്ദ ഇരിക്കാനും നബി(സ) കൽപ്പിച്ചു. (ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 168, 168, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا فِي قِصَّةِ بَرِيرَةَ قَالَتْ: كَانَ زَوْجُهَا عَبْدًا، فَخَيَّرَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَاخْتَارَتْ نَفْسَهَا، وَلَوْ كَانَ حُرًّا لَمْ يُخَيِّرْهَا. (م,د,ت,ن)', 'ആഇശ(റ): ബരീറ(റ)യുടെ സംഭവത്തെക്കുറിച്ച് മഹതി പറയുന്നു: അവരുടെ ഭർത്താവ് അടിമയായിരുന്നു. അവർക്ക് റസൂൽ(സ) ഇഷ്ടാനുസൃതം പ്രവർത്തിക്കാൻ അവസരം കൊടുത്തു. അവൾ സ്വന്തത്തെ തെരഞ്ഞെടുത്തു. അദ്ദേഹം സ്വതന്ത്രനായിരുന്നുവെങ്കിൽ റസൂൽ(സ) അവൾക്ക് ഇഷ്ടാനുസരണം പ്രവർത്തിക്കാൻ അനുമതി നൽകുമായിരുന്നില്ല. (മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 168, 168, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ زَوْجَ بَرِيرَةَ كَانَ حُرًّا حِينَ أُعْتِقَتْ، وَأَنَّهَا خُيِّرَتْ، فَقَالَتْ: مَا أُحِبُّ أَنْ أَكُونَ مَعَهُ وَأَنَّ لِي كَذَا وَكَذَا. (خ,د,ت,ن,جه)', 'ആഇശ(റ): ബരീറ(റ) സ്വതന്ത്രയാക്കപ്പെട്ടപ്പോൾ അവളുടെ ഭർത്താവ് സ്വതന്ത്രനായിരുന്നു. ബരീറ(റ)ക്ക് ഇഷ്ടാനുസൃതം പ്രവർത്തിക്കാൻ അനുമതി നൽകപ്പെട്ടു. ബരീറ(റ) പറഞ്ഞു: അദ്ദേഹത്തിന്റെ കൂടെയാവാൻ എനിക്കിഷ്ടമില്ല. എനിക്ക് ഇന്നതുമിന്നതുമൊക്കെ ഉണ്ട്. (ബു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 168, 168, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَبِي تَمِيمَةَ الْهُجَيْمِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا قَالَ لِامْرَأَتِهِ: يَا أُخَيَّةُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أُخْتُكِ هِيَ". فَكَرِهَ ذَلِكَ وَنَهَى عَنْهُ. وفي رواية: عَنْ أَبِي تَمِيمَةَ، عَنْ رَجُلٍ مِنْ قَوْمِهِ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَمِعَ رَجُلًا يَقُولُ لِامْرَأَتِهِ: يَا أُخَيَّةُ، فَنَهَاهُ. (د)', 'അബൂതമീമതുൽ ജുഹൈമി(റ): ഒരാൾ തന്റെ ഭാര്യയെ സഹോദരി എന്ന് വിളിച്ചു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "അവൾ നിന്റെ സഹോദരിയാണോ?" അവിടന്ന് അക്കാര്യത്തെ വെറുക്കുകയും അപ്രകാരം വിളിക്കുന്നത് നിരോധിക്കുകയും ചെയ്തു. മറ്റൊരു നിവേദനം: തന്റെ കുടുംബത്തിൽ പെട്ട ഒരാളിൽ നിന്ന് അബൂതമീമ(റ) നിവേദനം ചെയ്യുന്നു: ഒരാൾ തന്റെ ഭാര്യയെ സഹോദരീ എന്ന് വിളിക്കുന്നത് തിരുമേനി(സ) കേൾക്കുകയും അവിടന്ന് അത് നിരോധിക്കുകയും ചെയ്തു. (ദ)', 'أَبِي تَمِيمَةَ الْهُجَيْمِيِّ', 'അബൂതമീമതുൽ ജുഹൈമി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 168, 168, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=69), 1, 'وَفِي رِوَايَةٍ: عَنْ أَبِي تَمِيمَةَ، عَنْ رَجُلٍ مِنْ قَوْمِهِ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَمِعَ رَجُلًا يَقُولُ لِامْرَأَتِهِ: يَا أُخَيَّةُ، فَنَهَاهُ. (د)', 'മറ്റൊരു നിവേദനം: തന്റെ കുടുംബത്തിൽ പെട്ട ഒരാളിൽ നിന്ന് അബൂതമീമ(റ) നിവേദനം ചെയ്യുന്നു: ഒരാൾ തന്റെ ഭാര്യയെ സഹോദരീ എന്ന് വിളിക്കുന്നത് തിരുമേനി(സ) കേൾക്കുകയും അവിടന്ന് അത് നിരോധിക്കുകയും ചെയ്തു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنَّ إِبْرَاهِيمَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمْ يَكْذِبْ قَطُّ إِلَّا ثَلَاثًا: ثِنْتَانِ فِي ذَاتِ اللهِ تَعَالَى: قَوْلُهُ {إِنِّي سَقِيمٌ} [الصّافات: ٨٩] وَقَوْلُهُ: {بَلْ فَعَلَهُ كَبِيرُهُمْ هَذَا} [الأنبياء: ٦٣]. وَبَيْنَمَا هُوَ يَسِيرُ فِي أَرْضِ جَبَّارٍ مِنَ الْجَبَابِرَةِ إِذْ نَزَلَ مَنْزِلًا، فَأُتِيَ الْجَبَّارُ فَقِيلَ لَهُ: إِنَّهُ نَزَلَ هَاهُنَا رَجُلٌ مَعَهُ امْرَأَةٌ هِيَ أَحْسَنُ النَّاسِ، قَالَ: فَأَرْسَلَ إِلَيْهِ فَسَأَلَهُ عَنْهَا، فَقَالَ: إِنَّهَا أُخْتِي، فَلَمَّا رَجَعَ إِلَيْهَا قَالَ: إِنَّ هَذَا سَأَلَنِي عَنْكِ فَأَنْبَأْتُهُ أَنَّكِ أُخْتِي، وَإِنَّهُ لَيْسَ الْيَوْمَ مُسْلِمٌ غَيْرِي وَغَيْرُكِ، وَإِنَّكِ أُخْتِي فِي كِتَابِ اللهِ، فَلَا تُكَذِّبِينِي عِنْدَهُ". (ق,د,ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഇബ്റാഹീം(അ) മൂന്ന് പ്രാവശ്യമല്ലാതെ നുണ പറഞ്ഞിട്ടില്ല. അതിൽ രണ്ടെണ്ണം അല്ലാഹുവിന്റെ കാര്യത്തിലാണ്. ''ഞാൻ രോഗിയാണ്'' (അസ്സ്വാഫാത്: 89) എന്ന സൂക്തത്തിലുള്ളതും ''അവരിലെ വലിയവനാണത് ചെയ്തത്'' (അമ്പിയാഅ്: 63) എന്ന സൂക്തത്തിലുള്ളതുമായ രണ്ട് സംഭവങ്ങളാണവ. മറ്റൊരു സന്ദർഭം: ഒരിക്കൽ ഇബ്റാഹീം(അ) ഒരു ക്രൂരനായ ഭരണാധികാരിയുടെ നാട്ടിലൂടെ നടന്നുപോകുമ്പോൾ ഒരു സ്ഥലത്ത് ഇറങ്ങി. അപ്പോൾ ആരോ ആ ഭരണാധികാരിയുടെ അടുത്ത് പോയി പറഞ്ഞു: ഇവിടെ ഒരു മനുഷ്യൻ വന്നിരിക്കുന്നു. അദ്ദേഹത്തോടൊപ്പം അതിസുന്ദരിയായ ഒരു സ്ത്രീയുമുണ്ട്. അപ്പോൾ ആ ഭരണാധികാരി ഇബ്റാഹീം(അ)ന്റെ അടുത്തേക്ക് ആളെ അയക്കുകയും ആ സ്ത്രീയെക്കുറിച്ച് ചോദിക്കുകയും ചെയ്തു. ഇബ്റാഹീം(അ) പറഞ്ഞു: അവൾ എന്റെ സഹോദരിയാണ്. ശേഷം അവളുടെ അടുത്ത് ചെന്നപ്പോൾ ഇബ്റാഹീം(അ) പറഞ്ഞു: ഈ ഭരണാധികാരി നിന്നെക്കുറിച്ച് ചോദിച്ചപ്പോൾ നീ എന്റെ സഹോദരിയാണെന്ന് ഞാൻ പറഞ്ഞിട്ടുണ്ട്. നിശ്ചയം ഇന്ന് ഞാനും നീയും അല്ലാതെ ഒരു മുസ്ലിമും ഇല്ല. അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ നീ എന്റെ സഹോദരി തന്നെയാണ്. അതിനാൽ ആ ഭരണാധികാരിയുടെ മുമ്പിൽ വെച്ച് ഞാൻ പറഞ്ഞത് തെറ്റാണെന്ന് നീ പറയരുത്." (ബു,മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], 'الأنبياء: ٦٣', null, 169, 169, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَرْسَلَ إِلَيَّ زَوْجِي بِطَلَاقِي، فَشَدَدْتُ عَلَيَّ ثِيَابِي ثُمَّ أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "كَمْ طَلَّقَكِ". فَقُلْتُ: ثَلَاثًا. قَالَ: "لَيْسَ لَكِ نَفَقَةٌ، وَاعْتَدِّي فِي بَيْتِ ابْنِ عَمِّكِ ابْنِ أُمِّ مَكْتُومٍ، فَإِنَّهُ ضَرِيرُ الْبَصَرِ تُلْقِينَ ثِيَابَكِ عِنْدَهُ، فَإِذَا انْقَضَتْ عِدَّتُكِ فَآذِنِينِي". (ن)', 'ഫാതിമതു ബിൻതുഖൈസ്(റ): എന്നെ വിവാഹമോചനം ചെയ്തിട്ടുണ്ടെന്ന സന്ദേശം എന്റെ ഭർത്താവ് എന്റെയടുത്തേക്ക് പറഞ്ഞയച്ചു. ഉടനെത്തന്നെ ഞാൻ വസ്ത്രം മാറ്റുകയും നബി(സ)യുടെ അടുത്ത് ചെല്ലുകയും ചെയ്തു. തിരുമേനി(സ) ചോദിച്ചു: "അവൻ നിന്നെ എത്ര ത്വലാഖാണ് ചൊല്ലിയത്?" ഞാൻ പറഞ്ഞു: മൂന്ന് ത്വലാഖ്. തിരുമേനി(സ) പറഞ്ഞു: "നിനക്ക് ചെലവ് നിശ്ചയിക്കപ്പെട്ടിട്ടില്ല, നിന്റെ പിതൃവ്യ പുത്രൻ ഇബ്നു ഉമ്മിമഖ്തൂം(റ)വിന്റെയടുത്ത് നീ ഇദ്ദയിരിക്കുക. അദ്ദേഹം അന്ധനാണ്. നിന്റെ വസ്ത്രങ്ങൾ അവിടെ വെക്കാം. ഇദ്ദയുടെ കാലം കഴിഞ്ഞാൽ നീ എന്നോട് സമ്മതം ചോദിക്കുക." (ന)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാതിമതു ബിൻതുഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 169, 169, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَكَثْتُ سَنَةً وَأَنَا أُرِيدُ أَنْ أَسْأَلَ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ عَنْ آيَةٍ، فَمَا أَسْتَطِيعُ أَنْ أَسْأَلَهُ هَيْبَةً لَهُ، حَتَّى خَرَجَ حَاجًّا فَخَرَجْتُ مَعَهُ، فَلَمَّا رَجَعَ فَكُنَّا بِبَعْضِ الطَّرِيقِ، عَدَلَ إِلَى الْأَرَاكِ لِحَاجَةٍ لَهُ، فَوَقَفْتُ لَهُ حَتَّى فَرَغَ ثُمَّ سِرْتُ مَعَهُ، فَقُلْتُ: يَا أَمِيرَ الْمُؤْمِنِينَ، مَنِ اللَّتَانِ تَظَاهَرَتَا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ أَزْوَاجِهِ؟ فَقَالَ: تِلْكَ حَفْصَةُ وَعَائِشَةُ، قَالَ: فَقُلْتُ لَهُ: وَاللهِ إِنْ كُنْتُ لَأُرِيدُ أَنْ أَسْأَلَكَ عَنْ هَذَا مُنْذُ سَنَةٍ، فَمَا أَسْتَطِيعُ هَيْبَةً لَكَ. قَالَ: فَلَا تَفْعَلْ، مَا ظَنَنْتَ أَنَّ عِنْدِي مِنْ عِلْمٍ فَسَلْنِي عَنْهُ، فَإِنْ كُنْتُ أَعْلَمُهُ أَخْبَرْتُكَ. قَالَ: وَقَالَ عُمَرُ: وَاللهِ إِنْ كُنَّا فِي الْجَاهِلِيَّةِ مَا نَعُدُّ لِلنِّسَاءِ أَمْرًا، حَتَّى أَنْزَلَ اللهُ تَعَالَى فِيهِنَّ مَا أَنْزَلَ، وَقَسَمَ لَهُنَّ مَا قَسَمَ، قَالَ: فَبَيْنَمَا أَنَا فِي أَمْرٍ أَأْتَمِرُهُ إِذْ قَالَتْ لِي امْرَأَتِي: لَوْ صَنَعْتَ كَذَا وَكَذَا، فَقُلْتُ لَهَا: وَمَا لَكِ أَنْتِ وَلِمَا هَاهُنَا، وَمَا تَكَلُّفُكِ فِي أَمْرٍ أُرِيدُهُ؟ فَقَالَتْ لِي: عَجَبًا لَكَ يَا ابْنَ الْخَطَّابِ، مَا تُرِيدُ أَنْ تُرَاجَعَ أَنْتَ، وَإِنَّ ابْنَتَكَ لَتُرَاجِعُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى يَظَلَّ يَوْمَهُ غَضْبَانَ. قَالَ عُمَرُ: فَآخُذُ رِدَائِي، ثُمَّ أَخْرُجُ مَكَانِي حَتَّى أَدْخُلَ عَلَى حَفْصَةَ، فَقُلْتُ لَهَا: يَا بُنَيَّةُ إِنَّكِ لَتُرَاجِعِينَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى يَظَلَّ يَوْمَهُ غَضْبَانَ؟ فَقَالَتْ حَفْصَةُ: وَاللهِ إِنَّا لَنُرَاجِعُهُ، فَقُلْتُ: تَعْلَمِينَ أَنِّي أُحَذِّرُكِ عُقُوبَةَ اللهِ وَغَضَبَ رَسُولِهِ، يَا بُنَيَّةُ، لَا تَغُرَّنَّكِ هَذِهِ الَّتِي قَدْ أَعْجَبَهَا حُسْنُهَا، وَحُبُّ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِيَّاهَا. ثُمَّ خَرَجْتُ حَتَّى أَدْخُلَ عَلَى أُمِّ سَلَمَةَ لِقَرَابَتِي مِنْهَا، فَكَلَّمْتُهَا، فَقَالَتْ لِي أُمُّ سَلَمَةَ: عَجَبًا لَكَ يَا ابْنَ الْخَطَّابِ، قَدْ دَخَلْتَ فِي كُلِّ شَيْءٍ حَتَّى تَبْتَغِيَ أَنْ تَدْخُلَ بَيْنَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَبَيْنَ أَزْوَاجِهِ؟ قَالَ: فَأَخَذَتْنِي أَخْذًا كَسَرَتْنِي عَنْ بَعْضِ مَا كُنْتُ أَجِدُ، فَخَرَجْتُ مِنْ عِنْدِهَا، وَكَانَ لِي صَاحِبٌ مِنَ الْأَنْصَارِ إِذَا غِبْتُ أَتَانِي بِالْخَبَرِ، وَإِذَا غَابَ كُنْتُ أَنَا آتِيهِ بِالْخَبَرِ، وَنَحْنُ حِينَئِذٍ نَتَخَوَّفُ مَلِكًا مِنْ مُلُوكِ غَسَّانَ، ذُكِرَ لَنَا أَنَّهُ يُرِيدُ أَنْ يَسِيرَ إِلَيْنَا، فَقَدِ امْتَلَأَتْ صُدُورُنَا مِنْهُ، فَأَتَى صَاحِبِي الْأَنْصَارِيُّ يَدُقُّ الْبَابَ وَقَالَ: افْتَحِ افْتَحْ، فَقُلْتُ: جَاءَ الْغَسَّانِيُّ؟ فَقَالَ: أَشَدُّ مِنْ ذَلِكَ، اعْتَزَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَزْوَاجَهُ. فَقُلْتُ: رَغِمَ أَنْفُ حَفْصَةَ وَعَائِشَةَ، ثُمَّ آخُذُ ثَوْبِي فَأَخْرُجُ حَتَّى جِئْتُ، فَإِذَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مَشْرُبَةٍ لَهُ يُرْتَقَى إِلَيْهَا بِعَجَلَةٍ، وَغُلَامٌ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَسْوَدُ عَلَى رَأْسِ الدَّرَجَةِ، فَقُلْتُ: هَذَا عُمَرُ، فَأْذَنْ لِي. قَالَ عُمَرُ: فَقَصَصْتُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ هَذَا الْحَدِيثَ، فَلَمَّا بَلَغْتُ حَدِيثَ أُمِّ سَلَمَةَ تَبَسَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَإِنَّهُ لَعَلَى حَصِيرٍ مَا بَيْنَهُ وَبَيْنَهُ شَيْءٌ، وَتَحْتَ رَأْسِهِ وِسَادَةٌ مِنْ أَدَمٍ حَشْوُهَا لِيفٌ، وَإِنَّ عِنْدَ رِجْلَيْهِ قَرَظًا مَضْبُورًا، وَعِنْدَ رَأْسِهِ أُهُبًا مُعَلَّقَةً، فَرَأَيْتُ أَثَرَ الْحَصِيرِ فِي جَنْبِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَبَكَيْتُ، فَقَالَ: "مَا يُبْكِيكَ يَا عُمَرُ". فَقُلْتُ: يَا رَسُولَ اللهِ، إِنَّ كِسْرَى وَقَيْصَرَ فِيمَا هُمَا فِيهِ، وَأَنْتَ رَسُولُ اللهِ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَمَا تَرْضَى أَنْ تَكُونَ لَهُمَا الدُّنْيَا وَلَكَ الْآخِرَةُ". (ق)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): ഒരു ആയതിനെക്കുറിച്ച് ഉമറുബ്നുൽ ഖത്താബ്(റ)വിനോട് ചോദിക്കണമെന്ന് ആഗ്രഹിച്ച് കൊണ്ട് ഞാൻ ഒരു വർഷം കഴിച്ചുകൂട്ടി. ഉമർ(റ)വിനോടുള്ള പേടി കാരണത്താൽ എനിക്കത് ചോദിക്കാൻ സാധിക്കുമായിരുന്നില്ല. അങ്ങനെ ഒരിക്കൽ ഉമർ(റ) ഹജ്ജിന് പോവുകയും അദ്ദേഹത്തോടൊപ്പം ഞാൻ പുറപ്പെടുകയും ചെയ്തു. അവിടെ നിന്ന് മടങ്ങുന്നതിനിടയിൽ വഴിയിൽ വെച്ച് എന്തോ ആവശ്യത്തിന് വേണ്ടി ഉമർ(റ) അറാക് മരത്തിന്റെ ഭാഗത്തേക്ക് മാറിനിന്നു. അദ്ദേഹം തന്റെ ആവശ്യം പൂർത്തീകരിക്കുവോളം ഞാനവരെ കാത്തുനിൽക്കുകയും ശേഷം അവരോടൊന്നിച്ച് യാത്ര ചെയ്യുകയും ചെയ്തു. ഞാൻ ചോദിച്ചു: അമീറുൽ മുഅ്മിനീൻ, റസൂൽ(സ)ക്കെതിരെ പരസ്പരം സഹകരിച്ച അവിടത്തെ രണ്ട് ഭാര്യമാർ ആരെല്ലാമാണ്? ഉമർ(റ) പറഞ്ഞു: അത് ഹഫ്സ(റ)യും ആഇശ(റ)യുമാണ്. ഞാൻ പറഞ്ഞു: ഒരു വർഷമായിട്ട് അങ്ങയോടിത് ചോദിക്കാൻ ആഗ്രഹിക്കുന്നുണ്ടായിരുന്നു. പക്ഷേ, അങ്ങയോടുള്ള ഭയം കാരണം അതിന് സാധിച്ചില്ല. ഉമർ(റ) പറഞ്ഞു: നീ അപ്രകാരം ചെയ്യരുത്. എന്റെയടുത്ത് വല്ല വിജ്ഞാനവുമുണ്ടെന്ന് കണ്ടാൽ അതേക്കുറിച്ച് എന്നോട് ചോദിക്കണം. എനിക്കറിയുന്നതാണെങ്കിൽ ഞാൻ പറഞ്ഞുതരും. ഉമർ(റ) പറഞ്ഞു: ജാഹിലിയ്യാ കാലത്ത് ഞങ്ങൾ സ്ത്രീകൾക്ക് ഒരു വിലയും കൽപിച്ചിരുന്നില്ല. ശേഷം അവരുടെ വിഷയത്തിൽ അല്ലാഹു പല സൂക്തങ്ങളുമിറക്കുകയും പല അവകാശങ്ങളും അവർക്ക് നൽകുകയും ചെയ്തു. അങ്ങനെ ഒരിക്കൽ ഏതോ ഒരു കാര്യം ഞാൻ ചിന്തിച്ചു കൊണ്ടിരിക്കുമ്പോൾ എന്റെ ഭാര്യ എന്നോട് ചോദിച്ചു: നിങ്ങൾക്ക് ഇപ്രകാരം ചെയ്തു കൂടേ? ഞാനവളോട് പറഞ്ഞു: ഇക്കാര്യത്തിൽ ഇടപെടാൻ നിനക്കെന്ത് അവകാശമാണുള്ളത്? ഞാനുദ്ദേശിക്കുന്ന കാര്യത്തിൽ നീയെന്തിനാണ് തീർപ്പ് പറയുന്നത്? അവൾ പറഞ്ഞു: ഖത്താബിന്റെ പുത്രാ, അങ്ങയുടെ കാര്യം അത്ഭുതം തന്നെ! നിങ്ങളുടെ ഭാര്യ അങ്ങയോട് ദേഷ്യപ്പെടുന്നത് എന്തു കൊണ്ട് നിങ്ങൾ വെറുക്കുന്നു? നിങ്ങളുടെ മകൾ - റസൂൽ(സ)യുടെ ഭാര്യ ഹഫ്സ(റ) - റസൂൽ(സ)യോട് ദേഷ്യപ്പെടുകയും അതു കാരണം തിരുമേനി(സ) ആ ദിവസം മുഴുവൻ കോപാകുലരാവുകയും ചെയ്യാറുണ്ട്. ഉമർ(റ) പറഞ്ഞു: ഉടനെത്തന്നെ ഞാൻ എന്റെ തട്ടം എടുക്കുകയും ഹഫ്സ(റ)യുടെ അടുത്ത് ചെല്ലുകയും ചെയ്തു. ഞാൻ ചോദിച്ചു: മകളേ, നീ റസൂൽ(സ)യോട് ദേഷ്യപ്പെട്ട് സംസാരിക്കുകയും അതു കാരണം അവിടന്ന് ആ ദിവസം മുഴുവൻ കോപാകുലരാവുകയും ചെയ്യാറുണ്ടോ? ഹഫ്സ(റ) പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, ഞങ്ങൾ തിരുമേനി(സ)യോട് ദേഷ്യപ്പെട്ട് സംസാരിക്കാറുണ്ട്. ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ശിക്ഷയെ കുറിച്ചും അവന്റെ റസൂലിന്റെ കോപത്തെക്കുറിച്ചും ഞാൻ നിനക്ക് മുന്നറിയിപ്പ് നൽകുന്നു. മകളേ, റസൂൽ(സ) തന്നെ അതിയായി സ്നേഹിക്കുന്നുവെന്നും താൻ സുന്ദരിയാണെന്നും കരുതുന്ന ഇവളുടെ - ആഇശ(റ)യുടെ - അവസ്ഥ നിന്നെ വഞ്ചിക്കാതിരിക്കട്ടെ. ശേഷം ഞാൻ ഉമ്മുസലമ(റ)യുടെ അടുത്ത് ചെന്നു. കാരണം മഹതി എന്റെ കുടുംബക്കാരിയായിരുന്നു. ഞാൻ മഹതിയോട് സംസാരിച്ചപ്പോൾ മഹതി പറഞ്ഞു: ഇബ്നുൽ ഖത്താബേ, അങ്ങയുടെ കാര്യം അത്ഭുതം! അങ്ങ് എല്ലാ കാര്യങ്ങളിലും ഇടപെട്ടു കൊണ്ടിരിക്കുന്നു. എത്രത്തോളമെന്നാൽ റസൂൽ(സ)യുടെയും അവിടത്തെ ഭാര്യമാരുടെയും കാര്യങ്ങൾക്കിടയിൽ പോലും ഇടപെടാൻ അങ്ങ് ആഗ്രഹിക്കുന്നു. മഹതിയുടെ സംസാരം എന്നെ അത്ഭുതപ്പെടുത്തി. എന്റെ ദേഷ്യം അകന്നു. ഞാൻ മഹതിയുടെ അടുത്ത് നിന്ന് പോന്നു. എനിക്ക് അൻസാരിയായ ഒരു സുഹൃത്തുണ്ടായിരുന്നു. ഞാൻ സ്ഥലത്തില്ലായെങ്കിൽ അന്നത്തെ എല്ലാ വാർത്തകളും അദ്ദേഹം എനിക്ക് പറഞ്ഞു തരുമായിരുന്നു. അദ്ദേഹമാണ് സ്ഥലത്തില്ലാത്തതെങ്കിൽ എല്ലാ വാർത്തകളും ഞാൻ അദ്ദേഹത്തിനും പറഞ്ഞു കൊടുക്കുമായിരുന്നു. അക്കാലത്ത് ഗസ്സാനിലെ രാജാവ് യുദ്ധത്തിനായി ഞങ്ങളുടെ അടുത്തേക്ക് വരുന്നുണ്ടെന്ന് വാർത്ത പരക്കുകയും ഞങ്ങൾ അത് പ്രതീക്ഷിച്ചു കൊണ്ടിരിക്കുകയും ചെയ്തിരുന്നു. ഞങ്ങളുടെ മനസ്സുകളിലെല്ലാം ആ ചിന്തയുണ്ടായിരുന്നു. അങ്ങനെയിരിക്കെ അൻസാരിയായ എന്റെ സുഹൃത്ത് വന്ന് വാതിൽ മുട്ടുകയും വാതിൽ തുറക്കാൻ ആവശ്യപ്പെടുകയും ചെയ്തു. ഞാൻ ചോദിച്ചു: ഗസ്സാൻ രാജാവ് സൈന്യവുമായി എത്തിയിട്ടുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: അതിനെക്കാൾ ഗൗരവമേറിയ വിഷയമുണ്ടായിട്ടുണ്ട്. റസൂൽ(സ) തന്റെ ഭാര്യമാരെ വെടിഞ്ഞു ഒഴിഞ്ഞിരിക്കുകയാണ്. ഞാൻ പറഞ്ഞു: ഹഫ്സ(റ)യുടെയും ആഇശ(റ)യുടെയും നാശം! ഉടനെ ഞാൻ വസ്ത്രം മാറി അവിടെ ചെന്നു. അന്നേരം റസൂൽ(സ) കോണി വെച്ച് മാത്രം കയറാൻ കഴിയുന്ന തട്ടിൻപുറത്തുള്ള ഒരു ചെറിയ മുറിയിലായിരുന്നു. റസൂൽ(സ)യുടെ കറുത്ത ഒരു അടിമ ആ കോണിയുടെ അറ്റത്ത് നിൽക്കുന്നുണ്ടായിരുന്നു. ഞാൻ പറഞ്ഞു: ഇത് ഉമറാണ്. അപ്പോൾ അവൻ എനിക്ക് അകത്ത് കടക്കാൻ അനുവാദം നൽകി. മുൻകഴിഞ്ഞ സംഭവങ്ങളെല്ലാം ഞാൻ റസൂൽ(സ)യോട് പറഞ്ഞുകൊടുത്തു. ഉമ്മുസലമ(റ)യുമായുള്ള കൂടിക്കാഴ്ച വിശദീകരിച്ചപ്പോൾ റസൂൽ(സ) ഒന്ന് പുഞ്ചിരിച്ചു. റസൂൽ(സ) ഈത്തപ്പനയോല കൊണ്ട് മെടഞ്ഞ ഒരു പായയിൽ ഒന്നും വിരിക്കാതെ കിടക്കുകയായിരുന്നു. അവിടത്തെ തലക്കു ചുവട്ടിൽ ഈത്തപ്പന നാര് നിറച്ച, തോൽ കൊണ്ട് നിർമ്മിച്ച ഒരു തലയിണയുമുണ്ടായിരുന്നു. തിരുമേനി(സ)യുടെ കാൽ ഭാഗത്ത് ഖറള് എന്ന ഇല (ഊറക്കിടാൻ ഉപയോഗിക്കുന്ന ഇല) കൂട്ടിയിട്ടിട്ടുണ്ടായിരുന്നു. തല ഭാഗത്ത് ഊറക്കിടാത്ത തോൽ തൂക്കിയിടുകയും ചെയ്തിരുന്നു. അവിടത്തെ ശരീരത്തിൽ ആ പായയുടെ അടയാളം വീണത് കണ്ട് ഞാൻ കരഞ്ഞു. റസൂൽ(സ) ചോദിച്ചു: "ഉമറേ, താങ്കൾ എന്തിനാണ് കരയുന്നത്?" ഞാൻ പറഞ്ഞു: റസൂലേ, ഖിസ്റയും ഖൈസറും അങ്ങേയറ്റം സുഖിച്ചു കൊണ്ടിരിക്കുന്നു. അങ്ങ് അല്ലാഹുവിന്റെ റസൂലായിട്ടും ഇപ്രകാരമാണല്ലോ? റസൂൽ(സ) ചോദിച്ചു: "ഖിസ്റക്കും ഖൈസറിനും ഐഹിക സുഖവും നിങ്ങൾക്ക് പാരത്രിക സുഖവും ലഭിക്കുന്നത് നിങ്ങൾ തൃപ്തിപ്പെടുന്നില്ലേ?" (ബു,മു)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 169, 172, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ سَلَمَةَ بْنِ صَخْرٍ الْبَيَاضِي رَضِيَ اللهُ عَنْهُ قَالَ: كُنتُ امْرَأً أُصِيبُ مِنَ النِّسَاءِ مَا لَا يُصِيبُ غَيْرِي، فَلَمَّا دَخَلَ شَهْرُ رَمَضَانَ خِفْتُ أَنْ أُصِيبَ مِنِ امْرَأَتِي شَيْئًا يُتَابِعُ بِي حَتَّى أُصْبِحَ، فَظَاهَرْتُ مِنْهَا حَتَّى يَنْسَلِخَ شَهْرُ رَمَضَانَ، فَبَيْنَا هِيَ تَخْدُمُنِي ذَاتَ لَيْلَةٍ إِذْ تَكَشَّفَ لِي مِنْهَا شَيْءٌ، فَلَمْ أَلْبَثْ أَنْ نَزَوْتُ عَلَيْهَا، فَلَمَّا أَصْبَحْتُ خَرَجْتُ إِلَى قَوْمِي، فَأَخْبَرْتُهُمُ الْخَبَرَ، وَقُلْتُ: امْشُوا مَعِي إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالُوا: لَا وَاللهِ، فَانْطَلَقْتُ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ، فَقَالَ: "أَنْتَ بِذَاكَ يَا سَلَمَةُ". قُلْتُ: أَنَا بِذَاكَ يَا رَسُولَ اللهِ، مَرَّتَيْنِ، وَأَنَا صَابِرٌ لِأَمْرِ اللهِ، فَاحْكُمْ فِيَّ مَا أَرَاكَ اللهُ. قَالَ: "حَرِّرْ رَقَبَةً". قُلْتُ: وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَمْلِكُ رَقَبَةً غَيْرَهَا، وَضَرَبْتُ صَفْحَةَ رَقَبَتِي. قَالَ: "فَصُمْ شَهْرَيْنِ مُتَتَابِعَيْنِ". قَالَ: وَهَلْ أَصَبْتُ الَّذِي أَصَبْتُ إِلَّا مِنَ الصِّيَامِ؟ قَالَ: "فَأَطْعِمْ وَسْقًا مِنْ تَمْرٍ بَيْنَ سِتِّينَ مِسْكِينًا". قُلْتُ: وَالَّذِي بَعَثَكَ بِالْحَقِّ، لَقَدْ بِتْنَا وَحْشَيْنِ، مَا لَنَا طَعَامٌ. قَالَ: "فَانْطَلِقْ إِلَى صَاحِبِ صَدَقَةِ بَنِي زُرَيْقٍ، فَلْيَدْفَعْهَا إِلَيْكَ، فَأَطْعِمْ سِتِّينَ مِسْكِينًا وَسْقًا مِنْ تَمْرٍ، وَكُلْ أَنْتَ وَعِيَالُكَ بَقِيَّتَهَا". فَرَجَعْتُ إِلَى قَوْمِي، فَقُلْتُ: وَجَدْتُ عِنْدَكُمُ الضِّيقَ وَسُوءَ الرَّأْيِ، وَوَجَدْتُ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ السَّعَةَ وَحُسْنَ الرَّأْيِ، وَقَدْ أَمَرَنِي – أَوْ: أَمَرَ لِي – بِصَدَقَتِكُمْ. (د,ت,جه)', 'സലമതുബ്നു സ്വഖ്റുൽ ബയാളി(റ): മറ്റാരെക്കാളും ഭാര്യമാരുമായി ബന്ധപ്പെടുന്ന വ്യക്തിയായിരുന്നു ഞാൻ. റമളാൻ മാസം ആഗതമായപ്പോൾ എന്റെ ഭാര്യയുമായി ബന്ധപ്പെടുമോ എന്ന് ഞാൻ ഭയന്നു. അങ്ങനെയെങ്കിൽ നേരം പുലരുവോളം ഞാൻ ആ കുറ്റത്തിൽ തന്നെയായിരിക്കും. അതില്ലാതിരിക്കാൻ റമളാൻ മാസം കഴിയും വരെ എന്റെ ഭാര്യയെ ഞാൻ ളിഹാർ (നിന്റെ മുതുക് എന്റെ ഉമ്മയുടേതിന് സമാനമാണെന്ന് പറഞ്ഞ് ഭാര്യയെ അകറ്റിനിർത്തൽ) ചെയ്തു. അങ്ങനെയിരിക്കെ ഒരു രാത്രി അവളെനിക്ക് എന്തോ ചെയ്ത് തന്ന് കൊണ്ടിരിക്കുന്നതിനിടയിൽ അവളുടെ ശരീരത്തിൽ ഒരു ഭാഗം വെളിവായി. ഉടനെത്തന്നെ ഞാനവളെ സമീപിച്ചു. നേരം പുലർന്നപ്പോൾ ഞാൻ എന്റെ കുടുംബക്കാരോട് ചെന്ന് വിവരം പറഞ്ഞു. എന്നെ റസൂൽ(സ)യുടെ അടുത്തേക്ക് കൊണ്ടുപോകാൻ ആവശ്യപ്പെടുകയും ചെയ്തു. പക്ഷേ, അവർ പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, ഞങ്ങളത് ചെയ്യില്ല. അങ്ങനെ ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെല്ലുകയും വിവരം പറയുകയും ചെയ്തു. അപ്പോൾ തിരുമേനി(സ) ചോദിച്ചു: "സലമ, നീ അത് ചെയ്തിട്ടുണ്ടോ?" ഞാൻ പറഞ്ഞു: അതെ, റസൂലേ. രണ്ട് പ്രാവശ്യം ഞാനത് ചെയ്തിരിക്കുന്നു. അല്ലാഹുവിന്റെ വിധിയും കാത്തിരിക്കുകയാണ് ഞാൻ, അതിനാൽ അല്ലാഹു അങ്ങേക്ക് അറിയിച്ചുതരുന്ന തീരുമാനം പറയുക. തിരുമേനി(സ) പറഞ്ഞു: "നീ ഒരു അടിമയെ മോചിപ്പിക്കുക." ഞാൻ എന്റെ പിരടി തൊട്ടുകൊണ്ട് പറഞ്ഞു: അങ്ങയെ സത്യവുമായി അയച്ചവൻ തന്നെ സത്യം, ഇതല്ലാതെ മറ്റൊരു തടിയും എന്റെ ഉടമസ്ഥതയിലില്ല. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ നീ തുടർച്ചയായി രണ്ടുമാസം നോമ്പെടുക്കുക." ഞാൻ പറഞ്ഞു: നോമ്പനുഷ്ഠിച്ചുകൊണ്ടല്ലേ ഇപ്പോൾ ഞാൻ ഈ കുറ്റം ചെയ്തിരിക്കുന്നത്. (പിന്നെ എങ്ങിനെയാണ് എനിക്ക് രണ്ട് മാസം മുഴുവൻ നോമ്പനുഷ്ഠിക്കാൻ സാധിക്കുക). റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ ഒരു വസ്ഖ് (അറുപത് സ്വാഅ് അഥവാ ഒരു ഒട്ടകത്തിന് വഹിക്കാനാകുന്ന അളവ്) കാരക്കയെടുത്ത് അറുപത് പാവങ്ങളെ ഭക്ഷിപ്പിക്കുക." ഞാൻ പറഞ്ഞു: അങ്ങയെ സത്യവുമായി അയച്ചവൻ തന്നെ സത്യം. ഞങ്ങൾ വിശന്നവരായിട്ടാണ് രാത്രി കഴിച്ച് കൂട്ടിയത്. ഞങ്ങൾക്ക് ഭക്ഷണമില്ല. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ നീ ബനൂസുറൈഖുകാരുടെ സകാതിന്റെ ആളുടെ അടുത്ത് ചെല്ലുക. അദ്ദേഹം നിനക്ക് ധാനം നൽകും. അതിൽ നിന്ന് ഒരു വസ്ഖ് കാരക്ക അറുപത് ദരിദ്രർക്ക് നൽകുക. അതിൽ ബാക്കിവന്നത് നീയും കുടുംബവും ഭക്ഷിക്കുക." ശേഷം ഞാൻ എന്റെ കുടുംബക്കാരുടെ അടുത്ത് ചെല്ലുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു. നിങ്ങളുടെ പക്കൽ നിന്ന് ബുദ്ധിമുട്ടും മോശം അഭിപ്രായവുമാണ് എനിക്ക് ലഭിച്ചത്. പക്ഷേ, നബി(സ)യിൽ നിന്ന് എനിക്ക് ലഭിച്ചത് നല്ല അയവും മാനസിക വിശാലതയുമാണ്. നിങ്ങളിൽ നിന്നുള്ള ദാനം സ്വീകരിക്കുവാൻ എന്നോട് അവിടന്ന് കൽപിച്ചിട്ടുണ്ട്. (ദ,തു,ജ)', 'سَلَمَةَ بْنِ صَخْرٍ الْبَيَاضِي', 'സലമതുബ്നു സ്വഖ്റുൽ ബയാളി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 172, 173, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ ظَاهَرَ مِنِ امْرَأَتِهِ فَوَقَعَ عَلَيْهَا – وَفِي رِوَايَةٍ: ثُمَّ غَشِيَهَا قَبْلَ أَنْ يَفْعَلَ مَا عَلَيْهِ – فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي ظَاهَرْتُ مِنِ امْرَأَتِي فَوَقَعْتُ قَبْلَ أَنْ أُكَفِّرَ؟ قَالَ: "وَمَا حَمَلَكَ عَلَى ذَلِكَ يَرْحَمُكَ اللهُ". قَالَ: رَأَيْتُ خَلْخَالَهَا – وَفِي رِوَايَةٍ: بَيَاضَ سَاقَيْهَا – فِي ضَوْءِ الْقَمَرِ. فَقَالَ: "لَا تَقْرَبْهَا – وَفِي رِوَايَةٍ: فَاعْتَزِلْهَا – حَتَّى تَفْعَلَ مَا أَمَرَ اللهُ عَزَّ وَجَلَّ". (د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): തന്റെ ഭാര്യയോട്, നിന്റെ മുതുക് എന്റെ ഉമ്മയുടേത് പോലെയാണെന്ന് പറയുകയും ശേഷമവളോട് ബന്ധപ്പെടുകയും ചെയ്ത ഒരാൾ - മറ്റൊരു നിവേദനം: തനിക്ക് നിർബന്ധമായ പ്രായശ്ചിത്തം വീട്ടുന്നതിന് മുമ്പ് അവളോട് ബന്ധപ്പെടുകയും ചെയ്ത ഒരാൾ - നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: റസൂലേ, ഞാൻ എന്റെ ഭാര്യയോട് നീ എന്റെ ഉമ്മയെപ്പോലെയാണെന്ന് പറയുകയും അതിനുള്ള പ്രായശ്ചിത്തം നൽകും മുമ്പ് അവളോട് ബന്ധപ്പെടുകയും ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "എന്ത് കൊണ്ടാണ് നീ അങ്ങനെ ചെയ്തത്, അല്ലാഹു നിനക്ക് അനുഗ്രഹം ചെയ്യട്ടെ." അദ്ദേഹം പറഞ്ഞു: ഞാൻ അവളുടെ പാദസരം - മറ്റൊരു നിവേദനത്തിൽ: അവളുടെ രണ്ട് കണങ്കാലുകൾ - രാവെളിച്ചത്തിൽ കണ്ടു. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു കൽപിച്ചത് ചെയ്യും വരെ നീ അവളോട് അടുക്കരുത്. - മറ്റൊരു നിവേദനം: "നീ അവളെ വെടിഞ്ഞ് നിൽക്കുക." (ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 173, 173, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=74), 1, 'وَفِي رِوَايَةٍ: ثُمَّ غَشِيَهَا قَبْلَ أَنْ يَفْعَلَ مَا عَلَيْهِ – فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي ظَاهَرْتُ مِنِ امْرَأَتِي فَوَقَعْتُ قَبْلَ أَنْ أُكَفِّرَ؟ قَالَ: "وَمَا حَمَلَكَ عَلَى ذَلِكَ يَرْحَمُكَ اللهُ". قَالَ: رَأَيْتُ خَلْخَالَهَا –', 'മറ്റൊരു നിവേദനം: തനിക്ക് നിർബന്ധമായ പ്രായശ്ചിത്തം വീട്ടുന്നതിന് മുമ്പ് അവളോട് ബന്ധപ്പെടുകയും ചെയ്ത ഒരാൾ - നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: റസൂലേ, ഞാൻ എന്റെ ഭാര്യയോട് നീ എന്റെ ഉമ്മയെപ്പോലെയാണെന്ന് പറയുകയും അതിനുള്ള പ്രായശ്ചിത്തം നൽകും മുമ്പ് അവളോട് ബന്ധപ്പെടുകയും ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "എന്ത് കൊണ്ടാണ് നീ അങ്ങനെ ചെയ്തത്, അല്ലാഹു നിനക്ക് അനുഗ്രഹം ചെയ്യട്ടെ." അദ്ദേഹം പറഞ്ഞു: ഞാൻ അവളുടെ പാദസരം -');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=74), 2, 'وَفِي رِوَايَةٍ: بَيَاضَ سَاقَيْهَا – فِي ضَوْءِ الْقَمَرِ. فَقَالَ: "لَا تَقْرَبْهَا –', 'മറ്റൊരു നിവേദനത്തിൽ: അവളുടെ രണ്ട് കണങ്കാലുകൾ - രാവെളിച്ചത്തിൽ കണ്ടു. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു കൽപിച്ചത് ചെയ്യും വരെ നീ അവളോട് അടുക്കരുത്. -');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=74), 3, 'وَفِي رِوَايَةٍ: فَاعْتَزِلْهَا – حَتَّى تَفْعَلَ مَا أَمَرَ اللهُ عَزَّ وَجَلَّ". (د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: "നീ അവളെ വെടിഞ്ഞ് നിൽക്കുക." (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ سَلَمَةَ بْنِ صَخْرٍ الْبَيَاضِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ امْرَأً أَسْتَكْثِرُ مِنَ النِّسَاءِ، لَا أَرَى رَجُلًا كَانَ يُصِيبُ مِنْ ذَلِكَ مَا أُصِيبُ، فَلَمَّا دَخَلَ رَمَضَانُ ظَاهَرْتُ مِنِ امْرَأَتِي حَتَّى يَنْسَلِخَ رَمَضَانُ، فَبَيْنَمَا هِيَ تُحَدِّثُنِي ذَاتَ لَيْلَةٍ انْكَشَفَ لِي مِنْهَا شَيْءٌ، فَوَثَبْتُ عَلَيْهَا فَوَاقَعْتُهَا، فَلَمَّا أَصْبَحْتُ غَدَوْتُ عَلَى قَوْمِي فَأَخْبَرْتُهُمْ خَبَرِي، وَقُلْتُ لَهُمْ: سَلُوا لِي رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَقَالُوا: مَا كُنَّا نَفْعَلُ، إِذَا يُنْزِلَ اللهُ عَزَّ وَجَلَّ فِينَا كِتَابًا، أَوْ يَكُونَ فِينَا مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَوْلٌ، فَيَبْقَى عَلَيْنَا عَارُهُ، وَلَكِنْ سَوْفَ نُسَلِّمُكَ بِجَرِيرَتِكَ، اذْهَبْ أَنْتَ فَاذْكُرْ شَأْنَكَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ: فَخَرَجْتُ حَتَّى جِئْتُهُ، فَأَخْبَرْتُهُ الْخَبَرَ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنْتَ بِذَاكَ". فَقُلْتُ: أَنَا بِذَاكَ، وَهَا أَنَا يَا رَسُولَ اللهِ، صَابِرٌ لِحُكْمِ اللهِ عَلَيَّ. قَالَ: "فَأَعْتِقْ رَقَبَةً". قَالَ: قُلْتُ وَالَّذِي بَعَثَكَ بِالْحَقِّ، مَا أَصْبَحْتُ أَمْلِكُ إِلَّا رَقَبَتِي هَذِهِ. قَالَ: "فَصُمْ شَهْرَيْنِ مُتَتَابِعَيْنِ". قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، وَهَلْ دَخَلَ عَلَيَّ مَا دَخَلَ مِنَ الْبَلَاءِ إِلَّا بِالصَّوْمِ؟ قَالَ: فَتَصَدَّقْ. أَوْ: أَطْعِمْ سِتِّينَ مِسْكِينًا". قَالَ: قُلْتُ: وَالَّذِي بَعَثَكَ بِالْحَقِّ، لَقَدْ بِتْنَا لَيْلَتَنَا هَذِهِ مَا لَنَا عَشَاءٌ. قَالَ: "فَاذْهَبْ إِلَى صَاحِبِ صَدَقَةِ بَنِي زُرَيْقٍ فَقُلْ لَهُ، فَلْيَدْفَعْهَا إِلَيْكَ، وَأَطْعِمْ سِتِّينَ مِسْكِينًا، وَانْتَفِعْ بِبَقِيَّتِهَا". (د,ت,جه)', 'സലമതുബ്നു സ്വഖ്റുൽ ബയാളി(റ): സ്ത്രീകളോട് കൂടുതൽ ബന്ധപ്പെടുന്ന വ്യക്തിയായിരുന്ന ഞാൻ. എന്റെയത്ര സ്ത്രീകളോട് ബന്ധപ്പെടുന്ന ഒരാളെയും ഞാൻ കണ്ടിട്ടില്ല. റമളാൻ വന്നപ്പോൾ റമളാൻ കഴിയുംവരെ ഞാനവളെ ളിഹാർ (നിന്റെ മുതുക് എന്റെ ഉമ്മയുടേതിന് സമാനമെന്ന് പറഞ്ഞ് ഭാര്യയെ അകറ്റിനിർത്തൽ) ചെയ്തു. ഒരു രാത്രിയിൽ അവൾ എന്നോട് സംസാരിച്ച് കൊണ്ടിരിക്കുമ്പോൾ അവളുടെ ശരീരത്തിൽ ഒരു ഭാഗം വെളിവാകുകയും ഞാനവളുടെ അടുത്ത് ചെന്ന് അവളോട് ബന്ധപ്പെടുകയും ചെയ്തു. നേരം പുലർന്നപ്പോൾ ഞാൻ എന്റെ സമുദായത്തിന്റെ അടുത്ത് ചെല്ലുകയും ആ വിവരം പറയുകയും ചെയ്തു. ഞാനവരോട് പറഞ്ഞു: എന്റെ കാര്യത്തെക്കുറിച്ച് നിങ്ങൾ റസൂൽ(സ)യോട് ചോദിക്കുക. അവർ പറഞ്ഞു: ഞങ്ങൾ അപ്രകാരം ചെയ്യുകയില്ല, കാരണം അങ്ങനെ ചെയ്താൽ ഞങ്ങളുടെ വിഷയത്തിൽ അല്ലാഹു വല്ല സൂക്തവുമിറക്കുകയോ റസൂൽ(സ) വല്ലതും പറയുകയോ ചെയ്യും. അതിന്റെ മോശത്തരം ഞങ്ങൾക്ക് എന്നെന്നും നിലനിൽക്കും. അതിനാൽ നിന്റെ തെറ്റ് ഞങ്ങൾ നിന്നെത്തന്നെ ഏൽപ്പിക്കുന്നു. നീ തന്നെ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് നിന്റെ കാര്യം പറയുക. അങ്ങനെ ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെല്ലുകയും വിവരം പറയുകയും ചെയ്തു. റസൂൽ(സ) ചോദിച്ചു: "നീ അത് ചെയ്തിട്ടുണ്ടോ?" ഞാൻ പറഞ്ഞു: അതെ റസൂലേ, ഞാൻ ചെയ്തിട്ടുണ്ട്. ഞാൻ അല്ലാഹുവിന്റെ വിധി കാത്തു നിൽക്കുകയാണ്. തിരുമേനി(സ) പറഞ്ഞു: "എങ്കിൽ നീ ഒരടിമയെ മോചിപ്പിക്കുക." ഞാൻ പറഞ്ഞു: അങ്ങയെ സത്യവുമായി അയച്ചവൻ തന്നെ സത്യം, ഇതല്ലാതെ (എന്റെ ശരീരമല്ലാതെ) ഒന്നും എന്റെ ഉടമസ്ഥതയിലില്ല. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ നീ രണ്ട് മാസം തുടർച്ചയായി നോമ്പനുഷ്ഠിക്കുക." ഞാൻ പറഞ്ഞു: റസൂലേ, നോമ്പനുഷ്ഠിച്ചതു കൊണ്ടാണ് എനിക്ക് ഈ ബുദ്ധിമുട്ട് വന്ന് പെട്ടത്. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ നീ ദാനം ചെയ്യുക. അല്ലെങ്കിൽ അറുപത് പാവപ്പെട്ടവർക്ക് ഭക്ഷണം നൽകുക." ഞാൻ പറഞ്ഞു: അങ്ങയെ സത്യവുമായി അയച്ചവൻ തന്നെ സത്യം, കഴിഞ്ഞ രാത്രി ഭക്ഷണം കഴിക്കാതെയാണ് ഞങ്ങൾ അന്തിയുറങ്ങിയത്. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ ബനൂ സുറൈഖ് ഗോത്രക്കാരുടെ സകാതിന്റെ ആളുടെ അടുത്ത് പോയി നിനക്ക് ദാനം നൽകാൻ ആവശ്യപ്പെടുക. എന്നിട്ട് നീ അറുപത് ദരിദ്രരെ ഭക്ഷിപ്പിക്കുകയും ബാക്കിയുള്ളത് നീ ഉപയോഗിക്കുകയും ചെയ്യുക." (ദ,തു,ജ)', 'سَلَمَةَ بْنِ صَخْرٍ الْبَيَاضِيِّ', 'സലമതുബ്നു സ്വഖ്റുൽ ബയാളി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 173, 174, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: تَبَارَكَ الَّذِي وَسِعَ سَمْعُهُ كُلَّ شَيْءٍ، إِنِّي لَأَسْمَعُ كَلَامَ خَوْلَةَ بِنْتِ ثَعْلَبَةَ، وَيَخْفَى عَلَيَّ بَعْضُهُ، وَهِيَ تَشْتَكِي زَوْجَهَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَهِيَ تَقُولُ: يَا رَسُولَ اللهِ، أَكَلَ شَبَابِي، وَنَثَرْتُ لَهُ بَطْنِي، حَتَّى إِذَا كَبِرَتْ سِنِّي، وَانْقَطَعَ وَلَدِي، ظَاهَرَ مِنِّي، اللَّهُمَّ إِنِّي أَشْكُو إِلَيْكَ. فَمَا بَرِحَتْ حَتَّى نَزَلَ جِبْرَائِيلُ بِهَؤُلَاءِ الْآيَاتِ: {قَدْ سَمِعَ اللهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللهِ}. (جه)', 'ആഇശ(റ): എല്ലാ വസ്തുക്കളുടെയും ശബ്ദം ശ്രവിക്കുന്നവനായ അല്ലാഹു പരിശുദ്ധൻ തന്നെ. ഖൗല ബിൻത് സഅ്ലബ(റ) തന്റെ ഭർത്താവിനെക്കുറിച്ച് റസൂൽ(സ)യോട് പരാതിപ്പെടുന്നത് ഞാൻ കേൾക്കുന്നുണ്ടായിരുന്നു. പക്ഷേ, ചില വാക്കുകൾ എനിക്ക് അവ്യക്തമായിരുന്നു. ഖൗല(റ) ഇപ്രകാരം പറയുന്നുണ്ടായിരുന്നു: റസൂലേ, അദ്ദേഹം എന്റെ യുവത്വത്തെ ആസ്വദിക്കുകയും ഞാൻ അദ്ദേഹം മുഖേന കുറേ മക്കളെ പ്രസവിക്കുകയും ചെയ്തു. ഇപ്പോൾ എനിക്ക് പ്രായമാകുകയും പ്രസവിക്കാൻ കഴിയാത്ത അവസ്ഥ വരികയും ചെയ്തപ്പോൾ അദ്ദേഹം എന്നെ ളിഹാർ (നിന്റെ മുതുക് എന്റെ ഉമ്മയുടെ മതുകിന് സമാനമാണ് എന്ന് പറഞ്ഞ് ഭാര്യയെ അകറ്റി നിർത്തൽ) ചെയ്തിരിക്കുന്നു. അല്ലാഹുവേ, ഞാൻ നിന്നോട് പരാതിപ്പെടുന്നു. ശേഷം, ''തന്റെ ഭർത്താവിന്റെ വിഷയത്തിൽ അങ്ങയോട് തർക്കിക്കുകയും അല്ലാഹുവിനോട് പരാതിപ്പെടുകയും ചെയ്തവളുടെ വാക്കുകളെ അല്ലാഹു കേട്ടിരിക്കുന്നു'' എന്ന സൂക്തവുമായി ജിബ്രീൽ(അ) ഇറങ്ങും വരെ ഖൗല(റ) അവിടെത്തന്നെ നിന്നു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 174, 174, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ خُوَيْلَةَ بِنْتِ مَالِكِ بْنِ ثَعْلَبَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: ظَاهَرَ مِنِّي زَوْجِي أَوْسُ بْنُ الصَّامِتِ، فَجِئْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَشْكُو إِلَيْهِ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُجَادِلُنِي فِيهِ وَيَقُولُ: "اتَّقِي اللهَ، فَإِنَّهُ ابْنُ عَمِّكِ". فَمَا بَرِحْتُ حَتَّى نَزَلَ الْقُرْآنُ: {قَدْ سَمِعَ اللهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا} [المجادلة: ١] إِلَى الْفَرْضِ، فَقَالَ: "يُعْتِقُ رَقَبَةً". قَالَتْ: لَا يَجِدُ، قَالَ: "فَيَصُومُ شَهْرَيْنِ مُتَتَابِعَيْنِ". قَالَتْ: يَا رَسُولَ اللهِ، إِنَّهُ شَيْخٌ كَبِيرٌ مَا بِهِ مِنْ صِيَامٍ. قَالَ: "فَلْيُطْعِمْ سِتِّينَ مِسْكِينًا". قَالَتْ: مَا عِنْدَهُ مِنْ شَيْءٍ يَتَصَدَّقُ بِهِ، قَالَتْ: فَأُتِيَ سَاعَتَئِذٍ بِعَرَقٍ مِنْ تَمْرٍ، قُلْتُ: يَا رَسُولَ اللهِ، فَإِنِّي أُعِينُهُ بِعَرَقٍ آخَرَ، قَالَ: "قَدْ أَحْسَنْتِ، اذْهَبِي فَأَطْعِمِي بِهَا عَنْهُ سِتِّينَ مِسْكِينًا، وَارْجِعِي إِلَى ابْنِ عَمِّكِ". قَالَ: وَالْعَرَقُ سِتُّونَ صَاعًا. وَفِي رِوَايَةٍ: وَالْعَرَقُ: مِكْتَلٌ يَسَعُ ثَلَاثِينَ صَاعًا. وَفِي رِوَايَةٍ: قَالَ: يَعْنِي بِالْعَرَقِ زِنْبِيلًا يَأْخُذُ خَمْسَةَ عَشَرَ صَاعًا. وَفِي رِوَايَةٍ: قَالَ: فَأُتِيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِتَمْرٍ، فَأَعْطَاهُ إِيَّاهُ، وَهُوَ قَرِيبٌ مِنْ خَمْسَةَ عَشَرَ صَاعًا، قَالَ: "تَصَدَّقْ بِهَذَا". قَالَ: يَا رَسُولَ اللهِ، عَلَى أَفْقَرَ مِنِّي وَمِنْ أَهْلِي؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُلْهُ أَنْتَ وَأَهْلُكَ". (د)', 'ഖുവൈലതുബിൻത് മാലികുബ്നു സഅ്ലബ(റ): എന്റെ ഭർത്താവ് ഔസുബ്നുസ്സാമിത്(റ) എന്നെ ളിഹാർ ചെയ്തു. അങ്ങനെ അദ്ദേഹത്തെക്കുറിച്ച് പരാതിപ്പെട്ടുകൊണ്ട് ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നു. റസൂൽ(സ) എന്നോട് തർക്കിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്യുന്നുണ്ടായിരുന്നു: "നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുക, അവൻ നിന്റെ പിതൃവ്യപുത്രനാണ്." ശേഷം ''തന്റെ ഭർത്താവിന്റെ വിഷയത്തിൽ അങ്ങയോട് തർക്കിക്കുന്നവളുടെ വാക്കിനെ അല്ലാഹു കേട്ടിരിക്കുന്നു'' എന്ന് തുടങ്ങി ളിഹാറിന്റെ പ്രായശ്ചിത്തം വിശദീകരിക്കുന്നത് വരെയുള്ള സൂക്തങ്ങൾ അവതരിക്കും വരെ ഞാൻ അവിടത്തോട് തർക്കിച്ചു കൊണ്ടിരുന്നു. ശേഷം റസൂൽ(സ) പറഞ്ഞു: "അവൻ (ഔസ്(റ)) ഒരു അടിമയെ മോചിപ്പിക്കണം." അവർ പറഞ്ഞു: അദ്ദേഹത്തിനത് ലഭിക്കുകയില്ല. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിലവൻ തുടർച്ചയായ രണ്ട് മാസം നോമ്പനുഷ്ഠിക്കണം." അവർ പറഞ്ഞു: റസൂലേ, അദ്ദേഹം പ്രായമായ വ്യക്തിയാണ്, അദ്ദേഹത്തിന് നോമ്പനുഷ്ഠിക്കാൻ സാധിക്കില്ല. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ അറുപത് ദരിദ്രർക്ക് ഭക്ഷണം നൽകിക്കൊള്ളട്ടെ." അവർ പറഞ്ഞു: ധാനം ചെയ്യാൻ പറ്റിയ ഒന്നും അദ്ദേഹത്തിനടുത്തില്ല. നിവേദക പറയുന്നു: അന്നേരം ഒരു അറക് (ഈത്തപ്പനയുടെ പട്ട കൊണ്ടുണ്ടാക്കുന്ന പാത്രം) നിറയെ കാരക്ക നബി(സ)യുടെ അടുത്ത് കൊണ്ടുവരപ്പെട്ടു. ഞാൻ പറഞ്ഞു: റസൂലേ, മറ്റൊരു പാത്രം നിറയെ കാരക്കകൂടി നൽകി ഞാനദ്ദേഹത്തെ സഹായിക്കും. റസൂൽ(സ) പറഞ്ഞു: "വളരെ നല്ലത്, നീ ഇത് കൊണ്ടുപോകുകയും അദ്ദേഹത്തിന് പകരമായി അറുപത് ദരിദ്രർക്ക് ഭക്ഷിപ്പിക്കുകയും ചെയ്യുക. ശേഷം നിന്റെ പിതൃവ്യപുത്രന്റെയടുത്തേക്ക് മടങ്ങുകയും ചെയ്യുക." നിവേദകൻ പറയുന്നു: അറക് എന്നാൽ അറുപത് സ്വാആണ്. മറ്റൊരു നിവേദനം: അറക് എന്നാൽ മുപ്പത് സ്വാഅ് കൊള്ളുന്ന ഒരു അളവ് പാത്രമാണ്. മറ്റൊരു നിവേദനം: അറക് എന്നാൽ പതിനഞ്ച് സ്വാഅ് കൊള്ളുന്ന പാത്രമാണ്. മറ്റൊരു നിവേദനം: അങ്ങനെ റസൂൽ(സ)യുടെ അടുത്ത് കുറെ കാരക്ക കൊണ്ടുവരപ്പെടുകയും അവ ഔസ്(റ)വിന് നബി(സ) നൽകുകയും ചെയ്തു. ആ കാരക്ക പതിനഞ്ച് സ്വാഓളം ഉണ്ടായിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "ഇത് നീ ദാനം ചെയ്യുക." അദ്ദേഹം ചോദിച്ചു: റസൂലേ, എന്നെക്കാളും എന്റെ കുടുംബത്തേക്കാളും ദരിദ്രരായവർക്കോ? തിരുമേനി(സ) പറഞ്ഞു: "അത് നീയും നിന്റെ കുടുംബവും ഭക്ഷിക്കുക." (ദ)', 'خُوَيْلَةَ بِنْتِ مَالِكِ بْنِ ثَعْلَبَةَ', 'ഖുവൈലതുബിൻത് മാലികുബ്നു സഅ്ലബ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'المجادلة: ١', null, 174, 175, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=77), 1, 'وَفِي رِوَايَةٍ: وَالْعَرَقُ: مِكْتَلٌ يَسَعُ ثَلَاثِينَ صَاعًا.', 'മറ്റൊരു നിവേദനം: അറക് എന്നാൽ മുപ്പത് സ്വാഅ് കൊള്ളുന്ന ഒരു അളവ് പാത്രമാണ്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=77), 2, 'وَفِي رِوَايَةٍ: قَالَ: يَعْنِي بِالْعَرَقِ زِنْبِيلًا يَأْخُذُ خَمْسَةَ عَشَرَ صَاعًا.', 'മറ്റൊരു നിവേദനം: അറക് എന്നാൽ പതിനഞ്ച് സ്വാഅ് കൊള്ളുന്ന പാത്രമാണ്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=77), 3, 'وَفِي رِوَايَةٍ: قَالَ: فَأُتِيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِتَمْرٍ، فَأَعْطَاهُ إِيَّاهُ، وَهُوَ قَرِيبٌ مِنْ خَمْسَةَ عَشَرَ صَاعًا، قَالَ: "تَصَدَّقْ بِهَذَا". قَالَ: يَا رَسُولَ اللهِ، عَلَى أَفْقَرَ مِنِّي وَمِنْ أَهْلِي؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُلْهُ أَنْتَ وَأَهْلُكَ". (د)', 'മറ്റൊരു നിവേദനം: അങ്ങനെ റസൂൽ(സ)യുടെ അടുത്ത് കുറെ കാരക്ക കൊണ്ടുവരപ്പെടുകയും അവ ഔസ്(റ)വിന് നബി(സ) നൽകുകയും ചെയ്തു. ആ കാരക്ക പതിനഞ്ച് സ്വാഓളം ഉണ്ടായിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "ഇത് നീ ദാനം ചെയ്യുക." അദ്ദേഹം ചോദിച്ചു: റസൂലേ, എന്നെക്കാളും എന്റെ കുടുംബത്തേക്കാളും ദരിദ്രരായവർക്കോ? തിരുമേനി(സ) പറഞ്ഞു: "അത് നീയും നിന്റെ കുടുംബവും ഭക്ഷിക്കുക." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ أَوْسٍ أَخِي عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَعْطَاهُ خَمْسَةَ عَشَرَ صَاعًا مِنْ شَعِيرٍ، إِطْعَامَ سِتِّينَ مِسْكِينًا. (د)', 'ഉബാദതുബ്നു സാമിത്(റ)വിന്റെ സഹോദരൻ ഔസ്(റ): അറുപത് ദരിദ്രരെ ഭക്ഷിപ്പിക്കുന്നതിന് വേണ്ടി നബി(സ) അദ്ദേഹത്തിന് പതിനഞ്ച് സ്വാഅ് ബാർലി നൽകി. (ദ)', 'أَوْسٍ أَخِي عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സാമിത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 175, 175, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ هِشَامِ بْنِ عُرْوَةَ: أَنَّ جَمِيلَةَ كَانَتْ تَحْتَ أَوْسِ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُمَا، وَكَانَ رَجُلًا بِهِ لَمَمٌ، فَكَانَ إِذَا اشْتَدَّ لَمَمُهُ ظَاهَرَ مِنِ امْرَأَتِهِ، فَأَنْزَلَ اللهُ تَعَالَى فِيهِ كَفَّارَةَ الظِّهَارِ. وفي رواية: عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، مِثْلَهُ. (د)', 'ഹിശാമുബ്നു ഉർവ(റ): ജമീല(റ) ഔസുബ്നു സാമിത്(റ)വിന്റെ ഭാര്യയായിരുന്നു. അദ്ദേഹം ഭാര്യയുമായി കൂടുതൽ ബന്ധപ്പെടുന്ന വ്യക്തിയായിരുന്നു. തന്റെ വികാരം അധികമായാൽ തന്റെ ഭാര്യയെ ളിഹാർ ചെയ്യുമായിരുന്നു. അങ്ങനെ അദ്ദേഹത്തിന്റെ വിഷയത്തിൽ അല്ലാഹു ളിഹാറിന്റെ പ്രായശ്ചിത്തം വിശദീകരിച്ച് കൊണ്ട് സൂക്തമിറക്കി. മറ്റൊരു നിവേദനം: ആഇശ(റ)യിൽ നിന്ന് ഉർവ്വ(റ) മുഖേന ഹിശാമുബ്നു ഉർവ(റ) ഇത് പോലുള്ള ഒരു ഹദീസ് നിവേദനം ചെയ്തിരിക്കുന്നു. (ദ)', 'هِشَامِ بْنِ عُرْوَةَ', 'ഹിശാമുബ്നു ഉർവ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 175, 175, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=79), 1, 'وَفِي رِوَايَةٍ: عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، مِثْلَهُ. (د)', 'മറ്റൊരു നിവേദനം: ആഇശ(റ)യിൽ നിന്ന് ഉർവ്വ(റ) മുഖേന ഹിശാമുബ്നു ഉർവ(റ) ഇത് പോലുള്ള ഒരു ഹദീസ് നിവേദനം ചെയ്തിരിക്കുന്നു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ سَلَمَةَ بْنِ صَخْرٍ الْبَيَاضِيِّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - فِي الْمُظَاهِرِ يُوَاقِعُ قَبْلَ أَنْ يُكَفِّرَ - قَالَ: "كَفَّارَةٌ وَاحِدَةٌ". (ت,جه)', 'സലമതുബ്നു സ്വഖ്റുൽ ബയാളീ(റ): ളിഹാർ ചെയ്ത് പ്രായശ്ചിത്തം നൽകുന്നതിന് മുമ്പ് ഭാര്യയുമായി ബന്ധപ്പെട്ട വ്യക്തിയെക്കുറിച്ച് നബി(സ) പറഞ്ഞു: "ഒരു പ്രായശ്ചിത്തം മാത്രം മതി." (തു,ജ)', 'سَلَمَةَ بْنِ صَخْرٍ الْبَيَاضِيِّ', 'സലമതുബ്നു സ്വഖ്റുൽ ബയാളീ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 176, 176, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ سَلْمَانَ بْنِ صَخْرٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: جَعَلَ امْرَأَتَهُ عَلَيْهِ كَظَهْرِ أُمِّهِ حَتَّى يَمْضِيَ رَمَضَانُ، فَلَمَّا مَضَى نِصْفٌ مِنْ رَمَضَانَ وَقَعَ عَلَيْهَا لَيْلًا، فَأَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَعْتِقْ رَقَبَةً". قَالَ: لَا أَجِدُهَا. قَالَ: "فَصُمْ شَهْرَيْنِ مُتَتَابِعَيْنِ". قَالَ: لَا أَسْتَطِيعُ. قَالَ: "أَطْعِمْ سِتِّينَ مِسْكِينًا". قَالَ: لَا أَجِدُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِفَرْوَةَ بْنِ عَمْرٍو: "أَعْطِهِ ذَلِكَ الْعَرَقَ - وَهُوَ مِكْتَلٌ يَأْخُذُ خَمْسَةَ عَشَرَ صَاعًا أَوْ سِتَّةَ عَشَرَ صَاعًا - إِطْعَامَ سِتِّينَ مِسْكِينًا". حَسَنٌ. (د,ت,جه)', 'സൽമാനുബ്നു സ്വഖ്റുൽ അൻസാരി(റ): റമളാൻ കഴിയും വരെ അദ്ദേഹം തന്റെ ഭാര്യയെ ളിഹാർ ചെയ്യുകയും റമളാനിലെ പകുതി ഭാഗം കഴിഞ്ഞപ്പോൾ അവളുമായി രാത്രിയിൽ ബന്ധപ്പെടുകയും ചെയ്തു. ശേഷം റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് വിവരം പറഞ്ഞു. റസൂൽ(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "നീ ഒരു അടിമയെ മോചിപ്പിക്കുക." അദ്ദേഹം പറഞ്ഞു: എനിക്ക് അടിമയെ ലഭിക്കാൻ വഴിയില്ല. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ നീ രണ്ട് മാസം തുടർച്ചയായി നോമ്പനുഷ്ഠിക്കുക." അദ്ദേഹം പറഞ്ഞു: എനിക്കതിന് സാധിക്കുകയില്ല. റസൂൽ(സ) പറഞ്ഞു: "നീ അറുപത് ദരിദ്രർക്ക് ഭക്ഷണം നൽകുക." അദ്ദേഹം പറഞ്ഞു: എനിക്ക് ആ ഭക്ഷണം ലഭിക്കാൻ ഒരു വഴിയുമില്ല. അപ്പോൾ റസൂൽ(സ) ഫർവതുബ്നു അംറ്(റ)വിനോട് പറഞ്ഞു: "അറുപത് ദരിദ്രർക്ക് ഭക്ഷണം നൽകാൻ വേണ്ടി ആ അറക് കാരക്ക നീ അവന് നൽകുക." അറക് എന്നാൽ പതിനഞ്ചോ പതിനാറോ സ്വാഅ് കൊള്ളുന്ന ഒരു അളവു പാത്രമാണ്. (ദ,തു,ജ)', 'سَلْمَانَ بْنِ صَخْرٍ الْأَنْصَارِيِّ', 'സൽമാനുബ്നു സ്വഖ്റുൽ അൻസാരി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 176, 176, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ عَمْرَةَ بِنْتَ الْجَوْنِ تَعَوَّذَتْ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ أُدْخِلَتْ عَلَيْهِ، فَقَالَ: "لَقَدْ عُذْتِ بِمُعَاذٍ". فَطَلَّقَهَا، وَأَمَرَ أُسَامَةَ - أَوْ: أَنَسًا - فَمَتَّعَهَا بِثَلَاثَةِ أَثْوَابٍ رَازِقِيَّةٍ. [ز: في سنده ضعيف مُتَّهم بالوضع] (جه)', 'ആഇശ(റ): അംറത് ബിൻതു ജൗൻ എന്ന സ്ത്രീയെ റസൂൽ(സ)യുടെ അടുത്ത് കൊണ്ടുവന്നപ്പോൾ അവൾ റസൂൽ(സ)യിൽ നിന്ന് അല്ലാഹുവിനോട് കാവൽ ചോദിച്ചു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "കാവൽ ചോദിക്കേണ്ട ഒരാളോടാണ് നീ കാവൽ ചോദിച്ചിരിക്കുന്നത്." ശേഷം റസൂൽ(സ) ആ സ്ത്രീയെ വിവാഹമോചനം ചെയ്യുകയും അവൾക്ക് ആശ്വാസധനമായി പരുത്തിയുടെ മൂന്ന് വെള്ള വസ്ത്രങ്ങൾ നൽകാൻ ഉസാമ(റ)വിനോട്, അല്ലെങ്കിൽ അനസ്(റ)വിനോട്, കൽപിക്കുകയും ചെയ്തു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف مُتَّهم بالوضع', null, 176, 176, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَسْأَلُ الْمَرْأَةُ زَوْجَهَا الطَّلَاقَ فِي غَيْرِ كُنْهِهِ فَتَجِدَ رِيحَ الْجَنَّةِ، وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ أَرْبَعِينَ عَامًا". [ز: إسناده ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ഒരു കാരണവുമില്ലാതെ തന്റെ ഭർത്താവിനോട് വിവാഹമോചനമാവശ്യപ്പെടുന്ന സ്ത്രീ സ്വർഗ്ഗത്തിന്റെ വാസന എത്തിക്കുകയില്ല. നിശ്ചയം അതിന്റെ വാസന നാൽപ്പത് വർഷത്തെ വഴിദൂരത്തേക്ക് വരെ എത്തുന്നതാണ്." (ഇതിന്റെ പരമ്പരയിൽ ഭംഗമുള്ളവരുണ്ട്) (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: إسناده ضعيف', null, 176, 177, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمُنْتَزِعَاتُ وَالْمُخْتَلِعَاتُ هُنَّ الْمُنَافِقَاتُ". (ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "കാരണമില്ലാതെയും പ്രതിഫലം നൽകിയും വിവാഹമോചനം ചോദിക്കുന്ന സ്ത്രീകളാണ് കപടവിശ്വാസിനികൾ." (തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 177, 177, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ حَبِيبَةَ بِنْتِ سَهْلٍ رَضِيَ اللهُ عَنْهَا: أَنَّهَا كَانَتْ تَحْتَ ثَابِتِ بْنِ قَيْسِ بْنِ شَمَّاسٍ، وَأَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ إِلَى الصُّبْحِ فَوَجَدَ حَبِيبَةَ بِنْتَ سَهْلٍ عِنْدَ بَابِهِ فِي الْغَلَسِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ هَذِهِ". قَالَتْ: أَنَا حَبِيبَةُ بِنْتُ سَهْلٍ يَا رَسُولَ اللهِ. قَالَ: "مَا شَأْنُكِ؟" قَالَتْ: لَا أَنَا وَلَا ثَابِتُ بْنُ قَيْسٍ، لِزَوْجِهَا، فَلَمَّا جَاءَ ثَابِتُ بْنُ قَيْسٍ قَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هَذِهِ حَبِيبَةُ بِنْتُ سَهْلٍ، قَدْ ذَكَرَتْ مَا شَاءَ اللهُ أَنْ تَذْكُرَ". فَقَالَتْ حَبِيبَةُ: يَا رَسُولَ اللهِ، كُلُّ مَا أَعْطَانِي عِنْدِي. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِثَابِتٍ: "خُذْ مِنْهَا". فَأَخَذَ مِنْهَا وَجَلَسَتْ فِي أَهْلِهَا. (د,ن)', 'ഹബീബ ബിൻത് സഹ്ൽ(റ): മഹതി സാബിതുബ്നു ഖൈസുബ്നു ശമ്മാസ്(റ)വിന്റെ ഭാര്യയായിരുന്നു. ഒരിക്കൽ റസൂൽ(സ) സുബ്ഹി നമസ്കാരത്തിന് പുറപ്പെട്ടപ്പോൾ ഇരുട്ടത്ത് തന്റെ വാതിൽക്കൽ ഹബീബ ബിൻത് സഹ്ൽ(റ) നിൽക്കുന്നത് കണ്ടു. റസൂൽ(സ) ചോദിച്ചു: "ആരാണിത്." മഹതി പറഞ്ഞു: ഇത് ഹബീബ ബിൻത് സഹ്ൽ ആണ്. തിരുമേനി(സ) ചോദിച്ചു: "എന്താണ് നിന്റെ പ്രശ്നം?" മഹതി പറഞ്ഞു: എനിക്കും എന്റെ ഭർത്താവ് സാബിതുബ്നു ഖൈസ്(റ)വിനും ഒരുമിച്ചുകഴിയാൻ സാധിക്കുകയില്ല. ശേഷം സാബിതുബ്നു ഖൈസ്(റ) വന്നപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "ഇത് ഹബീബ ബിൻത് സഹ്ലാണ്, തനിക്ക് പറയാനുള്ളതെല്ലാം അവൾ പറഞ്ഞിരിക്കുന്നു." ഹബീബ(റ) പറഞ്ഞു: റസൂലേ, അദ്ദേഹം എനിക്ക് തന്നതെല്ലാം (മഹ്റ്) എന്റെയടുത്തുണ്ട്. റസൂൽ(സ) സാബിതുബ്നു ഖൈസ്(റ)വിനോട് പറഞ്ഞു: "അത് അവളിൽ നിന്ന് വാങ്ങുക." അങ്ങനെ സാബിത്(റ) ഹബീബ(റ)യിൽ നിന്ന് ആ മുതൽ സ്വീകരിക്കുകയും ശേഷം മഹതി തന്റെ കുടുംബത്തോടൊപ്പം താമസിക്കുകയും ചെയ്തു. (ദ,ന)', 'حَبِيبَةَ بِنْتِ سَهْلٍ', 'ഹബീബ ബിൻത് സഹ്ൽ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 177, 177, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ حَبِيبَةَ بِنْتَ سَهْلٍ كَانَتْ عِنْدَ ثَابِتِ بْنِ قَيْسِ بْنِ شَمَّاسٍ، فَضَرَبَهَا فَكَسَرَ بَعْضَهَا، فَأَتَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاشْتَكَتْهُ إِلَيْهِ، فَدَعَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثَابِتًا فَقَالَ: "خُذْ بَعْضَ مَالِهَا وَفَارِقْهَا". فَقَالَ: وَيَصْلُحُ ذَلِكَ يَا رَسُولَ اللهِ؟ قَالَ: "نَعَمْ". قَالَ: فَإِنِّي أَصْدَقْتُهَا حَدِيقَتَيْنِ وَهُمَا بِيَدِهَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خُذْهُمَا وَفَارِقْهَا". فَفَعَلَ. (د)', 'ആഇശ(റ): ഹബീബതുബിൻതു സഹ്ല്(റ) സാബിതുബ്നു ഖൈസ്(റ)വിന്റെ ഭാര്യയായിരുന്നു. സാബിത്(റ) മഹതിയെ അടിക്കുകയും ഒരു അവയവത്തിൽ മുറിവേൽപ്പിക്കുകയും ചെയ്തു. ശേഷം മഹതി റസൂൽ(സ)യുടെ അടുത്ത് വരികയും തന്റെ ഭർത്താവിനെക്കുറിച്ച് പരാതിപ്പെടുകയും ചെയ്തു. അപ്പോൾ നബി(സ) സാബിത്(റ)വിനെ വിളിച്ചു. എന്നിട്ട് പറഞ്ഞു: "അവളുടെ മുതലിന്റെ അൽപഭാഗം നീ വാങ്ങുകയും അവളെ പിരിയുകുയം ചെയ്യുക." അദ്ദേഹം ചോദിച്ചു: അത് പറ്റുമോ, റസൂലേ? റസൂൽ(സ) പറഞ്ഞു: "അതെ." അദ്ദേഹം പറഞ്ഞു: ഞാൻ അവൾക്ക് രണ്ട് തോട്ടങ്ങൾ മഹ്റായി നൽകിയിട്ടുണ്ട്. അവ രണ്ടും അവളുടെ കയ്യിൽ തന്നെയുണ്ട്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "എങ്കിൽ അത് രണ്ടും നീ വാങ്ങുകയും അവളെ പിരിയുകയും ചെയ്യുക." അദ്ദേഹം അപ്രകാരം ചെയ്തു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 177, 177, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةَ ثَابِتِ بْنِ قَيْسٍ اخْتَلَعَتْ مِنْهُ، فَجَعَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عِدَّتَهَا حَيْضَةً. (د,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): സാബിതുബ്നു ഖൈസ്(റ)വിന്റെ ഭാര്യ അദ്ദേഹത്തിന് നഷ്ടപരിഹാരം നൽകി വിവാഹമോചിതയായി. അങ്ങനെ നബി(സ) അവർക്ക് ഒരു ആർത്തവത്തിന്റെ കാലം ഇദ്ദ (മറയിരിക്കൽ) നിശ്ചയിച്ചു. (ദ,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 177, 178, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ جَمِيلَةَ بِنْتَ سَلُولٍ - رَضِيَ اللهُ عَنْهَا - أَتَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: وَاللهِ، مَا أَعْتِبُ عَلَى ثَابِتٍ فِي دِينٍ وَلَا خُلُقٍ، وَلَكِنِّي أَكْرَهُ الْكُفْرَ فِي الْإِسْلَامِ، لَا أُطِيقُهُ بُغْضًا. فَقَالَ لَهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَتَرُدِّينَ عَلَيْهِ حَدِيقَتَهُ". قَالَتْ: نَعَمْ. فَأَمَرَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَأْخُذَ مِنْهَا حَدِيقَتَهُ وَلَا يَزْدَادَ. (خ,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ജമീല ബിൻത് സലൂൽ(റ) നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, സ്വഭാവത്തിന്റെ വിഷയത്തിലോ മതചിട്ടയുടെ വിഷയത്തിലോ ഞാൻ സാബിത്(റ)വിനെ ആക്ഷേപിക്കുന്നില്ല. പക്ഷേ, മുസ്ലിമായ ശേഷവും ദൈവനിഷേധത്തിന്റെ സ്വഭാവങ്ങൾ വന്നുചേരുന്നത് ഞാൻ വെറുക്കുന്നു. അദ്ദേഹത്തിന്റെ ദേഷ്യം എനിക്ക് സഹിക്കാൻ കഴിയുകയില്ല. അപ്പോൾ നബി(സ) മഹതിയോട് പറഞ്ഞു: "അദ്ദേഹത്തിന്റെ തോട്ടം നീ തിരികെ നൽകുമോ?" മഹതി പറഞ്ഞു: അതെ. അപ്പോൾ റസൂൽ(സ) സാബിത്(റ)വിനോട് ആ തോട്ടം തിരികെ വാങ്ങാനും അതിൽ കൂടുതൽ വാങ്ങാതിരിക്കാനും കൽപിച്ചു. (ബു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','ن','جه']::text[], array['ബു','ന','ജ']::text[], null, null, 178, 178, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: قَالَ: كَانَتْ حَبِيبَةُ بِنْتُ سَهْلٍ تَحْتَ ثَابِتِ بْنِ قَيْسِ بْنِ شَمَّاسٍ، وَكَانَ رَجُلًا دَمِيمًا، فَقَالَتْ: يَا رَسُولَ اللهِ، وَاللهِ، لَوْلَا مَخَافَةُ اللهِ: إِذَا دَخَلَ عَلَيَّ لَبَصَقْتُ فِي وَجْهِهِ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَتَرُدِّينَ عَلَيْهِ حَدِيقَتَهُ". قَالَتْ: نَعَمْ. فَرَدَّتْ عَلَيْهِ حَدِيقَتَهُ. قَالَ فَفَرَّقَ بَيْنَهُمَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ . [ز: في إسناده مدلس عنعنه] (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഹബീബ ബിൻത് സഹ്ല്(റ) സാബിതുബ്നു ഖൈസിബ്നി ശമ്മാസ്(റ)വിന്റെ ഭാര്യയായിരുന്നു. അദ്ദേഹം ചില മോശസ്വഭാവങ്ങളുള്ള (ദേഷ്യം അധികരിച്ച) മനുഷ്യനായിരുന്നു. അങ്ങനെ ഹബീബ(റ) നബി(സ)യോട് പറഞ്ഞു: റസൂലേ, അല്ലാഹുവിനെ തന്നെ സത്യം, അല്ലാഹുവിനെ പേടിയില്ലായിരുന്നെങ്കിൽ അദ്ദേഹം എന്റെയടുത്തേക്ക് വരുമ്പോൾ ഞാനദ്ദേഹത്തിന്റെ മുഖത്തേക്ക് തുപ്പുമായിരുന്നു. റസൂൽ(സ) ചോദിച്ചു: "നീ അദ്ദേഹത്തിന്റെ തോട്ടം തിരിച്ചു നൽകുമോ?" മഹതി പറഞ്ഞു: അതെ. നിവേദകൻ പറയുന്നു: അങ്ങനെ മഹതി സാബിത്(റ)വിന് തോട്ടം തിരിച്ച് നൽകുകയും റസൂൽ(സ) അവർ ഇരുവരെയും വേർപിരിക്കുകും ചെയ്തു. (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مدلس عنعنه', null, 178, 178, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، وَقَدْ سُئِلَ عَنْ عَبْدٍ طَلَّقَ امْرَأَتَهُ تَطْلِيقَتَيْنِ ثُمَّ أُعْتِقَا، يَتَزَوَّجُهَا؟ قَالَ: نَعَمْ. فَقِيلَ لَهُ: عَمَّنْ؟ قَالَ: قَضَى بِذَلِكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ . (د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു അടിമ തന്റെ ഭാര്യയെ രണ്ട് ത്വലാഖും ചൊല്ലിയ ശേഷം ഇരുവരും മോചിതരാക്കപ്പെട്ടാൽ ശേഷം അവളെ അവന് വിവാഹം കഴിക്കാൻ പറ്റുമോ? എന്ന് ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: അതെ. അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. ഈ വിധി ആരിൽ നിന്ന് കിട്ടിയതാണ്? അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) അപ്രകാരം വിധിച്ചിട്ടുണ്ട്. (ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 178, 178, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، وَهُوَ يُحَدِّثُ حَدِيثَهُ حِينَ تَخَلَّفَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ، وَقَالَ فِيهِ: إِذَا رَسُولُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْتِينِي فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكَ أَنْ تَعْتَزِلَ امْرَأَتَكَ. فَقُلْتُ: أُطَلِّقُهَا أَمْ مَاذَا؟ قَالَ: لَا، بَلِ اعْتَزِلْهَا فَلَا تَقْرَبْهَا – وَفِي رِوَايَةٍ: وَأَرْسَلَ إِلَى صَاحِبَيَّ بِمِثْلِ ذَلِكَ – فَقُلْتُ لِامْرَأَتِي: الْحَقِي بِأَهْلِكِ فَكُونِي عِنْدَهُمْ حَتَّى يَقْضِيَ اللَّهُ عَزَّ وَجَلَّ فِي هَذَا الْأَمْرِ○. وَفِي رِوَايَةٍ قَالَ: أَرْسَلَ إِلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَإِلَى صَاحِبَيَّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكُمْ أَنْ تَعْتَزِلُوا نِسَاءَكُمْ. فَقُلْتُ لِلرَّسُولِ: أُطَلِّقُ امْرَأَتِي أَمْ مَاذَا أَفْعَلُ؟ قَالَ: لَا، بَلْ تَعْتَزِلُهَا فَلَا تَقْرَبْهَا. فَقُلْتُ لِامْرَأَتِي: الْحَقِي بِأَهْلِكِ، فَكُونِي فِيهِمْ، فَلَحِقَتْ بِهِمْ. وَفِي رِوَايَةٍ: وَأَرْسَلَ إِلَى صَاحِبَيَّ بِمِثْلِ ذَلِكَ، فَقُلْتُ لِامْرَأَتِي: الْحَقِي بِأَهْلِكِ وَكُونِي عِنْدَهُمْ، حَتَّى يَقْضِيَ اللَّهُ عَزَّ وَجَلَّ فِي هَذَا الْأَمْرِ○. وَفِي رِوَايَةٍ: أَرْسَلَ إِلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَإِلَى صَاحِبَيَّ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكُمْ أَنْ تَعْتَزِلُوا نِسَاءَكُمْ. (ن)', 'കഅ്ബുബ്നു മാലിക്(റ): തബൂക് യുദ്ധത്തിൽ റസൂൽ(സ)യുടെ സംഘത്തിൽ നിന്ന് താൻ പിന്തിനിന്ന സംഭവം വിശദീകരിക്കുന്നതിനിടയിൽ അദ്ദേഹം പറഞ്ഞു: അങ്ങനെയിരിക്കെ റസൂൽ(സ)യുടെ ദൂതൻ എന്റെയടുത്ത് വന്നു പറഞ്ഞു: അങ്ങയുടെ ഭാര്യയെ വെടിയാൻ റസൂൽ(സ) അങ്ങയോട് കൽപിക്കുന്നു. ഞാൻ ചോദിച്ചു: ഞാൻ അവളെ വിവാഹമോചനം ചെയ്യണോ, അല്ലെങ്കിൽ എന്ത് ചെയ്യണം? ദൂതൻ പറഞ്ഞു: വിവാഹമോചനം ചെയ്യേണ്ടതില്ല, നീ അവളെ വെടിയുക, അവളോട് അടുക്കരുത്. മറ്റൊരു നിവേദനം: എന്റെ ഒപ്പമുണ്ടായിരുന്ന രണ്ടാളുകളിലേക്ക് റസൂൽ(സ) അപ്രകാരം പറഞ്ഞയച്ചു. അങ്ങനെ ഞാൻ എന്റെ ഭാര്യയോട് പറഞ്ഞു: നീ നിന്റെ കുടുംബക്കാരുടെ അടുത്ത് പോകുകയും ഈ കാര്യത്തിൽ അല്ലാഹു വിധി പറയുംവരെ അവരോടൊപ്പം കഴിയുകയും ചെയ്യുക. മറ്റൊരു നിവേദനം: കഅ്ബ്(റ) പറഞ്ഞു: റസൂൽ(സ) എന്റെ അടുത്തേക്കും എന്റെ ഒപ്പമുള്ള രണ്ട് ആളുകളുടെ അടുത്തേക്കും ആളെ അയച്ച് പറഞ്ഞു: റസൂൽ(സ) നിങ്ങളോട് ഭാര്യമാരെ വെടിയാൻ കൽപിക്കുന്നു. ഞാൻ ആ ദൂതനോട് ചോദിച്ചു: ഞാൻ എന്റെ ഭാര്യയെ വിവാഹമോചനം നടത്തണോ, അല്ലെങ്കിൽ ഞാൻ എന്താണ് ചെയ്യേണ്ടത്? അദ്ദേഹം പറഞ്ഞു: വിവാഹമോചനം നടത്തേണ്ടതില്ല, നീ അവളെ വെടയുക, അവളോട് അടുക്കരുത്. ഞാൻ എന്റെ ഭാര്യയോട് പറഞ്ഞു: നീ നിന്റെ കുടുംബക്കാരുടെ അടുത്തേക്ക് പോകുകയും അവരോടൊപ്പം കഴിയുകയും ചെയ്യുക. അങ്ങനെ അവൾ തന്റെ കുടുംബക്കാരുടെ അടുത്തേക്ക് പോയി. മറ്റൊരു നിവേദനം: എന്റെ രണ്ട് കൂട്ടുകാരുടെ അടുത്തേക്ക് കൂടെ റസൂൽ(സ) അപ്രകാരം പറഞ്ഞയച്ചു. ഞാൻ എന്റെ ഭാര്യയോട് പറഞ്ഞു: നീ നിന്റെ കുടുംബക്കാരുടെ അടുത്ത് പോകുകയും ഈ വിഷയത്തിൽ അല്ലാഹു വിധി പറയുംവരെ അവരോടൊപ്പം കഴിയുകയും ചെയ്യുക. മറ്റൊരു നിവേദനം: എന്നിലേക്കും എന്റെ രണ്ട് കൂട്ടുകാരുടെ അടുത്തേക്കും റസൂൽ(സ) ആളെ പറഞ്ഞയച്ച് കൊണ്ട് പറഞ്ഞു: റസൂൽ(സ) നിങ്ങളോട് നിങ്ങളുടെ ഭാര്യമാരെ വെടിയാൻ കൽപിക്കുന്നു. (ന)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 179, 179, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=91), 1, 'وَفِي رِوَايَةٍ: وَأَرْسَلَ إِلَى صَاحِبَيَّ بِمِثْلِ ذَلِكَ – فَقُلْتُ لِامْرَأَتِي: الْحَقِي بِأَهْلِكِ فَكُونِي عِنْدَهُمْ حَتَّى يَقْضِيَ اللَّهُ عَزَّ وَجَلَّ فِي هَذَا الْأَمْرِ○.', 'മറ്റൊരു നിവേദനം: എന്റെ ഒപ്പമുണ്ടായിരുന്ന രണ്ടാളുകളിലേക്ക് റസൂൽ(സ) അപ്രകാരം പറഞ്ഞയച്ചു. അങ്ങനെ ഞാൻ എന്റെ ഭാര്യയോട് പറഞ്ഞു: നീ നിന്റെ കുടുംബക്കാരുടെ അടുത്ത് പോകുകയും ഈ കാര്യത്തിൽ അല്ലാഹു വിധി പറയുംവരെ അവരോടൊപ്പം കഴിയുകയും ചെയ്യുക.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=91), 2, 'وَفِي رِوَايَةٍ قَالَ: أَرْسَلَ إِلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَإِلَى صَاحِبَيَّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكُمْ أَنْ تَعْتَزِلُوا نِسَاءَكُمْ. فَقُلْتُ لِلرَّسُولِ: أُطَلِّقُ امْرَأَتِي أَمْ مَاذَا أَفْعَلُ؟ قَالَ: لَا، بَلْ تَعْتَزِلُهَا فَلَا تَقْرَبْهَا. فَقُلْتُ لِامْرَأَتِي: الْحَقِي بِأَهْلِكِ، فَكُونِي فِيهِمْ، فَلَحِقَتْ بِهِمْ.', 'മറ്റൊരു നിവേദനം: കഅ്ബ്(റ) പറഞ്ഞു: റസൂൽ(സ) എന്റെ അടുത്തേക്കും എന്റെ ഒപ്പമുള്ള രണ്ട് ആളുകളുടെ അടുത്തേക്കും ആളെ അയച്ച് പറഞ്ഞു: റസൂൽ(സ) നിങ്ങളോട് ഭാര്യമാരെ വെടിയാൻ കൽപിക്കുന്നു. ഞാൻ ആ ദൂതനോട് ചോദിച്ചു: ഞാൻ എന്റെ ഭാര്യയെ വിവാഹമോചനം നടത്തണോ, അല്ലെങ്കിൽ ഞാൻ എന്താണ് ചെയ്യേണ്ടത്? അദ്ദേഹം പറഞ്ഞു: വിവാഹമോചനം നടത്തേണ്ടതില്ല, നീ അവളെ വെടയുക, അവളോട് അടുക്കരുത്. ഞാൻ എന്റെ ഭാര്യയോട് പറഞ്ഞു: നീ നിന്റെ കുടുംബക്കാരുടെ അടുത്തേക്ക് പോകുകയും അവരോടൊപ്പം കഴിയുകയും ചെയ്യുക. അങ്ങനെ അവൾ തന്റെ കുടുംബക്കാരുടെ അടുത്തേക്ക് പോയി.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=91), 3, 'وَفِي رِوَايَةٍ: وَأَرْسَلَ إِلَى صَاحِبَيَّ بِمِثْلِ ذَلِكَ، فَقُلْتُ لِامْرَأَتِي: الْحَقِي بِأَهْلِكِ وَكُونِي عِنْدَهُمْ، حَتَّى يَقْضِيَ اللَّهُ عَزَّ وَجَلَّ فِي هَذَا الْأَمْرِ○.', 'മറ്റൊരു നിവേദനം: എന്റെ രണ്ട് കൂട്ടുകാരുടെ അടുത്തേക്ക് കൂടെ റസൂൽ(സ) അപ്രകാരം പറഞ്ഞയച്ചു. ഞാൻ എന്റെ ഭാര്യയോട് പറഞ്ഞു: നീ നിന്റെ കുടുംബക്കാരുടെ അടുത്ത് പോകുകയും ഈ വിഷയത്തിൽ അല്ലാഹു വിധി പറയുംവരെ അവരോടൊപ്പം കഴിയുകയും ചെയ്യുക.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=91), 4, 'وَفِي رِوَايَةٍ: أَرْسَلَ إِلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَإِلَى صَاحِبَيَّ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكُمْ أَنْ تَعْتَزِلُوا نِسَاءَكُمْ. (ن)', 'മറ്റൊരു നിവേദനം: എന്നിലേക്കും എന്റെ രണ്ട് കൂട്ടുകാരുടെ അടുത്തേക്കും റസൂൽ(സ) ആളെ പറഞ്ഞയച്ച് കൊണ്ട് പറഞ്ഞു: റസൂൽ(സ) നിങ്ങളോട് നിങ്ങളുടെ ഭാര്യമാരെ വെടിയാൻ കൽപിക്കുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'وَفِي رِوَايَةٍ عَنْ أَبِي أُسَيْدٍ رَضِيَ اللهُ عَنْهُ: أَنَّهَا أُدْخِلَتْ عَلَيْهِ وَمَعَهَا دَايَتُهَا حَاضِنَةٌ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَبِي نَفْسَكِ لِي؟" قَالَتْ: وَهَلْ تَهَبُ الْمَلِكَةُ نَفْسَهَا لِلسُّوقَةِ. قَالَ: فَأَهْوَى بِيَدِهِ يَضَعُ يَدَهُ عَلَيْهَا لِتَسْكُنَ فَقَالَتْ: أَعُوذُ بِاللَّهِ مِنْكَ فَقَالَ: "لَقَدْ عُذْتِ بِمَعَاذٍ"، ثُمَّ خَرَجَ عَلَيْنَا، فَقَالَ: "يَا أَبَا أُسَيْدٍ، اكْسُهَا رَازِقِيَّتَيْنِ وَأَلْحِقْهَا بِأَهْلِهَا". (خ)', 'അബൂഉസൈദ്(റ)വിൽ നിന്നുള്ള മറ്റൊരു നിവേദനം: തിരുമേനി(സ)യുടെ അടുത്തേക്ക് അവളെ കൊണ്ട് പോയപ്പോൾ അവളെ പരിചരിച്ച് വളർത്തിയിരുന്ന ഒരു ആയ കൂടി അവളുടെ ഒപ്പമുണ്ടായിരുന്നു. അവളോട് നബി(സ) പറഞ്ഞു: "നീ നിന്നെ എനിക്ക് സമർപ്പിച്ചുകൊള്ളുക." അവൾ ചോദിച്ചു: ഒരു രാജ്ഞി അങ്ങാടിയിൽ ചുറ്റിത്തിരിയുന്ന ആൾക്ക് സ്വന്തത്തെ സമർപ്പിക്കുമോ? അവൾ ശാന്തയാവാൻ വേണ്ടി തിരുമേനി(സ) തന്റെ കൈ അവളിലേക്ക് നീട്ടിയപ്പോൾ അവൾ പറഞ്ഞു: താങ്കളിൽ നിന്ന് ഞാൻ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അഭയം പ്രാപിക്കേണ്ട സ്ഥലത്തു തന്നെയാണ് നീ അഭയം പ്രാപിച്ചിരിക്കുന്നത്." ശേഷം അവിടന്ന് ഞങ്ങളുടെ അടുത്ത് വന്നുകൊണ്ട് പറഞ്ഞു: "അബൂ ഉസൈദേ, അവൾക്ക് പരുത്തികൊണ്ട് നിർമ്മിച്ച രണ്ട് വസ്ത്രങ്ങൾ നൽകുകയും അവളുടെ കുടുംബത്തിലേക്ക് തന്നെ അവളെ കൊണ്ടുപോകുകയും ചെയ്യുക." (ബു)', null, 'അബൂഉസൈദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 179, 180, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=92), 1, 'وَفِي رِوَايَةٍ عَنْ أَبِي أُسَيْدٍ رَضِيَ اللهُ عَنْهُ: أَنَّهَا أُدْخِلَتْ عَلَيْهِ وَمَعَهَا دَايَتُهَا حَاضِنَةٌ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَبِي نَفْسَكِ لِي؟" قَالَتْ: وَهَلْ تَهَبُ الْمَلِكَةُ نَفْسَهَا لِلسُّوقَةِ. قَالَ: فَأَهْوَى بِيَدِهِ يَضَعُ يَدَهُ عَلَيْهَا لِتَسْكُنَ فَقَالَتْ: أَعُوذُ بِاللَّهِ مِنْكَ فَقَالَ: "لَقَدْ عُذْتِ بِمَعَاذٍ"، ثُمَّ خَرَجَ عَلَيْنَا، فَقَالَ: "يَا أَبَا أُسَيْدٍ، اكْسُهَا رَازِقِيَّتَيْنِ وَأَلْحِقْهَا بِأَهْلِهَا". (خ)', 'മറ്റൊരു നിവേദനം: തിരുമേനി(സ)യുടെ അടുത്തേക്ക് അവളെ കൊണ്ട് പോയപ്പോൾ അവളെ പരിചരിച്ച് വളർത്തിയിരുന്ന ഒരു ആയ കൂടി അവളുടെ ഒപ്പമുണ്ടായിരുന്നു. അവളോട് നബി(സ) പറഞ്ഞു: "നീ നിന്നെ എനിക്ക് സമർപ്പിച്ചുകൊള്ളുക." അവൾ ചോദിച്ചു: ഒരു രാജ്ഞി അങ്ങാടിയിൽ ചുറ്റിത്തിരിയുന്ന ആൾക്ക് സ്വന്തത്തെ സമർപ്പിക്കുമോ? അവൾ ശാന്തയാവാൻ വേണ്ടി തിരുമേനി(സ) തന്റെ കൈ അവളിലേക്ക് നീട്ടിയപ്പോൾ അവൾ പറഞ്ഞു: താങ്കളിൽ നിന്ന് ഞാൻ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അഭയം പ്രാപിക്കേണ്ട സ്ഥലത്തു തന്നെയാണ് നീ അഭയം പ്രാപിച്ചിരിക്കുന്നത്." ശേഷം അവിടന്ന് ഞങ്ങളുടെ അടുത്ത് വന്നുകൊണ്ട് പറഞ്ഞു: "അബൂ ഉസൈദേ, അവൾക്ക് പരുത്തികൊണ്ട് നിർമ്മിച്ച രണ്ട് വസ്ത്രങ്ങൾ നൽകുകയും അവളുടെ കുടുംബത്തിലേക്ക് തന്നെ അവളെ കൊണ്ടുപോകുകയും ചെയ്യുക." (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا ادَّعَتِ الْمَرْأَةُ طَلَاقَ زَوْجِهَا، فَجَاءَتْ عَلَى ذَلِكَ بِشَاهِدٍ عَدْلٍ، اسْتُحْلِفَ زَوْجُهَا: فَإِنْ حَلَفَ بَطَلَتْ شَهَادَةُ الشَّاهِدِ، وَإِنْ نَكَلَ فَنُكُولُهُ بِمَنْزِلَةِ شَاهِدٍ آخَرَ، وَجَازَ طَلَاقُهُ". (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "ഒരു സ്ത്രീ, തന്റെ ഭർത്താവ് തന്നെ വിവാഹമോചനം നടത്തിയെന്ന് വാദിക്കുകയും അതിന് സാക്ഷിയായി ഒരു വിശ്വസ്തനായ സാക്ഷിയെ കൊണ്ടുവരികയും ചെയ്താൽ അവളുടെ ഭർത്താവ് സത്യം ചെയ്യിക്കപ്പെടണം. ത്വലാഖ് ചൊല്ലിയിട്ടില്ലെന്ന് അവൻ സത്യംചെയ്യുകയാണെങ്കിൽ ആ സാക്ഷിയുടെ സാക്ഷിത്വം നഷ്ടപ്പെടും. ഭർത്താവ് സത്യം ചെയ്യാൻ വിസമ്മതിച്ചാൽ അത് മറ്റൊരു സാക്ഷിയുടെ സ്ഥാനത്താണ്. അങ്ങനെയാണെങ്കിൽ ത്വലാഖ് സംഭവിക്കുകയും ചെയ്യും." (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 180, 180, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَقْسَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ لَا يَدْخُلَ عَلَى نِسَائِهِ شَهْرًا، فَمَكَثَ تِسْعَةً وَعِشْرِينَ يَوْمًا، حَتَّى إِذَا كَانَ مَسَاءَ ثَلَاثِينَ دَخَلَ عَلَيَّ، فَقُلْتُ: إِنَّكَ أَقْسَمْتَ أَنْ لَا تَدْخُلَ عَلَيْنَا شَهْرًا. فَقَالَ: "الشَّهْرُ كَذَا". يُرْسِلُ أَصَابِعَهُ فِيهَا ثَلَاثَ مَرَّاتٍ "وَالشَّهْرُ كَذَا". وَأَرْسَلَ أَصَابِعَهُ كُلَّهَا وَأَمْسَكَ إِصْبَعًا وَاحِدًا فِي الثَّالِثَةِ. (جه)', 'ആഇശ(റ): ഒരുമാസം തന്റെ ഭാര്യമാരുടെ അടുത്തേക്ക് ചെല്ലുകയില്ലെന്ന് റസൂൽ(സ) സത്യം ചെയ്തു. ഇരുപത്തി ഒമ്പത് ദിവസം റസൂൽ(സ) അപ്രകാരം തങ്ങി. മുപ്പതാം ദിവസത്തെ വൈകുന്നേരം റസൂൽ(സ) എന്റെയടുത്ത് വന്നു. ഞാൻ ചോദിച്ചു: ഒരു മാസം ഞങ്ങളുടെ അടുത്തേക്ക് വരില്ലെന്ന് അങ്ങ് സത്യം ചെയ്തിട്ടില്ലെയോ? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "മാസം ഇത്രയാണ്, മാസം ഇത്രയാണ്." എന്നിട്ട് തന്റെ വിരലുകൾ മൂന്ന് പ്രാവശ്യം നിവർത്തി. മൂന്നാം പ്രാവശ്യം ഒരുവിരൽ മാത്രം മടക്കിപ്പിടിച്ചു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 180, 180, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّمَا آلَى لِأَنَّ زَيْنَبَ رَدَّتْ عَلَيْهِ هَدِيَّتَهُ، فَقَالَتْ عَائِشَةُ: لَقَدْ أَقْمَأْتِكِ. فَغَضِبَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَآلَى مِنْهُنَّ. [ز: في إسناده ضعيف] (جه)', 'ആഇശ(റ): റസൂൽ(സ) തന്റെ ഭാര്യമാരുടെ അടുത്ത് ചെല്ലില്ലെന്ന് സത്യം ചെയ്യാനുള്ള കാരണം ഇതായിരുന്നു. സൈനബ്(റ)വിന് റസൂൽ(സ) നൽകിയ സമ്മാനം മഹതി തിരിച്ചുനൽകി. ഇതറിഞ്ഞ ആഇശ(റ) പറഞ്ഞു: അവൾ അങ്ങയെ നിസ്സാരക്കാരനാക്കിയിരിക്കുന്നു. അത് കേട്ടപ്പോൾ തിരുമേനി(സ)ക്ക് ദേഷ്യം വരികയും ഭാര്യമാരുടെ അടുത്തേക്ക് പ്രവേശിക്കില്ലെന്ന് സത്യം ചെയ്യുകയും ചെയ്തു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 180, 181, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ آلَى مِنْ بَعْضِ نِسَائِهِ شَهْرًا، فَلَمَّا كَانَ تِسْعَةً وَعِشْرِينَ رَاحَ، أَوْ: غَدًا، فَقِيلَ: يَا رَسُولَ اللَّهِ، إِنَّمَا مَضَى تِسْعٌ وَعِشْرُونَ؟ فَقَالَ: "الشَّهْرُ تِسْعٌ وَعِشْرُونَ". (ق,جه)', 'ഉമ്മുസലമ(റ): ഒരു മാസം തന്റെ ചില ഭാര്യമാരുടെ അടുത്ത് പ്രവേശിക്കില്ലെന്ന് റസൂൽ(സ) സത്യം ചെയ്തു. അങ്ങനെ ഇരുപത്തിഒമ്പത് ദിവസം കഴിഞ്ഞപ്പോൾ രാവിലെ അല്ലെങ്കിൽ വൈകുന്നേരം റസൂൽ(സ) വന്നു. റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു: ഇരുപത്തി ഒമ്പത് ദിവസമല്ലേ കഴിഞ്ഞിട്ടൊള്ളൂ, റസൂലേ? റസൂൽ(സ) പറഞ്ഞു: "മാസം ഇരുപത്തൊമ്പത് ദിവസമാണ്." (ബു,മു,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 181, 181, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَصْبَحْنَا يَوْمًا وَنِسَاءُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَبْكِينَ، عِنْدَ كُلِّ امْرَأَةٍ مِنْهُنَّ أَهْلُهَا، فَدَخَلْتُ الْمَسْجِدَ فَإِذَا هُوَ مَلْآنُ مِنَ النَّاسِ، قَالَ: فَجَاءَ عُمَرُ رَضِيَ اللهُ عَنْهُ فَصَعِدَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي عُلِّيَّةٍ لَهُ، فَسَلَّمَ عَلَيْهِ فَلَمْ يُجِبْهُ أَحَدٌ، ثُمَّ سَلَّمَ فَلَمْ يُجِبْهُ أَحَدٌ، ثُمَّ سَلَّمَ فَلَمْ يُجِبْهُ أَحَدٌ، فَرَجَعَ فَنَادَى بِلَالًا فَدَخَلَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَقَالَ أَطَلَّقْتَ نِسَاءَكَ؟ فَقَالَ: "لَا، وَلَكِنِّي آلَيْتُ مِنْهُنَّ شَهْرًا". فَمَكَثَ تِسْعًا وَعِشْرِينَ، ثُمَّ نَزَلَ فَدَخَلَ عَلَى نِسَائِهِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു ദിവസം നേരം പുലർന്നപ്പോൾ നബി(സ)യുടെ ഭാര്യമാരെല്ലാം കരയുന്നുണ്ടായിരുന്നു. അവരിൽ ഓരോരുത്തരോടൊപ്പം അവരുടെ കുടുംബക്കാരുമുണ്ടായിരുന്നു. അങ്ങനെ ഞാൻ പള്ളിയിൽ പ്രവേശിച്ചു, അവിടെ ജനങ്ങളെല്ലാം തടിച്ച് കൂടിയിരുന്നു. അന്നേരം ഉമർ(റ) വരികയും നബി(സ)യുടെ അടുത്തേക്ക് കയറുകയും ചെയ്തു. റസൂൽ(സ) ഒരു ഉയർന്ന മുറിയിലായിരുന്നു. ഉമർ(റ) റസൂൽ(സ)യോട് സലാം ചൊല്ലി. പക്ഷേ ആരും സലാം മടക്കിയില്ല. വീണ്ടും സലാം പറഞ്ഞു: പക്ഷേ ആരും മടക്കിയില്ല. പിന്നെയും സലാം പറഞ്ഞെങ്കിലും അപ്പോഴും ആരും സലാം മടക്കിയില്ല. അങ്ങനെ ഉമർ(റ) മടങ്ങിവന്ന് ബിലാൽ(റ)വിനെ വിളിച്ചു. ശേഷം റസൂൽ(സ)യുടെ അടുത്ത് പ്രവേശിച്ചു. എന്നിട്ട് ചോദിച്ചു: അങ്ങ് അവിടത്തെ ഭാര്യമാരെ വിവാഹമോചനം ചെയ്തുവോ? റസൂൽ(സ) പറഞ്ഞു: "ഇല്ല, പക്ഷേ ഒരു മാസം അവരുടെ അടുത്ത് പ്രവേശിക്കില്ലെന്ന് ഞാൻ സത്യം ചെയ്തിരിക്കുന്നു." അപ്രകാരം നബി(സ) ഇരുപത്തി ഒമ്പത് ദിവസം കഴിച്ച് കൂട്ടി. ശേഷം അവിടെ നിന്ന് ഇറങ്ങുകയും തന്റെ ഭാര്യമാരുടെ അടുത്ത് പ്രവേശിക്കുകയും ചെയ്തു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 181, 181, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: آلَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ نِسَائِهِ وَحَرَّمَ، فَجَعَلَ الْحَرَامَ حَلَالًا، وَجَعَلَ فِي الْيَمِينِ كَفَّارَةً. (ت,جه)', 'ആഇശ(റ): റസൂൽ(സ) തന്റെ ഭാര്യമാരുടെ അടുത്ത് പോകുകയില്ലെന്ന് സത്യം ചെയ്യുകയും തനിക്ക് അനുവദനീയമായ കാര്യം അനുവദനീയമല്ലാതാക്കുകയും ചെയ്തു. ശേഷം ആ അനുവദനീയമല്ലാത്ത കാര്യത്തെ (ഭാര്യമാരോട് ബന്ധപ്പെടൽ) അനുവദനീയമാക്കുകയും സത്യം ചെയ്തതിന് പ്രായശ്ചിത്തം നൽകുകയും ചെയ്തു. (തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 181, 181, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: فِي الْحَرَامِ يَمِينٌ. وَكَانَ ابْنُ عَبَّاسٍ يَقُولُ: {لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ} [الأحزاب: ٢١] (ق,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നിഷിദ്ധമായത് ചെയ്യുന്നതിലും സത്യം ചെയ്യാം. ഇബ്നുഅബ്ബാസ്(റ) പറയുമായിരുന്നു: അല്ലാഹുവിന്റെ റസൂലിൽ നിങ്ങൾക്ക് ഉത്തമ മാതൃകയുണ്ട്. (ബു,മു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], 'الأحزاب: ٢١', null, 181, 181, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "طَلَاقُ الْأَمَةِ اثْنَتَانِ، وَعِدَّتُهَا حَيْضَتَانِ". [ز: في إسناده راويان ضعيفان] (ت,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അടിമസ്ത്രീയെ രണ്ട് പ്രാവശ്യമാണ് വിവാഹമോചനം ചെയ്യാവുന്നത്. അവളുടെ ഇദ്ദ രണ്ട് ആർത്തവങ്ങളുടെ സമയമാണ്". (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], 'ز: في إسناده راويان ضعيفان', null, 182, 182, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ سَيِّدِي زَوَّجَنِي أَمَتَهُ، وَهُوَ يُرِيدُ أَنْ يُفَرِّقَ بَيْنِي وَبَيْنَهَا؟ قَالَ: فَصَعِدَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمِنْبَرَ فَقَالَ: "يَا أَيُّهَا النَّاسُ، مَا بَالُ أَحَدِكُمْ يُزَوِّجُ عَبْدَهُ أَمَتَهُ، ثُمَّ يُرِيدُ أَنْ يُفَرِّقَ بَيْنَهُمَا؟ إِنَّمَا الطَّلَاقُ لِمَنْ أَخَذَ بِالسَّاقِ". [ز: ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: റസൂലേ, എന്റെ ഉടമ എനിക്ക് അദ്ദേഹത്തിന്റെ അടിമസ്ത്രീയെ വിവാഹം ചെയ്ത് തന്നു. ഇപ്പോൾ അദ്ദേഹം എന്നേയും അവളേയും വേർപിരിക്കണമെന്ന് ആഗ്രഹിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) മിമ്പറിൽ കയറി. എന്നിട്ട് പറഞ്ഞു: "ജനങ്ങളേ, തന്റെ അടിമക്ക് തന്റെ അടിമസ്ത്രീയെ വിവാഹം ചെയ്ത് കൊടുക്കുകയും ശേഷം അവരെ വേർപിരിക്കണമെന്ന് ആഗ്രഹിക്കുകയും ചെയ്യുന്ന ഒരുത്തന്റെ അവസ്ഥയെന്താണ്? നിശ്ചയം കാലിന്റെ അവകാശിക്ക്(ഭർത്താവിന്ന്) മാത്രമാണ് വിവാഹമോചനത്തിന് അവകാശമുള്ളത്". (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: ضعيف', null, 182, 182, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا طَلَاقَ إِلَّا فِيمَا تَمْلِكُ، وَلَا عِتْقَ إِلَّا فِيمَا تَمْلِكُ، وَلَا بَيْعَ إِلَّا فِيمَا تَمْلِكُ، وَلَا وَفَاءَ نَذْرٍ إِلَّا فِيمَا تَمْلِكُ". وفي رواية: "مَنْ حَلَفَ عَلَى مَعْصِيَةٍ فَلَا يَمِينَ لَهُ، وَمَنْ حَلَفَ عَلَى قَطِيعَةِ رَحِمٍ فَلَا يَمِينَ لَهُ". وفي رواية: "وَلَا نَذْرَ إِلَّا فِيمَا ابْتُغِيَ بِهِ وَجْهُ اللَّهِ تَعَالَى ذِكْرُهُ". (د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "തന്റെ കീഴിലുള്ളതല്ലാത്ത സ്ത്രീയെ വിവാഹഹമോചനം ചെയ്യാവതല്ല, ഉടമസ്ഥതയിലുള്ളതല്ലാത്തതിനെ മോചിപ്പിക്കാൻ പാടില്ല, ഉടമസ്ഥതയിലുള്ളതല്ലാത്തത് വിൽക്കാൻ പാടില്ല, ഉടമസ്ഥതയിലുള്ളതല്ലാത്തതിന്റെ നേർച്ച വീട്ടേതില്ല". മറ്റൊരു നിവേദനം: "ആരെങ്കിലും ഒരു തെറ്റ് ചെയ്യാൻ സത്യം ചെയ്താൽ അവന്റെ സത്യം സ്വീകരിക്കപ്പെടുകയില്ല. കുടുംബബന്ധം മുറിക്കാൻ ആരെങ്കിലും സത്യം ചെയ്താൽ അവന്റെ സത്യവും സ്വീകരിക്കപ്പെടുകയില്ല". മറ്റൊരു നിവേദനം: "അല്ലാഹുവിന്റെ തൃപ്തി കാംക്ഷിച്ചു കൊണ്ടുള്ളതല്ലാത്ത ഒരു നേർച്ചയും പാടില്ല". (ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 182, 182, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=102), 1, 'وَفِي رِوَايَةٍ: "مَنْ حَلَفَ عَلَى مَعْصِيَةٍ فَلَا يَمِينَ لَهُ، وَمَنْ حَلَفَ عَلَى قَطِيعَةِ رَحِمٍ فَلَا يَمِينَ لَهُ".', 'മറ്റൊരു നിവേദനം: "ആരെങ്കിലും ഒരു തെറ്റ് ചെയ്യാൻ സത്യം ചെയ്താൽ അവന്റെ സത്യം സ്വീകരിക്കപ്പെടുകയില്ല. കുടുംബബന്ധം മുറിക്കാൻ ആരെങ്കിലും സത്യം ചെയ്താൽ അവന്റെ സത്യവും സ്വീകരിക്കപ്പെടുകയില്ല".');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=102), 2, 'وَفِي رِوَايَةٍ: "وَلَا نَذْرَ إِلَّا فِيمَا ابْتُغِيَ بِهِ وَجْهُ اللَّهِ تَعَالَى ذِكْرُهُ". (د,ت,جه)', 'മറ്റൊരു നിവേദനം: "അല്ലാഹുവിന്റെ തൃപ്തി കാംക്ഷിച്ചു കൊണ്ടുള്ളതല്ലാത്ത ഒരു നേർച്ചയും പാടില്ല". (ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا طَلَاقَ قَبْلَ نِكَاحٍ، وَلَا عِتْقَ قَبْلَ مِلْكٍ". (جه)', 'മിസ്വറുബ്നു മഖ്റമ(റ): നബി(സ) പറഞ്ഞു: "വിവാഹത്തിന് മുമ്പ് വിവാഹമോചനമില്ല. ഉടമപ്പെടുത്തുന്നതിന് മുമ്പ് അടിമമോചനവുമില്ല." (ജ)', 'الْمِسْوَرِ بْنِ مَخْرَمَةَ', 'മിസ്വറുബ്നു മഖ്റമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 182, 183, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ سَعِيدِ بْنِ جُبَيْرٍ قَالَ: سُئِلْتُ عَنِ الْمُتَلَاعِنَيْنِ فِي إِمَارَةِ مُصْعَبِ بْنِ الزُّبَيْرِ، أَيُفَرَّقُ بَيْنَهُمَا؟ فَمَا دَرَيْتُ مَا أَقُولُ، فَقُمْتُ مَكَانِي إِلَى مَنْزِلِ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، اسْتَأْذَنْتُ عَلَيْهِ فَقِيلَ لِي: إِنَّهُ قَائِلٌ، فَسَمِعَ كَلَامِي فَقَالَ: ابْنُ جُبَيْرٍ؟ ادْخُلْ، مَا جَاءَ بِكَ إِلَّا حَاجَةٌ. قَالَ: فَدَخَلْتُ فَإِذَا هُوَ مُفْتَرِشٌ بَرْدَعَةَ رَحْلٍ لَهُ، فَقُلْتُ: يَا أَبَا عَبْدِ الرَّحْمَنِ، الْمُتَلَاعِنَانِ، أَيُفَرَّقُ بَيْنَهُمَا؟ فَقَالَ: سُبْحَانَ اللَّهِ! نَعَمْ، إِنَّ أَوَّلَ مَنْ سَأَلَ عَنْ ذَلِكَ فُلَانُ بْنُ فُلَانٍ، أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ لَوْ أَنَّ أَحَدَنَا رَأَى امْرَأَتَهُ عَلَى فَاحِشَةٍ، كَيْفَ يَصْنَعُ؟ إِنْ تَكَلَّمَ بِأَمْرٍ عَظِيمٍ، وَإِنْ سَكَتَ سَكَتَ عَلَى أَمْرٍ عَظِيمٍ. قَالَ: فَسَكَتَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يُجِبْهُ، فَلَمَّا كَانَ بَعْدَ ذَلِكَ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ الَّذِي سَأَلْتُكَ عَنْهُ قَدِ ابْتُلِيتُ بِهِ. فَأَنْزَلَ اللَّهُ هَذِهِ الْآيَاتِ الَّتِي فِي سُورَةِ النُّورِ: {وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ وَلَمْ يَكُنْ لَهُمْ شُهَدَاءُ إِلَّا أَنْفُسُهُمْ} حَتَّى خَتَمَ الْآيَاتِ. فَدَعَا الرَّجُلَ فَتَلَا الْآيَاتِ عَلَيْهِ، وَوَعَظَهُ وَذَكَّرَهُ، وَأَخْبَرَهُ أَنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَةِ. فَقَالَ: لَا، وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا كَذَبْتُ عَلَيْهَا. ثُمَّ ثَنَّى بِالْمَرْأَةِ فَوَعَظَهَا وَذَكَّرَهَا، وَأَخْبَرَهَا أَنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَةِ، فَقَالَتْ: لَا، وَالَّذِي بَعَثَكَ بِالْحَقِّ، مَا صَدَقَ. قَالَ: فَبَدَأَ بِالرَّجُلِ فَشَهِدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الصَّادِقِينَ، وَالْخَامِسَةُ أَنَّ لَعْنَةَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنَ الْكَاذِبِينَ، ثُمَّ ثَنَّى بِالْمَرْأَةِ فَشَهِدَتْ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الْكَاذِبِينَ، وَالْخَامِسَةُ أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنَ الصَّادِقِينَ. ثُمَّ فَرَّقَ بَيْنَهُمَا. حسن صحيح. (ق,ت)', 'സഈദുബ്നു ജുബൈർ(റ): മുസ്അബുബ്നു ഉമൈർ(റ)വിന്റെ ഭരണകാലത്ത്, ലിആൻ ചെയ്യുന്ന ഭാര്യാഭർത്താക്കന്മാർ പരസ്പരം വേർപ്പിരിക്കപ്പെടണോ എന്ന് എന്നോട് ചോദിക്കപ്പെട്ടു. എന്താണ് ഉത്തരം പറയേണ്ടത് എന്ന് എനിക്കറിയില്ലായിരുന്നു. ഉടൻ തന്നെ ഞാൻ അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)വിന്റെ വീട്ടിൽ ചെന്നു. ഞാൻ അദ്ദേഹത്തോട് സമ്മതം ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം ഖൈലൂലത് (ഉച്ചയുറക്കം) ഉറങ്ങുകയാണെന്ന് എന്നോട് പറയപ്പെട്ടു. അദ്ദേഹം എന്റെ സംസാരം കേൾക്കുകയും ഇപ്രകാരം ചോദിക്കുകയും ചെയ്തു: ഇബ്നു ജുബൈർ അല്ലേ, താങ്കൾ ഉള്ളിൽ വരിക. എന്തോ ആവശ്യത്തിനാണല്ലോ താങ്കൾ വന്നിരിക്കുന്നത്. അങ്ങനെ ഞാൻ ഉള്ളിൽ പ്രവേശിച്ച് നോക്കുമ്പോൾ അദ്ദേഹം തന്റെ വാഹനപ്പുറത്തിടാറുണ്ടായിരുന്ന വിരിപ്പ് വിരിച്ചിരിക്കുകയായിരുന്നു. ഞാൻ ചോദിച്ചു: അബൂ അബ്ദുർറഹ്മാനേ, ലിആൻ ചെയ്യുന്ന ഭാര്യഭർത്താക്കന്മാരെ പരസ്പരം വേർപിരിക്കപ്പെടണോ? അദ്ദേഹം പറഞ്ഞു: അതെ, അല്ലാഹുവിന്റെ പരിശുദ്ധതയെ ഞാൻ വാഴ്ത്തുന്നു. അതിനെക്കുറിച്ച് ആദ്യമായി ചോദിച്ചത് ഇന്ന വ്യക്തിയാണ്. അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് വന്ന് ചോദിച്ചു: റസൂലേ, ഞങ്ങളിലൊരുത്തൻ തന്റെ ഭാര്യ മോശത്തരം(വ്യഭിചാരം) ചെയ്യുന്നത് കണ്ടാൽ എന്താണ് ചെയ്യേണ്ടത്? അവൻ പുറത്ത് പറയുകയാണെങ്കിൽ അത് വളരെ ഗൗരവമേറിയ വിഷയമാണ്, മൗനമവലംബിക്കുകയാണെങ്കിൽ വളരെ ഗൗരവമേറിയ വിഷയത്തെയാണ് അവൻ അവഗണിക്കുന്നത്. ഇത് കേട്ടപ്പോൾ റസൂൽ(സ) മൗനമവലംബിച്ചു. ഒന്നും പ്രതികരിച്ചില്ല. ശേഷം വീണ്ടും ആ വ്യക്തി നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: ഞാൻ അങ്ങയോട് ചോദിച്ചിരുന്ന വിഷയം കൊണ്ട് ഞാൻ പരീക്ഷിക്കപ്പെട്ടിരിക്കുന്നു. അപ്പോൾ അല്ലാഹു ''തങ്ങളുടെ ഭാര്യമാരുടെ പേരിൽ ആരോപണം പറയുകയും തങ്ങളല്ലാതെ മറ്റാരും സാക്ഷികളില്ലാത്തവരുമായ ആളുകൾ'' എന്ന സൂറതുന്നൂറിലെ സൂക്തങ്ങളിറക്കി. അങ്ങനെ നബി(സ) ആ വ്യക്തിയെ വിളിക്കുകയും ഈ സൂക്തങ്ങൾ ഓതിക്കേൾപ്പിക്കുകയും അദ്ദേഹത്തെ ഉപദേശിക്കുകുയം അതിന്റെ ഗൗരവം ഓർമ്മപ്പെടുത്തുകയും ദുൻയാവിലെ ശിക്ഷ പാരത്രിക ലോകത്തെ ശിക്ഷയേക്കാൾ നിസാരമാണെന്ന് പറഞ്ഞ് കൊടുക്കുകയും ചെയ്തു. അദ്ദേഹം പറഞ്ഞു: ഇല്ല, അങ്ങയെ സത്യവുമായി അയച്ചവൻ തന്നെ സത്യം, ഞാനവളെക്കുറിച്ച് നുണപറഞ്ഞിട്ടില്ല. രണ്ടാമതായി നബി(സ) അദ്ദേഹത്തിന്റെ ഭാര്യയെ വിളിക്കുകയും വിഷയത്തിന്റെ ഗൗരവം അവള ഓർമ്മപ്പെടുത്തുകയും ഇഹലോക ശിക്ഷ പാരത്രിക ലോകത്തെ ശിക്ഷയേക്കാൾ നിസാരമാണെന്ന് ഓർമ്മപ്പെടുത്തുകയും ചെയ്തു. അപ്പോൾ ആ സ്ത്രീ പറഞ്ഞു: അല്ല, അങ്ങയെ സത്യവുമായി അയച്ചവൻ തന്നെ സത്യം, അദ്ദേഹം പറഞ്ഞത് സത്യമല്ല. അങ്ങനെ നബി(സ) ആ വ്യക്തിയിൽ നിന്ന് തുടങ്ങുകയും അദ്ദേഹം നാലു പ്രാവശ്യം താൻ സത്യവാനാണെന്ന് അല്ലാഹുവിനെ മുൻനിർത്തി സത്യം ചെയ്യുകയും ചെയ്തു. അഞ്ചാം പ്രാവശ്യം താൻ നുണയാണ് പറയുന്നതെങ്കിൽ തന്റെ മേൽ അല്ലാഹുവിന്റെ ശാപമുണ്ടാവട്ടെ എന്നും അദ്ദേഹം പറഞ്ഞു. ശേഷം അദ്ദേഹം നുണയാണ് പറഞ്ഞതെന്ന് ആ സ്ത്രീ അല്ലാഹുവിനെ മുൻനിർത്തി നാല് പ്രാവശ്യം സത്യം ചെയ്തു. അഞ്ചാം പ്രാവശ്യം അവൻ സത്യമാണ് പറഞ്ഞതെങ്കിൽ തന്റെ മേൽ അല്ലാഹുവിന്റെ കോപമുണ്ടാവട്ടെ എന്നും അവൾ പറഞ്ഞു. ശേഷം റസൂൽ(സ) ഇരുവരെയും വേർപിരിച്ചു. (ബു,മു,തു)', 'سَعِيدِ بْنِ جُبَيْرٍ قَالَ', 'സഈദുബ്നു ജുബൈർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 183, 184, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ عُوَيْمِرٌ إِلَى عَاصِمِ بْنِ عَدِيٍّ فَقَالَ: سَلْ لِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَرَأَيْتَ رَجُلًا وَجَدَ مَعَ امْرَأَتِهِ رَجُلًا فَقَتَلَهُ، أَيُقْتَلُ بِهِ؟ أَمْ كَيْفَ يَصْنَعُ؟ فَسَأَلَ عَاصِمٌ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ، فَعَابَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَسَائِلَ، ثُمَّ لَقِيَهُ عُوَيْمِرٌ فَسَأَلَهُ، فَقَالَ: مَا صَنَعْتَ؟ فَقَالَ: صَنَعْتُ أَنَّكَ لَمْ تَأْتِنِي بِخَيْرٍ، سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَابَ الْمَسَائِلَ. فَقَالَ عُوَيْمِرٌ: وَاللَّهِ لَآتِيَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَأَسْأَلَنَّهُ. فَأَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَجَدَهُ وَقَدْ أُنْزِلَ عَلَيْهِ فِيهِمَا، فَلَاعَنَ بَيْنَهُمَا، فَقَالَ عُوَيْمِرٌ: وَاللَّهِ لَئِنِ انْطَلَقْتُ بِهَا - يَا رَسُولَ اللَّهِ - لَقَدْ كَذَبْتُ عَلَيْهَا. قَالَ: فَفَارَقَهَا قَبْلَ أَنْ يَأْمُرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَصَارَتْ سُنَّةً فِي الْمُتَلَاعِنَيْنِ. ثُمَّ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "انْظُرُوهَا فَإِنْ جَاءَتْ بِهِ أَسْحَمَ، أَدْعَجَ الْعَيْنَيْنِ، عَظِيمَ الْأَلْيَتَيْنِ، فَلَا أُرَاهُ إِلَّا قَدْ صَدَقَ عَلَيْهَا. وَإِنْ جَاءَتْ بِهِ أُحَيْمِرَ كَأَنَّهُ وَحَرَةٌ، فَلَا أُرَاهُ إِلَّا كَاذِبًا". قَالَ: فَجَاءَتْ بِهِ عَلَى النَّعْتِ الْمَكْرُوهِ. (ق,د,ن,جه)', 'സഹ്ലുബ്നു സഅ്ദുസ്സാഇദി(റ): ഉവൈമിർ(റ) ആസിമുബ്നു അദ്യ്(റ)വിന്റെയടുത്ത് വന്ന് പറഞ്ഞു: എനിക്കുവേണ്ടി അങ്ങ് റസൂൽ(സ)യോട് ഈ കാര്യം ചോദിക്കുക: ഒരു വ്യക്തി തന്റെ ഭാര്യയോടൊപ്പം മറ്റൊരുത്തനെ കാണുകയും അവനെ വധിക്കുകയും ചെയ്താൽ അതിന് പകരമായി ആ വ്യക്തി വധിക്കപ്പെടുമോ, അല്ലെങ്കിൽ അവൻ എന്താണ് ചെയ്യുക? അങ്ങനെ ആ കാര്യം റസൂൽ(സ)യോട് ചോദിച്ചു. റസൂൽ(സ) അത്തരം ചോദ്യങ്ങളെ വിമർശിച്ചു. ശേഷം ഉവൈമിർ(റ) ആസിം(റ)വിനെ കണ്ടുമുട്ടിയപ്പോൾ ചോദിച്ചു. താങ്കൾ എന്ത് ചെയ്തു. ആസിം(റ) പറഞ്ഞു: ഞാൻ അത് ചെയ്തു, പക്ഷേ നീ എന്നോട് ചെയ്തത് ശരിയല്ല. ഞാൻ അക്കാര്യം റസൂൽ(സ)യോട് ചോദിച്ചു, അപ്പോൾ അവിടന്ന് ചോദ്യക്കാരനെ ആക്ഷേപിച്ചു. അപ്പോൾ ഉവൈമിർ(റ) പറഞ്ഞു: ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെല്ലുകയും അക്കാര്യം നേരിട്ട് ചോദിക്കുകയും ചെയ്യും. ശേഷം അദ്ദേഹം റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നപ്പോൾ അവരുടെ കാര്യത്തിൽ റസൂൽ(സ)ക്ക് സന്ദേശമിറക്കിയിട്ടുണ്ടായിരുന്നു. അങ്ങനെ റസൂൽ(സ) അവർക്കിടയിൽ (ഉവൈമിർ(റ)വിനും തന്റെ ഭാര്യക്കുമിടയിൽ) ലിആൻ ചെയ്യിച്ചു. ശേഷം ഉവൈമിർ(റ) പറഞ്ഞു: റസൂലേ, ഞാൻ അവളെക്കുറിച്ച് നുണപറഞ്ഞിട്ടുണ്ടെന്ന് അവൾ പറഞ്ഞിരിക്കെ ഞാൻ അവളെയും കൂട്ടി പോവുകയോ? അങ്ങനെ റസൂൽ(സ) കൽപിക്കുന്നതിനു മുമ്പ് തന്നെ ഉവൈമിർ(റ) അവളുമായി പിരിയുകയും പരസ്പരം ലിആൻ ചെയ്യുന്ന ദമ്പതികൾക്ക് അത് ഒരു ചര്യയായി മാറുകയും ചെയ്തു. ശേഷം റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അവരുടെ കാര്യം ശ്രദ്ധിക്കുക, കറുത്ത നിറമുള്ള, കണ്ണിലെ കറുപ്പധികരിച്ച, വലിയ ഊരയുള്ള കുട്ടിയെയാണ് അവൾ പ്രസവിക്കുന്നതെങ്കിൽ അവൻ അവളെക്കുറിച്ച് പറഞ്ഞത് സത്യമാണെന്ന് ഞാൻ മനസ്സിലാക്കുന്നു. ഇനി ചുവന്ന പല്ലിയെപ്പോലെ ചുവപ്പ് നിറത്തോട് ചാഞ്ഞ കുട്ടിയെയാണ് അവൾ പ്രസവിക്കുന്നതെങ്കിൽ അവൻ പറഞ്ഞത് കളവാണെന്നും ഞാൻ മനസ്സിലാക്കും." സഹ്ല്(റ) പറഞ്ഞു: അങ്ങനെ മോശമായ വിശേഷണമുള്ള കുട്ടിയെയാണ് അവൾ പ്രസവിച്ചത്. (ബു,മു,ദ,ന,ജ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദുസ്സാഇദി(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 184, 185, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ عُوَيْمِرَ بْنَ أَشْقَرَ الْعَجْلَانِيَّ جَاءَ إِلَى عَاصِمِ بْنِ عَدِيٍّ، فَقَالَ لَهُ: يَا عَاصِمُ، أَرَأَيْتَ رَجُلًا وَجَدَ مَعَ امْرَأَتِهِ رَجُلًا، أَيَقْتُلُهُ فَتَقْتُلُونَهُ، أَمْ كَيْفَ يَفْعَلُ؟ سَلْ لِي يَا عَاصِمُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ. فَسَأَلَ عَاصِمٌ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَكَرِهَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَسَائِلَ وَعَابَهَا، حَتَّى كَبُرَ عَلَى عَاصِمٍ مَا سَمِعَ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا رَجَعَ عَاصِمٌ إِلَى أَهْلِهِ جَاءَهُ عُوَيْمِرٌ فَقَالَ لَهُ: يَا عَاصِمُ، مَاذَا قَالَ لَكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ عَاصِمٌ: لَمْ تَأْتِنِي بِخَيْرٍ، قَدْ كَرِهَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَسْأَلَةَ الَّتِي سَأَلْتُهُ عَنْهَا. فَقَالَ عُوَيْمِرٌ: وَاللهِ لَا أَنْتَهِي حَتَّى أَسْأَلَهُ عَنْهَا. فَأَقْبَلَ عُوَيْمِرٌ حَتَّى أَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ وَسْطَ النَّاسِ، فَقَالَ: يَا رَسُولَ اللهِ، أَرَأَيْتَ رَجُلًا وَجَدَ مَعَ امْرَأَتِهِ رَجُلًا، أَيَقْتُلُهُ فَتَقْتُلُونَهُ، أَمْ كَيْفَ يَفْعَلُ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "قَدْ أُنْزِلَ فِيكَ وَفِي صَاحِبَتِكَ قُرْآنٌ، فَاذْهَبْ فَأْتِ بِهَا" قَالَ سَهْلٌ: فَتَلَاعَنَا وَأَنَا مَعَ النَّاسِ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا فَرَغَا قَالَ عُوَيْمِرٌ: كَذَبْتُ عَلَيْهَا يَا رَسُولَ اللهِ إِنْ أَمْسَكْتُهَا، فَطَلَّقَهَا عُوَيْمِرٌ ثَلَاثًا قَبْلَ أَنْ يَأْمُرَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ ابْنُ شِهَابٍ: فَكَانَتْ تِلْكَ سُنَّةَ الْمُتَلَاعِنَيْنِ. وَفِي رِوَايَة: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِعَاصِمِ بْنِ عَدِيٍّ: "أَمْسِكِ الْمَرْأَةَ عِنْدَكَ حَتَّى تَلِدَ". وَفِي رِوَايَة: عَنْ سَهْلٍ قَالَ: حَضَرْتُ لِعَانَهُمَا عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا ابْنُ خَمْسَ عَشْرَةَ سَنَةً، وَسَاقَ الْحَدِيثَ، قَالَ فِيهِ: ثُمَّ خَرَجَتْ حَامِلًا، فَكَانَ الْوَلَدُ يُدْعَى إِلَى أُمِّهِ. (ق,د,جه)', 'സഹ്ലുബ്നു സഅ്ദുസ്സാഇദി(റ): ഉവൈമിറുബ്നു അശ്കറുൽ അജ്ലാനി(റ) ആസിമുബ്നു അദ്യ്(റ)വിന്റെ അടുത്ത് ചെന്നു, എന്നിട്ട് പറഞ്ഞു: ആസിമേ, ഒരു വ്യക്തി തന്റെ ഭാര്യയോടൊപ്പം അന്യ പുരുഷനെ കണ്ടാൽ അവനെ വധിക്കാമോ? അങ്ങനെ ചെയ്താൽ അതിനു പകരമായി നിങ്ങൾ ആ വ്യക്തിയെയും വധിക്കും. അല്ലെങ്കിൽ അവൻ എന്താണ് ചെയ്യേത്? ആസിമേ, എനിക്ക് വേണ്ടി ഇക്കാര്യം നീ റസൂൽ(സ)യോട് ചോദിക്കുക, അങ്ങനെ ആസിം(റ) അക്കാര്യം റസൂൽ(സ)യോട് ചോദിക്കുകയും റസൂൽ(സ) ആ ചോദ്യം വെറുക്കുകയും അത്തരം ചോദ്യങ്ങളെ ആക്ഷേപിക്കുകയും ചെയ്തു. റസൂൽ(സ)യുടെ പ്രതികരണം ആസിം(റ)വിന് വലിയ മനോവിശമമുണ്ടാക്കി. അദ്ദേഹം വീട്ടിലേക്ക് മടങ്ങിയപ്പോൾ ഉവൈമിർ(റ) വന്ന് ചോദിച്ചു: ആസിമേ, റസൂൽ(സ) അങ്ങയോട് എന്താണ് പറഞ്ഞത്? ആസിം(റ) പറഞ്ഞു: നീ എന്നോട് ചെയ്തത് ശരിയല്ല. എന്റെ ചോദ്യം റസൂൽ(സ) വെറുത്തിരിക്കുന്നു. ഉവൈമിർ(റ) പറഞ്ഞു: എങ്കിൽ ഞാൻ തന്നെ ചെന്ന് റസൂൽ(സ)യോട് അത് ചോദിക്കും. അങ്ങനെ ഉവൈമിർ(റ) റസൂൽ(സ) ജനങ്ങൾക്കിടയിലായിരിക്കെ അവിടെ വന്ന്, റസൂൽ(സ)യോട് ചോദിച്ചു: ഒരു വ്യക്തി തന്റെ ഭാര്യയോടൊന്നിച്ച് അന്യപുരുഷനെ കണ്ടാൽ അവനെ വധിക്കാമോ, അങ്ങനെ ചെയ്താൽ നിങ്ങൾ അവനെയും വധിക്കും, അല്ലെങ്കിൽ എന്താണ് അവൻ ചെയ്യേത്? റസൂൽ(സ) പറഞ്ഞു: "നിന്റെയും നിന്റെ ഭാര്യയുടെയും വിഷയത്തിൽ ഖുർആൻ അവതരിച്ചിട്ടുണ്ട്. നീ പോയി അവളെയും കൂട്ടി വരിക." സഹ്ല്(റ) പറഞ്ഞു: റസൂൽ(സ)യുടെ ചുറ്റുമുള്ള ജനക്കൂട്ടത്തിൽ ഞാനുമുണ്ടായിരിക്കെയാണ് ആ ദമ്പതികൾ ലിആൻ ചെയ്തത്. അതിൽ നിന്ന് അവർ വിരമിച്ചപ്പോൾ ഉവൈമിർ(റ) പറഞ്ഞു: ഇനിയും ഞാൻ അവളെ കൈവശം വെക്കുന്നുവെങ്കിൽ ഞാൻ അവളെക്കുറിച്ച് പറഞ്ഞത് കളവാകും. ശേഷം നബി(സ) കൽപിക്കുന്നതിന് മുമ്പ് തന്നെ ഉവൈമിർ(റ) അവളെ മൂന്ന് മൊഴിയും ചൊല്ലി. ഇബ്നു ശിഹാബ്(റ) പറഞ്ഞു: ശേഷം അത് ലിആൻ ചെയ്യുന്നവർക്ക് ഒരു ചര്യയായി മാറി. മറ്റൊരു നിവേദനം: നബി(സ) ആസിമുബ്നു അദ്യ്(റ)വിനോട് പറഞ്ഞു: "പ്രസവിക്കും വരെ ആ സ്ത്രീയെ നിന്റെയടുത്ത് താമസിപ്പിക്കുക."മറ്റൊരു നിവേദനം: സഹ്ല്(റ) പറഞ്ഞു: എനിക്ക് പതിനഞ്ച് വയസ്സ് പ്രായമുള്ളപ്പോഴാണ് നബി(സ)യുടെ അടുത്ത് വെച്ച് ഞാനവരുടെ ലിആനിൽ സന്നിഹിതനായത്. ശേഷം അദ്ദേഹം ബാക്കി ഹദീസ് പറഞ്ഞു: അതിൽ അദ്ദേഹം പറഞ്ഞു: ശേഷം അവൾ ഗർഭിണിയായി. ആ കുട്ടിയെ ശേഷം തന്റെ ഉമ്മയിലേക്കായിരുന്നു ചേർത്ത് വിളിച്ചിരുന്നത്. (ബു,മു,ദ,ജ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദുസ്സാഇദി(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 185, 186, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=106), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِعَاصِمِ بْنِ عَدِيٍّ: "أَمْسِكِ الْمَرْأَةَ عِنْدَكَ حَتَّى تَلِدَ".', 'മറ്റൊരു നിവേദനം: നബി(സ) ആസിമുബ്നു അദ്യ്(റ)വിനോട് പറഞ്ഞു: "പ്രസവിക്കും വരെ ആ സ്ത്രീയെ നിന്റെയടുത്ത് താമസിപ്പിക്കുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=106), 2, 'وَفِي رِوَايَةٍ: عَنْ سَهْلٍ قَالَ: حَضَرْتُ لِعَانَهُمَا عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا ابْنُ خَمْسَ عَشْرَةَ سَنَةً، وَسَاقَ الْحَدِيثَ، قَالَ فِيهِ: ثُمَّ خَرَجَتْ حَامِلًا، فَكَانَ الْوَلَدُ يُدْعَى إِلَى أُمِّهِ. (ق,د,جه)', 'മറ്റൊരു നിവേദനം: സഹ്ല്(റ) പറഞ്ഞു: എനിക്ക് പതിനഞ്ച് വയസ്സ് പ്രായമുള്ളപ്പോഴാണ് നബി(സ)യുടെ അടുത്ത് വെച്ച് ഞാനവരുടെ ലിആനിൽ സന്നിഹിതനായത്. ശേഷം അദ്ദേഹം ബാക്കി ഹദീസ് പറഞ്ഞു: അതിൽ അദ്ദേഹം പറഞ്ഞു: ശേഷം അവൾ ഗർഭിണിയായി. ആ കുട്ടിയെ ശേഷം തന്റെ ഉമ്മയിലേക്കായിരുന്നു ചേർത്ത് വിളിച്ചിരുന്നത്. (ബു,മു,ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ سَهْلِ بْنِ سَعْدٍ، عَنْ عَاصِمِ بْنِ عَدِيٍّ – رَضِيَ اللهُ عَنْهُ – قَالَ: جَاءَنِي عُوَيْمِرٌ – رَجُلٌ مِنْ بَنِي الْعَجْلَانِ – فَقَالَ: أَيْ عَاصِمُ، أَرَأَيْتُمْ رَجُلًا رَأَى مَعَ امْرَأَتِهِ رَجُلًا، أَيَقْتُلُهُ فَتَقْتُلُونَهُ، أَمْ كَيْفَ يَفْعَلُ؟ يَا عَاصِمُ، سَلْ لِي رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَسَأَلَ عَاصِمٌ عَنْ ذَلِكَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَعَابَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَسَائِلَ وَكَرِهَهَا، فَجَاءَهُ عُوَيْمِرٌ فَقَالَ: مَا صَنَعْتَ يَا عَاصِمُ؟ فَقَالَ: صَنَعْتُ أَنَّكَ لَمْ تَأْتِنِي بِخَيْرٍ، كَرِهَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَسَائِلَ وَعَابَهَا. قَالَ عُوَيْمِرٌ: وَاللهِ لَأَسْأَلَنَّ عَنْ ذَلِكَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَانْطَلَقَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "قَدْ أَنْزَلَ اللهُ عَزَّ وَجَلَّ فِيكَ وَفِي صَاحِبَتِكَ، فَأْتِ بِهَا". قَالَ سَهْلٌ: وَأَنَا مَعَ النَّاسِ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ بِهَا فَتَلَاعَنَا، فَقَالَ: يَا رَسُولَ اللهِ، وَاللهِ لَئِنْ أَمْسَكْتُهَا لَقَدْ كَذَبْتُ عَلَيْهَا. فَفَارَقَهَا قَبْلَ أَنْ يَأْمُرَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِفِرَاقِهَا، فَصَارَتْ سُنَّةَ الْمُتَلَاعِنَيْنِ. (ن)', 'ആസിമുബ്നു അദ്യ്(റ)വിൽ നിന്ന് സഹ്ലുബ്നു സഅ്ദ്(റ): ബനുൽ ഇജ്ലാൻ ഗോത്രത്തിൽപെട്ട ഉവൈമിർ(റ) എന്റെയടുത്ത് വന്ന് പറഞ്ഞു: ഒരു വ്യക്തി തന്റെ ഭാര്യയോടൊപ്പം അന്യപുരുഷനെ കണ്ടാൽ അവനെ കൊല്ലാൻ പറ്റുമോ? അങ്ങനെയെങ്കിൽ നിങ്ങൾ അവനെയും വധിക്കും, അല്ലെങ്കിൽ അവൻ എന്താണ് ചെയ്യേണ്ടത്? ആസിമേ, എനിക്ക് വേണ്ടി നീ ഇത് റസൂൽ(സ)യോട് ചോദിക്കുക. അങ്ങനെ ആസിം(റ) ആ വിഷയം നബി(സ)യോട് ചോദിച്ചു. നബി(സ) ആ ചോദ്യത്തെ വെറുക്കുകയും അതിനെ ആക്ഷേപിക്കുകയും ചെയ്തു. ശേഷം ഉവൈമിർ(റ) വന്ന് ആസിം(റ)വിനോട് ചോദിച്ചു: ആസിമേ, നീ എന്താണ് ചെയ്തത്. ആസിം(റ) പറഞ്ഞു: ഞാനത് ചെയ്തു, പക്ഷേ നീ എന്നോട് ചെയ്ത കാര്യം ശരിയായില്ല, റസൂൽ(സ) ആ ചോദ്യം വെറുക്കുകയും അതിനെ ആക്ഷേപിക്കുകയും ചെയ്തു. ഉവൈമിർ(റ) പറഞ്ഞു: ഞാൻ റസൂൽ(സ)യോട് അതിനെക്കുറിച്ച് ചോദിക്കുക തന്നെ ചെയ്യും. അങ്ങനെ അദ്ദേഹം റസൂൽ(സ)യുടെ അടുത്ത് പോവുകയും അക്കാര്യം ചോദിക്കുകയും ചെയ്തു. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "നിന്റെയും നിന്റെ ഭാര്യയുടെയും വിഷയത്തിൽ അല്ലാഹു തീരുമാനിച്ചിട്ടുണ്ട്. അത്കൊണ്ട് നീ അവളെയും കൂട്ടി വരിക." സഹ്ല്(റ) പറഞ്ഞു: റസൂൽ(സ)യോടൊപ്പമുള്ള ജനങ്ങളിൽ ഞാനുമുണ്ടായിരുന്നു. അങ്ങനെ ഉവൈമിർ(റ) തന്റെ ഭാര്യയെ കൊണ്ട് വരികയും അവർ പരസ്പരം ലിആൻ ചെയ്യുകയും ചെയ്തു. ശേഷം അദ്ദേഹം പറഞ്ഞു: റസൂലേ, ഞാൻ ഇനിയും അവളെ കയ്യിൽ വെച്ചാൽ ഞാൻ അവളെക്കുറിച്ച് പറഞ്ഞത് കളവാകും. അങ്ങനെ റസൂൽ(സ) കൽപിക്കും മുമ്പ് തന്നെ ഉവൈമിർ(റ) അവളെ ഒഴിവാക്കുകയും പരസ്പരം ലിആൻ ചെയ്യുന്നവർക്ക് അതൊരു ചര്യയായി മാറുകയും ചെയ്തു. (ന)', 'سَهْلِ بْنِ سَعْدٍ، عَنْ عَاصِمِ بْنِ عَدِيٍّ –', 'ആസിമുബ്നു അദ്യ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 186, 186, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ، فِي خَبَرِ الْمُتَلَاعِنَيْنِ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَبْصِرُوهَا: فَإِنْ جَاءَتْ بِهِ أَدْعَجَ الْعَيْنَيْنِ، عَظِيمَ الْأَلْيَتَيْنِ، فَلَا أُرَاهُ إِلَّا قَدْ صَدَقَ. وَإِنْ جَاءَتْ بِهِ أُحَيْمِرَ، كَأَنَّهُ وَحَرَةٌ، فَلَا أُرَاهُ إِلَّا كَاذِبًا". قَالَ: فَجَاءَتْ بِهِ عَلَى النَّعْتِ الْمَكْرُوهِ. وَفِي رِوَايَة: فَكَانَ يُدْعَى – يَعْنِي الْوَلَدَ – لِأُمِّهِ. وَفِي رِوَايَة: فَطَلَّقَهَا ثَلَاثَ تَطْلِيقَاتٍ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَنْفَذَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ مَا صُنِعَ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُنَّةً. قَالَ سَهْلٌ: حَضَرْتُ هَذَا عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَمَضَتِ السُّنَّةُ بَعْدُ فِي الْمُتَلَاعِنَيْنِ: أَنْ يُفَرَّقَ بَيْنَهُمَا ثُمَّ لَا يَجْتَمِعَانِ أَبَدًا. (د)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): പരസ്പര ലിആൻ ചെയ്ത ഭാര്യഭർത്താക്കന്മാരെക്കുറിച്ചുള്ള ഹദീസിൽ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അവളെ നിരീക്ഷിക്കുക, കണ്ണിലെ കറുപ്പ് അധികരിച്ച വലിയ ഊരയുള്ള കുട്ടിയെയാണ് അവൾ പ്രസവിക്കുന്നതെങ്കിൽ അവൻ സത്യമാണ് പറഞ്ഞതെന്ന് ഞാൻ മനസ്സിലാക്കും. ചുവന്ന പല്ലിയുടെ രൂപത്തിൽ ചുവപ്പ് നിറത്തോട് ചാഞ്ഞ കുട്ടിയെയാണ് അവൾ പ്രസവിക്കുന്നതെങ്കിൽ അവൻ കളവ് പറഞ്ഞതാണെന്ന് ഞാൻ മനസ്സിലാക്കും." സഹ്ല്(റ) പറഞ്ഞു: ശേഷം വെറുക്കപ്പെടുന്ന വിശേഷണത്തോട് കൂടെ അവൾ ആ കുട്ടിയെ പ്രസവിച്ചു. മറ്റൊരു നിവേദനം: ആ കുട്ടിയെ തന്റെ ഉമ്മയിലേക്ക് ചേർത്തായിരുന്നു വിളിക്കപ്പെട്ടിരുന്നത്. മറ്റൊരു നിവേദനം: അങ്ങനെ റസൂൽ(സ)യുടെ അടുത്ത് വെച്ച് ഉവൈമിർ(റ) അവളെ മൂന്ന് മൊഴിയും ചൊല്ലി. റസൂൽ(സ) അത് നടപ്പാക്കുകയും ചെയ്തു. നബി(സ)യുടെ സന്നിഹിതിയിൽ ചെയ്യപ്പെട്ട ആ കാര്യം ഒരു ചര്യയായിട്ട് മാറി. സഹ്ല്(റ) പറഞ്ഞു: റസൂൽ(സ)യോടൊപ്പം ഈ സംഭവത്തിന് ഞാനും സന്നിഹിതനായിരുന്നു. അതിനുശേഷം ലിആൻ ചെയ്യുന്നവരിൽ നടപ്പിലാക്കുന്ന ചര്യ ഇതാണ്. അവരിരുവരെയും വേർപിരിക്കണം, ഇനി ഒരിക്കലും ഒരുമിച്ചുകഴിയരുത്. (ദ)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 186, 187, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=108), 1, 'وَفِي رِوَايَةٍ: فَكَانَ يُدْعَى – يَعْنِي الْوَلَدَ – لِأُمِّهِ.', 'മറ്റൊരു നിവേദനം: ആ കുട്ടിയെ തന്റെ ഉമ്മയിലേക്ക് ചേർത്തായിരുന്നു വിളിക്കപ്പെട്ടിരുന്നത്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=108), 2, 'وَفِي رِوَايَةٍ: فَطَلَّقَهَا ثَلَاثَ تَطْلِيقَاتٍ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَنْفَذَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ مَا صُنِعَ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُنَّةً. قَالَ سَهْلٌ: حَضَرْتُ هَذَا عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَمَضَتِ السُّنَّةُ بَعْدُ فِي الْمُتَلَاعِنَيْنِ: أَنْ يُفَرَّقَ بَيْنَهُمَا ثُمَّ لَا يَجْتَمِعَانِ أَبَدًا. (د)', 'മറ്റൊരു നിവേദനം: അങ്ങനെ റസൂൽ(സ)യുടെ അടുത്ത് വെച്ച് ഉവൈമിർ(റ) അവളെ മൂന്ന് മൊഴിയും ചൊല്ലി. റസൂൽ(സ) അത് നടപ്പാക്കുകയും ചെയ്തു. നബി(സ)യുടെ സന്നിഹിതിയിൽ ചെയ്യപ്പെട്ട ആ കാര്യം ഒരു ചര്യയായിട്ട് മാറി. സഹ്ല്(റ) പറഞ്ഞു: റസൂൽ(സ)യോടൊപ്പം ഈ സംഭവത്തിന് ഞാനും സന്നിഹിതനായിരുന്നു. അതിനുശേഷം ലിആൻ ചെയ്യുന്നവരിൽ നടപ്പിലാക്കുന്ന ചര്യ ഇതാണ്. അവരിരുവരെയും വേർപിരിക്കണം, ഇനി ഒരിക്കലും ഒരുമിച്ചുകഴിയരുത്. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: شَهِدْتُ الْمُتَلَاعِنَيْنِ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ تَلَاعَنَا. وَفِي رِوَايَةٍ: أَ○نَّهُ شَهِدَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرَّقَ بَيْنَ الْمُتَلَاعِنَيْنِ، فَقَالَ الرَّجُلُ: كَذَبْتُ عَلَيْهَا يَا رَسُولَ اللهِ إِنْ أَمْسَكْتُهَا. وَفِي رِوَايَةٍ: وَكَانَتْ حَامِلًا، فَأَنْكَرَ حَمْلَهَا، فَكَانَ ابْنُهَا يُدْعَى إِلَيْهَا، ثُمَّ جَرَتِ السُّنَّةُ فِي الْمِيرَاثِ أَنْ يَرِثَهَا وَتَرِثَ مِنْهُ مَا فَرَضَ اللهُ عَزَّ وَجَلَّ لَهَا. (د)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): റസൂൽ(സ)യുടെ കാലത്ത് ഭാര്യാഭർത്താക്കൻമാർ പരസ്പരം ലിആൻ ചെയ്യുമ്പോൾ ഞാനും അവിടെയുണ്ടായിരുന്നു. മറ്റൊരു നിവേദനം: പരസ്പരം ലിആൻ ചെയ്ത ഭാര്യഭർത്താക്കൻമാരെ നബി(സ) വേർപിരിക്കുമ്പോൾ സഹ്ല്(റ)വും അവിടെയുണ്ടായിരുന്നു. അപ്പോൾ ഭർത്താവ് പറഞ്ഞു: ഇനിയും അവളെ കയ്യിൽ വെക്കുകയാണെങ്കിൽ ഞാൻ അവളെക്കുറിച്ച് പറഞ്ഞത് കളവാകും, റസൂലേ. മറ്റൊരു നിവേദനം: ആ സ്ത്രീ ഗർഭിണിയായിരുന്നു. പക്ഷേ ആ ഗർഭം തന്നിൽ നിന്നുള്ളതല്ലെന്ന് ഭർത്താവ് പറഞ്ഞു. അങ്ങനെ അവളുടെ മകൻ അവളിലേക്ക് തന്നെ ചേർക്കപ്പെടുകയും ചെയ്തു. ഇത് പോലുള്ള വിഷയത്തിൽ മകൻ ഉമ്മയിൽ നിന്നും ഉമ്മ മകനിൽ നിന്നും അല്ലാഹു നിശ്ചയിച്ച വിഹിതം അനന്തരമെടുക്കുമെന്ന ചര്യ നടപ്പായി. (ദ)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 187, 187, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=109), 1, 'وَفِي رِوَايَةٍ: أَ○نَّهُ شَهِدَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرَّقَ بَيْنَ الْمُتَلَاعِنَيْنِ، فَقَالَ الرَّجُلُ: كَذَبْتُ عَلَيْهَا يَا رَسُولَ اللهِ إِنْ أَمْسَكْتُهَا.', 'മറ്റൊരു നിവേദനം: പരസ്പരം ലിആൻ ചെയ്ത ഭാര്യഭർത്താക്കൻമാരെ നബി(സ) വേർപിരിക്കുമ്പോൾ സഹ്ല്(റ)വും അവിടെയുണ്ടായിരുന്നു. അപ്പോൾ ഭർത്താവ് പറഞ്ഞു: ഇനിയും അവളെ കയ്യിൽ വെക്കുകയാണെങ്കിൽ ഞാൻ അവളെക്കുറിച്ച് പറഞ്ഞത് കളവാകും, റസൂലേ.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=109), 2, 'وَفِي رِوَايَةٍ: وَكَانَتْ حَامِلًا، فَأَنْكَرَ حَمْلَهَا، فَكَانَ ابْنُهَا يُدْعَى إِلَيْهَا، ثُمَّ جَرَتِ السُّنَّةُ فِي الْمِيرَاثِ أَنْ يَرِثَهَا وَتَرِثَ مِنْهُ مَا فَرَضَ اللهُ عَزَّ وَجَلَّ لَهَا. (د)', 'മറ്റൊരു നിവേദനം: ആ സ്ത്രീ ഗർഭിണിയായിരുന്നു. പക്ഷേ ആ ഗർഭം തന്നിൽ നിന്നുള്ളതല്ലെന്ന് ഭർത്താവ് പറഞ്ഞു. അങ്ങനെ അവളുടെ മകൻ അവളിലേക്ക് തന്നെ ചേർക്കപ്പെടുകയും ചെയ്തു. ഇത് പോലുള്ള വിഷയത്തിൽ മകൻ ഉമ്മയിൽ നിന്നും ഉമ്മ മകനിൽ നിന്നും അല്ലാഹു നിശ്ചയിച്ച വിഹിതം അനന്തരമെടുക്കുമെന്ന ചര്യ നടപ്പായി. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلْمُتَلَاعِنَيْنِ: "حِسَابُكُمَا عَلَى اللهِ، أَحَدُكُمَا كَاذِبٌ، لَا سَبِيلَ لَكَ عَلَيْهَا". قَالَ: يَا رَسُولَ اللهِ مَالِي؟ قَالَ: "لَا مَالَ لَكَ إِنْ كُنْتَ صَدَقْتَ عَلَيْهَا فَهُوَ بِمَا اسْتَحْلَلْتَ مِنْ فَرْجِهَا، وَإِنْ كُنْتَ كَذَبْتَ عَلَيْهَا فَذَاكَ أَبْعَدُ لَكَ مِنْهَا". (ق,د,ن)', 'ഇബ്നുഉമർ(റ): ലിആൻ ചെയ്ത ഭാര്യഭർത്താക്കന്മാരോട് റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ രണ്ടു പേരെയും വിചാരണ നടത്തേണ്ടത് അല്ലാഹുവാണ്. നിങ്ങളിലൊരുത്തൻ കളവാണ് പറഞ്ഞിട്ടുള്ളത്. നിനക്ക് (ഭർത്താവിന്) അവളുടെ കാര്യത്തിൽ ഒരു മാർഗ്ഗവുമില്ല." ഭർത്താവ് പറഞ്ഞു: റസൂലേ, എന്റെ മുതൽ? റസൂൽ(സ) പറഞ്ഞു: "നിനക്ക് നിന്റെ മുതൽ ലഭിക്കുകയില്ല, നീ അവളെക്കുറിച്ച് പറഞ്ഞത് സത്യമാണെങ്കിൽ നീ അവളുടെ ഗുഹ്യസ്ഥാനത്തെ അനുവദനീയമാക്കിയതിന് പകരമാണത്. നീ അവളെക്കുറിച്ച് പറഞ്ഞത് നുണയാണെങ്കിൽ നിനക്കത് ഇപ്പറഞ്ഞതിനേക്കാൾ അന്യമാണ്." (ബു,മു,ദ,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 187, 187, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ مُحَمَّدٍ – هُوَ ابْنُ سِيرِينَ – قَالَ: سَأَلْتُ أَنَسَ بْنَ مَالِكٍ رَضِيَ اللهُ عَنْهُ، وَأَنَا أُرَى أَنَّ عِنْدَهُ مِنْهُ عِلْمًا، فَقَالَ: إِنَّ هِلَالَ بْنَ أُمَيَّةَ قَذَفَ امْرَأَتَهُ بِشَرِيكِ بْنِ سَحْمَاءَ، وَكَانَ أَخَا الْبَرَاءِ بْنِ مَالِكٍ لِأُمِّهِ، وَكَانَ أَوَّلَ رَجُلٍ لَاعَنَ فِي الْإِسْلَامِ، قَالَ: فَلَاعَنَهَا، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَبْصِرُوهَا فَإِنْ جَاءَتْ بِهِ أَبْيَضَ سَبِطًا قَضِيءَ الْعَيْنَيْنِ فَهُوَ لِهِلَالِ بْنِ أُمَيَّةَ، وَإِنْ جَاءَتْ بِهِ أَكْحَلَ جَعْدًا حَمْشَ السَّاقَيْنِ فَهُوَ لِشَرِيكِ بْنِ سَحْمَاءَ". قَالَ فَأُنْبِئْتُ أَنَّهَا جَاءَتْ بِهِ أَكْحَلَ جَعْدًا، حَمْشَ السَّاقَيْنِ. (م)', 'മുഹമ്മദുബ്നു സീരീൻ(റ): അനസുബ്നു മാലിക്(റ)വിന്റെയടുത്ത് എന്തോ വിജ്ഞാനമുണ്ടെന്നറിഞ്ഞ് ഈ വിഷയം ഞാൻ അദ്ദേഹത്തോട് ചോദിച്ചു: അപ്പോൾ അനസ്(റ) പറഞ്ഞു: ഹിലാലുബ്നു ഉമയ്യ(റ) തന്റെ ഭാര്യക്ക് ശരീകുബ്നു സഹ്മാഉമായി അവിഹത ബന്ധമുെന്ന് ആരോപിച്ചു. ഹിലാൽ(റ) ബറാഉബ്നു മാലിക്(റ)വിന്റെ ഉമ്മയൊത്ത സഹോദരനായിരുന്നു. ഇസ്ലാമിൽ ആദ്യമായി ലിആൻ ചെയ്ത വ്യക്തിയും അദ്ദേഹമാണ്. അദ്ദേഹം തന്റെ ഭാര്യയെ ലിആൻ ചെയ്തു. ശേഷം റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അവളെ നിരീക്ഷിക്കുക, വെളുത്തതും നീണ്ടതും ഇരുകണ്ണുകളിലും ചുവപ്പുള്ളതുമായ കുട്ടിയെയാണ് അവൾ പ്രസവിക്കുന്നതെങ്കിൽ ആ കുട്ടി ഹിലാലുബ്നു ഉമയ്യ(റ)വിന്റേതാണ്. സുറുമക്കണ്ണും ചുരുണ്ട മുടിയും നേർത്ത കണങ്കാലുമുള്ള കുട്ടിയെയാണ് അവൾ പ്രസവിക്കുന്നതെങ്കിൽ ആ കുട്ടി ശരീകുബ്നു സഹ്മാഇന്റേതാണ്." നിവേദകൻ പറഞ്ഞു: സുറുമക്കണ്ണുള്ള, ചുരുണ്ട മുടിയുള്ള നേർത്ത കാലുള്ള കുട്ടിയെയാണ് അവൾ പ്രസവിച്ചതെന്ന് ശേഷം ഞാൻ അറിഞ്ഞു. (മു)', 'مُحَمَّدٍ – هُوَ ابْنُ سِيرِينَ – قَالَ', 'മുഹമ്മദുബ്നു സീരീൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 187, 188, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ سَعْدُ بْنُ عُبَادَةَ رَضِيَ اللهُ عَنْهُ: يَا رَسُولَ اللهِ، لَوْ وَجَدْتُ مَعَ أَهْلِي رَجُلًا لَمْ أَمَسَّهُ حَتَّى آتِيَ بِأَرْبَعَةِ شُهَدَاءَ؟ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "نَعَمْ". قَالَ: كَلَّا وَالَّذِي بَعَثَكَ بِالْحَقِّ، إِنْ كُنْتُ لَأُعَاجِلُهُ بِالسَّيْفِ قَبْلَ ذَلِكَ. قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اسْمَعُوا إِلَى مَا يَقُولُ سَيِّدُكُمْ، إِنَّهُ لَغَيُورٌ، وَأَنَا أَغْيَرُ مِنْهُ، وَاللهُ أَغْيَرُ مِنِّي". (م)', 'അബൂഹുറൈറ(റ): സഅ്ദുബ്നു ഉബാദ(റ) ചോദിച്ചു: റസൂലേ, എന്റെ ഭാര്യയോടൊപ്പം അന്യപുരുഷനെ കണ്ടാൽ നാല് സാക്ഷികളെ ലഭിക്കുംവരെ എനിക്ക് അവനെ ഒന്നും ചെയ്യാൻ പറ്റില്ലേ. റസൂൽ(സ) പറഞ്ഞു: "ഇല്ല." സഅ്ദ്(റ) പറഞ്ഞു: അങ്ങയെ സത്യവുമായി അയച്ചവൻ തന്നെ സത്യം, അതിനുമുമ്പ് തന്നെ ഞാനവനെ വാള് കൊണ്ട് വെട്ടും. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ നേതാവ് എന്താണ് പറയുന്നതെന്ന് നിങ്ങൾ കേൾക്കുക, അദ്ദേഹം വാക്ക് പാലിക്കുന്നവനാണ്, ഞാൻ അദ്ദേഹത്തേക്കാൾ വാക്ക് പാലിക്കുന്നവനാണ്, അല്ലാഹു എന്നേക്കാളും വാക്ക് പാലിക്കുന്നവനാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 188, 188, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ هِلَالَ بْنَ أُمَيَّةَ قَذَفَ امْرَأَتَهُ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِشَرِيكِ بْنِ سَحْمَاءَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْبَيِّنَةُ أَوْ حَدٌّ فِي ظَهْرِكَ". قَالَ: يَا رَسُولَ اللهِ، إِذَا رَأَى أَحَدُنَا رَجُلًا عَلَى امْرَأَتِهِ يَلْتَمِسُ الْبَيِّنَةَ؟ فَجَعَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْبَيِّنَةُ وَإِلَّا فَحَدٌّ فِي ظَهْرِكَ". فَقَالَ هِلَالٌ: وَالَّذِي بَعَثَكَ بِالْحَقِّ نَبِيًّا إِنِّي لَصَادِقٌ، وَلَيُنْزِلَنَّ اللهُ فِي أَمْرِي مَا يُبْرِئُ بِهِ ظَهْرِي مِنَ الْحَدِّ. فَنَزَلَتْ: {وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ وَلَمْ يَكُنْ لَهُمْ شُهَدَاءُ إِلَّا أَنْفُسُهُمْ} فَقَرَأَ حَتَّى بَلَغَ: {مِنَ الصَّادِقِينَ} فَانْصَرَفَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَرْسَلَ إِلَيْهِمَا فَجَاءَا، فَقَامَ هِلَالُ بْنُ أُمَيَّةَ فَشَهِدَ، وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللهُ يَعْلَمُ أَنَّ أَحَدَكُمَا كَاذِبٌ، فَهَلْ مِنْكُمَا مِنْ تَائِبٍ". ثُمَّ قَامَتْ فَشَهِدَتْ، فَلَمَّا كَانَ عِنْدَ الْخَامِسَةِ: {أَنَّ غَضَبَ اللهِ عَلَيْهَا إِنْ كَانَ مِنَ الصَّادِقِينَ} وَقَالُوا لَهَا: إِنَّهَا مُوجِبَةٌ، فَقَالَ ابْنُ عَبَّاسٍ: فَتَلَكَّأَتْ وَنَكَصَتْ حَتَّى ظَنَنَّا أَنَّهَا سَتَرْجِعُ، فَقَالَتْ: لَا أَفْضَحُ قَوْمِي سَائِرَ الْيَوْمِ. فَمَضَتْ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَبْصِرُوهَا فَإِنْ جَاءَتْ بِهِ أَكْحَلَ الْعَيْنَيْنِ سَابِغَ الْأَلْيَتَيْنِ خَدَلَّجَ السَّاقَيْنِ فَهُوَ لِشَرِيكِ بْنِ سَحْمَاءَ". فَجَاءَتْ بِهِ كَذَلِكَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْلَا مَا مَضَى مِنْ كِتَابِ اللهِ لَكَانَ لِي وَلَهَا شَأْنٌ". (خ,د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഹിലാലുബ്നു ഉമയ്യ(റ) തന്റെ ഭാര്യക്ക് ശരീകുബ്നു സഹ്മാഉമായി അവിഹിത ബന്ധമുണ്ടെന്നാരോപിച്ചു. നബി(സ) പറഞ്ഞു: "തെളിവ് കൊണ്ട് വരിക, അല്ലെങ്കിൽ നിന്നെ ഹദ്ദടിക്കും." ഹിലാൽ(റ) ചോദിച്ചു: റസൂലേ, തന്റെ ഭാര്യയുടെ മേലെ മറ്റൊരുത്തനെ കണ്ടവൻ തെളിവ് തേടേണ്ടതുണ്ടോ? നബി(സ) വീണ്ടും പറഞ്ഞു: "തെളിവ് കൊണ്ടുവരിക, അല്ലെങ്കിൽ നിന്നെ ഹദ്ദടിക്കും." ഹിലാൽ(റ) പറഞ്ഞു: അങ്ങയെ സത്യസന്ദേശത്തിന്റെ പ്രവാചകനായി അയച്ചവൻ തന്നെ സത്യം, ഞാൻ സത്യവാനാണ്. എന്നെ ശിക്ഷയിൽ നിന്ന് മുക്തനാക്കുന്ന സന്ദേശം അല്ലാഹു ഇറക്കുകതന്നെ ചെയ്യും. അപ്പോൾ: ''തങ്ങളുടെ ഭാര്യമാരെക്കുറിച്ച് ആരോപണമുന്നയിക്കുകയും തങ്ങളല്ലാതെ മറ്റാരും സാക്ഷികളില്ലാത്തവരുമായ ആളുകൾ'' എന്ന് തുടങ്ങി ''നിശ്ചയം താൻ സത്യസന്ധരുടെ ഗണത്തിലാകുന്നുവെന്ന് അല്ലാഹുവിന്റെ പേരിൽ നാല് പ്രാവശ്യം സാക്ഷ്യംവഹിക്കലാകുന്നു'' എന്നത് വരെയുള്ള സൂക്തമിറങ്ങി. അതുകഴിഞ്ഞപ്പോൾ റസൂൽ(സ) അവരിരുവരുടെ അടുത്തേക്കും ആളെ അയച്ചു. അങ്ങനെ അവർ രണ്ട് പേരും വന്നു. ആദ്യം ഹിലാഹുബ്നു ഉമയ്യ(റ) എഴുന്നേറ്റ് സത്യം ചെയ്തു. നബി(സ) ഇപ്രകാരം പറയുന്നുണ്ടായിരുന്നു: "നിങ്ങളിലൊരാൾ നുണയാണ് പറയുന്നതെന്ന് അല്ലാഹുവിനറിയാം, അതിനാൽ ആരെങ്കിലും പശ്ചാത്താപിക്കാൻ തയ്യാറുണ്ടോ?" ശേഷം ഹിലാൽ(റ)വിന്റെ ഭാര്യ എഴുന്നേറ്റ് സത്യം ചെയ്തു. അഞ്ചാം പ്രാവശ്യം ''അവൻ സത്യമാണ് പറയുന്നതെങ്കിൽ തന്റെ മേൽ അല്ലാഹുവിന്റെ കോപമുണ്ടാവട്ടെ'' എന്ന് പറയാനൊരുങ്ങിയപ്പോൾ ജനങ്ങൾ അവളോട് പറഞ്ഞു: ഇത് ശിക്ഷയെ നിർബന്ധമാക്കുന്നതാണ്. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അത് കേട്ടപ്പോൾ അവൾ ഒന്ന് അടങ്ങുകയും മൗനമവലംബിക്കുകയും ചെയ്തു. അവൾ പിന്തിരിഞ്ഞു എന്ന്വരെ ഞങ്ങൾ വിചാരിച്ചു. ശേഷമവൾ പറഞ്ഞു: വരും ദിവസങ്ങളിലും, ഞാൻ എന്റെ കുടുംബക്കാരെ വഷളാക്കുകയില്ല. അങ്ങനെ അവൾ അഞ്ചാമത്തെ സത്യവും ചെയ്തു. ശേഷം റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളവളെ നിരീക്ഷിക്കുക, സുറുമക്കണ്ണുകളുള്ള, വലിയ ഊരയുള്ള, തടിച്ച കണങ്കാലുകളുള്ള കുട്ടിയെയാണ് അവൾ പ്രസവിക്കുന്നതെങ്കിൽ ആ കുട്ടി ശരീകുബ്നു സഹ്മാഇന്റേതാണ്." അങ്ങനെ അവൾ അതേ വിശേഷണത്തിലുള്ള കുട്ടിയെ പ്രസവിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ വിധി ഇറങ്ങിയിട്ടില്ലായിരുന്നുവെങ്കിൽ ഞാൻ അവളുടെ കാര്യത്തിൽ പ്രത്യേക നടപടി എടുക്കുമായിരുന്നു." (ബു,ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 188, 189, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَ رَجُلًا حِينَ أَمَرَ الْمُتَلَاعِنَيْنِ أَنْ يَتَلَاعَنَا: أَنْ يَضَعَ يَدَهُ عَلَى فِيهِ عِنْدَ الْخَامِسَةِ، وَيَقُولَ: إِنَّهَا مُوجِبَةٌ. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ലിആൻ ചെയ്യുന്ന ദമ്പതികളോട് ലിആൻ ചെയ്യാൻ വേണ്ടി പറഞ്ഞശേഷം, അഞ്ചാമതായി സത്യം ചെയ്യുന്ന സമയത്ത് തന്റെ വായയുടെ മേൽ കൈവെക്കാനും, ഇത് ശിക്ഷയെ നിർബന്ധമാക്കുന്നതാണ് എന്ന് പറയാനും നബി(സ) ഒരാളോട് കൽപിച്ചു. (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 189, 189, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ هِلَالُ بْنُ أُمَيَّةَ – وَهُوَ أَحَدُ الثَّلَاثَةِ الَّذِينَ تَابَ اللهُ عَلَيْهِمْ – فَجَاءَ مِنْ أَرْضِهِ عَشِيًّا فَوَجَدَ عِنْدَ أَهْلِهِ رَجُلًا، فَرَأَى بِعَيْنِهِ وَسَمِعَ بِأُذُنِهِ، فَلَمْ يَهِجْهُ حَتَّى أَصْبَحَ، ثُمَّ غَدَا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي جِئْتُ أَهْلِي عِشَاءً فَوَجَدْتُ عِنْدَهُمْ رَجُلًا، فَرَأَيْتُ بِعَيْنَيَّ وَسَمِعْتُ بِأُذُنَيَّ. فَكَرِهَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَا جَاءَ بِهِ، وَاشْتَدَّ عَلَيْهِ، فَنَزَلَتْ: {وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ وَلَمْ يَكُنْ لَهُمْ شُهَدَاءُ إِلَّا أَنْفُسُهُمْ فَشَهَادَةُ أَحَدِهِمْ} الْآيَتَيْنِ كِلْتَيْهِمَا، فَسُرِّيَ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "أَبْشِرْ يَا هِلَالُ، قَدْ جَعَلَ اللهُ عَزَّ وَجَلَّ لَكَ فَرَجًا وَمَخْرَجًا". قَالَ هِلَالٌ: قَدْ كُنْتُ أَرْجُو ذَلِكَ مِنْ رَبِّي، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَرْسِلُوا إِلَيْهَا". فَجَاءَتْ، فَتَلَاهَا عَلَيْهِمَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَذَكَّرَهُمَا وَأَخْبَرَهُمَا أَنَّ عَذَابَ الْآخِرَةِ أَشَدُّ مِنْ عَذَابِ الدُّنْيَا، فَقَالَ هِلَالٌ: وَاللهِ لَقَدْ صَدَقْتُ عَلَيْهَا، فَقَالَتْ: قَدْ كَذَبَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَاعِنُوا بَيْنَهُمَا". فَقِيلَ لِهِلَالٍ: اشْهَدْ، فَشَهِدَ أَرْبَعَ شَهَادَاتٍ بِاللهِ إِنَّهُ لَمِنَ الصَّادِقِينَ، فَلَمَّا كَانَتِ الْخَامِسَةُ قِيلَ لَهُ: "يَا هِلَالُ، اتَّقِ اللهَ، فَإِنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَةِ، وَإِنَّ هَذِهِ الْمُوجِبَةُ الَّتِي تُوجِبُ عَلَيْكَ الْعَذَابَ". فَقَالَ: وَاللهِ، لَا يُعَذِّبُنِي اللهُ عَلَيْهَا كَمَا لَمْ يَجْلِدْنِي عَلَيْهَا. فَشَهِدَ الْخَامِسَةَ أَنَّ لَعْنَةَ اللهِ عَلَيْهِ إِنْ كَانَ مِنَ الْكَاذِبِينَ، ثُمَّ قِيلَ لَهَا: اشْهَدِي، فَشَهِدَتْ أَرْبَعَ شَهَادَاتٍ بِاللهِ إِنَّهُ لَمِنَ الْكَاذِبِينَ، فَلَمَّا كَانَتِ الْخَامِسَةُ قِيلَ لَهَا: "اتَّقِي اللهَ، فَإِنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَةِ، وَإِنَّ هَذِهِ الْمُوجِبَةَ الَّتِي تُوجِبُ عَلَيْكِ الْعَذَابَ". فَتَلَكَّأَتْ سَاعَةً ثُمَّ قَالَتْ: وَاللهِ لَا أَفْضَحُ قَوْمِي، فَشَهِدَتِ الْخَامِسَةَ: أَنَّ غَضَبَ اللهِ عَلَيْهَا إِنْ كَانَ مِنَ الصَّادِقِينَ. فَفَرَّقَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُمَا، وَقَضَى أَنْ لَا يُدْعَى وَلَدُهَا لِأَبٍ، وَلَا تُرْمَى وَلَا يُرْمَى وَلَدُهَا، وَمَنْ رَمَاهَا أَوْ رَمَى وَلَدَهَا فَعَلَيْهِ الْحَدُّ، وَقَضَى: أَنْ لَا بَيْتَ لَهَا عَلَيْهِ وَلَا قُوتَ، مِنْ أَجْلِ أَنَّهُمَا يَتَفَرَّقَانِ مِنْ غَيْرِ طَلَاقٍ، وَلَا مُتَوَفًّى عَنْهَا. وَقَالَ: "إِنْ جَاءَتْ بِهِ أُصَيْهِبَ أُرَيْصِحَ أُثَيْبِجَ حَمْشَ السَّاقَيْنِ فَهُوَ لِهِلَالٍ، وَإِنْ جَاءَتْ بِهِ أَوْرَقَ جَعْدًا جُمَالِيًّا خَدَلَّجَ السَّاقَيْنِ سَابِغَ الْأَلْيَتَيْنِ، فَهُوَ لِلَّذِي رُمِيَتْ بِهِ". فَجَاءَتْ بِهِ أَوْرَقَ جَعْدًا جُمَالِيًّا خَدَلَّجَ السَّاقَيْنِ سَابِغَ الْأَلْيَتَيْنِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْلَا الْأَيْمَانُ لَكَانَ لِي وَلَهَا شَأْنٌ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): അല്ലാഹു പശ്ചാത്താപം സ്വീകരിച്ച മൂന്നുപേരിൽ ഒരാളായ ഹിലാലുബ്നു ഉമയ്യ(റ) വൈകുന്നേരം തന്റെ തോട്ടത്തിൽ നിന്ന് തിരിച്ചെത്തിയപ്പോൾ തന്റെ ഭാര്യയുടെ അടുത്ത് അന്യപുരുഷനെ (വ്യഭിചരിക്കുന്നതായി) കണ്ടു. അദ്ദേഹം സ്വന്തം കണ്ണ്കൊണ്ട് കാണുകയും സ്വന്തം ചെവികൊണ്ട് കേൾക്കുകയും ചെയ്തു. നേരം പുലരുവോളം അത് കണ്ടെന്ന് അദ്ദേഹം കാണിച്ചില്ല. ശേഷം റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: റസൂലേ, വൈകുന്നേരം എന്റെ ഭാര്യയുടെ അടുത്ത് ചെന്നപ്പോൾ അവിടെ ഒരു അന്യപുരുഷനെ കണ്ടു. ഞാൻ അത് സ്വന്തം കണ്ണ്കൊണ്ട് കാണുകയും സ്വന്തം ചെവികൊണ്ട് അതിന്റെ ശബ്ദം കേൾക്കുകയും ചെയ്തു. അദ്ദേഹത്തിന്റെ പരാതിയെ റസൂൽ(സ) വെറുക്കുകയും അദ്ദേഹത്തോട് ഗൗരവത്തോടെ സംസാരിക്കുകയും ചെയ്തു. അപ്പോൾ ''തങ്ങളുടെ ഭാര്യമാർക്കുനേരെ ആരോപണമുന്നയിക്കുന്നവരും തങ്ങളല്ലാതെ മറ്റൊരും സാക്ഷിയില്ലാത്തവരുമായ ആളുകൾ'' എന്ന് തുടങ്ങുന്ന രണ്ട് സൂക്തങ്ങളിറങ്ങി. സൂക്തങ്ങൾ ഇറങ്ങിക്കഴിഞ്ഞതിനു ശേഷം റസൂൽ(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "ഹിലാലേ, നീ സന്തോഷിക്കുക, അല്ലാഹു അങ്ങേക്ക് രക്ഷാമാർഗ്ഗം നിശ്ചയിച്ചു തന്നിരിക്കുന്നു." ഹിലാൽ(റ) പറഞ്ഞു: ഞാൻ എന്റെ രക്ഷിതാവിൽ നിന്ന് അത് പ്രതീക്ഷിച്ച് കൊണ്ടിരിക്കുകയായിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അവളിലേക്ക് ആളെ പറഞ്ഞയക്കുക." അങ്ങനെ അവൾ (ഹിലാൽ(റ)വിന്റെ ഭാര്യ) വന്നു. റസൂൽ(സ) ആ സൂക്തങ്ങൾ ഇരുവർക്കും ഓതിക്കൊടുക്കുകയും ഇരുവരെയും വിഷയത്തിന്റെ ഗൗരവം ഓർമ്മപ്പെടുത്തുകയും, പാരത്രിക ലോകത്തെ ശിക്ഷ ഐഹിക ലോകത്തേതിനേക്കാൾ കഠിനമാണെന്ന് പറഞ്ഞ് കൊടുക്കുകയും ചെയ്തു. അപ്പോൾ ഹിലാൽ(റ) പറഞ്ഞു: അല്ലാഹുവാണേ, ഞാനവളെക്കുറിച്ച് പറഞ്ഞത് സത്യമാണ്. ഭാര്യ പറഞ്ഞു: അദ്ദേഹം പറഞ്ഞത് നുണയാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവർ ഇരുവരെയും നിങ്ങൾ ലിആൻ ചെയ്യിക്കുക." അപ്പോൾ ഹിലാൽ(റ)വിനോട് താങ്കൾ സത്യം ചെയ്യുക എന്ന് പറയപ്പെട്ടു. അങ്ങനെ താൻ സത്യവാനാണെന്ന് അല്ലാഹുവിനെ മുൻനിർത്തി അദ്ദേഹം നാല് പ്രാവശ്യം സത്യം ചെയ്തു. അഞ്ചാമത്തെ സത്യത്തിനൊരുങ്ങിയപ്പോൾ ഹിലാൽ(റ)വിനോട് റസൂൽ(സ) പറഞ്ഞു: "ഹിലാലേ, നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുക, ഐഹിക ലോകത്തെ ശിക്ഷ പാരത്രിക ലോകത്തേതിനേക്കാൾ ചെറുതാണ്. ഈ സത്യം നിന്റെ മേൽ അല്ലാഹുവിന്റെ ശിക്ഷയെ നിർബന്ധമാക്കുന്ന സത്യമാണ്." ഹിലാൽ(റ) പറഞ്ഞു: ഇതിന്റെ പേരിൽ എന്നെ അടക്കേണ്ടി വന്നിട്ടില്ലാത്ത പോലെ ഇതിന്റെ പേരിൽ അല്ലാഹു എന്നെ ശിക്ഷിക്കുകയുമില്ല. അങ്ങനെ അഞ്ചാം പ്രാവശ്യം താൻ നുണയാണ് പറയുന്നതെങ്കിൽ തന്റെ മേൽ അല്ലാഹുവിന്റെ ശാപമുണ്ടാവട്ടെ എന്ന് അദ്ദേഹം സത്യം ചെയ്തു. ശേഷം അദ്ദേഹത്തിന്റെ ഭാര്യയോട് നീ സത്യം ചെയ്യുക എന്ന് പറയപ്പെട്ടു. അങ്ങനെ അവൾ നാല് പ്രാവശ്യം ഹിലാൽ(റ) പറഞ്ഞത് നുണയാണെന്ന് സത്യം ചെയ്തു. അഞ്ചാമത്തെ സത്യത്തിനൊരുങ്ങിയപ്പോൾ അവളോട് ഇപ്രകാരം പറയപ്പെട്ടു: "നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുക. ഐഹിക ലോകത്തെ ശിക്ഷ പാരത്രികലോകത്തേതിനേക്കാൾ ചെറുതാണ്. ഈ സത്യം നിന്റെമേൽ അല്ലാഹുവിന്റെ ശിക്ഷ നിർബന്ധമാക്കുന്ന സത്യവുമാണ്." അപ്പോൾ ഒരു നിമിഷം അവൾ പിന്തിരിഞ്ഞു എന്നിട്ട് പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, ഞാനെന്റെ സമൂഹത്തെ വഷളാക്കുകയില്ല. അങ്ങനെ അഞ്ചാം പ്രാവശ്യം അവൻ പറഞ്ഞത് സത്യമാണെങ്കിൽ തന്റെ മേൽ അല്ലാഹുവിന്റെ കോപമുണ്ടാവട്ടെ എന്ന് അവൾ സത്യം ചെയ്തു. ശേഷം റസൂൽ(സ) അവരിരുവരെയും വേർപിരിയുകയും അവളുടെ കുട്ടി പിതാവിലേക്ക് ചേർക്കപ്പെടരുതെന്നും അവൾക്കെതിരെയും അവളുടെ കുട്ടിക്കെതിരെയും വ്യഭിചാരാരോപണം ഉന്നയിക്കപ്പെടരുതെന്നും വിധിച്ചു. ആരെങ്കിലും അവളെയോ അവളുടെ കുട്ടിയെയോ ആക്ഷേപിച്ചാൽ അവന് ഹദ്ദ് (ശിക്ഷ) ലഭിക്കും. മരണത്തിലൂടെയോ ത്വലാഖിലൂടെയോ അല്ലാതെ അവർ പിരിഞ്ഞത് കാരണം അവൾക്ക് ചെലവോ പാർപ്പിടമോ ലഭിക്കില്ലെന്നും, റസൂൽ(സ) വിധിച്ചു. ശേഷം റസൂൽ(സ) പറഞ്ഞു: "വെളുത്ത നിറമുള്ള, ഊര മെലിഞ്ഞ, ചുമല് വിശാലമായ, മെലിഞ്ഞ കണങ്കാലുകലുള്ള കുട്ടിയെയാണ് അവൾ പ്രസവിക്കുന്നതെങ്കിൽ അത് ഹിലാലുബ്നു ഉമയ്യ(റ)വിന്റെ കുട്ടിയാണ്. കറുത്ത നിറവും ചുരുണ്ട മുടിയുമുള്ള, അവയവങ്ങൾ തടിച്ച, തടിച്ച കണങ്കാലുകളും വലിയ ഈരയുമുള്ള കുട്ടിയെയാണ് അവൾ പ്രസവിക്കുന്നതെങ്കിൽ അത് അവളുമായി ആരോപിക്കപ്പെട്ട ആ വ്യക്തിയുടെ കുട്ടിയാണ്." അങ്ങനെ കറുത്ത നിറവും ചുരുണ്ട മുടിയുമുള്ള, അവയവങ്ങൾ തടിച്ച, തടിച്ച കണങ്കാലുകളും വലിയ ഊരയുമുള്ള ഒരു കുട്ടിയെ അവൾ പ്രസവിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവൾ ചെയ്ത സത്യങ്ങളില്ലായിരുന്നെങ്കിൽ അവളുടെ മേൽ ഞാൻ പ്രത്യേകം നടപടിയെടുക്കുമായിരുന്നു." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 189, 191, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: تَزَوَّجَ رَجُلٌ مِنَ الْأَنْصَارِ امْرَأَةً مِنْ بَلْعِجْلَانَ، فَدَخَلَ بِهَا، فَبَاتَ عِنْدَهَا، فَلَمَّا أَصْبَحَ قَالَ: مَا وَجَدْتُهَا عَذْرَاءَ. فَرُفِعَ شَأْنُهَا إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَدَعَا الْجَارِيَةَ فَسَأَلَهَا، فَقَالَتْ: بَلَى، قَدْ كُنْتُ عَذْرَاءَ. فَأَمَرَ بِهِمَا فَتَلَاعَنَا، وَأَعْطَاهَا الْمَهْرَ. [ز: في سنده مدلس عنعنه] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അൻസാരിയായ ഒരാൾ ബൽഇജ്ലാനിൽ പെട്ട ഒരു സ്ത്രീയെ വിവാഹം ചെയ്തു. അങ്ങനെ അവളോടൊപ്പം ആദിരാത്രി കൂടുകയും അന്തിയുറങ്ങുകയും ചെയ്തു. നേരം പുലർന്നപ്പോൾ അദ്ദേഹം പറഞ്ഞു: കന്യകയായിട്ടല്ല ഞാൻ അവളെ കണ്ടത്. അദ്ദേഹം ആ പ്രശ്നം നബി(സ)യോടുന്നയിച്ചു. നബി(സ) ആ സ്ത്രീയെ വിളിക്കുകയും വിവരം ചോദിക്കുകയും ചെയ്തു. അപ്പോൾ അവൾ പറഞ്ഞു: അതെ, ഞാൻ കന്യക തന്നെയായിരുന്നു. അതിനെത്തുടർന്ന് നബി(സ) അവർ രണ്ടുപേരോടും ലിആൻ ചെയ്യാൻ ആവശ്യപ്പെടുകയും അവർ അപ്രകാരം ചെയ്യുകയും ആ വ്യക്തി ആ സ്ത്രീക്ക് മഹ്റ് നൽകുകയും ചെയ്തു. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده مدلس عنعنه', null, 191, 191, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَرْبَعٌ مِنَ النِّسَاءِ لَا مُلَاعَنَةَ بَيْنَهُنَّ: النَّصْرَانِيَّةُ تَحْتَ الْمُسْلِمِ، وَالْيَهُودِيَّةُ تَحْتَ الْمُسْلِمِ، وَالْحُرَّةُ تَحْتَ الْمَمْلُوكِ، وَالْمَمْلُوكَةُ تَحْتَ الْحُرِّ". [في سنده راو متفق على تضعيفه] (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "നാല് തരം സ്ത്രീകൾക്ക് ലിആൻ ചെയ്യാൻ പറ്റുകയില്ല, മുസ്ലിമിന്റെ ഭാര്യയായ കൃസ്ത്യൻ സ്ത്രീ, മുസ്ലിമിന്റെ ഭാര്യയായ ജൂതസ്ത്രീ, അടിമയുടെ ഭാര്യയായ സ്വതന്ത്ര, സ്വതന്ത്രന്റെ ഭാര്യയായ അടിമസ്ത്രീ എന്നിവരാണവർ." (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في سنده راو متفق على تضعيفه', null, 191, 191, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّا لَلَيْلَةَ جُمُعَةٍ فِي الْمَسْجِدِ إِذْ دَخَلَ رَجُلٌ مِنَ الْأَنْصَارِ فِي الْمَسْجِدِ، فَقَالَ: لَوْ أَنَّ رَجُلًا وَجَدَ مَعَ امْرَأَتِهِ رَجُلًا: فَتَكَلَّمَ بِهِ جَلَدْتُمُوهُ، أَوْ قَتَلَ قَتَلْتُمُوهُ، فَإِنْ سَكَتَ سَكَتَ عَلَى غَيْظٍ، وَاللهِ لَأَسْأَلَنَّ عَنْهُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَلَمَّا كَانَ مِنَ الْغَدِ أَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ، فَقَالَ: لَوْ أَنَّ رَجُلًا وَجَدَ مَعَ امْرَأَتِهِ رَجُلًا، فَتَكَلَّمَ بِهِ جَلَدْتُمُوهُ، أَوْ قَتَلَ قَتَلْتُمُوهُ، أَوْ سَكَتَ سَكَتَ عَلَى غَيْظٍ؟ فَقَالَ: "اللَّهُمَّ افْتَحْ". وَجَعَلَ يَدْعُو، فَنَزَلَتْ آيَةُ اللِّعَانِ: {وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ وَلَمْ يَكُنْ لَهُمْ شُهَدَاءُ إِلَّا أَنْفُسُهُمْ} هَذِهِ الْآيَةَ، فَابْتُلِيَ بِهِ ذَلِكَ الرَّجُلُ مِنْ بَيْنِ النَّاسِ، فَجَاءَ هُوَ وَامْرَأَتُهُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَتَلَاعَنَا: فَشَهِدَ الرَّجُلُ أَرْبَعَ شَهَادَاتٍ بِاللهِ إِنَّهُ لَمِنَ الصَّادِقِينَ، ثُمَّ لَعَنَ الْخَامِسَةَ عَلَيْهِ إِنْ كَانَ مِنَ الْكَاذِبِينَ. قَالَ: فَذَهَبَتْ لِتَلْعَنَ، فَقَالَ لَهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَهْ". فَأَبَتْ، فَفَعَلَتْ، فَلَمَّا أَدْبَرَا قَالَ: "لَعَلَّهَا أَنْ تَجِيءَ بِهِ أَسْوَدَ جَعْدًا". فَجَاءَتْ بِهِ أَسْوَدَ جَعْدًا. (م,د,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഒരു വെള്ളിയാഴ്ച രാവിൽ ഞങ്ങൾ പള്ളിയിലായിരിക്കെ അൻസാരിയായ ഒരാൾ പള്ളിയിൽ വന്ന് പറഞ്ഞു: ഒരു വ്യക്തി തന്റെ ഭാര്യയോടൊന്നിച്ച് അന്യപുരുഷനെ കണ്ടാൽ, അത് പുറത്ത് പറഞ്ഞാൽ നിങ്ങൾ അവനെ ശിക്ഷിക്കും, അന്യപുരുഷനെ അവൻ വധിക്കുന്ന പക്ഷം അവനെയും നിങ്ങൾ വധിക്കും, അതുമല്ലെങ്കിൽ അവൻ മൗനമവലംബിക്കുകയാണെങ്കിൽ വളരെ ഗൗരവമേറിയ വിഷയത്തെയാണ് അവൻ അവഗണിക്കുന്നത്. അല്ലാഹുവാണ് സത്യം, ഈ വിഷയം ഞാൻ റസൂൽ(സ)യോട് ചോദിക്കുക തന്നെ ചെയ്യും. പിറ്റേ ദിവസം അദ്ദേഹം റസൂൽ(സ)യുടെ അടുത്ത് വരികയും ഇപ്രകാരം പറയുകയും ചെയ്തു: ഒരു വ്യക്തി തന്റെ ഭാര്യയോടൊപ്പം അന്യപുരുഷനെ കാണുകയും ആ വിഷയം പുറത്ത് പറയുകയും ചെയ്താൽ നിങ്ങൾ അവനെ അടിക്കും. ആ അന്യപുരുഷനെ വധിക്കുകയാണെങ്കിൽ നിങ്ങൾ അവനെയും വധിക്കും. അതല്ലെങ്കിൽ അവൻ മൗനമവലംബിക്കുകയാണെങ്കിൽ വളരെ ഗൗരവമേറിയ വിഷയത്തെയാണ് അവൻ അവഗണിക്കുന്നത്? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവേ, നീ വിധി പറഞ്ഞുതരണേ." അവിടന്ന് പ്രാർത്ഥിച്ചുകൊണ്ടിരുന്നു. അങ്ങനെ അല്ലാഹു ''തങ്ങളുടെ ഭാര്യമാർക്ക് നേരെ ആരോപണമുന്നയിക്കുകയും സ്വന്തമല്ലാതെ മററാരും സാക്ഷികളില്ലാത്തവരുമായ ആളുകൾ'' എന്ന ലിആനിന്റെ സൂക്തമിറക്കി. അങ്ങനെ ജനങ്ങൾക്കിടയിൽ വെച്ച് ആ സൂക്തവുമായി ആ വ്യക്തിയെ പരീക്ഷിച്ചു. ശേഷം അദ്ദേഹവും അദ്ദേഹത്തിന്റെ ഭാര്യയും റസൂൽ(സ)യുടെ അടുത്ത് വന്നു. അവർ പരസ്പരം ലിആൻ ചെയ്തു. താൻ സത്യവാനാണെന്ന് നാല് പ്രാവശ്യം അല്ലാഹുവിനെ മുൻനിർത്തി ആ വ്യക്തി സത്യം ചെയ്തു. അഞ്ചാം പ്രാവശ്യം, താൻ പറഞ്ഞത് നുണയാണെങ്കിൽ തനിക്കുമേൽ അല്ലാഹുവിന്റെ ശാപമുണ്ടാവട്ടെ എന്നും അദ്ദേഹം സത്യം ചെയ്തു. ശേഷം ഭാര്യ ലിആൻ ചെയ്യുവാനൊരുങ്ങിയപ്പോൾ നബി(സ) അവളോട് പറഞ്ഞു: "നീ അത് ചെയ്യരുത്." പക്ഷേ അവൾ അനുസരിച്ചില്ല, അവൾ ലിആൻ ചെയ്തു. അവർ രണ്ടുപേരും അവിടെ നിന്ന് പോയപ്പോൾ നബി(സ) പറഞ്ഞു: "അവൾ പ്രസവിക്കുന്നത് ചുരുണ്ട മുടിയുള്ള കറുത്ത കുട്ടിയെ ആവാം." അങ്ങനെ അവൾ കറുത്ത നിറവും ചുരുണ്ട മുടിയുമുള്ള കുട്ടിയെ പ്രസവിച്ചു. (മു,ദ,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 191, 192, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ أَوَّلَ لِعَانٍ كَانَ فِي الْإِسْلَامِ أَنَّ هِلَالَ بْنَ أُمَيَّةَ قَذَفَ شَرِيكَ بْنَ السَّحْمَاءِ بِامْرَأَتِهِ، فَأَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ بِذَلِكَ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَرْبَعَةُ شُهَدَاءَ، وَإِلَّا فَحَدٌّ فِي ظَهْرِكَ". يُرَدِّدُ ذَلِكَ عَلَيْهِ مِرَارًا، فَقَالَ لَهُ هِلَالٌ: وَاللهِ يَا رَسُولَ اللهِ، إِنَّ اللهَ عَزَّ وَجَلَّ لَيَعْلَمُ أَنِّي صَادِقٌ، وَلَيُنْزِلَنَّ اللهُ عَزَّ وَجَلَّ عَلَيْكَ مَا يُبَرِّئُ ظَهْرِي مِنَ الْجَلْدِ. فَبَيْنَمَا هُمْ كَذَلِكَ إِذْ نَزَلَتْ عَلَيْهِ آيَةُ اللِّعَانِ: {وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ} [النور: ٦] إِلَى آخِرِ الْآيَةِ، فَدَعَا هِلَالًا فَشَهِدَ أَرْبَعَ شَهَادَاتٍ بِاللهِ إِنَّهُ لَمِنَ الصَّادِقِينَ، وَالْخَامِسَةُ أَنَّ لَعْنَةَ اللهِ عَلَيْهِ إِنْ كَانَ مِنَ الْكَاذِبِينَ. ثُمَّ دُعِيَتِ الْمَرْأَةُ فَشَهِدَتْ أَرْبَعَ شَهَادَاتٍ بِاللهِ إِنَّهُ لَمِنَ الْكَاذِبِينَ، فَلَمَّا أَنْ كَانَ فِي الرَّابِعَةِ أَوِ الْخَامِسَةِ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَقِّفُوهَا، فَإِنَّهَا مُوجِبَةٌ". فَتَلَكَّأَتْ حَتَّى مَا شَكَكْنَا أَنَّهَا سَتَعْتَرِفُ، ثُمَّ قَالَتْ: لَا أَفْضَحُ قَوْمِي سَائِرَ الْيَوْمِ. فَمَضَتْ عَلَى الْيَمِينِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهِ عَلَيْهِ وَسَلَّمَ: "انْظُرُوهَا: فَإِنْ جَاءَتْ بِهِ أَبْيَضَ سَبِطًا قَضِيءَ الْعَيْنَيْنِ فَهُوَ لِهِلَالِ بْنِ أُمَيَّةَ، وَإِنْ جَاءَتْ بِهِ آدَمَ جَعْدًا رَبْعًا حَمْشَ السَّاقَيْنِ فَهُوَ لِشَرِيكِ بْنِ السَّحْمَاءِ". فَجَاءَتْ بِهِ آدَمَ جَعْدًا رَبْعًا حَمْشَ السَّاقَيْنِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْلَا مَا سَبَقَ فِيهَا مِنْ كِتَابِ اللهِ لَكَانَ لِي وَلَهَا شَأْنٌ". (ن)', 'അനസുബ്നു മാലിക്(റ): ഇസ്ലാമിൽ ആദ്യമായി ലിആൻ സംഭവിച്ചത് ശരീകുബ്നു സഹ്മാഅ് തന്റെ ഭാര്യയെ വ്യഭിചരിച്ചുവെന്ന് ഹിലാലുബ്നു ഉമയ്യ(റ) ആരോപണമുന്നയിച്ചു കൊണ്ടാണ്. അങ്ങനെ അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് വന്ന് വിഷയം പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നാലു സാക്ഷികൾ വേണം. അല്ലെങ്കിൽ നിന്റെ മേൽ പ്രതികാര നടപടിയുണ്ടാകും." ഇത് നബി(സ) പലപ്രവാശ്യം ആവർത്തിച്ചു പറഞ്ഞു. ഹിലാൽ(റ) പ്രവാചകർ(സ)യോട് പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, റസൂലേ, ഞാൻ സത്യവാനാണെന്ന് തീർച്ചയായും അല്ലാഹു അറിയിക്കും. എന്നെ ശിക്ഷയിൽ നിന്നൊഴിവാക്കി അല്ലാഹു അങ്ങേക്ക് സൂക്തമിറക്കുക തന്നെ ചെയ്യും. അങ്ങനെയിരിക്കുമ്പോൾ, ''അവരുടെ ഭാര്യമാർക്കെതിരെ ആരോപണമുന്നയിക്കുന്നവർ'' എന്നു തുടങ്ങിയ സൂക്തങ്ങൾ (സൂറതുന്നൂർ: 6 - 9) ഇറങ്ങി. അപ്പോൾ നബി(സ) ഹിലാൽ(റ)വിനെ വിളിച്ചുവരുത്തി. താൻ സത്യവാനാണെന്ന് അല്ലാഹുവിനെക്കൊണ്ട് അദ്ദഹം നാലുപ്രാവശ്യം സത്യംചെയ്തു. അഞ്ചാമതായി, ഞാൻ കളവ് പറയുന്നവനാണെങ്കിൽ അല്ലാഹുവിന്റെ ശാപം തന്റെ മേലുണ്ടാവട്ടെ എന്നും സത്യംചെയ്തു. പിന്നെ ഭാര്യയെ വിളിച്ചു കൊണ്ടുവന്നു. അദ്ദേഹം കളവ് പറയുകയാണെന്ന് അവളും നാലുപ്രാവശ്യം അല്ലാഹുവിനെക്കൊണ്ട് സത്യംചെയ്തു. നാലാമതോ അഞ്ചാമതോ ആയപ്പോൾ നബി(സ) "അവളോട് നിർത്താൻ പറയൂ, ഇത് ശിക്ഷയെ നിർബന്ധമാക്കുന്നതാണ്." എന്ന് പറഞ്ഞു. അപ്പോൾ അവൾ ഒന്നിടറി നിർത്തി. അവൾ കുറ്റമേറ്റു പറയുമെന്നു ഞങ്ങൾ ഉറച്ചുവിശ്വസിച്ചു. പിന്നെ അവൾ പറഞ്ഞു: എന്റെ സമുദായത്തെ ഞാനിനി വരുംദിനങ്ങളിൽ ആക്ഷേപിക്കില്ല. അവൾ തുടർന്നും സത്യം ചെയ്തുകൊണ്ടേയിരുന്നു. ശേഷം തിരുമേനി(സ) പറഞ്ഞു: "അവളെ ശ്രദ്ധിക്കുക: തൊലിവെളുത്ത് നേർത്ത തലമുടിയുള്ള, കണ്ണ് വലുപ്പമുള്ള കുഞ്ഞിനെയാണവൾ പ്രസവിക്കുന്നതെങ്കിൽ അത് ഹിലാലിന്റേതാണ്. തവിട്ടുനിറത്തിൽ, മുടി ചുരുണ്ട, ഒത്ത വലിപ്പമുള്ള, കണങ്കാലുകൾ നേർത്ത കുഞ്ഞാണെങ്കിൽ അത് ശരീകുബ്നു സഹ്മാഇന്റെ മകനായിരിക്കും." അങ്ങനെ അവൾ തവിട്ടുനിറമുള്ള മുടി ചുരുണ്ട, ഒത്ത വലിപ്പമുള്ള, കണങ്കാലുകൾ നേർത്ത ഒരു കുഞ്ഞിനെ പ്രസവിച്ചു. അന്നേരം നബി(സ) പറഞ്ഞു: "അല്ലാഹു ഈ വിഷയത്തിൽ അവന്റെ വിധി മുൻകൂട്ടി അറിയിച്ചില്ലായിരുന്നുവെങ്കിൽ ഞാൻ അവൾക്കെതിരെ നടപടി (ശിക്ഷ) എടുക്കുമായിരുന്നു." (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'النور: ٦', null, 192, 193, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا أَنَّهُ قَالَ: ذُكِرَ التَّلَاعُنُ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: عَاصِمُ بْنُ عَدِيٍّ فِي ذَلِكَ قَوْلًا ثُمَّ انْصَرَفَ، فَأَتَاهُ رَجُلٌ مِنْ قَوْمِهِ يَشْكُو إِلَيْهِ أَنَّهُ وَجَدَ مَعَ امْرَأَتِهِ رَجُلًا، قَالَ عَاصِمٌ: مَا ابْتُلِيتُ بِهَذَا إِلَّا بِقَوْلِي. فَذَهَبَ بِهِ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ بِالَّذِي وَجَدَ عَلَيْهِ امْرَأَتَهُ، وَكَانَ ذَلِكَ الرَّجُلُ مُصْفَرًّا قَلِيلَ اللَّحْمِ سَبِطَ الشَّعْرِ، وَكَانَ الَّذِي ادَّعَى عَلَيْهِ أَنَّهُ وَجَدَهُ عِنْدَ أَهْلِهِ آدَمَ خَدْلًا كَثِيرَ اللَّحْمِ – وَفِي رِوَايَةٍ: جَعْداً قِطَطاً – فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ بَيِّنْ". فَوَضَعَتْ شَبِيهًا بِالرَّجُلِ الَّذِي ذَكَرَ زَوْجُهَا أَنَّهُ وَجَدَهُ عِنْدَهَا، فَلَاعَنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُمَا. فَقَالَ رَجُلٌ لِابْنِ عَبَّاسٍ فِي الْمَجْلِسِ: أَهِيَ الَّتِي قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْ رَجَمْتُ أَحَدًا بِغَيْرِ بَيِّنَةٍ رَجَمْتُ هَذِهِ". قَالَ ابْنُ عَبَّاسٍ: لَا، تِلْكَ امْرَأَةٌ كَانَتْ تُظْهِرُ فِي الْإِسْلَامِ الشَّرَّ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യുടെ സന്നിധിയിൽ ഒരു ലിആനിന്റെ പ്രശ്നം ഉന്നയിക്കപ്പെട്ടു. അന്നേരം ആസിമുബ്നു അദിയ്യ്(റ) അതിനെക്കുറിച്ച് എന്തോ പറഞ്ഞു പിന്തിരിഞ്ഞു. അപ്പോൾ അദ്ദേഹത്തിന്റെ സമൂഹത്തിൽ പെട്ട ഒരാൾ, തന്റെ ഭാര്യയെ ഒരന്യ പുരുഷന്റെ കൂടെ കണ്ടുവെന്ന് പരാതി ബോധിപ്പിച്ച് - അദ്ദേഹത്തെ സമീപിച്ചു. അപ്പോൾ ആസിം(റ) പറഞ്ഞു: എന്റെ ആ വാക്ക് കൊണ്ടു മാത്രമാണ് ഞാനീ കുരുക്കിൽ പെട്ടത്. അങ്ങനെ അദ്ദേഹം അയാളെ കൂട്ടി നബി(സ)യുടെയടുത്തേക്ക് പോയി. തന്റെ ഭാര്യയുടെ കൂടെ അന്യ പുരുഷനെ കണ്ടതിനെക്കുറിച്ച് പറഞ്ഞു കൊടുത്തു. മഞ്ഞ നിറമുള്ള തടി കുറഞ്ഞ നേർത്ത നീണ്ട മുടിയുള്ള ഒരാളായിരുന്നു അയാൾ. തന്റെ ഭാര്യയോടൊപ്പം കണ്ടുവെന്ന് അദ്ദേഹം ആരോപിച്ചയാൾ മാംസളമായ ശരീരമുള്ള - മറ്റൊരു റിപ്പോർട്ടിൽ: ചെറിയ ചുരുണ്ട മുടിയുള്ള - തടിച്ച ശക്തനായൊരാളാണ്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹുവേ, നീ വ്യക്തമാക്കിത്തരൂ." കൂടെ കണ്ടുവെന്ന് ആരോപിക്കപ്പെട്ടയാളുടെ രൂപത്തിലുള്ള ഒരു കുട്ടിയെയാണ് പിന്നീടവൾ പ്രസവിച്ചത്. അന്നേരം നബി(സ) അവർക്കിടയിൽ ലിആൻ ചെയ്യിച്ചു. അപ്പോൾ സദസ്സിലിരിക്കുന്ന ഒരാൾ ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ചോദിച്ചു: "ഒരു തെളിവും കൂടാതെ ആരെയെങ്കിലും എറിയാമെങ്കിൽ (ശിക്ഷ നടപ്പാക്കൽ) ഞാൻ ഇവളെ എറിയുമായിരുന്നു." എന്ന് നബി(സ) പറഞ്ഞത് ഈ സ്ത്രീയെക്കുറിച്ചാണോ?. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അല്ല, ഇസ്ലാമിൽ ചേർന്ന് പരസ്യമായി തിന്മകൾ ചെയ്യുമായിരുന്ന സ്ത്രീയാണത്. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 193, 194, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=120), 1, 'وَفِي رِوَايَةٍ: جَعْداً قِطَطاً – فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ بَيِّنْ". فَوَضَعَتْ شَبِيهًا بِالرَّجُلِ الَّذِي ذَكَرَ زَوْجُهَا أَنَّهُ وَجَدَهُ عِنْدَهَا، فَلَاعَنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَهُمَا. فَقَالَ رَجُلٌ لِابْنِ عَبَّاسٍ فِي الْمَجْلِسِ: أَهِيَ الَّتِي قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْ رَجَمْتُ أَحَدًا بِغَيْرِ بَيِّنَةٍ رَجَمْتُ هَذِهِ". قَالَ ابْنُ عَبَّاسٍ: لَا، تِلْكَ امْرَأَةٌ كَانَتْ تُظْهِرُ فِي الْإِسْلَامِ الشَّرَّ. (ن)', 'മറ്റൊരു നിവേദനിൽ: ചെറിയ ചുരുണ്ട മുടിയുള്ള - തടിച്ച ശക്തനായൊരാളാണ്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹുവേ, നീ വ്യക്തമാക്കിത്തരൂ." കൂടെ കണ്ടുവെന്ന് ആരോപിക്കപ്പെട്ടയാളുടെ രൂപത്തിലുള്ള ഒരു കുട്ടിയെയാണ് പിന്നീടവൾ പ്രസവിച്ചത്. അന്നേരം നബി(സ) അവർക്കിടയിൽ ലിആൻ ചെയ്യിച്ചു. അപ്പോൾ സദസ്സിലിരിക്കുന്ന ഒരാൾ ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ചോദിച്ചു: "ഒരു തെളിവും കൂടാതെ ആരെയെങ്കിലും എറിയാമെങ്കിൽ (ശിക്ഷ നടപ്പാക്കൽ) ഞാൻ ഇവളെ എറിയുമായിരുന്നു." എന്ന് നബി(സ) പറഞ്ഞത് ഈ സ്ത്രീയെക്കുറിച്ചാണോ?. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അല്ല, ഇസ്ലാമിൽ ചേർന്ന് പരസ്യമായി തിന്മകൾ ചെയ്യുമായിരുന്ന സ്ത്രീയാണത്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَاعَنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ الْعَجْلَانِيِّ وَامْرَأَتِهِ، وَكَانَتْ حُبْلَى. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അജ്ലാൻ ഗോതത്രത്തിൽ പെട്ട ഒരാളുടെയും ഭാര്യയുടെയുമിടയിൽ നബി(സ) ലിആൻ ചെയ്യിച്ചു. ആ സമയം അവൾ ഗർഭിണിയായിരുന്നു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 194, 194, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا مِنْ أَهْلِ الْبَادِيَةِ أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، إِنَّ امْرَأَتِي وَلَدَتْ عَلَى فِرَاشِي غُلَامًا أَسْوَدَ، وَإِنَّا – أَهْلُ بَيْتٍ – لَمْ يَكُنْ فِينَا أَسْوَدُ قَطُّ. قَالَ: "هَلْ لَكَ مِنْ إِبِلٍ". قَالَ: نَعَمْ. قَالَ: "فَمَا أَلْوَانُهَا". قَالَ: حُمْرٌ. قَالَ: "هَلْ فِيهَا أَسْوَدُ". قَالَ: لَا. قَالَ: "فِيهَا أَوْرَقُ". قَالَ: نَعَمْ. قَالَ: "فَأَنَّى كَانَ ذَلِكَ". قَالَ: عَسَى أَنْ يَكُونَ نَزَعَهُ عِرْقٌ. قَالَ: "فَلَعَلَّ ابْنَكَ هَذَا نَزَعَهُ عِرْقٌ". (جه)', 'ഇബ്നുഉമർ(റ): പ്രാന്തപ്രദേശ വാസികളൊരാൾ നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: തിരുദൂതരേ, എന്റെ ഭാര്യയിൽ എനിക്ക് ഒരു കറുത്ത കുട്ടി ജനിച്ചു. ഞങ്ങളുടെ കുടുംബത്തിൽ ഇതുവരെ കറുത്ത കുഞ്ഞ് ജനിച്ചിട്ടില്ല. നബി(സ) ചോദിച്ചു: "നിങ്ങൾക്ക് ഒട്ടകങ്ങളുണ്ടോ?" അയാൾ പറഞ്ഞു: അതെ. നബി(സ) ചോദിച്ചു: "അവയുടെ നിറമെന്താണ്?" അയാൾ പറഞ്ഞു: ചുവപ്പ്. നബി(സ) ചോദിച്ചു: "അതിൽ കറുപ്പുമുണ്ടോ?" അയാൾ പറഞ്ഞു: ഇല്ല, നബി(സ) ചോദിച്ചു: "ചാരനിറമുള്ളതുണ്ടോ?" അയാൾ പറഞ്ഞു: ഉണ്ട്. നബി(സ) പറഞ്ഞു: "ശരി, എങ്ങനെയാണത് സംഭവിച്ചത്?" അയാൾ പറഞ്ഞു: അതിന്റെ മുൻകഴിഞ്ഞ പിതൃപരമ്പരയിൽ ഇതിനോട് സാമ്യമുള്ളതുണ്ടായിരുന്നിരിക്കാം. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ മകനും അതുപോലെ സാദൃശ്യമുള്ളവനാവാം." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 194, 194, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: قَالَ بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَامَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي وُلِدَ لِي غُلَامٌ أَسْوَدُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَأَنَّى كَانَ ذَلِكَ". قَالَ: مَا أَدْرِي. قَالَ: "فَهَلْ لَكَ مِنْ إِبِلٍ". قَالَ: نَعَمْ. قَالَ: "فَمَا أَلْوَانُهَا". قَالَ: حُمْرٌ. قَالَ: "فَهَلْ فِيهَا جَمَلٌ أَوْرَقُ". قَالَ: فِيهَا إِبِلٌ وُرْقٌ. قَالَ: "فَأَنَّى كَانَ ذَلِكَ". قَالَ: مَا أَدْرِي يَا رَسُولَ اللَّهِ، إِلَّا أَنْ يَكُونَ نزعهُ عِرْقٌ. قَالَ: "وَهَذَا لَعَلَّهُ نزعهُ عِرْقٌ". فَمِنْ أَجْلِهِ قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَذَا: "لَا يَجُوزُ لِرَجُلٍ أَنْ يَنْتَفِيَ مِنْ وَلَدٍ وُلِدَ عَلَى فِرَاشِهِ، إِلَّا أَنْ يَزْعُمَ أَنَّهُ رَأَى فَاحِشَةً". (ن)', 'അബൂഹുറൈറ(റ): ഞങ്ങൾ നബി(സ)യുടെ കൂടെയിരിക്കുന്ന സന്ദർഭം ഒരാൾ എണീറ്റു കൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എനിക്ക് ഒരു കറുത്ത കുഞ്ഞാണ് പിറന്നത്. അപ്പോൾ നബി(സ) ചോദിച്ചു: "അതെങ്ങനെ സംഭവിച്ചു?" അയാൾ പറഞ്ഞു: "എനിക്കറിയില്ല." നബി(സ) ചോദിച്ചു: "നിങ്ങൾക്ക് ഒട്ടകങ്ങളുണ്ടോ?" അയാൾ പറഞ്ഞു: ഉണ്ട്. നബി(സ) ചോദിച്ചു: "അവയുടെ നിറമെന്താണ്?" അയാൾ പറഞ്ഞു: ചുവപ്പ്. നബി(സ) ചോദിച്ചു: "അവയിൽ ചാരനിറത്തിലുള്ള ഏതെങ്കിലുമുണ്ടോ?" അയാൾ പറഞ്ഞു: ചാരനിറമുള്ള ഒട്ടകങ്ങളുമുണ്ട്. അപ്പോൾ നബി(സ) ചോദിച്ചു: "അതെങ്ങനെ സംഭവിച്ചു?" അയാൾ പറഞ്ഞു: അവയുടെ കഴിഞ്ഞുപോയ പിതൃപരമ്പരയിൽ രൂപസാദൃശ്യമുള്ളതുണ്ടായിരുന്നത് കൊണ്ടായിരിക്കും, കൂടുതലൊന്നും എനിക്കറിയില്ല. നബി(സ) പറഞ്ഞു: "എങ്കിൽ നിന്റെ മകന്റെ പരമ്പരയിലും അങ്ങനെ രൂപസാദൃശ്യമുണ്ടാവാം." ഇതിനെത്തുടർന്ന് നബി(സ) ഇപ്രകാരം വിധി പറഞ്ഞു: "അസാന്മാർഗ്ഗികമായതെന്തോ സംഭവിച്ചതായി താൻ കണ്ടുവെന്ന് വാദിക്കുന്നവനൊഴികെ, തന്റെ ഭാര്യക്ക് പിറന്ന കുഞ്ഞിന്റെ പിതൃത്വം നിഷേധിക്കുന്നത് അനുവദനീയമല്ല." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 194, 195, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا مَسْرُورًا تُعْرَفُ أَسَارِيرُ وَجْهِهِ، فَقَالَ: أَيْ عَائِشَةُ، أَلَمْ تَرَيْ أَنَّ مُجَزِّزًا الْمُدْلِجِيَّ رَأَى زَيْدًا وَأُسَامَةَ، قَدْ غَطَّيَا رُءُوسَهُمَا بِقَطِيفَةٍ وَبَدَتْ أَقْدَامُهُمَا، فَقَالَ: إِنَّ هَذِهِ الْأَقْدَامَ بَعْضُهَا مِنْ بَعْضٍ". وفي رِوَايةٍ: قَالَتْ: دَخَلَ عَلَيَّ مَسْرُورًا تَبْرُقُ أَسَارِيرُ وَجْهِهِ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): വളരെ സന്തോഷവാനായി ഒരു ദിവസം റസൂൽ(സ) എന്റെയടുക്കൽ വന്നു. അവിടത്തെ മുഖം തന്നെ സന്തോഷം വിളിച്ചോതുന്നുണ്ടായിരുന്നു. എന്നിട്ട് റസൂൽ(സ) പറഞ്ഞു: "ആഇശാ, നീയറിഞ്ഞോ സൈദ്(റ)വും ഉസാമ(റ)വും കാലുകൾ വെളിവാക്കി, ഒരു പുതപ്പുകൊണ്ട് തലയടക്കം പുതച്ചുകിടക്കുന്നത് മുജസ്സിസുൽ മുദ്ലിജി കണ്ടു. അന്നേരം അദ്ദേഹം പറഞ്ഞു: ഈ കാലുകൾ ചിലത് ചിലതിൽ നിന്നുള്ളതാണല്ലോ" മറ്റൊരു റിപ്പോർട്ടിൽ: ആഇശ(റ) പറഞ്ഞു: നബി(സ) എന്റെയടുത്ത് വന്നു. അവിടത്തെ മുഖത്തെ വരകൾ സന്തോഷാധികൃത്താൽ തിളങ്ങുന്നുണ്ടായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 195, 195, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=124), 1, 'وَفِي رِوَايَةٍ: قَالَتْ: دَخَلَ عَلَيَّ مَسْرُورًا تَبْرُقُ أَسَارِيرُ وَجْهِهِ. (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: ആഇശ(റ) പറഞ്ഞു: നബി(സ) എന്റെയടുത്ത് വന്നു. അവിടത്തെ മുഖത്തെ വരകൾ സന്തോഷാധികൃത്താൽ തിളങ്ങുന്നുണ്ടായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: اخْتَصَمَ سَعْدُ بْنُ أَبِي وَقَّاصٍ، وَعَبْدُ بْنُ زَمْعَةَ فِي غُلَامٍ، فَقَالَ سَعْدٌ: هَذَا – يَا رَسُولَ اللَّهِ – ابْنُ أَخِي عُتْبَةَ بْنِ أَبِي وَقَّاصٍ، عَهِدَ إِلَيَّ أَنَّهُ ابْنُهُ، انْظُرْ إِلَى شَبَهِهِ. وَقَالَ عَبْدُ بْنُ زَمْعَةَ: هَذَا أَخِي يَا رَسُولَ اللهِ، وُلِدَ عَلَى فِرَاشِ أَبِي مِنْ وَلِيدَتِهِ. فَنَظَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى شَبَهِهِ فَرَأَى شَبَهًا بَيِّنًا بِعُتْبَةَ. فَقَالَ: "هُوَ لَكَ يَا عَبْدُ، الْوَلَدُ لِلْفِرَاشِ، وَلِلْعَاهِرِ الْحَجَرُ، وَاحْتَجِبِي مِنْهُ يَا سَوْدَةُ بِنْتُ زَمْعَةَ". قَالَتْ: فَلَمْ يَرَ سَوْدَةَ قَطُّ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): സഅ്ദുബ്നു അബീവഖാസ്(റ)വും അബ്ദുബ്നു സംഅ(റ)വും ഒരു കുട്ടിക്ക് വേണ്ടി പരസ്പരം തർക്കിച്ചു. അങ്ങനെ സഅ്ദ്(റ) പറഞ്ഞു: റസൂലേ, ഇവൻ എന്റെ സഹോദരൻ ഉത്ബതുബ്നു അബീവഖാസിന്റെ മകനാണ്. അദ്ദേഹമെന്നോട് ഇവൻ തന്റെ മകനാണെന്ന് പറഞ്ഞിട്ടുണ്ട്. അവിടന്ന് ഇവന്റെ സദൃശ്യനെ നോക്കൂ. അബ്ദുബ്നു സംഅ(റ) പറഞ്ഞു: ഇത് എന്റെ സഹോദരനാണ് റസൂലേ, എന്റെ പിതാവിന്റെ അടിമപ്പെണ്ണ് അദ്ദേഹത്തിന്റെ വിരിപ്പിൽ പ്രസവിച്ചതാണ് ഇവനെ. നബ(സ) കുട്ടിയുടെ സാദൃശ്യം നോക്കി. അപ്പോൾ ഉത്ബയോട് വ്യക്തമായ സാദൃശ്യമുണ്ടെന്ന് കണ്ടു. അന്നേരം നബി(സ) പറഞ്ഞു: "ഇവൻ നിനക്കുള്ളതാണ് അബ്ദേ, ആരുടെ വിരിപ്പിലാണോ കുട്ടി പിറന്നത് കുട്ടി അവനുള്ളതാണ്. വ്യഭിചാരിക്ക് കല്ലുണ്ട്. സൗദ ബിൻത് സംഅ, നീ അവനിൽ നിന്ന് മറ സ്വീകരിക്കണം. ആഇശ(റ) പറയുന്നു: പിന്നീട് സൗദ ഒരിക്കലും അയാളെ കണ്ടിട്ടില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 195, 196, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: اخْتَصَمَ سَعْدُ بْنُ أَبِي وَقَّاصٍ وَعَبْدُ بْنُ زَمْعَةَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ابْنِ أَمَةِ زَمْعَةَ، فَقَالَ سَعْدٌ: أَوْصَانِي أَخِي عُتْبَةُ إِذَا قَدِمْتُ مَكَّةَ: أَنْ أَنْظُرَ إِلَى ابْنِ أَمَةِ زَمْعَةَ فَأَقْبِضَهُ، فَإِنَّهُ ابْنُهُ. وَقَالَ عَبْدُ بْنُ زَمْعَةَ: أَخِي، ابْنُ أَمَةِ أَبِي، وُلِدَ عَلَى فِرَاشِ أَبِي. فَرَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَبَهًا بَيِّنًا بِعُتْبَةَ، فَقَالَ: "الْوَلَدُ لِلْفِرَاشِ، وَلِلْعَاهِرِ الْحَجَرُ. وَاحْتَجِبِي عَنْهُ يَا سَوْدَةُ". وَفِي رِوَايَةٍ: "هُوَ أَخُوكَ يَا عَبْدُ". (ق,د,ت,ن,جه)', 'ആഇശ(റ): സഅ്ദുബ്നു അബീ വഖാസ്(റ)വും അബ്ദുബ്നു സംഅ(റ)വും സംഅയുടെ അടിമസ്ത്രീക്കുണ്ടായ ഒരു മകന്റെ വിഷയത്തിൽ തർക്കിച്ചു, നബി(സ)യുടെ അടുത്തെത്തി. സഅ്ദ്(റ) പറഞ്ഞു: ഞാൻ മക്കയിൽ എത്തിയാൽ സംഅയുടെ അടിമപ്പെണ്ണിലുണ്ടായ മകനെ കണ്ടുപിടിക്കണം എന്ന്, എന്റെ സഹോദരൻ ഉത്ബ എന്നോട് വസ്വിയ്യത് ചെയ്തിട്ടുണ്ട്. ഇവൻ ഉത്ബയുടെ മകനാണ്. അബ്ദുബ്നു സംഅ(റ) പറഞ്ഞു: അതെന്റെ സഹോദരനാണ്. എന്റെ പിതാവിന് അടിമപ്പെണ്ണിലുണ്ടായ മകനാണവൻ, എന്റെ പിതാവിന്റെ വിരിപ്പിലാണവൻ പിറന്നത്. നബി(സ) കുട്ടിയെ വീക്ഷിച്ചപ്പോൾ ഉത്ബയോട് പൂർണ്ണമായ സാദൃശ്യമുള്ളതായി കണ്ടു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ആരുടെ വിരിപ്പിലാണോ കുട്ടി പിറന്നത്, കുട്ടി അവന്റേതാണ്. വ്യഭിചാരിക്ക് കല്ലുണ്ട്. സൗദേ, അവനിൽ നിന്ന് നീ മറഞ്ഞിരിക്കണം." മറ്റൊരു നിവേദനത്തിൽ: "ഇത് നിന്റെ സഹോദരനാണ് അബ്ദേ," (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 196, 196, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=126), 1, 'وَفِي رِوَايَةٍ: "هُوَ أَخُوكَ يَا عَبْدُ". (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: "ഇത് നിന്റെ സഹോദരനാണ് അബ്ദേ," (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، قَالَ: قَامَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ فُلَانًا ابْنِي، عَاهَرْتُ بِأُمِّهِ فِي الْجَاهِلِيَّةِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا دَعْوَةَ فِي الْإِسْلَامِ، ذَهَبَ أَمْرُ الْجَاهِلِيَّةِ، الْوَلَدُ لِلْفِرَاشِ وَلِلْعَاهِرِ الْحَجَرُ". (د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഒരാൾ എണീറ്റു നിന്നു പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഇന്നയാൾ എന്റെ മകനാണ്, അവന്റെ ഉമ്മയുമായി ഞാൻ ജാഹിലിയ്യാ കാലത്ത് അവിഹിതമായി ബന്ധപ്പെട്ടതാണ്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇസ്ലാമിൽ അവകാശവാദമുന്നയിക്കലില്ല. ജാഹിലിയ്യാ കാലത്തെ സമ്പ്രദായമൊക്കെ കഴിഞ്ഞുപോയി. ആരുടെ വിരിപ്പിലാണോ കുട്ടി പിറന്നത് അവന് അവകാശപ്പെട്ടതാണ് കുട്ടി. വ്യഭിചാരിക്ക് കല്ലാണുള്ളത്." (ദ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 196, 196, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ رَبَاحٍ الْكُوفِيِّ قَالَ: زَوَّجَنِي أَهْلِي أَمَةً لَهُمْ رُومِيَّةً، فَوَقَعْتُ عَلَيْهَا فَوَلَدَتْ غُلَامًا أَسْوَدَ مِثْلِي، فَسَمَّيْتُهُ عَبْدَ اللهِ. ثُمَّ وَقَعْتُ عَلَيْهَا فَوَلَدَتْ غُلَامًا أَسْوَدَ مِثْلِي، فَسَمَّيْتُهُ عُبَيْدَ اللهِ. ثُمَّ طَبَنَ لَهَا غُلَامٌ لِأَهْلِي رُومِيٌّ، يُقَالُ لَهُ يُوحَنَّهْ، فَرَاطَنَهَا بِلِسَانِهِ، فَوَلَدَتْ غُلَامًا كَأَنَّهُ وَزَغَةٌ مِنَ الْوَزَغَاتِ، فَقُلْتُ لَهَا: مَا هَذَا؟ فَقَالَتْ: هَذَا لِيُوحَنَّهْ، فَرَفَعْنَا إِلَى عُثْمَانَ، فَسَأَلَهُمَا فَاعْتَرَفَا، فَقَالَ لَهُمَا: أَتَرْضَيَانِ أَنْ أَقْضِيَ بَيْنَكُمَا بِقَضَاءِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى أَنَّ الْوَلَدَ لِلْفِرَاشِ. فَجَلَدَهَا وَجَلَدَهُ وَكَانَا مَمْلُوكَيْنِ. (د)', 'റബാഹുൽ കൂഫി(റ): എന്റെ ബന്ധുക്കൾ അവരുടെ പക്കലുണ്ടായിരുന്ന റോം വംശജയായ അടിമസ്ത്രീയെ എനിക്ക് വിവാഹം ചെയ്ത് തന്നു. അനന്തരം ഞാനവളുമായി ബന്ധപ്പെട്ട് അവൾ എന്നെപ്പോലോത്ത ഒരു കറുത്ത കുട്ടിയെ പ്രസവിച്ചു. ഞാനവന് അബ്ദുല്ല എന്ന് പേരിട്ടു. പിന്നെയും ബന്ധപ്പെട്ട് വീണ്ടും എന്നെപ്പോലെ കറുത്ത ഒരു കുട്ടിക്ക് ജന്മം നൽകി. അവന് ഞാൻ ഉബൈദുല്ല എന്ന് പേരിട്ടു. പിന്നീട് ബന്ധുക്കളുടെയടുത്തുണ്ടായിരുന്ന മറ്റൊരു റോം വംശജനായ അടിമ ഇവളെക്കുറിച്ചറിഞ്ഞു. യോഹന്ന എന്നാണവന്റെ പേര്. അവൾക്ക് മാത്രം മനസ്സിലാകുന്ന ഭാഷയിൽ അവനവളോട് സംസാരിച്ച് വശീകരിച്ച് അവിഹിത വേഴ്ച നടത്തി. അങ്ങനെ അവൾ പല്ലിയെപ്പോലെ നിറമുള്ളൊരു കുഞ്ഞിന് ജന്മം നൽകി. അപ്പോൾ ഞാനവളോട് ചോദിച്ചു: ഇവനേതാ? അവൾ പറഞ്ഞു: ഇവൻ യോഹന്നയുടേതാണ്. ഈ വിവരം ഞങ്ങൾ ഉസ്മാൻ(റ)വിനോട് ഉണർത്തി. അദ്ദേഹം അവരെ ചോദ്യം ചെയ്തു. അവർ കുറ്റം സമ്മതിച്ചു. അദ്ദേഹം അവരോട് ചോദിച്ചു: നബി(സ) വിധിച്ച പോലെ നിങ്ങൾക്കിടയിൽ വിധിച്ചാൽ നിങ്ങൾക്ക് തൃപ്തിയടയുകയില്ലേ? തിരുമേനി(സ) വിധിച്ചത് ആരുടെ വിരിപ്പിലാണോ കുട്ടിപിറന്നത് അവനാണ് കുട്ടിയെന്നാണ്. പിന്നീട് അവർ രണ്ടുപേരെയും (നിശ്ചിത അടി) ഹദ്ദടിച്ചു. അവരിരുവരും അടിമകളായിരുന്നു. (ദ)', 'رَبَاحٍ الْكُوفِيِّ قَالَ', 'റബാഹുൽ കൂഫി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 196, 197, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ عَبْدِ اللهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا، قَالَ: كَانَتْ لِزَمْعَةَ جَارِيَةٌ يَطُؤُهَا هُوَ، وَكَانَ يَظُنُّ بِآخَرَ يَقَعُ عَلَيْهَا، فَجَاءَتْ بِوَلَدٍ شِبْهِ الَّذِي كَانَ يَظُنُّ بِهِ، فَمَاتَ زَمْعَةُ وَهِيَ حُبْلَى، فَذَكَرَتْ ذَلِكَ سَوْدَةُ رَضِيَ اللهُ عَنْهَا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْوَلَدُ لِلْفِرَاشِ، وَاحْتَجِبِي مِنْهُ يَا سَوْدَةُ، فَلَيْسَ لَكِ بِأَخٍ". (ن)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): സംഅ(റ)വിന് താൻ ബന്ധപ്പെടാറുള്ള ഒരടിമസ്ത്രീയുണ്ടായിരുന്നു. വേറൊരാൾ അവളുമായി ബന്ധപ്പെടാറുണ്ടെന്ന് അദ്ദേഹത്തിന് സംശയമായി. അദ്ദേഹം കരുതിയയാളുടെ രൂപസാദൃശ്യമുള്ള ഒരു കുഞ്ഞിനെ അവൾ പ്രസവിച്ചു. അവൾ ഗർഭിണിയായിരിക്കെ സംഅ(റ) മരിച്ചു. ഈ വിവരം സൗദ(റ) റസൂൽ(സ)യോട് പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ആരുടെ വിരിപ്പിലാണോ കുട്ടി പിറന്നത് അവന്റെതാണ് കുട്ടി. നീ അവനിൽ നിന്ന് അകൽച്ച പാലിക്കണം. അവൻ നിനക്ക് സഹോദരനാവുകയില്ല." (ന)', 'عَبْدِ اللهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 197, 197, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةً قَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ ابْنِي هَذَا كَانَ بَطْنِي لَهُ وِعَاءً، وَثَدْيِي لَهُ سِقَاءً، وَحِجْرِي لَهُ حِوَاءً، وَإِنَّ أَبَاهُ طَلَّقَنِي، وَأَرَادَ أَنْ يَنْتَزِعَهُ مِنِّي. فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنْتِ أَحَقُّ بِهِ مَا لَمْ تَنْكِحِي". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഒരു സ്ത്രീ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ ഈ മകന് ഞാനാണ് ഗർഭം നൽകിയത്. സ്വന്തം മടിത്തട്ടിൽ കിടത്തി പാലൂട്ടി പോറ്റിവളർത്തിയതും ഞാനാണ്. ഇവന്റെ പിതാവ് എന്നെ മൊഴി ചൊല്ലിയിരിക്കുന്നു. എന്നിട്ട് ഇവനെ എന്നിൽനിന്ന് പിടിച്ചുവാങ്ങാനും അയാൾ ശ്രമിക്കുന്നു. അപ്പോൾ അവരോട് റസൂൽ(സ) പറഞ്ഞു: "നീ വിവാഹം കഴിക്കാത്തിടത്തോളം ഇവൻ നിനക്ക് അവകാശപ്പെട്ടതാണ്." (ദ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 197, 197, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ أَبِي مَيْمُونَةَ سَلْمَى – مَوْلًى مِنْ أَهْلِ الْمَدِينَةِ رَجُلَ صِدْقٍ – قَالَ بَيْنَمَا أَنَا جَالِسٌ مَعَ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ جَاءَتْهُ امْرَأَةٌ فَارِسِيَّةٌ مَعَهَا ابْنٌ لَهَا، فَادَّعَيَاهُ، وَقَدْ طَلَّقَهَا زَوْجُهَا، فَقَالَتْ: يَا أَبَا هُرَيْرَةَ – وَرَطَنَتْ لَهُ بِالْفَارِسِيَّةِ – زَوْجِي يُرِيدُ أَنْ يَذْهَبَ بِابْنِي، فَقَالَ أَبُو هُرَيْرَةَ: اسْتَهِمَا عَلَيْهِ، وَرَطَنَ لَهَا بِذَلِكَ، فَجَاءَ زَوْجُهَا فَقَالَ: مَنْ يُحَاقُّنِي فِي وَلَدِي؟ فَقَالَ أَبُو هُرَيْرَةَ: اللَّهُمَّ إِنِّي لَا أَقُولُ هَذَا، إِلَّا أَنِّي سَمِعْتُ امْرَأَةً جَاءَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا قَاعِدٌ عِنْدَهُ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ زَوْجِي يُرِيدُ أَنْ يَذْهَبَ بِابْنِي، وَقَدْ سَقَانِي مِنْ بِئْرِ أَبِي عِنَبَةَ، وَقَدْ نَفَعَنِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اسْتَهِمَا عَلَيْهِ". فَقَالَ زَوْجُهَا: مَنْ يُحَاقُّنِي فِي وَلَدِي؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَذَا أَبُوكَ، وَهَذِهِ أُمُّكَ، فَخُذْ بِيَدِ أَيِّهِمَا شِئْتَ". فَأَخَذَ بِيَدِ أُمِّهِ، فَانْطَلَقَتْ بِهِ. (د,ت,ن,جه)', 'അബൂമൈമൂനതു സൽമാ - മദീനക്കാരനായ സത്യസന്ധനായ ഒരടിമയായിരുന്നു അദ്ദേഹം -: അദ്ദേഹം അബൂഹുറൈറ(റ)വിന്റെ കൂടെയിരിക്കുന്ന സമയത്ത് ഒരു പേർഷ്യൻ അടിമസ്ത്രീ തന്റെ പുത്രനുമായി അദ്ദേഹത്തിന്റെ സമീപം വന്നു. അവളും ഭർത്താവും അദ്ദേഹത്തോട് വാദമുന്നയിച്ചു. അവളുടെ ഭർത്താവ് അവളെ മൊഴി ചൊല്ലിയിരിക്കുന്നു. അവൾ പറഞ്ഞു: അബൂഹുറൈറാ, അദ്ദേഹത്തോടവൾ പേർഷ്യൻ ഭാഷയിലാണ് സംസാരിച്ചത് എന്റെ ഭർത്താവ് മകനെ കൊണ്ടുപോകാനുദ്ദേശിക്കുന്നു. അപ്പോൾ അബൂഹുറൈറ(റ) പറഞ്ഞു: നിങ്ങൾ നറുക്കിടുക. അദ്ദേഹം അവൾക്കു മാത്രം ഗ്രഹിക്കുന്ന ഭാഷയിലാണ് സംസാരിച്ചത്. അന്നേരം അവളുടെ ഭർത്താവ് വന്നു ചോദിച്ചു: എന്റെ മകന്റെ കാര്യത്തിൽ ആരാണ് എന്നോട് തർക്കിക്കുന്നത്? അപ്പോൾ അബൂഹുറൈറ(റ) പറഞ്ഞു: അല്ലാഹുവാണ! ഞാനങ്ങനെ പറയുകയില്ല. എന്നാൽ ഞാനൊരിക്കൽ നബി(സ)യോടൊത്തിരിക്കുമ്പോൾ ഒരു സ്ത്രീ വന്നു കൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ ഭർത്താവ് എന്റെ മകനെ കൂട്ടിക്കൊണ്ടു പോകാനുദ്ദേശിക്കുന്നു. അവൻ അബൂഇനബയുടെ കിണറിൽ നിന്ന് എനിക്ക് കുറെ വെള്ളമെടുത്തു തന്നിട്ടുണ്ട്. പല ഉപകാരങ്ങളും ചെയ്തു തന്നിട്ടുണ്ട്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ രണ്ടു പേരും അവനു വേണ്ടി നറുക്കിടുക." അപ്പോൾ അവളുടെ ഭർത്താവ് ചോദിച്ചു: എന്റെ കുട്ടിയുടെ കാര്യത്തിൽ ആരാണെന്നോട് തർക്കിക്കുന്നത്? നബി(സ) കുട്ടിയോട് പറഞ്ഞു: "ഇത് നിന്റെ പിതാവ്, ഇത് മാതാവും. നീ ഇഷ്ടമുള്ളയാളുടെ കൈ പിടിച്ചു കൊള്ളുക." കുട്ടി ഉമ്മയുടെ കൈ പിടിച്ചു. ആ സ്ത്രീ കുട്ടിയുമായി പോകുകയും ചെയ്തു. (ദ,തു,ന,ജ)', 'أَبِي مَيْمُونَةَ سَلْمَى – مَوْلًى مِنْ أَهْلِ الْمَدِينَةِ رَجُلَ صِدْقٍ – قَالَ بَيْنَمَا أَنَا جَالِسٌ مَعَ أَبِي هُرَيْرَةَ', null, null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 197, 198, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجَ زَيْدُ بْنُ حَارِثَةَ إِلَى مَكَّةَ، فَقَدِمَ بِابْنَةِ حَمْزَةَ، فَقَالَ جَعْفَرٌ: أَنَا آخُذُهَا، أَنَا أَحَقُّ بِهَا، ابْنَةُ عَمِّي وَعِنْدِي خَالَتُهَا، وَإِنَّمَا الْخَالَةُ أُمٌّ. فَقَالَ عَلِيٌّ: أَنَا أَحَقُّ بِهَا، ابْنَةُ عَمِّي، وَعِنْدِي ابْنَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ أَحَقُّ بِهَا، فَقَالَ زَيْدٌ: أَنَا أَحَقُّ بِهَا، أَنَا خَرَجْتُ إِلَيْهَا، وَسَافَرْتُ، وَقَدِمْتُ بِهَا. فَخَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ حَدِيثًا، قَالَ: "وَأَمَّا الْجَارِيَةُ فَأَقْضِي بِهَا لِجَعْفَرٍ، تَكُونُ مَعَ خَالَتِهَا، وَإِنَّمَا الْخَالَةُ أُمٌّ". وَفِي رِوَايَةٍ: "إِنَّ خَالَتَهَا عِنْدَهُ". (خ,د,ت)', 'അലി(റ): സൈദുബ്നു ഹാരിസ(റ) മക്കയിലേക്ക് പോയി. ഹംസ(റ)വിന്റെ മകളെയും കൊണ്ട് തിരിച്ചുവന്നു. അപ്പോൾ ജഅ്ഫർ(റ) പറഞ്ഞു: അവളെ ഞാൻ നോക്കാം. എനിക്കാണതിന് കൂടുതൽ അർഹതയുള്ളത്. എന്റെ എളാപ്പയുടെ പുത്രിയാണവൾ. അവളുടെ മാതൃസഹോദരി എന്റെ ഭാര്യയാണ്. മാതൃസഹോദരി ഉമ്മയുടെ സ്ഥാനത്താണ്. അപ്പോൾ അലി(റ) പറഞ്ഞു: ഞാനാണ് ഏറ്റവും അർഹൻ. എന്റെ പിതൃവ്യപുത്രിയാണവൾ. എന്റടുത്തുള്ളത് അല്ലാഹുവിന്റെ റസൂലിന്റെ മകളാണ്. അവളാണ് കൂടുതൽ ഇവളോട് ബന്ധമുള്ളവൾ. അന്നേരം സൈദ്(റ) പറഞ്ഞു: എനിക്കാണ് കൂടുതൽ അർഹത. ഞാനാണവളുടെയടുത്തേക്ക് പുറപ്പെട്ട്, യാത്ര ചെയ്ത് അവളെ കൂട്ടിക്കൊണ്ട് വന്നത്. എന്നിട്ടദ്ദേഹം നബി(സ)യുടെയടുത്തേക്ക് പോയി വിവരം പറഞ്ഞു: നബി(സ) പറഞ്ഞു: "പെൺകുട്ടിയെ ഞാൻ ജഅ്ഫർ(റ)വിന് നൽകാൻ വിധികൽപിക്കുന്നു. അവൾ തന്റെ മാതൃസഹോദരിയുടെ കൂടെയാണ്. മാതൃസഹോദരി ഉമ്മ തന്നെയാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ: "അവളുടെ മാതൃസഹോദരിയാണ് അദ്ദേഹത്തിന്റെ ഭാര്യ." (ബു,ദ,തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 198, 198, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=132), 1, 'وَفِي رِوَايَةٍ: "إِنَّ خَالَتَهَا عِنْدَهُ". (خ,د,ت)', 'മറ്റൊരു നിവേദനിൽ: "അവളുടെ മാതൃസഹോദരിയാണ് അദ്ദേഹത്തിന്റെ ഭാര്യ." (ബു,ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا خَرَجْنَا مِنْ مَكَّةَ تَبِعَتْنَا بِنْتُ حَمْزَةَ، تُنَادِي: يَا عَمِّ، يَا عَمِّ، فَتَنَاوَلَهَا عَلِيٌّ، فَأَخَذَ بِيَدِهَا، وَقَالَ: دُونَكِ بِنْتَ عَمِّكِ. فَحَمَلَتْهَا، فَقَصَّ الْخَبَرَ، قَالَ: وَقَالَ جَعْفَرٌ: ابْنَةُ عَمِّي، وَخَالَتُهَا تَحْتِي، فَقَضَى بِهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِخَالَتِهَا، وَقَالَ: "الْخَالَةُ بِمَنْزِلَةِ الْأُمِّ". (د)', 'അലി(റ): ഞങ്ങൾ മക്കയിൽ നിന്ന് മടങ്ങിയപ്പോൾ ഹംസ(റ)വിന്റെ മകൾ പിതൃവ്യാ, പിതൃവ്യാ എന്ന് വിളിച്ചു കൊണ്ട് ഞങ്ങളെ പിന്തുടർന്നു. അലി(റ) അവളെയെടുത്തു. അവളുടെ കൈ പിടിച്ചു. അലി(റ) (ഫാതിമ(റ)യോട്) പറഞ്ഞു: നിന്റെ പിതൃവ്യപുത്രിയെ പിടിച്ചുകൊള്ളുക. അങ്ങനെ മഹതി അവളെയും കൂട്ടി. നിവേദകൻ പറഞ്ഞു: നിവേദകൻ തുടരുന്നു: ജഅ്ഫർ(റ) പറഞ്ഞു: അവളെന്റെ പിതൃവ്യപുത്രിയാണ്. അവളുടെ മാതൃസഹോദരി എന്റെ ഭാര്യയാണ്. അങ്ങനെ അവളുടെ മാതൃസഹോദരിക്ക് അനുകൂലമായി നബി(സ) വിധിച്ചു. ശേഷം പറഞ്ഞു: "മാതൃസഹോദരി ഉമ്മയുടെ സ്ഥാനത്താണ്." (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 198, 199, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أُتِيَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ بِثَلَاثَةٍ - وَهُوَ بِالْيَمَنِ - وَقَعُوا عَلَى امْرَأَةٍ فِي طُهْرٍ وَاحِدٍ، فَسَأَلَ اثْنَيْنِ: أَتُقِرَّانِ لِهَذَا بِالْوَلَدِ؟ قَالَا: لَا. ثُمَّ سَأَلَ اثْنَيْنِ: أَتُقِرَّانِ لِهَذَا بِالْوَلَدِ؟ قَالَا: لَا. فَأَقْرَعَ بَيْنَهُمْ، فَأَلْحَقَ الْوَلَدَ بِالَّذِي صَارَتْ عَلَيْهِ الْقُرْعَةُ، وَجَعَلَ عَلَيْهِ ثُلُثَيِ الدِّيَةِ. فَذُكِرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَضَحِكَ حَتَّى بَدَتْ نَوَاجِذُهُ. وَفِي رِوَايَةٍ قَالَ: بَيْنَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَهُ رَجُلٌ مِنَ الْيَمَنِ، فَجَعَلَ يُخْبِرُهُ وَيُحَدِّثُهُ، وَعَلِيٌّ بِهَا، فَقَالَ: يَا رَسُولَ اللَّهِ، أَتَى عَلِيًّا ثَلَاثَةُ نَفَرٍ يَخْتَصِمُونَ فِي وَلَدٍ، وَقَعُوا عَلَى امْرَأَةٍ فِي طُهْرٍ.. وَسَاقَ الْحَدِيثَ. (ن)', 'സൈദുബ്നു അർഖം(റ): യമനിൽ വെച്ച് അലി(റ)വിന്റെ സന്നിധിയിൽ മൂന്നാളുകളെ കൊണ്ടുവന്നു. ഒരേ ശുദ്ധിയുടെ കാലത്ത് ഒരു സ്ത്രീയെ സംയോഗം ചെയ്തവരായിരുന്നു അവർ. അലി(റ) അവരിൽ രണ്ടുപേരോട് ചോദിച്ചു: നിങ്ങൾ കുട്ടിയെ ഇദ്ദേഹത്തിന് വിട്ടുകൊടുക്കുമോ? അവർ പറഞ്ഞു: ഇല്ല. പിന്നെ അടുത്ത രണ്ടു പേരോട് ചോദിച്ചു: നിങ്ങൾ കുട്ടിയെ ഇദ്ദേഹത്തിന് വിട്ടുകൊടുക്കുമോ? അവർ പറഞ്ഞു: ഇല്ല. അന്നേരം അലി(റ) അവർക്കിടയിൽ നറുക്കിട്ടു. നറുക്ക് വീണ വ്യക്തിയിലേക്ക് കുട്ടിയെ ചേർക്കുകയും ഈ നഷ്ടപരിഹാരത്തിന്റെ മൂന്നിൽ രണ്ടു ഭാഗം അവൻ നൽകണമെന്ന് നിശ്ചയിക്കുകയും ചെയ്തു. ഈ സംഭവം നബി(സ)യുടെ സന്നിധിയിലെത്തി. അപ്പോൾ അണപ്പല്ലുകൾ കാണുമാറ് അവിടന്ന് ചിരിച്ചു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=134), 1, 'وَفِي رِوَايَةٍ قَالَ: بَيْنَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَهُ رَجُلٌ مِنَ الْيَمَنِ، فَجَعَلَ يُخْبِرُهُ وَيُحَدِّثُهُ، وَعَلِيٌّ بِهَا، فَقَالَ: يَا رَسُولَ اللَّهِ، أَتَى عَلِيًّا ثَلَاثَةُ نَفَرٍ يَخْتَصِمُونَ فِي وَلَدٍ، وَقَعُوا عَلَى امْرَأَةٍ فِي طُهْرٍ.. وَسَاقَ الْحَدِيثَ. (ن)', 'മറ്റൊരു നിവേദനം: നിവേദകൻ പറഞ്ഞു: ഞങ്ങൾ നബി(സ)യുടെ കൂടെയിരിക്കുമ്പോൾ യമനിൽ നിന്നൊരാൾ വന്നു. എന്നിട്ടയാൾ നബി(സ)യോട് കാര്യങ്ങൾ അറിയിക്കുകയും സംസാരിക്കുകയും ചെയ്യാൻ തുടങ്ങി. അലി(റ) ഈ സമയം യമനിലായിരുന്നു. എന്നിട്ടയാൾ പറഞ്ഞു: തിരുമേനീ, ഒരു കുട്ടിയുടെ വിഷയത്തിൽ പരസ്പരം തർക്കിച്ചു കൊണ്ട് മൂന്നാളുകൾ അലി(റ)വിന്റെ അടുക്കൽ വന്നു. ഒരു ശുദ്ധിയുടെ സമയത്ത് അവർ ഒരു സ്ത്രീയെ സംയോഗം ചെയ്തിരിക്കുന്നു. ഹദീസ് ബാക്കി പൂർത്തീകരിച്ചു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ جَالِسًا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ رَجُلٌ مِنَ الْيَمَنِ، فَقَالَ: إِنَّ ثَلَاثَةَ نَفَرٍ مِنْ أَهْلِ الْيَمَنِ أَتَوْا عَلِيًّا يَخْتَصِمُونَ إِلَيْهِ فِي وَلَدٍ، وَقَدْ وَقَعُوا عَلَى امْرَأَةٍ فِي طُهْرٍ وَاحِدٍ، فَقَالَ لِاثْنَيْنِ مِنْهُمَا: طِيبَا بِالْوَلَدِ لِهَذَا، فَغَلَيَا، ثُمَّ قَالَ لِاثْنَيْنِ: طِيبَا بِالْوَلَدِ لِهَذَا، فَغَلَيَا، ثُمَّ قَالَ لِاثْنَيْنِ: طِيبَا بِالْوَلَدِ لِهَذَا، فَغَلَيَا، فَقَالَ: أَنْتُمْ شُرَكَاءُ مُتَشَاكِسُونَ، إِنِّي مُقْرِعٌ بَيْنَكُمْ، فَمَنْ قُرِعَ فَلَهُ الْوَلَدُ، وَعَلَيْهِ لِصَاحِبَيْهِ ثُلُثَا الدِّيَةِ. فَأَقْرَعَ بَيْنَهُمْ، فَجَعَلَهُ لِمَنْ قُرِعَ. فَضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى بَدَتْ أَضْرَاسُهُ، أَوْ: نَوَاجِذُهُ. وَفِي رِوَايَةٍ قَالَ: أُتِيَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ بِثَلَاثَةٍ - وَهُوَ بِالْيَمَنِ - وَقَعُوا عَلَى امْرَأَةٍ فِي طُهْرٍ وَاحِدٍ، فَسَأَلَ اثْنَيْنِ: أَتُقِرَّانِ لِهَذَا بِالْوَلَدِ؟ قَالَا: لَا، حَتَّى سَأَلَهُمْ جَمِيعًا، فَجَعَلَ كُلَّمَا سَأَلَ اثْنَيْنِ قَالَا: لَا، فَأَقْرَعَ بَيْنَهُمْ، فَأَلْحَقَ الْوَلَدَ بِالَّذِي صَارَتْ عَلَيْهِ الْقُرْعَةُ، وَجَعَلَ عَلَيْهِ ثُلُثَيِ الدِّيَةِ، قَالَ: فَذُكِرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَضَحِكَ حَتَّى بَدَتْ نَوَاجِذُهُ. (د,ن,جه)', 'സൈദുബ്നു അർഖം(റ): ഞാൻ നബി(സ)യുടെ കൂടെയിരിക്കുകയായിരുന്നു. അന്നേരം യമനിൽ നിന്നൊരാൾ വന്നു കൊണ്ട് പറഞ്ഞു: യമൻ നിവാസികളായ മൂന്നു പേർ, ഒരേ ശുദ്ധിയുടെ സമയത്ത് ഒരു സ്ത്രീയെ ബന്ധപ്പെട്ടുണ്ടായ കുട്ടിയുടെ കാര്യത്തിൽ തർക്കിച്ചു കൊണ്ട് അലി(റ)വിന്റെയടുക്കൽ വന്നു. അവരിൽ രണ്ടു പേരോട് അദ്ദേഹം പറഞ്ഞു: ഇയാൾക്ക് കുട്ടിയെ നൽകുന്നതിൽ നിങ്ങൾ തൃപ്തരാവുക. അവർ നിഷേധസ്വരത്തിൽ ശബ്ദമുണ്ടാക്കി. പിന്നെ അടുത്ത രണ്ട് പേരോട് പറഞ്ഞു: കുട്ടിയെ ഇയാൾക്ക് നൽകുന്നതിന് നിങ്ങൾ തൃപ്തരാവുക. അവരും നിഷേധാത്മകമായി ശബ്ദമുണ്ടാക്കി. പിന്നെ അടുത്ത രണ്ടു പേരോട് പറഞ്ഞു: കുട്ടിയെ ഇദ്ദേഹത്തിന് നൽകുന്നതിന് നിങ്ങൾ തൃപ്തരാവുക. അവരും നിഷേധിച്ചു കൊണ്ട് ശബ്ദമുണ്ടാക്കി. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നിങ്ങളോരോരുത്തരും ഇപ്പോഴും തർക്കത്തിൽ പങ്കാളികളാണ്. ഞാൻ നിങ്ങൾക്കിടയിൽ നറുക്കിടാം. ആർക്ക് നറുക്ക് വീണുവോ കുട്ടി അവനായിരിക്കും. മറ്റു രണ്ടു പേർക്കും നഷ്ടപരിഹാരത്തിന്റെ മൂന്നിൽ രണ്ടു ഭാഗം നൽകുകയും വേണം. അങ്ങനെ അദ്ദേഹം അവർക്കിടയിൽ നറുക്കിട്ടു. നറുക്ക് കിട്ടിയവന് കുട്ടിയെ നൽകുകയും ചെയ്തു. ഇതു കേട്ടപ്പോൾ നബി(സ) ചിരിച്ചു. അവിടത്തെ അണപ്പല്ലുകൾ വെളിവായി.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=135), 1, 'وَفِي رِوَايَةٍ قَالَ: أُتِيَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ بِثَلَاثَةٍ - وَهُوَ بِالْيَمَنِ - وَقَعُوا عَلَى امْرَأَةٍ فِي طُهْرٍ وَاحِدٍ، فَسَأَلَ اثْنَيْنِ: أَتُقِرَّانِ لِهَذَا بِالْوَلَدِ؟ قَالَا: لَا، حَتَّى سَأَلَهُمْ جَمِيعًا، فَجَعَلَ كُلَّمَا سَأَلَ اثْنَيْنِ قَالَا: لَا، فَأَقْرَعَ بَيْنَهُمْ، فَأَلْحَقَ الْوَلَدَ بِالَّذِي صَارَتْ عَلَيْهِ الْقُرْعَةُ، وَجَعَلَ عَلَيْهِ ثُلُثَيِ الدِّيَةِ، قَالَ: فَذُكِرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَضَحِكَ حَتَّى بَدَتْ نَوَاجِذُهُ. (د,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: അലി(റ) യമനിലായിരിക്കുമ്പോൾ ഒരു ശുദ്ധിയുടെ സമയത്ത് സ്ത്രീയെ ബന്ധപ്പെട്ട മൂന്നാളുകളെ അദ്ദേഹത്തിന്റെയടുക്കൽ കൊണ്ടുവന്നു. അവരിൽ രണ്ടാളുകളോട് അദ്ദേഹം ചോദിച്ചു: കുട്ടിയെ ഇദ്ദേഹത്തിന് നൽകാൻ നിങ്ങൾ സമ്മതിക്കുമോ? അവർ രണ്ടു പേരും പറഞ്ഞു: ഇല്ല. അപ്രകാരം അവരോരോരുത്തരോടും ചോദിച്ചു. ഓരോ ഈരണ്ടു പേരോടും ചോദിക്കുമ്പോഴെല്ലാം ഇല്ല എന്നു മറുപടി പറഞ്ഞു. അപ്പോൾ അദ്ദേഹം അവർക്കിടയിൽ നറുക്കിട്ടു. നറുക്ക് വീണവന് കുട്ടിയെ നൽകുകയും നഷ്ടപരിഹാരത്തിന്റെ മൂന്നിൽ രണ്ടു ഭാഗം അയാളുടെ മേൽ നിർബന്ധമാക്കുകയും ചെയ്തു. നിവേദകൻ പറഞ്ഞു: ഈ സംഭവം നബി(സ)യോട് പറഞ്ഞു: അപ്പോൾ അവിടന്ന് അണപ്പല്ലുകൾ കാണും വിധം ചിരിച്ചു. (ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ حِينَ نَزَلَتْ آيَةُ الْمُلَاعَنَةِ: "أَيُّمَا امْرَأَةٍ أَدْخَلَتْ عَلَى قَوْمٍ رَجُلًا لَيْسَ مِنْهُمْ فَلَيْسَتْ مِنَ اللَّهِ فِي شَيْءٍ، وَلَا يُدْخِلُهَا اللَّهُ جَنَّتَهُ. وَأَيُّمَا رَجُلٍ جَحَدَ وَلَدَهُ وَهُوَ يَنْظُرُ إِلَيْهِ احْتَجَبَ اللَّهُ عَزَّ وَجَلَّ مِنْهُ، وَفَضَحَهُ عَلَى رُءُوسِ الْأَوَّلِينَ وَالْآخِرِينَ يَوْمَ الْقِيَامَةِ". (د,ن,جه)', 'അബൂഹുറൈറ(റ): ലിആനിനെക്കുറിച്ചുള്ള സൂക്തമിറങ്ങിയപ്പോൾ നബി(സ) അരുളിയത് അദ്ദേഹം കേട്ടു: "ഏതെങ്കിലും സ്ത്രീ, കുടുംബത്തിൽ പെടാത്ത പുരുഷനെ ആ കുടുംബത്തിൽ കടത്തിയാൽ (അവിഹിത ബന്ധത്തിലൂടെ കുട്ടി ജനിച്ചാൽ) അവൾക്ക് അല്ലാഹുവിന്റെ അടുത്ത് ഒരു സ്ഥാനവുമുായിരിക്കില്ല. അവളെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുകയുമില്ല. ഏതെങ്കലുമൊരാൾ, താൻ കണ്ട്കൊണ്ടിരിക്കുന്ന തന്റെ മകനെക്കുറിച്ച് അവൻ തന്റേതല്ലെന്ന് വാദിച്ചാൽ, അല്ലാഹു അവനിൽനിന്ന് മറഞ്ഞിരിക്കുന്നതാണ്. അന്ത്യനാളിൽ കഴിഞ്ഞ്പോയവരും വരാനിരിക്കുന്നവരുമായ സർവ്വ ജനങ്ങളുടെയും മുന്നിൽ വെച്ച് അവനെ വഷളാക്കുകയും ചെയ്യും." (ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 200, 200, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا مُسَاعَاةَ فِي الْإِسْلَامِ، مَنْ سَاعَى فِي الْجَاهِلِيَّةِ فَقَدْ لَحِقَ بِعَصَبَتِهِ، وَمَنِ ادَّعَى وَلَدًا مِنْ غَيْرِ رِشْدَةٍ فَلَا يَرِثُ وَلَا يُورَثُ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ലൈംഗിക തൊഴിൽ (യജമാനൻ കാശുണ്ടാക്കാൻ അടിമസ്ത്രീയെ ലൈംഗിക തൊഴിലിന് നിർത്തൽ) ഇസ്ലാമിൽ നിരോധിക്കപ്പെട്ടതാണ്. ജാഹിലിയ്യാ കാലത്ത് ആരെങ്കിലും അപ്രകാരം ചെയ്തിട്ടുണ്ടെങ്കിൽ കുട്ടി തന്റെ പിതൃകുടുംബത്തിലേക്ക് ചേർക്കപ്പെടുന്നതാണ്. നേർമാർഗ്ഗത്തിലൂടെയല്ലാതെയുണ്ടായ കുട്ടി തന്റെ കുട്ടിയാണെന്ന് വാദിച്ചാൽ കുട്ടിക്ക് അനന്തരാവകാശം ലഭിക്കുകയോ അവനിൽനിന്ന് അനന്തരമെടുക്കപ്പെടുകയോ ഇല്ല." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 200, 201, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى أَنَّ كُلَّ مُسْتَلْحَقٍ اسْتُلْحِقَ بَعْدَ أَبِيهِ الَّذِي يُدْعَى لَهُ، ادِّعَاهُ وَرَثَتُهُ، فَقَضَى: أَنَّ كُلَّ مَنْ كَانَ مِنْ أَمَةٍ يَمْلِكُهَا يَوْمَ أَصَابَهَا فَقَدْ لَحِقَ بِمَنِ اسْتَلْحَقَهُ، وَلَيْسَ لَهُ مِمَّا قُسِمَ قَبْلَهُ مِنَ الْمِيرَاثِ شَيْءٌ. وَمَا أَدْرَكَ مِنْ مِيرَاثٍ لَمْ يُقْسَمْ فَلَهُ نَصِيبُهُ، وَلَا يَلْحَقُ إِذَا كَانَ أَبُوهُ الَّذِي يُدْعَى لَهُ أَنْكَرَهُ. وَإِنْ كَانَ مِنْ أَمَةٍ لَمْ يَمْلِكْهَا أَوْ مِنْ حُرَّةٍ عَاهَرَ بِهَا فَإِنَّهُ لَا يَلْحَقُ بِهِ وَلَا يَرِثُ، وَإِنْ كَانَ الَّذِي يُدْعَى لَهُ هُوَ ادَّعَاهُ، فَهُوَ وَلَدُ زِنْيَةٍ مِنْ حُرَّةٍ كَانَ أَوْ أَمَةٍ. وَفِي رِوَايَةٍ: هُوَ وَلَدُ زِنًا، لِأَهْلِ أُمِّهِ مَنْ كَانُوا، حُرَّةً أَوْ أَمَةً. وَذَلِكَ فِيمَا اسْتُلْحِقَ فِي أَوَّلِ الْإِسْلَامِ، فَمَا اقْتُسِمَ مِنْ مَالٍ قَبْلَ الْإِسْلَامِ فَقَدْ مَضَى. (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): താൻ ചേർത്തുവിളിക്കപ്പെടുന്ന തന്റെ പിതാവിന്റെ മരണശേഷം അദ്ദേഹത്തിന്റെ കുടുംബമായി പരിഗണിക്കപ്പെടുകയും, പിതാവിന്റെ അനന്തരാവകാശികൾ അവകാശമുന്നയിക്കുകയും ചെയ്ത കുട്ടിയുടെ കാര്യത്തിൽ നബി(സ) ഇപ്രകാരം വിധിച്ചു: ലൈംഗിക ബന്ധത്തിലേർപ്പെടുമ്പോൾ പിതാവിന്റെ ഉടമയിലുണ്ടായിരുന്ന അടിമസ്ത്രീയുടെ സന്തതിയാണ് അവനെങ്കിൽ തന്നെ; കുടുംബമായി ചേർക്കുന്നവരുടെ കൂട്ടത്തിൽ അവൻ ഉൾപ്പപ്പെടുന്നതാണ്. എന്നാൽ അതിനുമുമ്പ് ഓഹരിവെക്കപ്പെട്ട സ്വത്തിൽ നിന്ന് അവന് ഒന്നും ലഭിക്കുകയില്ല. ഓഹരി വെക്കപ്പെടാത്ത സ്വത്തിൽ ഇവന് അവകാശമുണ്ടാവും. എന്നാൽ താൻ ചേർത്തുവിളിക്കപ്പെടുന്ന പിതാവ് അവനെ നിരാകരിച്ചാൽ അവൻ അനന്തരാവകാശികളിൽ ഉൾപ്പെടുകയില്ല. അവൻ അദ്ദേഹത്തിന്റെ ഉടമസ്ഥതയിലില്ലാത്ത അടിമസ്ത്രീയിൽ നിന്നുണ്ടായ കുട്ടിയോ അയാൾ സ്വതന്ത്രയെ അവിഹിതമായി ബന്ധപ്പെട്ടുണ്ടായ കുട്ടിയോ ആണെങ്കിൽ അവൻ അയാളുടെ കുടുംബത്തിൽ ചേർക്കപ്പെടുകയോ അവന് അനന്തരം ലഭിക്കുകയോ ചെയ്യില്ല. താൻ ചേർത്തുവിളിക്കപ്പെടുന്നവൻ അവകാശമുന്നയിച്ചാലും ശരി. അടിമസ്ത്രീയിൽ നിന്നുണ്ടായതായാലും സ്വതന്ത്രയിൽ നിന്നുണ്ടായതായാലും അവൻ അവിഹിത സന്തതിയാണ്.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=138), 1, 'وَفِي رِوَايَةٍ: هُوَ وَلَدُ زِنًا، لِأَهْلِ أُمِّهِ مَنْ كَانُوا، حُرَّةً أَوْ أَمَةً. وَذَلِكَ فِيمَا اسْتُلْحِقَ فِي أَوَّلِ الْإِسْلَامِ، فَمَا اقْتُسِمَ مِنْ مَالٍ قَبْلَ الْإِسْلَامِ فَقَدْ مَضَى. (د)', 'മറ്റൊരു നിവേദനം: അവൻ അവന്റെ ഉമ്മയുടെ അവിഹിത സന്തതിയാണ്, അവൾ അടിമയായാലും, സ്വതന്ത്രയായാലും. ഇത് ഇസ്ലാമിന്റെ ആദ്യകാലത്ത് ചേർക്കപ്പെട്ടതിനെക്കുറിച്ചാണ്. എന്നാൽ ഇസ്ലാമിനുമുമ്പ് ഓഹരിവെക്കപ്പെട്ടത്, അതുകഴിഞ്ഞുപോയി. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهَا أَخْبَرَتْ بِهَذِهِ الْأَحَادِيثِ الثَّلَاثَةِ: قَالَتْ زَيْنَبُ رَضِيَ اللَّهُ عَنْهَا: دَخَلْتُ عَلَى أُمِّ حَبِيبَةَ رَضِيَ اللَّهُ عَنْهَا - زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - حِينَ تُوُفِّيَ أَبُوهَا أَبُو سُفْيَانَ بْنُ حَرْبٍ رَضِيَ اللَّهُ عَنْهُ، فَدَعَتْ بِطِيبٍ فِيهِ صُفْرَةٌ - خَلُوقٌ أَوْ غَيْرُهُ - فَدَهَنَتْ بِهِ جَارِيَةً، ثُمَّ مَسَّتْ بِعَارِضَيْهَا، ثُمَّ قَالَتْ: وَاللَّهِ مَا لِي بِالطِّيبِ مِنْ حَاجَةٍ، غَيْرَ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ تُحِدَّ عَلَى مَيِّتٍ فَوْقَ ثَلَاثَةِ أَيَّامٍ، إِلَّا عَلَى زَوْجٍ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا". وَقَالَتْ زَيْنَبُ رَضِيَ اللَّهُ عَنْهَا: وَسَمِعْتُ أُمِّي أُمَّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا تَقُولُ: جَاءَتِ امْرَأَةٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ ابْنَتِي تُوُفِّيَ عَنْهَا زَوْجُهَا، وَقَدِ اشْتَكَتْ عَيْنَيْهَا، أَفَنَكْحُلُهَا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا". مَرَّتَيْنِ أَوْ ثَلَاثَ مَرَّاتٍ، كُلَّ ذَلِكَ يَقُولُ: "لَا". ثُمَّ قَالَ: "إِنَّمَا هِيَ أَرْبَعَةُ أَشْهُرٍ وَعَشْرٌ، وَقَدْ كَانَتْ إِحْدَاكُنَّ فِي الْجَاهِلِيَّةِ تَرْمِي بِالْبَعْرَةِ عَلَى رَأْسِ الْحَوْلِ". قَالَتْ زَيْنَبُ رَضِيَ اللَّهُ عَنْهَا: وَدَخَلْتُ عَلَى زَيْنَبَ بِنْتِ جَحْشٍ رَضِيَ اللَّهُ عَنْهَا حِينَ تُوُفِّيَ أَخُوهَا، فَدَعَتْ بِطِيبٍ فَمَسَّتْ مِنْهُ، ثُمَّ قَالَتْ: وَاللَّهِ مَا لِي بِالطِّيبِ مِنْ حَاجَةٍ، غَيْرَ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ وَهُوَ عَلَى الْمِنْبَرِ: "لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ تُحِدَّ عَلَى مَيِّتٍ فَوْقَ ثَلَاثِ لَيَالٍ، إِلَّا عَلَى زَوْجٍ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا". (ق,د,ت,ن)', 'സൈനബ് ബിൻത് അബീസലമ(റ): താഴെപറയുന്ന മൂന്ന് കാര്യങ്ങൾ മഹതി പറഞ്ഞു: സൈനബ്(റ) പറഞ്ഞു: നബി(സ)യുടെ ഭാര്യയായ ഉമ്മുഹബീബ(റ)യുടെ പിതാവ് അബൂസുഫ്യാനുബ്നു ഹർബ്(റ) മരിച്ചപ്പോൾ ഞാൻ അവരുടെ അടുത്തേക്ക് ചെന്നു. ഖലൂഖോ അല്ലെങ്കിൽ മഞ്ഞനിറമുള്ള സുഗന്ധമോ കൊണ്ടുവരാൻ മഹതി പറഞ്ഞു. അപ്പോൾ മഹതി അതെടുത്ത് ഒരു പെൺകുട്ടിക്ക് പുരട്ടിക്കൊടുത്തു. എന്നിട്ടവളുടെ കവിളുകളിൽ തൊട്ടു. പിന്നീടവർ പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, എനിക്ക് സുഗന്ധമാവശ്യമില്ല. പക്ഷേ, നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "അല്ലാഹുവിലും അന്ത്യനാളിലും വിശ്വസിക്കുന്ന ഒരു സ്ത്രീക്കും മൂന്ന് ദിവസത്തിലധികം ഒരു പരേതന്റെ മേൽ ദുഃഖാചാരണം നടത്താൻ പാടില്ല, ഭർത്താവിന്റെ മേലിലൊഴികെ, അപ്പോൾ നാലുമാസവും പത്തുദിവസവും നിർബന്ധമാണ്."
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ صَفِيَّةَ بِنْتِ أَبِي عُبَيْدٍ رَضِيَ اللَّهُ عَنْهَا، عَنْ بَعْضِ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ تَحِدُّ عَلَى مَيِّتٍ أَكْثَرَ مِنْ ثَلَاثَةِ أَيَّامٍ، إِلَّا عَلَى زَوْجٍ، فَإِنَّهَا تَحِدُّ عَلَيْهِ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا". قِيلَ لِزَيْنَبَ رَضِيَ اللَّهُ عَنْهَا: وَمَا تَرْمِي بِالْبَعْرَةِ عَلَى رَأْسِ الْحَوْلِ؟ فَقَالَتْ زَيْنَبُ رَضِيَ اللَّهُ عَنْهَا: كَانَتِ الْمَرْأَةُ إِذَا تُوُفِّيَ عَنْهَا زَوْجُهَا دَخَلَتْ حِفْشًا، وَلَبِسَتْ شَرَّ ثِيَابِهَا، وَلَمْ تَمَسَّ طِيبًا وَلَا شَيْئًا، حَتَّى تَمُرَّ بِهَا سَنَةٌ، ثُمَّ تُؤْتَى بِدَابَّةٍ، حِمَارٍ أَوْ شَاةٍ أَوْ طَائِرٍ، فَتَفْتَضُّ بِهِ، فَقَلَّمَا تَفْتَضُّ بِشَيْءٍ إِلَّا مَاتَ، ثُمَّ تَخْرُجُ فَتُعْطَى بَعْرَةً فَتَرْمِي بِهَا، ثُمَّ تُرَاجِعُ بَعْدُ مَا شَاءَتْ مِنْ طِيبٍ أَوْ غَيْرِهِ. (ق,د,ت,ن,جه)', 'സ്വഫിയ്യ ബിൻത് അബീഉബൈദ്(റ): നബി(സ)യുടെ ഒരു ഭാര്യയിൽ നിന്നും ഉമ്മുസലമ(റ)യിൽ നിന്നും മഹതി നിവേദനം ചെയ്യുന്നു: നിശ്ചയം നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിലും അന്ത്യനാളിലും വിശ്വസിക്കുന്ന ഒരു സ്ത്രീക്ക് ഒരു മയ്യിതിന്റെ മേൽ മൂന്ന് ദിവസത്തിലധികം ദുഃഖമാചരിക്കൽ പാടില്ല, ഭർത്താവിന്റെ മേലൊഴികെ. ഭർത്താവിന്റെ മേൽ നാലു മാസവും പത്തുദിവസവും ദുഃഖമാചരിക്കണം." സൈനബ്(റ)യോട് ചോദിച്ചു: വർഷാവസാനം ഒട്ടകക്കാഷ്ടം കൊണ്ടെറിയുന്നതെന്താണ്? അപ്പോൾ സൈനബ്(റ) പറഞ്ഞു: ഭർത്താവ് മരണപ്പെട്ടാൽ പെണ്ണിനെ മോശമായ വസ്ത്രങ്ങൾ ധരിപ്പിച്ച് മേൽക്കൂര താഴ്ന്ന ഒരു ചെറിയ വീട്ടിൽ കടത്തും. സുഗന്ധദ്രവ്യങ്ങളോ മറ്റോ ഒന്നും തൊടാതെ ഒരു വർഷം മുഴുവൻ ഇപ്രകാരം തുടർന്നുകൊണ്ടേയിരിക്കും. പിന്നെ ഒരു മൃഗത്തെ കൊണ്ട് വരും. കഴുതയോ ആടോ അല്ലെങ്കിൽ പക്ഷിയോ ആയിരിക്കുമത്. അവളുടെ ഗുഹ്യസ്ഥാനവും ശരീരം ആസകലവും ആ മൃഗത്തെക്കൊണ്ട് തടവിക്കും. അങ്ങനെ ചെയ്യപ്പെട്ട ജീവികൾ കുറഞ്ഞപക്ഷം മാത്രമേ അതിജീവിക്കാറുള്ളൂ. പിന്നെ അവൾ പുറത്ത് വരികയും മൃഗത്തിന്റെ ചാണകം അവൾക്ക് കൊടുക്കുകയും അവളത് എറിയുകയും ചെയ്യും. ശേഷം സുഗന്ധം പോലോത്ത വസ്തുക്കൾ ആഗ്രഹം പോലെ അവൾക്കുപയോഗിക്കാം. (ബു,മു,ദ,തു,ന,ജ)', 'صَفِيَّةَ بِنْتِ أَبِي عُبَيْدٍ', 'സ്വഫിയ്യ ബിൻത് അബീഉബൈദ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 202, 203, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: نَسَخَتْ هَذِهِ الْآيَةُ عِدَّتَهَا عِنْدَ أَهْلِهَا، فَتَعْتَدُّ حَيْثُ شَاءَتْ، وَهُوَ قَوْلُ اللهِ تَعَالَى: {غَيْرَ إِخْرَاجٍ} [البقرة: ٢٤٠] إِنْ شَاءَتِ اعْتَدَّتْ عِنْدَ أَهْلِهِ وَسَكَنَتْ فِي وَصِيَّتِهَا، وَإِنْ شَاءَتْ خَرَجَتْ، لِقَوْلِ اللهِ تَعَالَى: {فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ} ثُمَّ جَاءَ الْمِيرَاثُ فَنَسَخَ السُّكْنَى، تَعْتَدُّ حَيْثُ شَاءَتْ. (خ,د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): തന്റെ വീട്ടിൽ തന്നെ ഇദ്ദയിരിക്കണമെന്ന വിധി ഈ സൂക്തം ദുർബ്ബലപ്പെടുത്തി. അതിനാൽ എവിടെയും ഇദ്ദയിരിക്കാം. അത് ഈ സൂക്തമാണ്: ''പുറത്ത് പോകലൊഴികെ'' (അൽ ബഖറ: 240) ഭർത്താവിന്റെ ബന്ധുമിത്രാദികളുടെ കൂടെ അവൾക്ക് ഇദ്ദയിരിക്കാം. മരണസമയത്ത് ഭർത്താവ് വസ്വിയ്യത്ത് ചെയ്തിടത്ത് താമസിക്കാം. ഉദ്ദേശിക്കുമ്പോൾ പുറത്ത് പോകാം. ഈ സൂക്തമാണതിന് നിദാനം: ''അവർ പുറത്തിറങ്ങുകയാണെങ്കിൽ അവർ ചെയ്യുന്ന പ്രവർത്തിയിൽ ശിക്ഷയില്ല''. പിന്നീട് അനന്തര സ്വത്തിനെക്കുറിച്ച് വിധി വന്നു. അപ്പോൾ താമസസ്ഥലം ദുർബ്ബലപ്പെട്ടു. അവൾക്കെവിടെയും ഇദ്ദയിരിക്കാം. (ബു,ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], 'البقرة: ٢٤٠', null, 203, 203, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سُئِلَ عَنْ رَجُلٍ تَزَوَّجَ امْرَأَةً، وَلَمْ يَفْرِضْ لَهَا صَدَاقًا وَلَمْ يَدْخُلْ بِهَا حَتَّى مَاتَ؟ قَالَ ابْنُ مَسْعُودٍ: لَهَا مِثْلُ صَدَاقِ نِسَائِهَا، لَا وَكْسَ وَلَا شَطَطَ، وَعَلَيْهَا الْعِدَّةُ وَلَهَا الْمِيرَاثُ. فَقَامَ مَعْقِلُ بْنُ سِنَانٍ الأَشْجَعِيُّ – رَضِيَ اللهُ عَنْهُ – فَقَالَ: قَضَى فِينَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي بَرْوَعَ بِنْتِ وَاشِقٍ – امْرَأَةٌ مِنَّا – مِثْلَ مَا قَضَيْتَ. فَفَرِحَ ابْنُ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ. (ن)', 'ഇബ്നുമസ്ഊദ്(റ): മഹറ്റ് നിശ്ചയിക്കാതെ വിവാഹം കഴിക്കുകയും മരിക്കുന്നത്വരെ ബന്ധപ്പെടാതിരിക്കുകയും ചെയ്തയാളെക്കുറിച്ച് അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. ഇബ്നുമസ്ഊദ്(റ) പറഞ്ഞു: അവളുടെ ബന്ധുക്കളിലെ സ്ത്രീകളുടെ മഹറ്റ് അവൾക്കുണ്ട്. കുറയാനോ കൂടാനോ പാടില്ല. ഇദ്ദ അവൾക്ക് അനിവാര്യമാണ്. അനന്തരസ്വത്തും അവൾക്ക് ലഭിക്കും. അപ്പോൾ മഅ്ഖലുബ്നു സിനാനിൽ അശ്ജഇൗ(റ) എഴുന്നേറ്റുനിന്നുകൊണ്ട് പറഞ്ഞു: അങ്ങ് വിധിച്ചതുപോലെത്തന്നെയാണ് ഞങ്ങളിൽപെട്ട ബർവഅ് ബിൻത് വാശിഖിന്റെ കാര്യത്തിൽ നബി(സ)യും വിധിച്ചത്. അന്നേരം ഇബ്നു മസ്ഊദ്(റ) വളരെ സന്തോഷിച്ചു. (ന)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 203, 203, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ بْنِ عُتْبَةَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أَبَاهُ كَتَبَ إِلَى عُمَرَ بْنِ عَبْدِ اللهِ بْنِ الْأَرْقَمِ الزُّهْرِيِّ، يَأْمُرُهُ أَنْ يَدْخُلَ عَلَى سُبَيْعَةَ بِنْتِ الْحَارِثِ الأَسْلَمِيَّةِ، فَيَسْأَلَهَا عَنْ حَدِيثِهَا وَعَمَّا قَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ اسْتَفْتَتْهُ. فَكَتَبَ عُمَرُ بْنُ عَبْدِ اللهِ إِلَى عَبْدِ اللهِ بْنِ عُتْبَةَ رَضِيَ اللهُ عَنْهُمَا يُخْبِرُهُ: أَنَّ سُبَيْعَةَ أَخْبَرَتْهُ أَنَّهَا كَانَتْ تَحْتَ سَعْدِ بْنِ خَوْلَةَ، وَهُوَ فِي بَنِي عَامِرِ بْنِ لُؤَيٍّ، وَكَانَ مِمَّنْ شَهِدَ بَدْرًا، فَتُوُفِّيَ عَنْهَا فِي حَجَّةِ الْوَدَاعِ وَهِيَ حَامِلٌ، فَلَمْ تَنْشَبْ أَنْ وَضَعَتْ حَمْلَهَا بَعْدَ وَفَاتِهِ، فَلَمَّا تَعَلَّتْ مِنْ نِفَاسِهَا تَجَمَّلَتْ لِلْخُطَّابِ، فَدَخَلَ عَلَيْهَا أَبُو السَّنَابِلِ بْنُ بَعْكَكٍ – رَجُلٌ مِنْ بَنِي عَبْدِ الدَّارِ – فَقَالَ لَهَا: مَا لِي أَرَاكِ مُتَجَمِّلَةً، لَعَلَّكِ تَرْجِينَ النِّكَاحَ؟ إِنَّكِ وَاللهِ مَا أَنْتِ بِنَاكِحٍ حَتَّى تَمُرَّ عَلَيْكِ أَرْبَعَةُ أَشْهُرٍ وَعَشْرٌ. قَالَتْ سُبَيْعَةُ: فَلَمَّا قَالَ لِي ذَلِكَ جَمَعْتُ عَلَيَّ ثِيَابِي حِينَ أَمْسَيْتُ، فَأَتَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَأَلْتُهُ عَنْ ذَلِكَ؟ فَأَفْتَانِي بِأَنِّي قَدْ حَلَلْتُ حِينَ وَضَعْتُ حَمْلِي، وَأَمَرَنِي بِالتَّزَوُّجِ إِنْ بَدَا لِي. قَالَ ابْنُ شِهَابٍ: فَلَا أَرَى بَأْسًا أَنْ تَتَزَوَّجَ حِينَ وَضَعَتْ وَإِنْ كَانَتْ فِي دَمِهَا، غَيْرَ أَنْ لَا يَقْرَبَهَا زَوْجُهَا حَتَّى تَطْهُرَ. (ق,د,ن,جه)', 'ഉബൈദുല്ലാഹിബ്നി അബ്ദില്ലാഹിബ്നി ഉത്ബ(റ): സുബൈഅത് ബിൻത് ഹാരിസിൽ അസ്ലമിയ്യ(റ)യുടെ അടുത്ത് ചെന്ന്, മഹതിയുടെ പ്രശ്നത്തിൽ നബി(സ)യോട് വിധി തേടിയപ്പോൾ അവിടന്ന് എന്താണ് മറുപടി നൽകിയതെന്ന് ചോദിച്ചറിയാൻ കൽപിച്ചുകൊണ്ട് ഉമറുബ്നു അബ്ദില്ല(റ)വിന് ഉബൈദുല്ല(റ)വിന്റെ പിതാവ് കത്തെഴുതി. അങ്ങനെ ഉമറുബ്നു അബ്ദില്ല(റ) അബ്ദുല്ലാഹിബ്നു ഉത്ബ(റ)വിന് വിവരങ്ങളറിയിച്ചുകൊണ്ട് മറുപടിയെഴുതി: സുബൈഅ(റ) പറയുന്നു: മഹതി സഅ്ദുബ്നു ഖൗല(റ)വിന്റെ ഭാര്യയായിരുന്നു. അദ്ദേഹം ബനൂആമിറുബ്നു ലുഅയ്യ് ഗോത്രത്തിൽ പെട്ടയാളായിരുന്നു. ബദ്റിൽ പങ്കെടുത്തയാളുമാണ്. അങ്ങനെ മഹതി ഗർഭിണിയായിരിക്കെ ഹജ്ജത്തുൽ വിദാഇന്റെ അവസരത്തിൽ മഹതിയെ വെടിഞ്ഞു കൊണ്ട് പരലോകം പുൽകി. അദ്ദേഹത്തിന്റെ വേർപാടിനു ശേഷം അധികം താമസിയാതെ അവർ പ്രസവിച്ചു. പ്രസവരക്തത്തിന്റെ കാലയളവ് കഴിഞ്ഞപ്പോൾ വിവാഹാന്വേഷകരെ പ്രതീക്ഷിച്ച് ചമഞ്ഞൊരുങ്ങി നിന്നു. തദവസരത്തിൽ അബ്ദുദ്ദാർ ഗോത്രത്തിലെ അബുസ്സനാബിലുബ്നു ബഅ്കക് വന്നുകൊണ്ട് മഹതിയോട് പറഞ്ഞു: നീയെന്താണ് അണിഞ്ഞൊരുങ്ങിയിരിക്കുന്നത്? വിവാഹം പ്രതീക്ഷിച്ചിരിക്കുകയായിരിക്കുമല്ലേ, അല്ലാഹുവാണ! നാലു മാസവും പത്തു ദിവസവും കഴിയാതെ നിനക്ക് വിവാഹം കഴിക്കാൻ പാടില്ല. സുബൈഅ(റ) പറയുന്നു: അദ്ദേഹം ഇപ്രകാരം പറഞ്ഞതിനാൽ അന്നു വൈകുന്നേരം തന്നെ വസ്ത്രങ്ങൾ കൂട്ടിവെച്ച് ഞാൻ നബി(സ)യുടെ സന്നിധിയിലെത്തി, അതേകുറിച്ച് ചോദിച്ചു. പ്രസവിച്ചു കഴിഞ്ഞപ്പോൾ തന്നെ ഞാൻ ഇദ്ദയിൽ നിന്ന് മുക്തമായിരിക്കുന്നുവെന്ന് അവിടന്ന് വിധിച്ചു. ആവശ്യമെങ്കിൽ വിവാഹം കഴിച്ചുകൊള്ളാൻ ആജ്ഞാപിച്ചു. ഇബ്നുശിഹാബ്(റ) പറയുന്നു: പ്രസവം കഴിഞ്ഞ് ശുദ്ധിയുടെ കാലം അവസാനിച്ചിട്ടില്ലെങ്കിലും വിവാഹം കഴിക്കുന്നതിൽ കുഴപ്പമില്ലെന്നാണ് എന്റെ അഭിപ്രായം. പക്ഷേ, ശുദ്ധിയുടെ കാലം കഴിയുന്നതു വരെ ഭർത്താവ് അവളെ സമീപിക്കരുത്. (ബു,മു,ദ,ന,ജ)', 'عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ بْنِ عُتْبَةَ', 'ഉബൈദുല്ലാഹിബ്നി അബ്ദില്ലാഹിബ്നി ഉത്ബ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 204, 204, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ أَبِي السَّنَابِلِ رَضِيَ اللهُ عَنْهُ قَالَ: وَضَعَتْ سُبَيْعَةُ حَمْلَهَا بَعْدَ وَفَاةِ زَوْجِهَا بِثَلَاثَةٍ وَعِشْرِينَ أَوْ خَمْسَةٍ وَعِشْرِينَ لَيْلَةً، فَلَمَّا تَعَلَّتْ تَشَوَّفَتْ لِلْأَزْوَاجِ، فَعِيبَ ذَلِكَ عَلَيْهَا، فَذُكِرَ ذَلِكَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مَا يَمْنَعُهَا قَدِ انْقَضَى أَجَلُهَا". (ن,جه)', 'അബുസ്സനാബിൽ(റ): ഭർത്താവിന്റെ വേർപാടിന് ശേഷം ഇരുപത്തിമൂന്നോ ഇരുപത്തഞ്ചോ രാത്രി കഴിഞ്ഞപ്പോൾ സുബൈഅ(റ) പ്രസവിച്ചു. അങ്ങനെ ശുദ്ധിയുടെ കാലം കഴിഞ്ഞപ്പോൾ അവർ നവവരന്മാരെ പ്രതീക്ഷിച്ചിരുന്നു. അതുകാരണം അവർ ആക്ഷേപിക്കപ്പെട്ടു. അന്നേരം പ്രശ്നം നബി(സ)യോട് പറയപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "എന്തിനാണ് അവരെ തടയുന്നത്?" അവരുടെ ഇദ്ദാകാലം കഴിഞ്ഞിരിക്കുന്നു." (ന,ജ)', 'أَبِي السَّنَابِلِ', 'അബുസ്സനാബിൽ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 204, 205, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ أَبِي سَلَمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سُئِلَ ابْنُ عَبَّاسٍ وَأَبُو هُرَيْرَةَ – رَضِيَ اللهُ عَنْهُمْ – عَنِ الْمُتَوَفَّى عَنْهَا زَوْجُهَا وَهِيَ حَامِلٌ؟ قَالَ ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: آخِرُ الأَجَلَيْنِ. وَقَالَ أَبُو هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: إِذَا وَلَدَتْ فَقَدْ حَلَّتْ. فَدَخَلَ أَبُو سَلَمَةَ رَضِيَ اللهُ عَنْهُ إِلَى أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا فَسَأَلَهَا عَنْ ذَلِكَ؟ فَقَالَتْ: وَلَدَتْ سُبَيْعَةُ الأَسْلَمِيَّةُ بَعْدَ وَفَاةِ زَوْجِهَا بِنِصْفِ شَهْرٍ، فَخَطَبَهَا رَجُلَانِ: أَحَدُهُمَا شَابٌّ وَالآخَرُ كَهْلٌ، فَحَطَّتْ إِلَى الشَّابِّ، فَقَالَ الْكَهْلُ: لَمْ تَحْلِلْ. وَكَانَ أَهْلُهَا غُيَّبًا، فَرَجَا إِذَا جَاءَ أَهْلُهَا أَنْ يُؤْثِرُوهُ بِهَا، فَجَاءَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "قَدْ حَلَلْتِ، فَانْكِحِي مَنْ شِئْتِ". (ت,ن,جه)', 'അബൂസലമ(റ): ഗർഭിണിയായിരിക്കെ ഭർത്താവ് മരിച്ച ഒരു സ്ത്രീയുടെ ഇദ്ദയെക്കുറിച്ച് ഇബ്നുഅബ്ബാസ്(റ)വിനോടും അബൂഹുറൈറ(റ)വിനോടും ചോദിക്കപ്പെട്ടു. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: രണ്ടുകാലയളവുകളിൽ (പ്രസവവും, നാലുമാസവും പത്ത് ദിവസവും) കൂടുതൽ ദൂരമുള്ളത് സ്വീകരിക്കണം. അബൂഹുറൈറ(റ) പറഞ്ഞു: അവൾ പ്രസവിച്ചാൽ തന്നെ കഴിയും. അപ്പോൾ അബൂസലമ(റ) ഉമ്മുസലമ(റ)യുടെ അടുത്ത് ചെന്ന് അതിനെക്കുറിച്ച് ചോദിച്ചു. മഹതി പറഞ്ഞു: സുബൈഅതുൽ അസ്ലമിയ്യ(റ) തന്റെ ഭർത്താവ് മരിച്ച് പകുതി മാസം കഴിഞ്ഞപ്പോൾ തന്നെ പ്രസവിച്ചു. അന്നേരം രണ്ടാളുകൾ അവരോട് വിവാഹാഭ്യർത്ഥന നടത്തി. ഒരു യുവാവും ഒരു വൃദ്ധനുമായിരുന്നു അവർ. യുവാവിനെ വിവാഹം കഴിക്കാൻ അവർ ആഗ്രഹം പ്രകടിപ്പിച്ചു. അപ്പോൾ വൃദ്ധൻ പറഞ്ഞു: നിന്റെ ഇദ്ദകാലം കഴിഞ്ഞിട്ടില്ല. അവരുടെ കുടുംബക്കാരാരും അവിടെയുണ്ടായിരുന്നില്ല. അവർ വന്നാൽ തനിക്കവളെ വിവാഹം കഴിച്ചുതരുമെന്ന് പ്രതീക്ഷിച്ചാണ് അയാളതു പറഞ്ഞത്. അപ്പോളവർ നബി(സ)യുടെ അടുത്ത് ചെന്നു വിഷയം പറഞ്ഞു: അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിന്റെ ഇദ്ദ കഴിഞ്ഞിരിക്കുന്നു. നീ ഇഷ്ടമുള്ളവരെ വിവാഹം കഴിച്ചുകൊള്ളുക." (തു,ന,ജ)', 'أَبِي سَلَمَةَ', 'അബൂസലമ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 205, 205, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ رَضِيَ اللهُ عَنْهُ قَالَ: قِيلَ لِابْنِ عَبَّاسٍ – رَضِيَ اللهُ عَنْهُمَا – فِي امْرَأَةٍ وَضَعَتْ بَعْدَ وَفَاةِ زَوْجِهَا بِعِشْرِينَ لَيْلَةً: أَيَصْلُحُ لَهَا أَنْ تَزَوَّجَ؟ قَالَ: لَا، إِلَّا آخِرَ الأَجَلَيْنِ. قَالَ: قُلْتُ: قَالَ اللهُ تَبَارَكَ وَتَعَالَى: {وَأُولَاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ} [الطلاق: ٤]. فَقَالَ: إِنَّمَا ذَلِكَ فِي الطَّلَاقِ. فَقَالَ أَبُو هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَا مَعَ ابْنِ أَخِي. يَعْنِي أَبَا سَلَمَةَ، فَأَرْسَلَ غُلَامَهُ كُرَيْبًا فَقَالَ: ائْتِ أُمَّ سَلَمَةَ فَسَلْهَا: هَلْ كَانَ هَذَا سُنَّةً مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ فَجَاءَ فَقَالَ: قَالَتْ: نَعَمْ، سُبَيْعَةُ الأَسْلَمِيَّةُ وَضَعَتْ بَعْدَ وَفَاةِ زَوْجِهَا بِعِشْرِينَ لَيْلَةً، فَأَمَرَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ تَزَوَّجَ، فَكَانَ أَبُو السَّنَابِلِ فِيمَنْ يَخْطُبُهَا. (ق,ت,ن)', 'അബൂസലമതുബ്നു അബ്ദിർറഹ്മാൻ(റ): ഭർത്താവിന്റെ മരണം കഴിഞ്ഞ് ഇരുപത് ദിവസത്തിനകം സ്ത്രീ പ്രസവിച്ചാൽ അവൾക്ക് വിവാഹം കഴിക്കാൻ പറ്റുമോയെന്ന് ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: പാടില്ല, രണ്ട് കാലയളവുകളിൽ അവസാനത്തേതിലൊഴികെ. നിവേദകൻ പറയുന്നു: ഞാൻ പറഞ്ഞു: അല്ലാഹു പറഞ്ഞിരിക്കുന്നല്ലോ, ''ഗർഭമുള്ളവരുടെ അവധി അവർ പ്രസവിക്കുന്നത് വരെയാണ്.'' (ത്വലാഖ്: 4) അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അത് ത്വലാഖിനെക്കുറിച്ചാണ് പറഞ്ഞത്. അപ്പോൾ അബൂഹുറൈറ(റ) പറഞ്ഞു: ഞാൻ എന്റെ സഹോദരപുത്രന്റെ കൂടെയാണ്. അബൂസലമ(റ)വിനെയാണ് അദ്ദേഹം ഉദ്ദേശിക്കുന്നത്. അങ്ങനെ അദ്ദേഹം ഇബ്നുഅബ്ബാസ്(റ)വിന്റെ അടിമയെ വിളിച്ച് ഉമ്മുസലമ(റ) യുടെ അടുത്തേക്ക് അയച്ചു കൊണ്ട് പറഞ്ഞു: ഇത് റസൂൽ(സ)യുടെ ചര്യയിൽ പെട്ടതാണോ എന്ന് ചോദിക്കുക. പിന്നീട് അയാൾ വന്നു കൊണ്ട് പറഞ്ഞു: മഹതി പറഞ്ഞു: അതെ, സുബൈഅതുൽ അസ്ലമിയ്യ(റ) തന്റെ ഭർത്താവ് മരിച്ച് ഇരുപത് രാത്രികൾ കഴിഞ്ഞപ്പോൾ തന്നെ പ്രസവിച്ചു. അപ്പോൾ നബി(സ) അവരോട് വിവാഹം കഴിക്കാൻ കൽപിച്ചു. അബുസ്സനാബിൽ(റ) അവരോട് വിവാഹാഭ്യർത്ഥന നടത്തിയവരിലൊരാളാണ്. (ബു,മു,തു,ന)', 'أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ', 'അബൂസലമതുബ്നു അബ്ദിർറഹ്മാൻ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], 'الطلاق: ٤', null, 205, 206, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ، عَنْ أُمِّهَا أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةً مِنْ أَسْلَمَ يُقَالُ لَهَا سُبَيْعَةُ، كَانَتْ تَحْتَ زَوْجِهَا فَتُوُفِّيَ عَنْهَا وَهِيَ حُبْلَى، فَخَطَبَهَا أَبُو السَّنَابِلِ بْنُ بَعْكَكٍ. فَأَبَتْ أَنْ تَنْكِحَهُ، فَقَالَ: مَا يَصْلُحُ لَكِ أَنْ تَنْكِحِي حَتَّى تَعْتَدِّي آخِرَ الأَجَلَيْنِ، فَمَكَثَتْ قَرِيبًا مِنْ عِشْرِينَ لَيْلَةً ثُمَّ نُفِسَتْ، فَجَاءَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "انْكِحِي". (ت,ن,جه)', 'സൈനബ് ബിൻത് അബീസലമ(റ) തന്റെ മാതാവ് ഉമ്മുസലമ(റ)യിൽ നിവേദനം ചെയ്യുന്നു: അസ്ലം ഗോത്രത്തിൽ പെട്ട സുബൈഅ എന്ന സ്ത്രീ ഗർഭിണിയായിരിക്കുമ്പോൾ അവരുടെ ഭർത്താവ് മരണപ്പെട്ടു. അപ്പോൾ അബുസ്സനാബിലുബ്നു ബഅ്കക്(റ) അവരോട് വിവാഹാഭ്യർത്ഥന നടത്തി. മഹതി അഭ്യർത്ഥന നിരസിച്ചു. അപ്പോൾ അയാൾ പറഞ്ഞു: രണ്ട് കാലയളവിൽ അവസാനത്തേതിന് ശേഷമല്ലാതെ നിനക്ക് വിവാഹം കഴിക്കാൻ പാടില്ല. ശേഷം ഇരുപത് രാത്രികൾക്കകം അവർ പ്രസവിച്ചു. അപ്പോൾ അവർ നബി(സ)യുടെയടുത്ത് ചെന്ന് വിഷയം പറഞ്ഞു: നബി(സ) പറഞ്ഞു: "നീ വിവാഹം കഴിച്ചുകൊള്ളുക." (തു,ന,ജ)', 'زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ، عَنْ أُمِّهَا أُمِّ سَلَمَةَ', 'സൈനബ് ബിൻത് അബീസലമ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 206, 206, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ زُفَرَ بْنِ أَوْسِ بْنِ الْحَدَثَانِ النَّصْرِيِّ رَضِيَ اللهُ عَنْهُ: حَدَّثَهُ أَنَّ أَبَا السَّنَابِلِ بْنَ بَعْكَكِ بْنِ السَّبَّاقِ قَالَ لِسُبَيْعَةَ الأَسْلَمِيَّةِ: لَا تَحِلِّينَ حَتَّى يَمُرَّ عَلَيْكِ أَرْبَعَةُ أَشْهُرٍ وَعَشْرًا، أَقْصَى الأَجَلَيْنِ. فَأَتَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَتْهُ عَنْ ذَلِكَ، فَزَعَمَتْ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَفْتَاهَا: أَنْ تَنْكِحَ إِذَا وَضَعَتْ حَمْلَهَا، وَكَانَتْ حُبْلَى فِي تِسْعَةِ أَشْهُرٍ حِينَ تُوُفِّيَ زَوْجُهَا، وَكَانَتْ تَحْتَ سَعْدِ بْنِ خَوْلَةَ، فَتُوُفِّيَ فِي حَجَّةِ الْوَدَاعِ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَنَكَحَتْ فَتًى مِنْ قَوْمِهَا حِينَ وَضَعَتْ مَا فِي بَطْنِهَا. (ت,ن,جه)', 'സുഫറുബ്നു ഔസിബ്നിൽ ഹദസാനിന്നസ്രി(റ): അബുസ്സനാബിലുബ്നു ബഅ്കകിബ്നിസ്സബ്ബാഖ്(റ) സുബൈഅതുൽ അസ്ലമിയ്യ(റ)യോട് പറഞ്ഞു: രണ്ട് കലാവധികളിൽ അങ്ങേയറ്റത്തേതായ, നാലുമാസവും പത്തുദിവസവും നിനക്ക് കടന്നുകഴിയുന്നത് വരെ നീ (ഇദ്ദയിൽ നിന്നും) ഒഴിവാവുകയില്ല. അപ്പോഴവർ നബി(സ)യുടെ അടുത്ത് ചെന്ന് അതിനെക്കുറിച്ച് ചോദിച്ചു. പ്രസവം കഴിഞ്ഞാൽ വിവാഹം കഴിച്ചുകൊള്ളാൻ നബി(സ) വിധി നൽകിയതായി അവർ പറഞ്ഞു. ഭർത്താവിന്റെ മരണസമയത്ത് അവർക്ക് ഒമ്പത് മാസം ഗർഭമുണ്ടായിരുന്നു. സഅ്ദുബ്നു ഖൗല(റ)വിന്റെ ഭാര്യയായിരുന്നു അവർ. നബി(സ)യുടെ കൂടെ ഹജ്ജതുൽ വിദാഇന്റെ അവസരത്തിലാണ് അദ്ദേഹം മരണപ്പെട്ടത്. പ്രസവം കഴിഞ്ഞപ്പോൾതന്നെ മഹതി തന്റെ കുടുംബത്തിൽ നിന്നൊരു യുവാവിനെ വിവാഹം കഴിച്ചു. (തു,ന,ജ)', 'زُفَرَ بْنِ أَوْسِ بْنِ الْحَدَثَانِ النَّصْرِيِّ', 'സുഫറുബ്നു ഔസിബ്നിൽ ഹദസാനിന്നസ്രി(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 206, 206, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ سُبَيْعَةَ بِنْتِ الْحَارِثِ رَضِيَ اللهُ عَنْهَا: أَنَّهَا وَضَعَتْ بَعْدَ وَفَاةِ زَوْجِهَا بِخَمْسَةٍ وَعِشْرِينَ، فَتَهَيَّأَتْ تَطْلُبُ الْخَيْرَ، فَمَرَّ بِهَا أَبُو السَّنَابِلِ بْنُ بَعْكَكٍ فَقَالَ: قَدْ أَسْرَعْتِ، اعْتَدِّي آخِرَ الأَجَلَيْنِ، أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا. فَأَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللهِ، اِسْتَغْفِرْ لِي. قَالَ: "وَفِيمَ ذَاكِ". فَأَخْبَرْتُهُ. فَقَالَ: "إِنْ وَجَدْتِ زَوْجًا صَالِحًا فَتَزَوَّجِي". (ق,د,ن,جه)', 'സുബൈഅതുബിൻത് ഹാരിസ്(റ): ഭർത്താവിന്റെ മരണശേഷം ഇരുപത്തഞ്ച് ദിവസത്തിനകം അവർ പ്രസവിച്ചു. അങ്ങനെ വിവാഹം ചെയ്യാൻ വരന്മാരെ പ്രതീക്ഷിച്ച് ഒരുങ്ങിനിന്നു. അതേയവസരത്തിൽ അബുസ്സനാബിലുബ്നു ബഅ്കക് മഹതിയുടെയടുത്ത് കൂടി നടന്നുപോയപ്പോൾ പറഞ്ഞു: ഇദ്ദയുടെ വിഷയത്തിൽ നീ ധൃതികൂട്ടി. രണ്ടുകാലയളവിന്റെ അവസാനം വരെ (നാലുമാസവും പത്തുദിവസവും) ഇദ്ദയിരിക്കണം. അന്നേരം ഞാൻ നബി(സ)യുടെയടുത്ത് ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എനിക്ക് പൊറുത്ത് തന്നാലും. നബി(സ) ചോദിച്ചു: "അതിന് മാത്രം എന്താണുണ്ടായിട്ടുള്ളത്?" അപ്പോൾ ഞാൻ അവിടത്തോട് കാര്യം പറഞ്ഞു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നല്ല ഒരു വരനെ ലഭിച്ചാൽ നീ വിവാഹം കഴിക്കുക." (ബു,മു,ദ,ന,ജ)', 'سُبَيْعَةَ بِنْتِ الْحَارِثِ', 'സുബൈഅതുബിൻത് ഹാരിസ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 206, 207, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ مُحَمَّدِ بْنِ سِيرِينَ رَضِيَ اللهُ عَنْهُ، قَالَ: كُنْتُ جَالِسًا فِي نَاسٍ بِالْكُوفَةِ فِي مَجْلِسٍ لِلْأَنْصَارِ عَظِيمٍ، فِيهِمْ عَبْدُ الرَّحْمَنِ بْنُ أَبِي لَيْلَى، فَذَكَرُوا شَأْنَ سُبَيْعَةَ، فَذَكَرْتُ عَنْ عَبْدِ اللهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ: حَتَّى تَضَعَ. قَالَ ابْنُ أَبِي لَيْلَى: لَكِنَّ عَمَّهُ لَا يَقُولُ ذَلِكَ. فَرَفَعْتُ صَوْتِي وَقُلْتُ: إِنِّي لَجَرِيءٌ أَنْ أَكْذِبَ عَلَى عَبْدِ اللهِ بْنِ عُتْبَةَ وَهُوَ فِي نَاحِيَةِ الْكُوفَةِ. قَالَ: فَلَقِيتُ مَالِكًا، قُلْتُ: كَيْفَ كَانَ ابْنُ مَسْعُودٍ يَقُولُ فِي شَأْنِ سُبَيْعَةَ؟ قَالَ: قَالَ: أَتَجْعَلُونَ عَلَيْهَا التَّغْلِيظَ، وَلَا تَجْعَلُونَ لَهَا الرُّخْصَةَ؟ لَأُنْزِلَتْ سُورَةُ النِّسَاءِ الْقُصْرَى بَعْدَ الطُّولَى. (ن)', 'മുഹമ്മദുബ്നു സീരിൻ(റ): കൂഫയിൽ വെച്ച് അൻസാരികളുടെ ഒരു വലിയ സദസ്സിൽ ഞാനിരിക്കുകയായിരുന്നു. അബ്ദുർറഹ്മാനുബ്നു അബീലൈലയുമുണ്ടായിരുന്നു അക്കൂട്ടത്തിൽ. അന്നേരമവർ സുബൈഅ(റ)യെക്കുറിച്ച് സംസാരിച്ചു. മഹതി പ്രസവിച്ചുവെന്ന് അബ്ദുല്ലാഹിബ്നു ഉത്ബതുബ്നു മസ്ഊദ്(റ) പറഞ്ഞതായി പറയപ്പെട്ടു. ഇബ്നു അബീലൈല(റ) പറഞ്ഞു: പക്ഷേ, അദ്ദേഹത്തിന്റെ പിതൃസഹോദരൻ അങ്ങനെ പറയുകയില്ല. അപ്പോൾ ഞാൻ ശബ്ദമുയർത്തി പറഞ്ഞു: അബ്ദുല്ലാഹിബ്നു ഉത്ബ(റ) കൂഫയിലുണ്ടായിരിക്കെ അദ്ദേഹത്തിന്റെ മേൽ അസത്യം ചാർത്താൻ ഞാൻ തയ്യാറാണ്. നിവേദകൻ പറയുന്നു: അന്നേരം ഞാൻ മാലിക്(റ)വിനെ കണ്ടുമുട്ടി. ഞാൻ ചോദിച്ചു: സുബൈഅ(റ)യുടെ വിഷയത്തിൽ ഇബ്നു മസ്ഊദ്(റ) എന്താണ് പറയാറുണ്ടായിരുന്നത്? നിവേദകൻ പറയുന്നു: അദ്ദേഹം ചോദിച്ചു: നിങ്ങളെന്തുകൊണ്ടാണ് അവർക്ക് ബുദ്ധിമുട്ടുള്ള വിധി കൽപിക്കുന്നത്? എന്ത് കൊണ്ട് ഇളവ് നൽകുന്നില്ല? സ്ത്രീയുടെ വിഷയങ്ങളുള്ള ചെറിയ സൂറത് (സൂറതുത്വലാഖ്) വലിയ സൂറതിന് (സൂറതുൽ ബഖറ) ശേഷമാണ് ഇറക്കപ്പെട്ടത്. (ന)', 'مُحَمَّدِ بْنِ سِيرِينَ', 'മുഹമ്മദുബ്നു സീരിൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 207, 207, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَنْ شَاءَ لَاعَنْتُهُ: مَا أُنْزِلَتْ: {وَأُولَاتُ الأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ} [الطلاق: ٤] إِلَّا بَعْدَ آيَةِ الْمُتَوَفَّى عَنْهَا زَوْجُهَا، إِذَا وَضَعَتِ الْمُتَوَفَّى عَنْهَا زَوْجُهَا فَقَدْ حَلَّتْ. (ن)', 'ഇബ്നു മസ്ഊദ്(റ): ഉദ്ദേശിക്കുന്നവർക്ക് ഞാൻ പറഞ്ഞുകൊടുത്തുകൊള്ളാം: ''ഗർഭിണികളുടെ ഇദ്ദകാലം അവർ പ്രസവിക്കുന്നത് വരെയാണ്'' (ത്വലാഖ്: 4) എന്ന സൂക്തം, ഭർത്താവ് മരിച്ചവളെക്കുറിച്ച് ഇറങ്ങിയ സൂറത്തിന് (നാലുമാസവും പത്തുദിവസവും ഇദ്ദയിരിക്കണമെന്ന് കൽപിക്കുന്ന സൂക്തം) ശേഷം മാത്രമാണ് ഇറക്കപ്പെട്ടത്. അതിനാൽ ഭർത്താവ് മരിച്ച സ്ത്രീ പ്രസവിച്ചാൽ തന്നെ ഇദ്ദയിൽ നിന്ന് മുക്തമാകും. (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'ഇബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الطلاق: ٤', null, 207, 207, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ سُورَةَ النِّسَاءِ الْقُصْرَى نَزَلَتْ بَعْدَ الْبَقَرَةِ. (د,ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): സ്ത്രീകളെക്കുറിച്ച് പറയുന്ന ചെറിയ സൂറത് (സൂറതുത്വലാഖ്) ബഖറ സൂറതിന് ശേഷമാണ് ഇറക്കപ്പെട്ടത്. (ദ,ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 207, 207, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَنْ شَاءَ لَاعَنْتُهُ: لَأُنْزِلَتْ سُورَةُ النِّسَاءِ الْقُصْرَى بَعْدَ الأَرْبَعَةِ الأَشْهُرِ وَعَشْرًا. (د,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ആവശ്യമുള്ളവർക്ക് ഞാൻ അറിയിച്ചുകൊള്ളാം: സ്ത്രീകളെക്കുറിച്ചുള്ള ചെറിയ സൂറത്ത് (സൂറതുത്വലാഖ്) നാലുമാസവും പത്തുദിവസവും ഇദ്ദയിരിക്കണമെന്ന നിയമത്തിന്റെ ശേഷമാണ് ഇറക്കപ്പെട്ടത്. (ദ,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 207, 207, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنِ الزُّبَيْرِ بْنِ الْعَوَّامِ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ كَانَتْ عِنْدَهُ أُمُّ كُلْثُومٍ بِنْتُ عُقْبَةَ، فَقَالَتْ لَهُ، وَهِيَ حَامِلٌ: طَيِّبْ نَفْسِي بِتَطْلِيقَةٍ. فَطَلَّقَهَا تَطْلِيقَةً، ثُمَّ خَرَجَ إِلَى الصَّلَاةِ فَرَجَعَ وَقَدْ وَضَعَتْ، فَقَالَ: مَا لَهَا؟ خَدَعَتْنِي، خَدَعَهَا اللَّهُ. ثُمَّ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "سَبَقَ الْكِتَابُ أَجَلَهُ، اخْطُبْهَا إِلَى نَفْسِهَا". [ز: منقطع] (جه)', 'സുബൈറുബ്നുൽ അവ്വാം(റ): ഉമ്മുകുൽസൂം(റ) സുബൈർ(റ)വിന്റെ ഭാര്യയായിരുന്നു. ഗർഭിണിയായിരിക്കെ അവർ അദ്ദേഹത്തോട് പറഞ്ഞു: ഒരു മൊഴിചൊല്ലിക്കൊണ്ട് എന്നെ തൃപ്തിപ്പെടുത്തുക. അപ്പോഴദ്ദേഹം അവളെ ഒരു മൊഴിചൊല്ലി. പിന്നെ അദ്ദേഹം നിസ്കരിക്കാൻ പോയി. തിരുച്ചുവരുമ്പോഴേക്ക് മഹതി പ്രസവിച്ചിരുന്നു. അദ്ദേഹം പറഞ്ഞു: എന്താണവൾക്ക് സംഭവിച്ചത്? അവളെന്നെ വഞ്ചിച്ചു. അല്ലാഹു അവളെയും വഞ്ചിക്കട്ടെ. പിന്നീടദ്ദേഹം നബി(സ)യുടെയടുത്ത് ചെന്നു വിഷയം പറഞ്ഞു: അപ്പോൾ നബി(സ) പറഞ്ഞു: "വിവാഹകാലയളവ് അവസാനിച്ചിരിക്കുന്നു. അവളെത്തന്നെ വീണ്ടും വിവാഹാലോചന നടത്തുക." (ജ)', 'الزُّبَيْرِ بْنِ الْعَوَّامِ', 'സുബൈറുബ്നുൽ അവ്വാം(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: منقطع', null, 208, 208, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: طُلِّقَتْ خَالَتِي ثَلَاثًا، فَخَرَجَتْ تَجُدُّ نَخْلًا لَهَا، فَلَقِيَهَا رَجُلٌ فَنَهَاهَا، فَأَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَتْ ذَلِكَ لَهُ، فَقَالَ لَهَا: "أُخْرُجِي، فَجُدِّي نَخْلَكِ، لَعَلَّكِ أَنْ تَصَدَّقِي مِنْهُ أَوْ تَفْعَلِي خَيْرًا". (م,د,ن,جه)', 'ജാബിർ(റ): എന്റെ മാതൃസഹോദരി മൂന്ന് ത്വലാഖ് ചൊല്ലപ്പെട്ടു. അപ്പോൾ അവർ തന്റെ ഒരു ഈത്തപ്പനത്തോട്ടത്തിലേക്ക് പഴം പറിക്കാൻ പോയി. അപ്പോൾ അവരെ ഒരാൾ കണ്ടുമുട്ടുകയും അയാൾ അവരെ (പുറത്തിറങ്ങുന്നത്) വിലക്കുകയും ചെയ്തു. അവർ നബി(സ)യുടെ അടുത്ത് വന്ന് അക്കാര്യം അവിടത്തെ ബോധിപ്പിച്ചു. അപ്പോൾ അവിടന്ന് അവരോട് പറഞ്ഞു: "നീ പുറത്തിറങ്ങി ഈത്തപ്പഴം പറിക്കുക. നിനക്കതിൽനിന്നും ദാനം ചെയ്യാം, അല്ലെങ്കിൽ വല്ല നന്മയും പ്രവർത്തിക്കാം." (മു,ദ,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 208, 208, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللَّهُ عَنْهَا، وَكَانَتْ عِنْدَ رَجُلٍ مِنْ بَنِي مَخْزُومٍ: أَنَّهُ طَلَّقَهَا ثَلَاثًا، وَخَرَجَ إِلَى بَعْضِ الْمَغَازِي، وَأَمَرَ وَكِيلَهُ أَنْ يُعْطِيَهَا بَعْضَ النَّفَقَةِ، فَتَقَالَّتْهَا، فَانْطَلَقَتْ إِلَى بَعْضِ نِسَاءِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَدَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ عِنْدَهَا، فَقَالَتْ: يَا رَسُولَ اللَّهِ، هَذِهِ فَاطِمَةُ بِنْتُ قَيْسٍ، طَلَّقَهَا فُلَانٌ، فَأَرْسَلَ إِلَيْهَا بِبَعْضِ النَّفَقَةِ فَرَدَّتْهَا، وَزَعَمَ أَنَّهُ شَيْءٌ تَطَوَّلَ بِهِ. قَالَ: "صَدَقَ". قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَانْتَقِلِي إِلَى أُمِّ كُلْثُومٍ فَاعْتَدِّي عِنْدَهَا". ثُمَّ قَالَ: "إِنَّ أُمَّ كُلْثُومٍ امْرَأَةٌ يَكْثُرُ عُوَّادُهَا، فَانْتَقِلِي إِلَى عَبْدِ اللَّهِ ابْنِ أُمِّ مَكْتُومٍ فَإِنَّهُ أَعْمَى". فَانْتَقَلَتْ إِلَى عَبْدِ اللَّهِ، فَاعْتَدَّتْ عِنْدَهُ حَتَّى انْقَضَتْ عِدَّتُهَا، ثُمَّ خَطَبَهَا أَبُو الْجَهْمِ وَمُعَاوِيَةُ بْنُ أَبِي سُفْيَانَ - رَضِيَ اللَّهُ عَنْهُمْ - فَجَاءَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَسْتَأْمِرُهُ فِيهِمَا، فَقَالَ: "أَمَّا أَبُو الْجَهْمِ فَرَجُلٌ أَخَافُ عَلَيْكِ قَسْقَاسَتَهُ لِلْعَصَا، وَأَمَّا مُعَاوِيَةُ فَرَجُلٌ أَمْلَقُ مِنَ الْمَالِ". فَتَزَوَّجَتْ أُسَامَةَ بْنَ زَيْدٍ رَضِيَ اللَّهُ عَنْهُ بَعْدَ ذَلِكَ. (ن)', 'ഫാത്വിമതു ബിൻത് ഖൈസ്(റ): ബനൂമഖ്സൂമിൽ പെട്ട ഒരാളുടെ ഭാര്യയായിരുന്നു അവർ. അവരെ അദ്ദേഹം മൂന്ന് മൊഴിയും ചൊല്ലി. എന്നിട്ടദ്ദേഹം ഏതോ യുദ്ധത്തിന് പോയി. മഹതിക്ക് അൽപം ചെലവിന് കൊടുക്കാൻ ഒരാളെ ഏൽപിക്കുകയും ചെയ്തു. മഹതി അത് വളരെ ചുരുക്കമായി കണ്ടു. അപ്പോളവർ നബി(സ)യുടെ ഒരു ഭാര്യയുടെ അടുത്തേക്ക് ചെന്നു. മഹതി അവരുടെ കൂടെ ഉണ്ടായിരിക്കെ നബി(സ) അങ്ങോട്ട് വന്നു. അപ്പോൾ മഹതി പറഞ്ഞു: റസൂലേ, ഇത് ഫാത്വിമതുബിൻത് ഖൈസ്(റ). ഇന്നയാൾ അവരെ മൊഴിചൊല്ലിയതാണ്. അങ്ങനെ അയാൾ ചെലവിന് അൽപം കൊടുത്തയച്ചു. പക്ഷേ, ഇവരത് സ്വീകരിച്ചില്ല. താൻ ചെയ്യുന്നത് (അനിവാര്യമായത് കഴിഞ്ഞ്) സേവനമായി തരുന്നതാണെന്ന് അയാൾ വാദിക്കുന്നുമുണ്ട്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അദ്ദേഹം പറഞ്ഞത് സത്യമാണ്." നബി(സ) അവരോട് പറഞ്ഞു: "നീ ഉമ്മുകുൽസൂമിന്റെ അടുത്ത് പോയി ഇദ്ദയിരിക്കുക." പിന്നീട് പറഞ്ഞു: ഉമ്മുകുൽസൂമിന് കൂടുതൽ സന്ദർശകരുണ്ടാകും. അതുകൊണ്ട് നീ അബ്ദുല്ലാഹിബ്നു ഉമ്മിമക്തൂം(റ)വിന്റെയടുത്ത് പോകുക. അദ്ദേഹം അന്ധനാണ്." അങ്ങനെ മഹതി അബ്ദുല്ല(റ)വിന്റെയടുത്ത് പോയി ഇദ്ദയിരുന്നു. അങ്ങനെ അവിടന്ന് ഇദ്ദ കഴിയുകയും ചെയ്തു. പിന്നെ അബുൽ ജഹ്മും മുആവിയതുബ്നു അബീസുഫ്യാൻ(റ)വും അവരോട് വിവാഹാഭ്യർത്ഥന നടത്തി. അപ്പോൾ മഹതി നബി(സ)യുടെയടുത്ത് ചെന്ന് അവരെക്കുറിച്ച് അഭിപ്രായമാരാഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിന്റെ മേൽ അബുൽജഹ്മിന്റെ വടി കൊണ്ടുള്ള അടിപ്രയോഗം ഞാൻ ഭയക്കുന്നു. മുആവിയ(റ)വാണെങ്കിൽ തീരെ ദരിദ്രനാണ്." പിന്നീടവർ ഉസാമതുബ്നു സൈദ്(റ)വിനെ വിവാഹം കഴിച്ചു. (ന)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമതു ബിൻത് ഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 208, 209, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللَّهُ عَنْهَا: أَنَّهَا أَخْبَرَتْهُ أَنَّهَا كَانَتْ تَحْتَ أَبِي عَمْرِو بْنِ حَفْصِ بْنِ الْمُغِيرَةِ، فَطَلَّقَهَا آخِرَ ثَلَاثِ تَطْلِيقَاتٍ، فَزَعَمَتْ فَاطِمَةُ أَنَّهَا جَاءَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاسْتَفْتَتْهُ فِي خُرُوجِهَا مِنْ بَيْتِهَا، فَأَمَرَهَا أَنْ تَنْتَقِلَ إِلَى ابْنِ أُمِّ مَكْتُومٍ الْأَعْمَى. (ن)', 'ഫാത്വിമ ബിൻത് ഖൈസ്(റ): അബൂഅംറുബ്നു ഹഫ്സുബ്നുൽ മുഗീറയുടെ ഭാര്യയായിരുന്നു അവർ. അദ്ദേഹമവരെ മൂന്ന് ത്വലാഖിലെ അവസാന ത്വലാഖും ചൊല്ലി. ഫാത്വിമ(റ) വാദിച്ചു. അവർ നബി(സ)യുടെ അടുത്ത് ചെന്ന് വീട്ടിൽനിന്ന് പുറത്തിറങ്ങാൻ പറ്റുമോ എന്ന് വിധിതേടി. അപ്പോൾ നബി(സ) അവരോട് ഇബ്നു ഉമ്മിക്തൂം(റ) എന്ന അന്ധനായ സ്വഹാബിയുടെ അടുത്തേക്ക് പോകാൻ ആജ്ഞാപിച്ചു. (ന)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമ ബിൻത് ഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 209, 209, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ عُرْوَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى مَرْوَانَ فَقُلْتُ لَهُ: امْرَأَةٌ مِنْ أَهْلِكَ طُلِّقَتْ، فَمَرَرْتُ عَلَيْهَا وَهِيَ تَنْتَقِلُ، فَقَالَتْ: أَمَرَتْنَا فَاطِمَةُ بِنْتُ قَيْسٍ، وَأَخْبَرَتْنَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَهَا أَنْ تَنْتَقِلَ. فَقَالَ مَرْوَانُ: هِيَ أَمَرْتُهُمْ بِذَلِكَ. قَالَ عُرْوَةُ: فَقُلْتُ: أَمَا وَاللَّهِ، لَقَدْ عَابَتْ ذَلِكَ عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا وَقَالَتْ: إِنَّ فَاطِمَةَ كَانَتْ فِي مَسْكَنٍ وَحْشٍ فَخِيفَ عَلَيْهَا، فَلِذَلِكَ أَرْخَصَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ,د,جه)', 'ഉർവ(റ): മർവാന്റെ അടുത്ത് ചെന്ന് ഞാൻ പറഞ്ഞു: നിങ്ങളുടെ കുടുംബത്തിലെ ഒരു സ്ത്രീ മൊഴിചൊല്ലപ്പെട്ടിരിക്കുന്നു. അങ്ങനെ ഞാനവളുടെയരികിലൂടെ നടന്നപ്പോൾ അവർ അങ്ങോട്ടുമിങ്ങോട്ടും നടക്കുന്നത് കണ്ടു. അവൾ പറഞ്ഞു: ഫാത്വിമതുബ്നു ഖൈസ്(റ) തന്നോട് കൽപിക്കുകയും അവരറിയിക്കുകയും ചെയ്തു. റസൂൽ(സ) അവരോട് ഇങ്ങനെ വീടുമാറാൻ കൽപിച്ചുവത്രെ. അപ്പോൾ മർവാൻ പറഞ്ഞു: അവൾ അവരോട് ഇങ്ങനെ കൽപിച്ചിട്ടുണ്ട്. ഉർവ(റ) പറയുന്നു: അന്നേരം ഞാൻ പറഞ്ഞു: അറിയുക, അല്ലാഹുവാണ് സത്യം, നിശ്ചയം ആഇശ(റ) ഇതിനെ ആക്ഷേപിച്ചിട്ടുണ്ട്. അവർ പറയുകയും ചെയ്തു: വിജനമായ ഒരു വീട്ടിൽ താമസിക്കുന്നതുകാരണം ഫാത്വിമ(റ)യുടെ വിഷയത്തിൽ പേടി തോന്നിയതിനാലാണ് റസൂൽ(സ) അവർക്ക് ഇളവ് നൽകിയത്. (ബു,ദ,ജ)', 'عُرْوَةَ', 'ഉർവ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 209, 210, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: طَلَّقَنِي زَوْجِي، فَأَرَدْتُ النُّقْلَةَ، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "انْتَقِلِي إِلَى بَيْتِ ابْنِ عَمِّكِ عَمْرِو بْنِ أُمِّ مَكْتُومٍ، فَاعْتَدِّي فِيهِ". فَحَصَبَهُ الْأَسْوَدُ وَقَالَ: وَيْلَكَ، لِمَ تُفْتِي بِمِثْلِ هَذَا؟ قَالَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ: إِنْ جِئْتِ بِشَاهِدَيْنِ يَشْهَدَانِ أَنَّهُمَا سَمِعَاهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَإِلَّا لَمْ نَتْرُكْ كِتَابَ اللَّهِ لِقَوْلِ امْرَأَةٍ: {لَا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ} [الطلاق: ١]. (ن)', 'ഫാത്വിമതുബിൻതു ഖൈസ്(റ): എന്റെ ഭർത്താവ് എന്നെ മൊഴിചൊല്ലി. അപ്പോൾ ഞാൻ വീട് മാറാനുദ്ദേശിച്ചു. അങ്ങനെ ഞാൻ റസൂൽ(സ)യുടെ സന്നിധിയിൽ വന്ന് വിവരം പറഞ്ഞു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിന്റെ പിതൃവ്യപുത്രൻ അംറുബ്നു ഉമ്മിമക്തൂം(റ)വിന്റെ വീട്ടിലേക്ക് പോകുക, അവിടെ നീ ഇദ്ദയിരിക്കുക." ഇത് പറഞ്ഞപ്പോൾ അദ്ദേഹത്തെ (ഫാത്വിമ(റ)യിൽ നിന്നും നിവേനദം ചെയ്ത ശഅ്ബിയെ) അസ്വദ് ചെറിയ ചെരക്കല്ല്കൊണ്ടെറിഞ്ഞുകൊണ്ട് പറഞ്ഞു: നിന്റെ നാശം! എന്തുകൊണ്ടാണ് നീ ഇപ്രകാരം വിധി നൽകുന്നത്. ഉമർ(റ) ഫാത്വിമ(റ)യോട് പറഞ്ഞിട്ടുണ്ട്. നബി(സ)യുടെ ഈ വിധി കേട്ടുവെന്ന് സാക്ഷി നിൽക്കുന്ന രണ്ടുപേരെ കൊണ്ടുവന്നാൽ മാത്രമേ ഇതു സ്വീകരിക്കുകയുള്ളൂ. അല്ലാത്തപക്ഷം ഒരു സ്ത്രീയുടെ വാക്കിനു വേണ്ടി ഈ ഖുർആൻ സൂക്തം ഞങ്ങൾ തട്ടിക്കളയുകയില്ല. ''വ്യക്തമായ ഒരു അസാന്മാർഗ്ഗിക വൃത്തി ഉണ്ടായാലല്ലാതെ, അവരുടെ വീടുകളിൽ നിന്ന് നിങ്ങൾ അവരെ പുറത്താക്കകയോ, അവർ വീടുവിട്ടുപോകുകയോ ചയ്യാൻ പാടില്ല.'' (ത്വലാഖ്: 1) (ന)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമതുബിൻതു ഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الطلاق: ١', null, 210, 210, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ [بْنِ عَوْفٍ] رَضِيَ اللَّهُ عَنْهُ: أَنَّ فَاطِمَةَ بِنْتَ قَيْسٍ رَضِيَ اللَّهُ عَنْهَا أَخْبَرَتْهُ: أَنَّهَا كَانَتْ تَحْتَ أَبِي عَمْرِو بْنِ حَفْصِ بْنِ الْمُغِيرَةِ، فَطَلَّقَهَا آخِرَ ثَلَاثِ تَطْلِيقَاتٍ، فَزَعَمَتْ أَنَّهَا جَاءَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَسْتَفْتِيهِ فِي خُرُوجِهَا مِنْ بَيْتِهَا، فَأَمَرَهَا أَنْ تَنْتَقِلَ إِلَى ابْنِ أُمِّ مَكْتُومٍ الْأَعْمَى، فَأَبَى مَرْوَانُ أَنْ يُصَدِّقَهُ فِي خُرُوجِ الْمُطَلَّقَةِ مِنْ بَيْتِهَا. وَقَالَ عُرْوَةُ: إِنَّ عَائِشَةَ أَنْكَرَتْ ذَلِكَ عَلَى فَاطِمَةَ بِنْتِ قَيْسٍ. (م)', 'അബൂസലമതുബ്നു അബ്ദിർറഹ്മാൻ(റ): ഫാത്വിമതു ബിൻത് ഖൈസ്(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: അബൂഅംറുബ്നു ഹഫ്സുബ്നിൽ മുഗീറയുടെ ഭാര്യയായിരുന്നു അവർ. അയാളവരെ മൂന്നാമത്തെ ത്വലാഖും ചൊല്ലി. അവർ പറയുന്നു: തന്റെ വീട്ടിൽ നിന്ന് പുറത്തിറങ്ങുന്നതിനെക്കുറിച്ച് ചോദിക്കാൻ അവർ നബി(സ)യുടെയടുത്തേക്ക് പോയി. അപ്പോൾ നബി(സ) മഹതിയോട് ഇബ്നു ഉമ്മിമക്തൂം(റ)വിന്റെ വീട്ടിലേക്ക് മാറാൻ കൽപിച്ചു. മൊഴിചൊല്ലപ്പെട്ട പെണ്ണ് വീട്ടിൽ നിന്ന് പുറത്തിറങ്ങുന്ന വിഷയത്തിൽ അദ്ദേഹത്തെ വിശ്വസിക്കാൻ മർവാൻ കൂട്ടാക്കിയില്ല. ഉർവ പറയുന്നു: ഫാത്വിമബിൻത് ഖൈസ്(റ)യുടെ മേൽ ആഇശ(റ) നിഷേധിച്ചിട്ടുണ്ട്. (മു)', 'أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ [بْنِ عَوْفٍ]', 'അബൂസലമതുബ്നു അബ്ദിർറഹ്മാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], 'بْنِ عَوْفٍ', null, 210, 210, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَتْ فَاطِمَةُ بِنْتُ قَيْسٍ: يَا رَسُولَ اللَّهِ، إِنِّي أَخَافُ أَنْ يُقْتَحَمَ عَلَيَّ. فَأَمَرَهَا أَنْ تَتَحَوَّلَ. (م,ن,جه)', 'ആഇശ(റ): ഫാത്വിമതു ബിൻത് ഖൈസ്(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ ദ്രോഹിക്കപ്പെടുമെന്ന് ഞാൻ ഭയപ്പെടുന്നു. അപ്പോൾ നബി(സ) വീടുമാറിക്കൊള്ളാൻ കൽപിച്ചു. (മു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 210, 210, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ أَبِي إِسْحَقَ قَالَ: كنتُ فِي الْمَسْجِدِ الْجَامِعِ مَعَ الأَسْوَدِ، فَقَالَ: أَتَتْ فَاطِمَةُ بِنْتُ قَيْسٍ عُمَرَ بْنَ الْخَطَّابِ رَضِي الله عَنْهُ، فَقَالَ: مَا كُنَّا لِنَدَعَ كِتَابَ رَبِّنَا وَسُنَّةَ نَبِيِّنَا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِقَوْلِ امْرَأَةٍ، لا نَدْرِي أَحَفِظَتْ ذَلِكَ أَمْ لَا. (م,د,ت,ن)', 'അബൂഇസ്ഹാഖ്(റ): ഞാൻ അസ്വദിന്റെ കൂടെ ആ ജുമുഅത്തു പള്ളിയിൽ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഫാത്വിമ ബിൻത് ഖൈസ്(റ) ഉമറുബ്നുൽ ഖത്താബ്(റ)വിന്റെയടുത്ത് ചെന്നു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഒരു സ്ത്രീയുടെ വാക്ക് കേട്ട് ഞങ്ങളുടെ രക്ഷിതാവിന്റെ ഗ്രന്ഥവും ഞങ്ങളുടെ നബി(സ)യുടെ ചര്യയും ഞങ്ങൾ ഒഴിവാക്കുകയില്ല. ഞങ്ങൾക്കറിയില്ല അവൾ മനഃപാഠമാക്കിയതാണോ അല്ലയോ എന്ന്. (മു,ദ,തു,ന)', 'أَبِي إِسْحَقَ قَالَ', 'അബൂഇസ്ഹാഖ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 211, 211, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا: أَنَّهَا أَخْبَرَتْهُ أَنَّهَا كَانَتْ عِنْدَ أَبِي حَفْصِ بْنِ الْمُغِيرَةِ، وَأَنَّ أَبَا حَفْصٍ بْنَ الْمُغِيرَةِ طَلَّقَهَا آخِرَ ثَلاثِ تَطْلِيقَاتٍ، فَزَعَمَتْ أَنَّهَا جَاءَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاسْتَفْتَتْهُ فِي خُرُوجِهَا مِنْ بَيْتِهَا، فَأَمَرَهَا أَنْ تَنْتَقِلَ إِلَى ابْنِ أُمِّ مَكْتُومٍ الأَعْمَى. فَأَبَى مَرْوَانُ أَنْ يُصَدِّقَ حَدِيثَ فَاطِمَةَ فِي خُرُوجِ الْمُطَلَّقَةِ مِنْ بَيْتِهَا، قَالَ عُرْوَةُ: وَأَنْكَرَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا عَلَى فَاطِمَةَ بِنْتِ قَيْسٍ. (م,د,ن)', 'ഫാത്വിമതുബിൻത് ഖൈസ്(റ): അവർ അബൂഹഫ്സിനിബ്നി മുഗീറ(റ)യുടെ ഭാര്യയായിരുന്നു. അബൂഹഫ്സിബ്നു മുഗീറ(റ) അവരെ മൂന്ന് ത്വലാഖും ചൊല്ലി. അങ്ങനെ അവർ (ഫാത്വിമ) റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് അവളുടെ വീട്ടിൽ നിന്ന് പുറത്ത് പോകുന്നതിൽ ഫത്വ ചോദിച്ചുവെന്നും, അപ്പോൾ അവിടന്ന് അന്ധനായ ഉമ്മിമക്തൂമിന്റെ അടുത്തേക്ക് പോകണമെന്ന് അവരോട് കൽപിച്ചുവെന്നും മഹതി വാദിച്ചു. എന്നാൽ ത്വലാഖ് ചൊല്ലപ്പെട്ടവൾ തന്റെ വീട്ടിൽ നിന്ന് പുറത്ത് പോകുന്നതിലുള്ള, ഫാത്വിമയുടെ ഹദീസ് സത്യമാക്കാൻ മർവാൻ വിസമ്മതിച്ചു. ഉർവ പറഞ്ഞു: ഫാത്വിമ ബിൻത് ഖൈസിന്റെ മേൽ ആഇശ(റ) നിഷേധിച്ചിട്ടുണ്ട്. (മു,ദ,ന)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമതുബിൻത് ഖൈസ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 211, 211, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ عُرْوَةَ قَالَ: لَقَدْ عَابَتْ ذَلِكَ عَائِشَةُ رَضِيَ اللهُ عَنْهَا أَشَدَّ الْعَيْبِ – يَعْنِي حَدِيثَ فَاطِمَةَ بِنْتِ قَيْسٍ – وَقَالَتْ: إِنَّ فَاطِمَةَ كَانَتْ فِي مَكَانٍ وَحْشٍ، فَخِيفَ عَلَى نَاحِيَتِهَا، فَلِذَلِكَ رَخَّصَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د,جه)', 'ഉർവ(റ): തീർച്ചയായും ആഇശ(റ) അക്കാര്യത്തിൽ – ഫാത്വിമ ബിൻത് ഖൈസ്(റ)യുടെ ഹദീസാണെന്നദ്ദേഹം ഉദ്ദേശിക്കുന്നത് – ശക്തമായ ആക്ഷേപം ആക്ഷേപിച്ചിട്ടുണ്ട്. മഹതി പറയുകയും ചെയ്തു: നിശ്ചയം, ഫാത്വിമ ഏകാന്തമായ ഒരു സ്ഥലത്തായിരുന്നു, അപ്പോൾ അവളുടെ ഭാഗത്തെക്കുറിച്ച് ഭയം തോന്നിയതിനാൽ റസൂൽ(സ) അവർക്ക് ഇളവ് ചെയ്ത് കൊടുത്തു. (ദ,ജ)', 'عُرْوَةَ قَالَ', 'ഉർവ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 211, 211, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ: أَنَّهُ قِيلَ لِعَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَلَمْ تَرَيْ إِلَى قَوْلِ فَاطِمَةَ؟ قَالَتْ: أَمَا إِنَّهُ لَا خَيْرَ لَهَا فِي ذَلِكَ. (ق,د)', 'ഉർവതുബ്നു സുബൈർ(റ): ആഇശ(റ)യോട് ചോദിക്കപ്പെട്ടു: താങ്കൾ ഫാത്വിമ(റ)യുടെ വാക്കുകൾ കേട്ടില്ലേ. മഹതി പറഞ്ഞു: അവർക്കതിൽ ഒരു നന്മയുമില്ല. (ബു,മു,ദ)', 'عُرْوَةَ بْنِ الزُّبَيْرِ', 'ഉർവതുബ്നു സുബൈർ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 211, 211, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ سُلَيْمَانَ بْنِ يَسَارٍ، فِي خُرُوجِ فَاطِمَةَ رَضِيَ اللهُ عَنْهَا قَالَ: إِنَّمَا كَانَ ذَلِكَ مِنْ سُوءِ الْخُلُقِ. (د)', 'സുലൈമാനുബ്നു യസാർ: ഫാത്വിമ(റ)വിന്റെ പുറത്ത് പോകലിനെക്കുറിച്ച് അദ്ദേഹം പറഞ്ഞു: നിശ്ചയം അത് ചീത്ത സ്വഭാവത്താൽ ഉണ്ടായതാണ്. (ദ)', 'سُلَيْمَانَ بْنِ يَسَارٍ، فِي خُرُوجِ فَاطِمَةَ', 'സുലൈമാനുബ്നു യസാർ', null, null, array['د']::text[], array['ദ']::text[], null, null, 211, 212, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ يَحْيَى بْنِ سَعِيدِ بْنِ الْعَاصِ: أَنَّهُ طَلَّقَ بِنْتَ عَبْدِ الرَّحْمَنِ بْنِ الْحَكَمِ الْبَتَّةَ، فَانْتَقَلَهَا عَبْدُ الرَّحْمَنِ، فَأَرْسَلَتْ عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا إِلَى مَرْوَانَ بْنِ الْحَكَمِ، وَهُوَ أَمِيرُ الْمَدِينَةِ، فَقَالَتْ لَهُ: اتَّقِ اللَّهَ وَارْدُدِ الْمَرْأَةَ إِلَى بَيْتِهَا. فَقَالَ مَرْوَانُ: إِنَّ عَبْدَ الرَّحْمَنِ غَلَبَنِي وَقَالَ: أَوَ مَا بَلَغَكِ شَأْنُ فَاطِمَةَ بِنْتِ قَيْسٍ؟ فَقَالَتْ عَائِشَةُ: لَا يَضُرُّكِ أَنْ لَا تَذْكُرَ حَدِيثَ فَاطِمَةَ، فَقَالَ مَرْوَانُ: إِنْ كَانَ بِكِ الشَّرُّ فَحَسْبُكِ مَا كَانَ بَيْنَ هَذَيْنِ مِنَ الشَّرِّ. (م,د)', 'യഹ്യയബ്നു സഈദുബ്നുൽ ആസ്(റ): അദ്ദേഹം അബ്ദുർറഹ്മാനുബ്നുൽ ഹകമിന്റെ മകളെ മുഴുവൻ ത്വലാഖും ചൊല്ലി. ശേഷം അബ്ദുർറഹ്മാൻ അവളെ വീട്ടിൽനിന്നും കൊണ്ടുപോയി. മദീനയുടെ അമീറായ മർവാനുബ്നുൽ ഹകമിന് ആഇശ(റ) സന്ദേശം അയച്ചു. മഹതി അദ്ദേഹത്തോട് പറഞ്ഞു: നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുക, ആ സ്ത്രീയെ അവളുടെ വീട്ടിലേക്ക് അയക്കുകയും ചെയ്യുക. അപ്പോൾ മർവാൻ പറഞ്ഞു: നിശ്ചയം അബ്ദുർറഹ്മാൻ എന്നെ കീഴ്പ്പെടുത്തുകയും എന്നോട് ഇപ്രകാരം ചോദിക്കുകയും ചെയ്തിരിക്കുന്നു: താങ്കൾക്ക് ഫാത്വിമ ബിൻത് ഖൈാസ്(റ)യുടെ സംഭവം അറിയില്ലെയോ? അപ്പോൾ ആഇശ(റ) പറഞ്ഞു: ഫാത്വിമയുടെ ഹദീസ് പറയാതിരുന്നത് കൊണ്ട് നിങ്ങൾക്ക് ഒരു ബുദ്ധിമുട്ടും വരാൻ പോകുന്നില്ല. അപ്പോൾ മർവാൻ പറഞ്ഞു: അത് (ഫാത്വിമ(റ)യുടെ സംഭവം) ചില ബുദ്ധിമുട്ടുകളുണ്ടായതുകൊണ്ടാണെന്ന് ഭവതിക്ക് തോന്നുന്നുവെങ്കിൽ, ഇവരിരുവർക്കുമിടയിലുണ്ടായതും ചില ബുദ്ധിമുട്ടുകളാണെന്ന് ഭവതിക്ക് തോന്നേണ്ടതാണ്. (മു,ദ)', 'يَحْيَى بْنِ سَعِيدِ بْنِ الْعَاصِ', 'യഹ്യയബ്നു സഈദുബ്നുൽ ആസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 212, 212, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ مَيْمُونِ بْنِ مِهْرَانَ قَالَ: قَدِمْتُ الْمَدِينَةَ فَدُفِعْتُ إِلَى سَعِيدِ بْنِ الْمُسَيِّبِ، فَقُلْتُ: فَاطِمَةُ بِنْتُ قَيْسٍ طُلِّقَتْ فَخَرَجَتْ مِنْ بَيْتِهَا؟ فَقَالَ سَعِيدٌ: تِلْكَ امْرَأَةٌ فَتَنَتِ النَّاسَ، إِنَّهَا كَانَتْ لَسِنَةً، فَوُضِعَتْ عَلَى يَدَيِ ابْنِ أُمِّ مَكْتُومٍ الأَعْمَى. (د)', 'മൈമൂനുബ്നു മിഹ്റാൻ: ഞാൻ മദീനയിൽ എത്തി. അനന്തരം സഈദുബ്നുൽ മുസയ്യബ്(റ)വിന്റെയടുക്കൽ വന്നു. അപ്പോൾ ഞാൻ ചോദിച്ചു: ഫാത്വിമതു ബിൻത് ഖൈസ്(റ), മൊഴിചൊല്ലപ്പെട്ട ശേഷം പുറത്തുപോയോ? അപ്പോൾ സഈദ്(റ) പറഞ്ഞു: അവൾ ജനങ്ങളെ പിഴപ്പിച്ച ഒരു പെണ്ണാണ്. അവളൊരു വയാടിയായിരുന്നു. അങ്ങിനെ അവൾ അന്ധനായ ഇബ്നു ഉമ്മിമക്തൂം(റ)വിന്റെയടുക്കൽ നിറുത്തപ്പെട്ടു. (ദ)', 'مَيْمُونِ بْنِ مِهْرَانَ قَالَ', 'മൈമൂനുബ്നു മിഹ്റാൻ', null, null, array['د']::text[], array['ദ']::text[], null, null, 212, 212, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنِ الْفُرَيْعَةِ بِنْتِ مَالِكِ بْنِ سِنَانٍ – وَهِيَ أُخْتُ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُمَا –: أَنَّهَا جَاءَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَسْأَلُهُ أَنْ تَرْجِعَ إِلَى أَهْلِهَا فِي بَنِي خُدْرَةَ، وَأَنَّ زَوْجَهَا خَرَجَ فِي طَلَبِ أَعْبُدٍ لَهُ أَبَقُوا، حَتَّى إِذَا كَانَ بِطَرَفِ الْقَدُومِ لَحِقَهُمْ فَقَتَلُوهُ. قَالَتْ: فَسَأَلْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أَرْجِعَ إِلَى أَهْلِي، فَإِنَّ زَوْجِي لَمْ يَتْرُكْ لِي مَسْكَنًا يَمْلِكُهُ وَلَا نَفَقَةً. قَالَتْ: فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "نَعَمْ". قَالَتْ: فَانْصَرَفْتُ، حَتَّى إِذَا كُنْتُ فِي الْحُجْرَةِ – أَوْ: فِي الْمَسْجِدِ – نَادَانِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – أَوْ: أَمَرَ بِي فَنُودِيتُ لَهُ – فَقَالَ: "كَيْفَ قُلْتِ". قَالَتْ: فَرَدَدْتُ عَلَيْهِ الْقِصَّةَ الَّتِي ذَكَرْتُ لَهُ مِنْ شَأْنِ زَوْجِي، قَالَ: "امْكُثِي فِي بَيْتِكِ حَتَّى يَبْلُغَ الْكِتَابُ أَجَلَهُ". قَالَتْ: فَاعْتَدَدْتُ فِيهِ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا. قَالَتْ: فَلَمَّا كَانَ عُثْمَانُ أَرْسَلَ إِلَيَّ، فَسَأَلَنِي عَنْ ذَلِكَ فَأَخْبَرْتُهُ، فَاتَّبَعَهُ وَقَضَى بِهِ. حسن صحيح. (د,ت,ن,جه)', 'ഫുറൈഅ ബിൻത് മാലികിബ്നി സിനാൻ(റ) - അബൂസഈദിൽ ഖുദ്രീ(റ)വിന്റെ സഹോദരിയാണവർ -: ബനൂഖുദ്റയിലുള്ള കുടുംബക്കാരുടെ അടുത്തേക്ക് മടങ്ങട്ടെ എന്ന് ചോദിച്ച് അവർ നബി(സ)യുടെ അടുത്തേക്ക് ചെന്നു. ഓടിപ്പോയ തന്റെ അടിമകളെത്തേടി പുറപ്പെട്ടതായിരുന്നു അവരുടെ ഭർത്താവ്. ഖദൂമിന്റെ ഭാഗത്തെത്തെത്തിയപ്പോൾ അവരെ കണ്ടുമുട്ടുകയും അവർ അദ്ദേഹത്തെ വധിക്കുകയും ചെയ്തു. മഹതി പറഞ്ഞു: എന്റെ ഭർത്താവ് തന്റെ ഉടമസ്ഥതയിലുള്ള പാർപ്പിടമോ ചെലവിനായുള്ളതോ ഒന്നും എനിക്കുവേണ്ടി ബാക്കിവെച്ചിട്ടില്ല, ഞാനെന്റെ കുടുംബത്തിലേക്ക് മടങ്ങട്ടെയോ? എന്ന് നബി(സ)യോട് സമ്മതമാരാഞ്ഞു. അവർ പറയുന്നു: അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ശരി, നീ മടങ്ങിക്കൊള്ളുക." മഹതി പറയുന്നു: അന്നേരം ഞാൻ പിന്തിരിഞ്ഞു. പിന്നീട് ഞാൻ നബി(സ)യുടെ ഒരു ഭാര്യയുടെ വീട്ടിൽ - അല്ലെങ്കിൽ പള്ളിയിൽ - ആയിരുന്നപ്പോൾ റസൂൽ(സ) എന്നെ വിളിച്ചു. - അല്ലെങ്കിൽ: എന്നെ വിളിക്കാനേൽപ്പിച്ചു. ഞാൻ വിളിക്കപ്പെട്ടു. - എന്നിട്ട് ചോദിച്ചു: "നീ എന്തായിരുന്നു പറഞ്ഞത്?" മഹതി പറയുന്നു: ഞാൻ ആദ്യം പറഞ്ഞതുപോലെ ഭർത്താവിന്റെ വിവരങ്ങൾ പറഞ്ഞുകൊടുത്തു. നബി(സ) പറഞ്ഞു: "കാലാവധി തീരുംവരെ നിന്റെ വീട്ടിൽ തന്നെ താമസിക്കുക." മഹതി പറയുന്നു: അങ്ങനെ നാലു മാസവും പത്ത് ദിവസവും ഞാനവിടത്തന്നെ ഇദ്ദയിരുന്നു. പിന്നീട് ഉസ്മാൻ(റ)വിന്റെ കാലത്ത് അദ്ദേഹം എന്റെയടുത്തേക്ക് ആളെയയച്ചു. എന്നോടതിനെക്കുറിച്ച് ചോദിച്ചു. ഞാൻ കാര്യം പറഞ്ഞുകൊടുത്തു. അങ്ങനെ അദ്ദേഹമത് പിൻപറ്റുകയും അപ്രകാരം വിധിക്കുകയും ചെയ്തു. (ദ,തു,ന,ജ)', 'الْفُرَيْعَةِ بِنْتِ مَالِكِ بْنِ سِنَانٍ – وَهِيَ أُخْتُ أَبِي سَعِيدٍ الْخُدْرِيِّ', 'ഫുറൈഅ ബിൻത് മാലികിബ്നി സിനാൻ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 212, 213, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ فُرَيْعَةَ بِنْتِ مَالِكٍ – أُخْتِ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُمَا قَالَتْ: تُوُفِّيَ زَوْجِي بِالْقَدُومِ، فَأَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ لَهُ: إِنَّ دَارَنَا شَاسِعَةٌ، فَأَذِنَ لَهَا، ثُمَّ دَعَاهَا فَقَالَ: "أُمْكُثِي فِي بَيْتِكِ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا حَتَّى يَبْلُغَ الْكِتَابُ أَجَلَهُ". (ن)', 'അബൂസഈദിൽ ഖുദ്രീ(റ)വിന്റെ സഹോദരി ഫുറൈഅതു ബിൻതുമാലിക്(റ): ഖദൂമിൽ വെച്ച് എന്റെ ഭർത്താവ് മരിച്ചു. അപ്പോൾ ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: ഞങ്ങളുടെ വീട് വളരെ ദൂരത്താണ്. നബി(സ) അവർക്ക് വീടുമാറാൻ സമ്മതം നൽകി. വീണ്ടും വിളിച്ചുകൊണ്ട് അവിടന്ന് പറഞ്ഞു: "അവധി തീരും വരെ, നാലു മാസവും പത്തു ദിവസവും നിന്റെ വീട്ടിൽ തന്നെ താമസമാക്കുക." (ന)', 'فُرَيْعَةَ بِنْتِ مَالِكٍ – أُخْتِ أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 213, 213, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ أُمِّ حَكِيمِ بِنْتِ أَسِيدٍ، عَنْ أُمِّهَا: أَنَّ زَوْجَهَا تُوُفِّيَ وَكَانَتْ تَشْتَكِي عَيْنَيْهَا فَتَكْتَحِلُ بِالْجِلَاءِ، فَأَرْسَلَتْ مَوْلَاةً لَهَا إِلَى أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا، فَسَأَلَتْهَا عَنْ كُحْلِ الْجِلَاءِ، فَقَالَتْ: لَا تَكْتَحِلِي بِهِ إِلَّا مِنْ أَمْرٍ لَا بُدَّ مِنْهُ يَشْتَدُّ عَلَيْكِ، فَتَكْتَحِلِينَ بِاللَّيْلِ وَتَمْسَحِينَهُ بِالنَّهَارِ، ثُمَّ قَالَتْ عِنْدَ ذَلِكَ أُمُّ سَلَمَةَ: دَخَلَ عَلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ تُوُفِّيَ أَبُو سَلَمَةَ، وَقَدْ جَعَلْتُ عَلَى عَيْنِي صَبِرًا، فَقَالَ: "يَا أُمَّ سَلَمَةَ". فَقُلْتُ: إِنَّمَا هُوَ صَبِرٌ يَا رَسُولَ اللهِ، لَيْسَ فِيهِ طِيبٌ. قَالَ: "إِنَّهُ يَشُبُّ الْوَجْهَ، فَلَا تَجْعَلِيهِ إِلَّا بِاللَّيْلِ وَتَنْزِعِينَهُ بِالنَّهَارِ، وَلَا تَمْتَشِطِي بِالطِّيبِ وَلَا بِالْحِنَّاءِ، فَإِنَّهُ خِضَابٌ". قَالَتْ: قُلْتُ: بِأَيِّ شَيْءٍ أَمْتَشِطُ يَا رَسُولَ اللهِ؟ قَالَ: "بِالسِّدْرِ، تُغَلِّفِينَ بِهِ رَأْسَكِ". (م,د,ن)', 'ഉമ്മുഹകീം ബിൻത് അസീദ്(റ) തന്റെ ഉമ്മയിൽ നിന്നും നിവേദനം ചെയ്യുന്നു: അവരുടെ ഭർത്താവ് മരിച്ചു. അവരുടെ കണ്ണിന് രോഗം ബാധിച്ചിരുന്നു. അവർ അഞ്ജനം കൊണ്ട് സുറുമയിട്ടുകൊണ്ടിരുന്നു. അങ്ങനെ അവർ, അഞ്ജനം കൊണ്ട് സുറുമയിടുന്നതിനെക്കുറിച്ച് ചോദിക്കാൻ, തന്റെ അടിമകളെ ഉമ്മുസലമ(റ)യുടെയടുത്തേക്ക് പറഞ്ഞയച്ചു. മഹതി പറഞ്ഞു: അത്യാവശ്യ കാര്യത്തിനല്ലാതെ അതു കൊണ്ട് സുറുമയിടരുത്. അപ്പോൾ നീ രാത്രി സുറുമയിട്ട് രാവിലെ തന്നെ അതു തുടക്കണം. പിന്നെ അവിടെ വെച്ച് ഉമ്മുസലമ(റ) പറഞ്ഞു: അബൂസലമ(റ) മരണപ്പെട്ടപ്പോൾ നബി(സ) എന്റെ സമീപം വന്നു. ഞാനെന്റെ കണ്ണുകളിൽ കറ്റുവാഴ നീര് ഉറ്റിച്ചിരുന്നു. നബി(സ) വിളിച്ചു: "ഉമ്മുസലമേ." ഞാൻ പറഞ്ഞു: അത് കറ്റുവാഴ നീരാണ് റസൂലേ. അതിൽ സുഗന്ധമില്ല. നബി(സ) പറഞ്ഞു: "അത് മുഖത്തെ കൂടുതൽ പ്രസന്നമാക്കും. രാത്രിയല്ലാതെ നീ അങ്ങനെ ചെയ്യരുത്. പ്രഭാതത്തിൽ തന്നെ തുടക്കുകയും ചെയ്യുക. മൈലാഞ്ചിയോ സുഗന്ധമോ തലയിലിടരുത്. അത് ചായം പൂശലാണ്." മഹതി പറയുന്നു: ഞാൻ ചോദിച്ചു: റസൂലേ, ഞാൻ എങ്ങനെയാണ് മുടിചീകുക? നബി(സ) പറഞ്ഞു: "താളികൊണ്ട്, അത് നിന്റെ തലമുടിയിൽ പുരട്ടുക." (മു,ദ,ന)', 'أُمِّ حَكِيمِ بِنْتِ أَسِيدٍ، عَنْ أُمِّهَا', 'ഉമ്മുഹകീം ബിൻത് അസീദ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 213, 214, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا، أَنَّ امْرَأَةً تُوُفِّيَ زَوْجُهَا فَخَشُوا عَلَى عَيْنَيْهَا، فَأَتَوْا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاسْتَأْذَنُوهُ فِي الْكُحْلِ، فَقَالَ: "لَا تَكَحَّلْ، قَدْ كَانَتْ إِحْدَاكُنَّ تَمْكُثُ فِي شَرِّ أَحْلَاسِهَا أَوْ شَرِّ بَيْتِهَا، فَإِذَا كَانَ حَوْلٌ فَمَرَّ كَلْبٌ رَمَتْ بِبَعَرَةٍ، فَلَا، حَتَّى تَمْضِيَ أَرْبَعَةُ أَشْهُرٍ وَعَشْرٌ". (خ,د,ت,ن,جه)', 'ഉമ്മുസലമ(റ): ഒരു സ്ത്രീയുടെ ഭർത്താവ് മരണപ്പെട്ടു. അവളുടെ കണ്ണുകൾക്ക് രോഗം ബാധിച്ച് ബന്ധുക്കൾ ആശങ്കാകുലരായി. അവർ നബി(സ)യെ സമീപിച്ച് സുറുമയിടാൻ സമ്മതമാരാഞ്ഞു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "സുറുമയിടരുത്. നിങ്ങളിലൊരുത്തി ചെറിയ ഇടുങ്ങിയ ഒരിടത്തോ തന്റെ ഏറ്റവും വൃത്തികെട്ട കൂടാരത്തിലോ താമസിക്കുകയും, പിന്നീട് ഒരു വർഷം പൂർത്തിയായാൽ ഒരു നായ നടന്ന് പോകുമ്പോൾ മൃഗക്കാഷ്ടംകൊണ്ട് എറിയേണ്ടി വരികയും ചെയ്യുന്ന ഒരു അവസ്ഥ അവൾക്കുണ്ടായിരുന്നില്ലേ? അതുകൊണ്ട് സുറുമയിടരുത്. നാലു മാസവും പത്തു ദിവസവും കഴിയുന്നതു വരെ." (ബു,ദ,തു,ന,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 214, 214, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ زَيْنَبَ رَضِيَ اللهُ عَنْهَا: أَنَّ امْرَأَةً سَأَلَتْ أُمَّ سَلَمَةَ وَأُمَّ حَبِيبَةَ، أَتَكْتَحِلُ فِي عِدَّتِهَا مِنْ وَفَاةِ زَوْجِهَا؟ فَقَالَتْ: أَتَتِ امْرَأَةٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَتْهُ عَنْ ذَلِكَ، فَقَالَ: "قَدْ كَانَتْ إِحْدَاكُنَّ فِي الْجَاهِلِيَّةِ إِذَا تُوُفِّيَ عَنْهَا زَوْجُهَا أَقَامَتْ سَنَةً، ثُمَّ قَذَفَتْ خَلْفَهَا بِبَعْرَةٍ ثُمَّ خَرَجَتْ، وَإِنَّمَا هِيَ أَرْبَعَةُ أَشْهُرٍ وَعَشْرٌ، حَتَّى يَنْقَضِيَ الْأَجَلُ". (ن)', 'സൈനബ്(റ): ഉമ്മുസലമ(റ)യോടും ഉമ്മുഹബീബ(റ)യോടും ഒരു സ്ത്രീ ചോദിച്ചു: ഭർതൃവിരഹത്തിനു ശേഷം ഇദ്ദയിരിക്കുമ്പോൾ എനിക്കു സുറുമയിടാമോ? മഹതി പറഞ്ഞു: ഒരിക്കൽ ഒരു സ്ത്രീ ഇതുപോലെ നബി(സ)യുടെ അടുത്ത് വന്ന് ചോദിച്ചു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ജാഹിലിയ്യാ കാലത്ത് നിങ്ങളിലൊരുത്തി, ഭർത്താവ് മരിച്ചാൽ ഒരു വർഷം താമസിക്കും. പിന്നെയവളുടെ പിന്നിലേക്ക് മൃഗക്കാഷ്ടം എറിയുകയും ശേഷം അവിടന്ന് പുറത്ത് പോകുകയും ചെയ്തിരുന്നു. അതിനാൽ അവധി തീരും വരെ, നാലു മാസവും പത്തു ദിവസവും കാത്തിരിക്കുക." (ന)', 'زَيْنَبَ', 'സൈനബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 214, 214, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُحِدُّ امْرَأَةٌ عَلَى مَيِّتٍ فَوْقَ ثَلَاثٍ، إِلَّا عَلَى زَوْجٍ، فَإِنَّهَا تُحِدُّ عَلَيْهِ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا. وَلَا تَلْبَسُ ثَوْبًا مَصْبُوغًا، وَلَا ثَوْبَ عَصْبٍ، وَلَا تَكْتَحِلُ وَلَا تَمْتَشِطُ، وَلَا تَمَسُّ طِيبًا إِلَّا عِنْدَ طُهْرِهَا حِينَ تَطْهُرُ، نُبْذًا مِنْ قُسْطٍ وَأَظْفَارٍ". (ن)', 'ഉമ്മുഅതിയ്യ(റ): നബി(സ) പറഞ്ഞു: "മൂന്ന് ദിനത്തിലേറെ ഒരു സ്ത്രീ ഭർത്താവല്ലാത്ത പരേതന്റെ മേൽ ദുഃഖമാചരിക്കരുത്. ഭർത്താവിന്റെ മേൽ നാലു മാസവും പത്തു ദിവസവും ഇദ്ദ ആചരിക്കണം. വർണവസ്ത്രങ്ങൾ ധരിക്കരുത്. കെട്ടുന്ന വസ്ത്രവും ധരിക്കരുത്. സുറുമയിടാനോ തല ചീകാനോ പാടില്ല. ശുദ്ധിയുടെ സമയത്തല്ലാതെ സുഗന്ധമുപയോഗിക്കുകയുമരുത്. എന്നാൽ ഖുസ്തും (ഒരിനം സുഗന്ധം), അള്ഫാറും (പുകപ്പിക്കുന്ന ഒരിനം സുഗന്ധദ്രവ്യം) അൽപം ഉപയോഗിക്കാം." (ന)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅതിയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 214, 215, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمُتَوَفَّى عَنْهَا زَوْجُهَا لَا تَلْبَسُ الْمُعَصْفَرَ مِنَ الثِّيَابِ، وَلَا الْمُمَشَّقَةَ، وَلَا تَخْتَضِبُ، وَلَا تَكْتَحِلُ". (ق,د,ن,جه)', 'നബി(സ)യുടെ ഭാര്യ ഉമ്മുസലമ(റ): നബി(സ) പറഞ്ഞു: "ഭർത്താവ് മരിച്ച സ്ത്രീ മഞ്ഞച്ചായം പൂശിയ വസ്ത്രം ധരിക്കാൻ പാടില്ല. (മറ്റൊരു രീതിയിൽ) ചായം പൂശപ്പെട്ട വസ്ത്രവും പാടില്ല. മുടിക്ക് ചായം പൂശാനോ സുറുമയിടാനോ പാടില്ല." (ബു,മു,ദ,ന,ജ)', 'أُمِّ سَلَمَةَ', 'നബി(സ)യുടെ ഭാര്യ ഉമ്മുസലമ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 215, 215, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُحِدُّ الْمَرْأَةُ فَوْقَ ثَلَاثٍ، إِلَّا عَلَى زَوْجٍ فَإِنَّهَا تُحِدُّ عَلَيْهِ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا، وَلَا تَلْبَسُ ثَوْبًا مَصْبُوغًا إِلَّا ثَوْبَ عَصْبٍ، وَلَا تَكْتَحِلُ، وَلَا تَمَسُّ طِيبًا إِلَّا أَدْنَى طُهْرَتِهَا إِذَا طَهُرَتْ مِنْ مَحِيضِهَا بِنُبْذَةٍ مِنْ قُسْطٍ أَوْ أَظْفَارٍ". وَفِي رِوَايَةٍ: "إِلَّا مَغْسُولًا" مَكَانَ "عَصْبٍ". وَفِي رِوَايَةٍ: "وَلَا تَخْتَضِبُ". (ق,د,ن,جه)', 'ഉമ്മുഅതിയ്യ(റ): നിശ്ചയം നബി(സ) പറഞ്ഞു: "ഭർത്താവിനു വേണ്ടിയല്ലാതെ സ്ത്രീ ദുഃഖാചരണം നടത്തരുത്. ഭർത്താവിനു വേണ്ടി നാലു മാസവും പത്തു ദിവസവും ആചരിക്കണം. കെട്ടുന്ന തുണിയല്ലാതെ ചായം പൂശിയ വസ്ത്രമെടുക്കാൻ പാടില്ല. സുറുമയിടരുത്. ആർത്തവം നിന്ന് ശുദ്ധിയാകുമ്പോഴെല്ലാതെ സുഗന്ധമുപയോഗിക്കരുത്, അൽപം ഖുസ്തും അള്ഫാറും അല്ലാതെ". മറ്റൊരു നിവേദനത്തിൽ, "കെട്ടുന്ന വസ്ത്രം" എന്നിടത്ത് "കഴുകപ്പെട്ട (വസ്ത്രം)" എന്നാണുപയോഗിച്ചത്. മറ്റൊരു നിവേദനത്തിൽ "മുടിയിൽ ചായം തേക്കരുത്" എന്നുണ്ട്. (ബു,മു,ദ,ന,ജ)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅതിയ്യ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 215, 215, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=176), 1, 'وَفِي رِوَايَةٍ: "إِلَّا مَغْسُولًا" مَكَانَ "عَصْبٍ".', 'മറ്റൊരു നിവേദനത്തിൽ, "കെട്ടുന്ന വസ്ത്രം" എന്നിടത്ത് "കഴുകപ്പെട്ട (വസ്ത്രം)" എന്നാണുപയോഗിച്ചത്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=176), 2, 'وَفِي رِوَايَةٍ: "وَلَا تَخْتَضِبُ". (ق,د,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ "മുടിയിൽ ചായം തേക്കരുത്" എന്നുണ്ട്. (ബു,മു,ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ رَخَّصَ لِلْمُتَوَفَّى عَنْهَا عِنْدَ طُهْرِهَا فِي الْقُسْطِ وَالْأَظْفَارِ. (ن)', 'ഉമ്മുഅതിയ്യ(റ): നബി(സ)യിൽ നിന്നും നിവേദനം ചെയ്യുന്നു: ശുദ്ധിയുള്ള സമയത്ത് ഖുസ്തും അള്ഫാറും ഉപയോഗിക്കാൻ ഭർത്താവ് മരിച്ചവർക്ക് നബി(സ) ഇളവ് നൽകി. (ന)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅതിയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 215, 215, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: {وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْوَاجًا وَصِيَّةً لِأَزْوَاجِهِمْ مَتَاعًا إِلَى الْحَوْلِ غَيْرَ إِخْرَاجٍ} [البقرة: ٢٤٠]. فَنُسِخَ ذَلِكَ بِآيَةِ الْمِيرَاثِ، بِمَا فَرَضَ لَهُنَّ مِنَ الرُّبُعِ وَالثُّمُنِ، وَنُسِخَ أَجَلُ الْحَوْلِ بِأَنْ جُعِلَ أَجَلُهَا أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ''നിങ്ങളിൽ നിന്ന് ഭാര്യമാരെ വിട്ടേച്ചു മരണപ്പെടുന്നവർ തങ്ങളുടെ ഭാര്യമാർക്ക് ഒരു വർഷത്തേക്ക് (വീട്ടിൽ നിന്ന്) പുറത്താക്കാതെ ജീവിത വിഭവം നൽകാൻ വസിയ്യത്ത് ചെയ്യേണ്ടതാണ്.'' (അൽബഖറ - 240) അനന്തരാവകാശത്തിന്റെ ആയത്ത് ഇറങ്ങിയതോടെ ഇത് നസ്ഖ് ചെയ്യപ്പെട്ടിരിക്കുന്നു. അതിൽ അവർക്ക് നാലിലൊന്നും എട്ടിലൊന്നും വിധിക്കപ്പെട്ടിട്ടുണ്ട്. ഇദ്ദയുടെ കാലയളവ് ഒരു വർഷത്തിൽ നിന്ന്, നാലു മാസവും പത്തു ദിവസവുമായി നസ്ഖ് ചെയ്യപ്പെട്ടു. (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], 'البقرة: ٢٤٠', null, 215, 216, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ، عَنِ الرُّبَيِّعِ بِنْتِ مُعَوِّذِ بْنِ عَفْرَاءَ رَضِيَ اللهُ عَنْهَا، قَالَ: قُلْتُ لَهَا: حَدِّثِينِي حَدِيثَكِ. قَالَتْ: اخْتَلَعْتُ مِنْ زَوْجِي، ثُمَّ جِئْتُ عُثْمَانَ، فَسَأَلْتُ: مَاذَا عَلَيَّ مِنَ الْعِدَّةِ؟ فَقَالَ: لَا عِدَّةَ عَلَيْكِ، إِلَّا أَنْ يَكُونَ حَدِيثَ عَهْدٍ بِكِ، فَتَمْكُثِينَ عِنْدَهُ حَتَّى تَحِيضِينَ حَيْضَةً. قَالَتْ: وَإِنَّمَا تَبِعَ فِي ذَلِكَ قَضَاءَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مَرْيَمَ الْمَغَالِيَّةِ، وَكَانَتْ تَحْتَ ثَابِتِ بْنِ قَيْسٍ، فَاخْتَلَعَتْ مِنْهُ. (ن,جه)', 'ഉബാദതുബ്നുസ്സാമിത്(റ): റുബയ്യിഅ്ബിൻതു മുഅവ്വദുബ്നു അഫ്റാഅ്(റ)യിൽ നിന്ന് നിവേദനം: ഞാനവളോട് ചോദിച്ചു: നിന്റെ സംഭവം എനിക്ക് നീ പറഞ്ഞുതരൂ. അവൾ പറഞ്ഞു: ഞാൻ എന്റെ ഭർത്താവിൽ നിന്ന് ഖുൽഅ് ചെയ്തു. പിന്നെ ഞാൻ ഉസ്മാൻ(റ)വിന്റെ അടുത്ത് ചെന്നു. ഞാൻ ചോദിച്ചു: എന്റെ ഇദ്ദ എന്താണ്? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അടുത്തകാലത്തൊന്നും അദ്ദേഹവുമായി ബന്ധപ്പെട്ടിട്ടില്ലെങ്കിൽ നിനക്ക് ഇദ്ദയില്ല. അങ്ങനെയെങ്കിൽ (അടുത്ത കാലത്ത് അവനുമായി ബന്ധപ്പെട്ടിട്ടുണ്ടെങ്കിൽ) നീ അവന്റെ അടുത്ത് ഒരു ആർത്തവം വരെ നിൽക്കുക. അവൾ പറഞ്ഞു: മറിയമുൽ മഗാലിയയിൽ റസൂൽ(സ) വിധിച്ച വിധി പിന്തുടരുക മാത്രമാണ് ഉസ്മാൻ(റ) ചെയ്തത്. മർയമുൽ മഗാലിയ(റ) സാബിതുബ്നു ഖൈസിന്റെ ഭാര്യയായിരുന്നു. അവൾ അദ്ദേഹത്തിൽ നിന്ന് ഖുൽഅ് ചെയ്തു. (ന,ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നുസ്സാമിത്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 216, 216, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنِ الرُّبَيِّعِ بِنْتِ مُعَوِّذِ بْنِ عَفْرَاءَ رَضِيَ اللهُ عَنْهَا: أَخْبَرَتْهُ أَنَّ ثَابِتَ بْنَ قَيْسِ بْنِ شَمَّاسٍ ضَرَبَ امْرَأَتَهُ فَكَسَرَ يَدَهَا، وَهِيَ جَمِيلَةُ بِنْتُ عَبْدِ اللهِ بْنِ أُبَيٍّ، فَأَتَى أَخُوهَا يَشْتَكِيهِ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَرْسَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى ثَابِتٍ فَقَالَ لَهُ: "خُذِ الَّذِي لَهَا عَلَيْكَ وَخَلِّ سَبِيلَهَا". قَالَ: نَعَمْ. فَأَمَرَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ تَتَرَبَّصَ حَيْضَةً وَاحِدَةً، فَتَلْحَقَ بِأَهْلِهَا. (ن)', 'മുഅവ്വിദുബ്നു അഫ്റാഇന്റെ പുത്രി റുബയ്യിഅ്(റ): സാബിതുബ്നു ഖൈസിബ്നി ശമ്മാസ്(റ) തന്റെ ഭാര്യയെ അടിച്ചു കൈ പൊട്ടിച്ചു. അവൾ അബ്ദുല്ലാഹിബ്നു ഉബയ്യിന്റെ പുത്രി ജമീലയാണ്. അവളുടെ സഹോദരൻ തിരുസന്നിധിയിൽ പരാതിയുമായി എത്തി. റസൂൽ(സ) സാബിതിലേക്ക് ആളെ അയച്ചു വരുത്തി. തിരുമേനി(സ) അയാളോട് പറഞ്ഞു: "അവളുടെ കൈവശമുള്ള നിന്റെ സ്വത്തുകൾ തിരികെ വാങ്ങുക, അവളെ അവളുടെ വഴിക്ക് വിട്ടയക്കുക." അദ്ദേഹം പറഞ്ഞു: അതെ. റസൂൽ(സ) ഒരു ആർത്തവക്കാലം വിട്ടുകടക്കുന്നത് വരെ കാത്തിരിക്കാനും അതിനുശേഷം തന്റെ വീട്ടുകാരിലേക്ക് ചേരുവാനും അവളോട് കൽപിച്ചു. (ന)', 'الرُّبَيِّعِ بِنْتِ مُعَوِّذِ بْنِ عَفْرَاءَ', 'മുഅവ്വിദുബ്നു അഫ്റാഇന്റെ പുത്രി റുബയ്യിഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 216, 216, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ يُونُسَ بْنِ جُبَيْرٍ قَالَ: سَأَلْتُ ابْنَ عُمَرَ عَنْ رَجُلٍ طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ، فَقَالَ: هَلْ تَعْرِفُ عَبْدَ اللهِ بْنَ عُمَرَ؟ فَإِنَّهُ طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ، فَسَأَلَ عُمَرُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَهُ أَنْ يُرَاجِعَهَا ثُمَّ يَسْتَقْبِلَ عِدَّتَهَا. فَقُلْتُ لَهُ: فَيَعْتَدُّ بِتِلْكَ التَّطْلِيقَةِ فَقَالَ: مَهْ، أَرَأَيْتَ إِنْ عَجَزَ وَاسْتَحْمَقَ. (ن)', 'യൂനുസുബ്നു ജുബൈർ(റ): ഞാൻ ഇബ്നുഉമർ(റ)വിനോട്, ആർത്തവമുള്ള ഭാര്യയെ ത്വലാഖ് ചൊല്ലിയവനെക്കുറിച്ച് ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: താങ്കൾ അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)വിനെ അറിയില്ലേ, നിശ്ചയം അദ്ദേഹം തന്റെ ഭാര്യയെ അവളുടെ ആർത്തവകാലത്ത് ത്വലാഖ് ചൊല്ലി. അപ്പോൾ ഉമർ(റ) നബി(സ)യോട് ഇതേക്കുറിച്ച് ചോദിച്ചു. അവിടന്ന്, അവളെ തിരിച്ചെടുക്കാനും അവളുടെ ശുദ്ധിയുള്ള സമയം കാത്തിരിക്കാനും അദ്ദേഹത്തോട് കൽപിച്ചു. ഞാൻ അദ്ദേഹത്തോട് പറഞ്ഞു: ആ ത്വലാഖ് പരിഗണിക്കപ്പെടുമോ? അദ്ദേഹം പറഞ്ഞു: നിർത്തൂ, അവൻ ബലഹീനനാവുകയും വിഡ്ഢിയെപ്പോലെ പെരുമാറുകയും ചെയ്താൽ (എന്താണ് കാര്യമെന്ന്) നീ പറയൂ. (ന)', 'يُونُسَ بْنِ جُبَيْرٍ قَالَ', 'യൂനുസുബ്നു ജുബൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 216, 217, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ بْنِ عُتْبَةَ: أَنَّ عَبْدَ اللهِ بْنَ عَمْرِو بْنِ عُثْمَانَ طَلَّقَ ابْنَةَ سَعِيدِ بْنِ زَيْدٍ – وَأُمُّهَا حَمْنَةُ بِنْتُ قَيْسٍ – الْبَتَّةَ، فَأَمَرَتْهَا خَالَتُهَا فَاطِمَةُ بِنْتُ قَيْسٍ بِالانْتِقَالِ مِنْ بَيْتِ عَبْدِ اللهِ بْنِ عَمْرٍو، وَسَمِعَ بِذَلِكَ مَرْوَانُ فَأَرْسَلَ إِلَيْهَا فَأَمَرَهَا أَنْ تَرْجِعَ إِلَى مَسْكَنِهَا حَتَّى تَنْقَضِيَ عِدَّتُهَا، فَأَرْسَلَتْ إِلَيْهِ تُخْبِرُهُ: أَنَّ خَالَتَهَا فَاطِمَةَ أَفْتَتْهَا بِذَلِكَ، وَأَخْبَرَتْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَفْتَاهَا بِالانْتِقَالِ حِينَ طَلَّقَهَا أَبُو عَمْرِو بْنُ حَفْصٍ الْمَخْزُومِيُّ. فَأَرْسَلَ مَرْوَانُ قَبِيصَةَ بْنَ ذُؤَيْبٍ إِلَى فَاطِمَةَ فَسَأَلَهَا عَنْ ذَلِكَ، فَزَعَمَتْ أَنَّهَا كَانَتْ تَحْتَ أَبِي عَمْرٍو، لَمَّا أَمَّرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلِيَّ بْنَ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ عَلَى الْيَمَنِ خَرَجَ مَعَهُ، فَأَرْسَلَ إِلَيْهَا بِتَطْلِيقَةٍ وَهِيَ بَقِيَّةُ طَلَاقِهَا، فَأَمَرَ لَهَا الْحَارِثَ بْنَ هِشَامٍ وَعَيَّاشَ بْنَ أَبِي رَبِيعَةَ بِنَفَقَتِهَا، فَأَرْسَلَتْ إِلَى الْحَارِثِ وَعَيَّاشٍ تَسْأَلُهُمَا النَّفَقَةَ الَّتِي أَمَرَ لَهَا بِهَا زَوْجُهَا، فَقَالَا: وَاللهِ مَا لَهَا عَلَيْنَا نَفَقَةٌ إِلَّا أَنْ تَكُونَ حَامِلًا، وَمَا لَهَا أَنْ تَسْكُنَ فِي مَسْكَنِنَا إِلَّا بِإِذْنِنَا. فَزَعَمَتْ فَاطِمَةُ أَنَّهَا أَتَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَتْ ذَلِكَ لَهُ، فَصَدَّقَهُمَا، قَالَتْ: فَقُلْتُ: أَيْنَ أَنْتَقِلُ يَا رَسُولَ اللهِ؟ فَقَالَ: "انْتَقِلِي عِنْدَ ابْنِ أُمِّ مَكْتُومٍ، وَهُوَ الْأَعْمَى الَّذِي عَاتَبَهُ اللهُ عَزَّ وَجَلَّ فِي كِتَابِهِ". فَانْتَقَلْتُ عِنْدَهُ، فَكُنْتُ أَضَعُ ثِيَابِي عِنْدَهُ، حَتَّى أَنْكَحَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، زَعَمَتْ أُسَامَةَ بْنَ زَيْدٍ. (ن)', 'ഉബൈദുല്ലാഹിബ്നു അബ്ദില്ലാഹിബ്നി ഉത്ബ(റ): സഈദുബ്നു സൈദ്(റ)വിന്റെ മകളെ - അവളുടെ ഉമ്മ ഹംനബിൻത് ഖൈസാണ് - അബ്ദുല്ലാഹിബ്നു അംറിബ്നി ഉസ്മാൻ(റ) മൂന്ന് മൊഴിയും ചൊല്ലി. അപ്പോൾ അവളുടെ മാതൃസഹോദരിയായ ഫാത്വിമ ബിൻത് ഖൈസ്(റ) അവളോട് അബ്ദുല്ലാഹിബ്നു അംറിന്റെ വീട്ടിൽ നിന്ന് പോകാൻ കൽപിച്ചു. അക്കാര്യം മർവാൻ കേട്ടു. അദ്ദേഹം അവളുടെ അടുത്തേക്ക് ആളെ അയച്ച് ഇദ്ദകഴിയും വരെ തന്റെ പാർപ്പിടത്തിലേക്ക് മടങ്ങാൻ കൽപിച്ചു. അപ്പോൾ അവർ മർവാന്റെയടുത്തേക്ക് ആളെ അയച്ച് ഇപ്രകാരം ഉണർത്തിച്ചു: അവരുടെ മാതൃസഹോദരിയായ ഫാത്വിമ(റ)യാണ് അവർക്ക് ഇപ്രകാരം ഫത്വ കൊടുത്തത്. അബൂഅംറ്(റ) മഹതിയെ മൊഴി ചൊല്ലിയപ്പോൾ മഹതിക്ക് പുറത്ത് പോകാമെന്ന് റസൂൽ(സ) ഫത്വ നൽകിയെന്ന് ഫാത്വിമ(റ) അവരോട് പറയുകയും ചെയ്യുകയുണ്ടായി. അങ്ങനെ മർവാൻ ഖബീസതുബ്നു ദുഐബിനെ ഫാത്വിമ(റ)യുടെ അടുത്തേക്ക് അയച്ച് അവരോട് അതേക്കുറിച്ച് ചോദിച്ചു. അപ്പോൾ അവർ വാദിച്ചു: അവർ അബൂഅംറിന്റെ ഭാര്യയായിരുന്നു. റസൂൽ(സ) അലിയ്യുബ്നു അബീത്വാലിബ്(റ)വിനെ യമനിലെ അമീറായി നിയോഗിച്ചപ്പോൾ അദ്ദേഹവും കൂടെപ്പോയി. അപ്പോൾ അവരിലേക്ക് തന്റെ അവശേഷിക്കുന്ന ഒരു ത്വലാഖുമായി അദ്ദേഹം ആളെ അയച്ചു. അങ്ങനെ അയാൾ ഹാരിസുബ്നു ഹിശാം(റ)വിനെയും അയ്യാശുബ്നു അബീറബീഅ(റ)വിനെയെയും അവർക്ക് ചെലവ് നൽകാൻ ഏൽപിച്ചു. ശേഷം, തന്റെ ഭർത്താവ് കൽപിച്ച ചെലവ് ചോദിച്ചുകൊണ്ട് അവർ ഹാരിസ്(റ)വിലേക്കും അയ്യാശ്(റ)വിലേക്കും ആളെ അയച്ചു. അവരിരുവരും പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, അവൾ ഗർഭിണിയല്ലെങ്കിൽ ഞങ്ങളുടെ മേൽ അവൾക്കൊരു ചെലവും (നൽകേണ്ടതായി) ഇല്ല. അവൾക്ക് നമ്മുടെ പാർപ്പിടത്തിൽ കഴിയാൻ പാടില്ല. ഫാത്വിമ(റ) പറയുന്നു: ശേഷം അവർ റസൂൽ(സ)യുടെ അടുത്ത് പോയി അവിടത്തോട് കാര്യം വിവരിച്ചു. അവിടന്ന് അവരിരുവരെയും സത്യപ്പെടുത്തി. അവർ പറയുന്നു: ഞാനപ്പോൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ, ഞാനെങ്ങോട്ട് പോകും? അവിടന്ന് പറഞ്ഞു: "നീ ഇബ്നുഉമ്മി മക്തൂമിന്റെയടുത്ത് പോകുക, അല്ലാഹു തന്റെ ഗ്രന്ഥത്തിൽ ആക്ഷേപിച്ച അന്ധനാണ് അയാൾ." അങ്ങനെ ഞാൻ അയാളുടെ അടുത്തേക്ക് പോയി. ഞാൻ അദ്ദേഹത്തിന്റെ അടുക്കൽ വെച്ചായിരുന്നു വസ്ത്രം അഴിച്ചുവെക്കാറുണ്ടായിരുന്നത്. ഉസാമതുബ്നു സൈദ്(റ)വിന് അവരെ വിവാഹം ചെയ്ത് കൊടുക്കുന്നത് വരെ. (ന)', 'عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ بْنِ عُتْبَةَ', 'ഉബൈദുല്ലാഹിബ്നു അബ്ദില്ലാഹിബ്നി ഉത്ബ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 217, 218, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ قَالَ: أَرْسَلَ مَرْوَانُ إِلَى فَاطِمَةَ فَسَأَلَهَا، فَأَخْبَرَتْهُ أَنَّهَا كَانَتْ عِنْدَ أَبِي حَفْصٍ، وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَّرَ عَلِيَّ بْنَ أَبِي طَالِبٍ – يَعْنِي عَلَى بَعْضِ الْيَمَنِ – فَخَرَجَ مَعَهُ زَوْجُهَا، فَبَعَثَ إِلَيْهَا بِتَطْلِيقَةٍ كَانَتْ بَقِيَتْ لَهَا، وَأَمَرَ عَيَّاشَ بْنَ أَبِي رَبِيعَةَ وَالْحَارِثَ بْنَ هِشَامٍ أَنْ يُنْفِقَا عَلَيْهَا، فَقَالَا: وَاللَّهِ مَا لَهَا نَفَقَةٌ إِلَّا أَنْ تَكُونَ حَامِلًا. فَأَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "لَا نَفَقَةَ لَكِ إِلَّا أَنْ تَكُونِي حَامِلًا". وَاسْتَأْذَنَتْهُ فِي الِانْتِقَالِ فَأَذِنَ لَهَا، فَقَالَتْ: أَيْنَ أَنْتَقِلُ يَا رَسُولَ اللَّهِ. قَالَ: "عِنْدَ ابْنِ أُمِّ مَكْتُومٍ". وَكَانَ أَعْمَى تَضَعُ ثِيَابَهَا عِنْدَهُ وَلَا يُبْصِرُهَا، فَلَمْ تَزَلْ هُنَاكَ حَتَّى مَضَتْ عِدَّتُهَا، فَأَنْكَحَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُسَامَةَ. فَرَجَعَ قَبِيصَةُ إِلَى مَرْوَانَ فَأَخْبَرَهُ بِذَلِكَ، فَقَالَ مَرْوَانُ: لَمْ نَسْمَعْ هَذَا الْحَدِيثَ إِلَّا مِنِ امْرَأَةٍ، فَسَنَأْخُذُ بِالْعِصْمَةِ الَّتِي وَجَدْنَا النَّاسَ عَلَيْهَا. فَقَالَتْ فَاطِمَةُ حِينَ بَلَغَهَا ذَلِكَ: بَيْنِي وَبَيْنَكُمْ كِتَابُ اللَّهِ، قَالَ اللَّهُ تَعَالَى: {فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ} حَتَّى {لَا تَدْرِي لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَلِكَ أَمْرًا} [الطَّلَاق: ١] قَالَتْ: فَأَيُّ أَمْرٍ يُحْدِثُ بَعْدَ الثَّلَاثِ. (م,د,ن)', 'ഉബൈദുല്ലാഹിബ്നു അബ്ദില്ലാഹിബ്നി ഉത്ബ(റ): മർവാൻ ഫാത്വിമ(റ)യിലേക്ക് ആളെ അയച്ചു. അവരോടയാൾ ചോദിച്ചു. അവർ പറഞ്ഞുകൊടുത്തു: അവർ അബൂഹഫ്സിന്റെ ഭാര്യയായിരുന്നു. റസൂലുല്ലാഹി(സ) - യമനിലെ ചില സ്ഥലങ്ങളിൽ - അമീറായി അലി(റ)വിനെ നിയമിച്ചു. അപ്പോൾ അദ്ദേഹത്തിന്റെ കൂടെ അവരുടെ ഭർത്താവും പോയി. അവർക്ക് ശേഷിച്ചിരുന്ന (അവസാന) ത്വലാഖുമായി അയാൾ അവരിലേക്ക് ആളെ അയച്ചു. അദ്ദേഹം അയ്യാശുബ്നു അബീറബീഅ(റ)യോടും ഹാരിസുബ്നു ഹിശാം(റ)യോടും അവർക്ക് ചെലവ് ചെയ്യാൻ കൽപിച്ചു. അവരിരുവരും പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, അവൾ ഗർഭിണിയല്ലെങ്കിൽ അവൾക്ക് ചെലവ് നൽകേണ്ടതില്ല. അപ്പോൾ അവർ (ഫാത്വിമ) റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്നു. അവിടന്ന് പറഞ്ഞു: "നീ ഗർഭിണിയല്ലെങ്കിൽ നിനക്ക് ചെലവ് തരേണ്ടതില്ല". അവർ (ഫാത്വിമ) വീട്ടിൽ നിന്ന് പോകാൻ അവിടത്തോട് സമ്മതം ചോദിച്ചു. അവിടന്ന് സമ്മതം കൊടുത്തു. അവർ ചോദിച്ചു: ഞാനെങ്ങോട്ട് പോകും, അല്ലാഹുവിന്റെ ദൂതരെ? അവിടന്ന് പറഞ്ഞു: "ഇബ്നു ഉമ്മി മക്തൂമിന്റെയടുത്തേക്ക്." അയാൾ അന്ധനായിരുന്നു. അദ്ദേഹത്തിന്റെയടുത്ത് വെച്ച് അവർ വസ്ത്രം അഴിക്കുമായിരുന്നു, എന്നാൽ അദ്ദേഹമത് കാണുകയില്ല. അവരുടെ ഇദ്ദ കഴിയുംവരെ അവർ അവിടെത്തന്നെ തുടർന്നു. അങ്ങനെ അവരെ നബി(സ) ഉസാമ(റ)വിന് വിവാഹം ചെയ്തുകൊടുത്തു. അപ്പോൾ ഖബീസ്വ മർവാനിലേക്ക് മടങ്ങി സംഭവം വിവരിച്ചു. അപ്പോൾ മർവാൻ പറഞ്ഞു: നാം ഈ ഹദീസ് ഒരു സ്ത്രീയിൽ നിന്നല്ലാതെ കേട്ടിട്ടില്ല. അതുകൊണ്ട് ജനങ്ങൾ അനുവർത്തിക്കുന്നതായി കാണുന്ന നടപടിക്രമങ്ങളായിരിക്കും നാം സ്വീകരിക്കുക. ഈ വിവരമറിഞ്ഞപ്പോൾ ഫാത്വിമ(റ) പറഞ്ഞു: എനിക്കും നിങ്ങൾക്കുമിടയിൽ അല്ലാഹുവിന്റെ ഗ്രന്ഥമുണ്ട്. അല്ലാഹു പറഞ്ഞു: ''അവരുടെ ഇദ്ദാകാലത്ത് നിങ്ങൾ അവരെ ത്വലാഖ് ചൊല്ലുക.'' എന്ന സൂക്തം മുതൽ ''താങ്കൾ അറിയില്ല, അല്ലാഹു (ഒരുപക്ഷേ) അതിനുശേഷം ചിലത് നടപ്പിലാക്കിയേക്കും.'' എന്നത് വരെ. അവർ പറഞ്ഞു: മൂന്നിന് (മൂന്ന് ത്വലാഖിന്) ശേഷം പിന്നെന്തു കാര്യമാണുള്ളത്? (മു,ദ,ന)', 'عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ قَالَ', 'ഉബൈദുല്ലാഹിബ്നു അബ്ദില്ലാഹിബ്നി ഉത്ബ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], 'الطَّلَاق: ١', null, 218, 219, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا: أَنَّ أَبَا عَمْرِو بْنَ حَفْصٍ طَلَّقَهَا الْبَتَّةَ وَهُوَ غَائِبٌ، فَأَرْسَلَ إِلَيْهَا وَكِيلَهُ بِشَعِيرٍ فَتَسَخَّطَتْهُ، فَقَالَ: وَاللَّهِ مَا لَكِ عَلَيْنَا مِنْ شَيْءٍ. فَجَاءَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَتْ ذَلِكَ لَهُ، فَقَالَ لَهَا: "لَيْسَ لَكِ عَلَيْهِ نَفَقَةٌ". وَأَمَرَهَا أَنْ تَعْتَدَّ فِي بَيْتِ أُمِّ شَرِيكٍ، ثُمَّ قَالَ: "إِنَّ تِلْكَ امْرَأَةٌ يَغْشَاهَا أَصْحَابِي، اِعْتَدِّي فِي بَيْتِ ابْنِ أُمِّ مَكْتُومٍ، فَإِنَّهُ رَجُلٌ أَعْمَى تَضَعِينَ ثِيَابَكِ، وَإِذَا حَلَلْتِ فَآذِنِينِي". قَالَتْ: فَلَمَّا حَلَلْتُ ذَكَرْتُ لَهُ أَنَّ مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ وَأَبَا جَهْمٍ خَطَبَانِي، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا أَبُو جَهْمٍ فَلَا يَضَعُ عَصَاهُ عَنْ عَاتِقِهِ، وَأَمَّا مُعَاوِيَةُ فَصُعْلُوكٌ لَا مَالَ لَهُ، انْكِحِي أُسَامَةَ بْنَ زَيْدٍ" قَالَتْ: فَكَرِهْتُهُ، ثُمَّ قَالَ: "انْكِحِي أُسَامَةَ بْنَ زَيْدٍ". فَنَكَحْتُهُ، فَجَعَلَ اللَّهُ تَعَالَى فِيهِ خَيْرًا كَثِيرًا وَاغْتَبَطْتُ بِهِ. وَفِي رِوَايَةٍ: أَنَّ أَبَا حَفْصِ بْنَ الْمُغِيرَةِ – الْمَخْزُومِيَّ – طَلَّقَهَا ثَلَاثًا، وَأَنَّ خَالِدَ بْنَ الْوَلِيدِ وَنَفَرًا مِنْ بَنِي مَخْزُومٍ أَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: يَا نَبِيَّ اللَّهِ، إِنَّ أَبَا حَفْصِ بْنَ الْمُغِيرَةِ طَلَّقَ امْرَأَتَهُ ثَلَاثًا، وَإِنَّهُ تَرَكَ لَهَا نَفَقَةً يَسِيرَةً. فَقَالَ: "لَا نَفَقَةَ لَهَا". وَسَاقَ الْحَدِيثَ. وَفِي رِوَايَةٍ: "لَيْسَتْ لَهَا نَفَقَةٌ وَلَا مَسْكَنٌ". وَفِيهِ: وَأَرْسَلَ إِلَيْهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنْ لَا تَسْبِقِينِي بِنَفْسِكِ". وَفِي رِوَايَةٍ: قَالَتْ: كُنْتُ عِنْدَ رَجُلٍ مِنْ بَنِي مَخْزُومٍ، فَطَلَّقَنِي الْبَتَّةَ، وَفِيهِ: "وَلَا تُفَوِّتِينِي بِنَفْسِكِ". وَفِي رِوَايَةٍ: أَنَّ زَوْجَهَا طَلَّقَهَا ثَلَاثًا، فَلَمْ يَجْعَلْ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَفَقَةً وَلَا سُكْنَى. (م,د,ت,ن)', 'ഫാത്വിമതുബിൻത് ഖൈസ്(റ): അബൂഅംറുബ്നു ഹഫ്സ്(റ) തന്റെ അഭാവത്തിൽ മഹതിയെ പൂർണ്ണമായും ത്വലാഖ് ചൊല്ലി. അപ്പോൾ അദ്ദേഹം അവരുടെ അടുത്തേക്ക് ബാർലിയുമായി തന്റെ കാര്യസ്ഥനെ അയച്ചു. അവരതിനോട് അതൃപ്തി കാണിച്ചു. അപ്പോൾ അയാൾ അവരോട് പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, ഞങ്ങൾ ഒന്നും തന്നെ തരേണ്ടതായില്ല. അപ്പോൾ അവർ റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് അക്കാര്യം പറഞ്ഞു. അപ്പോൾ അവിടന്ന് അവരോട് പറഞ്ഞു: "നിനക്ക് അദ്ദേഹം ഒരു ചെലവും ചെയ്യേണ്ടതില്ല." അവരോട് ഉമ്മുശരീകിന്റെ വീട്ടിൽ ഇദ്ദയിരിക്കാനും അവിടന്ന് കൽപിച്ചു. പിന്നീട് അവിടന്ന് പറഞ്ഞു: "നിശ്ചയം അവർ എന്റെ അനുചരർ ചെല്ലാറുള്ള സ്ത്രീയാണ്. നീ ഇബ്നു ഉമ്മുമക്തൂമിന്റെ വീട്ടിൽ ഇദ്ദയിരിക്കൂ. നിശ്ചയം അയാൾ അന്ധനായ ഒരു മനുഷ്യനാണ്. നിനക്ക് സുഖമായി വസ്ത്രം മാറാം. നീ ഇദ്ദ കഴിഞ്ഞാൽ എന്നെ അറിയിക്കുക." അവർ പറഞ്ഞു: അങ്ങനെ എന്റെ ഇദ്ദ കഴിഞ്ഞപ്പോൾ ഞാനവിടത്തെ ഉണർത്തി, മുആവിയതുബ്നു അബീസുഫ്യാനും അബൂജഹ്മും എന്നെ വിവാഹാലോചന നടത്തി എന്ന്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അബൂജഹ്മാണെങ്കിൽ തന്റെ ഭാര്യയെത്തൊട്ട് വടി വെക്കാറില്ല. (അതായത്, അടി നിർത്താറില്ല). മുആവിയയാണെങ്കിലോ, സമ്പത്തൊന്നുമില്ലാത്ത ദരിദ്രനുമാണ്. നീ ഉസാമതുബ്നു സൈദിനെ വിവാഹം കഴിക്കൂ." അവർ പറഞ്ഞു: ഞാനത് ഇഷ്ടപ്പെട്ടില്ല. അവിടന്ന് വീണ്ടും പറഞ്ഞു: "ഉസാമതുബ്നു സൈദിനെ നീ വിവാഹം കഴിക്കൂ." അങ്ങനെ ഞാൻ അദ്ദേഹത്തെ വിവാഹം ചെയ്തു. അപ്പോൾ അല്ലാഹു അതിൽ ധാരാളം നന്മ നൽകുകയും ഞാനതിൽ സന്തുഷ്ടയാവുകയും ചെയ്തു. മറ്റൊരു നിവേദനം: അബൂഹഫ്സിബ്നുൽ മുഗീറ - അൽ മഖ്സൂമി - അവരെ (ഫാത്വിമയെ) മൂന്ന് ത്വലാഖും ചൊല്ലി. ഖാലിദുബ്നു വലീദ്(റ)വും ബനൂമഖ്സൂമിലെ ഒരു ചെറുസംഘവും നബി(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ നബിയേ, നിശ്ചയം അബൂഹഫ്സിബ്നുൽ മുഗീറ തന്റെ ഭാര്യയെ മൂന്ന് ത്വലാഖും ചൊല്ലിയിരിക്കുന്നു. അയാൾ അവൾക്കായി കുറഞ്ഞ ചെലവാണ് നൽകിയിരിക്കുന്നത്. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അവൾക്ക് ചെലവ് (അയാൾ നൽകേണ്ടതായി) ഇല്ല." ഹദീസ് തുടർന്നു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=184), 1, 'وَفِي رِوَايَةٍ: أَنَّ أَبَا حَفْصِ بْنَ الْمُغِيرَةِ – الْمَخْزُومِيَّ – طَلَّقَهَا ثَلَاثًا، وَأَنَّ خَالِدَ بْنَ الْوَلِيدِ وَنَفَرًا مِنْ بَنِي مَخْزُومٍ أَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: يَا نَبِيَّ اللَّهِ، إِنَّ أَبَا حَفْصِ بْنَ الْمُغِيرَةِ طَلَّقَ امْرَأَتَهُ ثَلَاثًا، وَإِنَّهُ تَرَكَ لَهَا نَفَقَةً يَسِيرَةً. فَقَالَ: "لَا نَفَقَةَ لَهَا". وَسَاقَ الْحَدِيثَ.', 'മറ്റൊരു നിവേദനം: അബൂഹഫ്സിബ്നുൽ മുഗീറ - അൽ മഖ്സൂമി - അവരെ (ഫാത്വിമയെ) മൂന്ന് ത്വലാഖും ചൊല്ലി. ഖാലിദുബ്നു വലീദ്(റ)വും ബനൂമഖ്സൂമിലെ ഒരു ചെറുസംഘവും നബി(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ നബിയേ, നിശ്ചയം അബൂഹഫ്സിബ്നുൽ മുഗീറ തന്റെ ഭാര്യയെ മൂന്ന് ത്വലാഖും ചൊല്ലിയിരിക്കുന്നു. അയാൾ അവൾക്കായി കുറഞ്ഞ ചെലവാണ് നൽകിയിരിക്കുന്നത്. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അവൾക്ക് ചെലവ് (അയാൾ നൽകേണ്ടതായി) ഇല്ല." ഹദീസ് തുടർന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=184), 2, 'وَفِي رِوَايَةٍ: "لَيْسَتْ لَهَا نَفَقَةٌ وَلَا مَسْكَنٌ". وَفِيهِ: وَأَرْسَلَ إِلَيْهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنْ لَا تَسْبِقِينِي بِنَفْسِكِ".', 'മറ്റൊരു നിവേദനം: "അവൾക്ക് ചിലവും താമസിക്കാനിടവും നൽകേണ്ടതില്ല." ഈ ഹദീസിൽ ഇങ്ങനെയുമുണ്ട്: നബി(സ) അവരിലേക്ക് സന്ദേശമയച്ചു: "എന്നോട് പറയും മുമ്പേ നീ വിവാഹം കഴിക്കരുത്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=184), 3, 'وَفِي رِوَايَةٍ: قَالَتْ: كُنْتُ عِنْدَ رَجُلٍ مِنْ بَنِي مَخْزُومٍ، فَطَلَّقَنِي الْبَتَّةَ، وَفِيهِ: "وَلَا تُفَوِّتِينِي بِنَفْسِكِ".', 'മറ്റൊരു നിവേദനം: അവർ പറയുന്നു: ഞാൻ മഖ്സൂം ഗോത്രത്തിൽപെട്ട ഒരാളുടെ ഭാര്യയായിരുന്നു. അദ്ദേഹമെന്നെ മൂന്ന് ത്വലാഖും ചൊല്ലി. പ്രസ്തുത ഹദീസിൽ ഇതുകൂടിയുണ്ട്: "എന്നെ വിവരമറിയിക്കും മുമ്പ് നീ സ്വയം തീരുമാനമെടുക്കരുത്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=184), 4, 'وَفِي رِوَايَةٍ: أَنَّ زَوْجَهَا طَلَّقَهَا ثَلَاثًا، فَلَمْ يَجْعَلْ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَفَقَةً وَلَا سُكْنَى. (م,د,ت,ن)', 'മറ്റൊരു നിവേദനം: അവരുടെ ഭർത്താവ് അവരെ മൂന്ന് ത്വലാഖും ചൊല്ലി. അപ്പോൾ നബി(സ) അവർക്ക് ആവശ്യമായ ചെലവോ ഭവനമോ നിശ്ചയിച്ചില്ല. (മു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا لِفَاطِمَةَ خَيْرٌ أَنْ تَذْكُرَ هَذَا. تَعْنِي قَوْلَهَا: لَا سُكْنَى وَلَا نَفَقَةَ. (م)', 'ആഇശ(റ): ഫാത്വിമ ഇത് പറയുന്നതിൽ അവൾക്ക് ഒരു നന്മയുമില്ല. അവൾക്ക് ചെലവും പാർപ്പിടവുമില്ല എന്ന ഫാത്വിമയുടെ വാക്കാണ് മഹതി ഉദ്ദേശിക്കുന്നത്. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 220, 220, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ أَبِي إِسْحَقَ قَالَ: كُنْتُ مَعَ الْأَسْوَدِ بْنِ يَزِيدَ جَالِسًا فِي الْمَسْجِدِ الْأَعْظَمِ وَمَعَنَا الشَّعْبِيُّ، فَحَدَّثَ الشَّعْبِيُّ بِحَدِيثِ فَاطِمَةَ بِنْتِ قَيْسٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَجْعَلْ لَهَا سُكْنَى وَلَا نَفَقَةً. ثُمَّ أَخَذَ الْأَسْوَدُ كَفًّا مِنْ حَصًى فَحَصَبَهُ بِهِ، فَقَالَ: وَيْلَكَ، تُحَدِّثُ بِمِثْلِ هَذَا؟ قَالَ عُمَرُ رَضِيَ اللهُ عَنْهُ: لَا نَتْرُكُ كِتَابَ اللَّهِ وَسُنَّةَ نَبِيِّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِقَوْلِ امْرَأَةٍ، لَا نَدْرِي لَعَلَّهَا حَفِظَتْ أَوْ نَسِيَتْ، لَهَا السُّكْنَى وَالنَّفَقَةُ، قَالَ اللَّهُ عَزَّ وَجَلَّ: {لَا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ} [الطَّلَاق: ١]. (م)', 'അബൂഇസ്ഹാഖ്(റ): അസ്വദുബ്നു യസീദിന്റെ കൂടെ ഞാൻ ആ വലിയ പള്ളിയിൽ ഇരിക്കുകയായിരുന്നു. ശഅബിയും ഞങ്ങളുടെ കൂടെയുണ്ടായിരുന്നു. അപ്പോൾ, ഫാത്വിമ ബിൻത് ഖൈസ്(റ)യുടെ, റസൂൽ(സ) അവൾക്ക് ചെലവും പാർപ്പിടവും (നിർബന്ധം) ആക്കിയില്ല എന്ന ഹദീസ് ശഅബി പറഞ്ഞു. ഉടനെ അസ്വദ് ഒരുപിടി ചരൽക്കല്ലെടുത്ത് അദ്ദേഹത്തിന്റെ അടുക്കലേക്കെറിഞ്ഞുകൊണ്ട് പറഞ്ഞു: നിനക്ക് നാശം, ഇത്തരം ഹദീസാണോ താൻ പറയുന്നത്? ഉമർ(റ) പറഞ്ഞു: നാം അല്ലാഹുവിന്റെ ഗ്രന്ഥമോ നമ്മുടെ നബി(സ)യുടെ ചര്യയോ ഒരു പെണ്ണിന്റെ വാക്കിനായി ഒഴിവാക്കുകയില്ല. നമുക്കറിയില്ല അവൾ മനഃപാഠമാക്കിയതാണോ അതോ മറന്നതാണോ എന്ന്, അവൾക്ക് പാർപ്പിടവും ചെലവുമുണ്ട്. മഹോന്നതനായ അല്ലാഹു പറഞ്ഞു: ''വ്യക്തമായ നീചവൃത്തി ചെയ്താലല്ലാതെ അവരെ നിങ്ങൾ നിങ്ങളുടെ വീടുകളിൽ നിന്ന് പുറത്താക്കുകയോ, അവർ പുറത്ത് പോകുകയോ അരുത്.'' (ത്വലാഖ്: 1) (മു)', 'أَبِي إِسْحَقَ قَالَ', 'അബൂഇസ്ഹാഖ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'الطَّلَاق: ١', null, 220, 220, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: طَلَّقَنِي زَوْجِي ثَلَاثًا عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا سُكْنَى لَكِ وَلَا نَفَقَةَ". قَالَ مُغِيرَةُ: فَذَكَرْتُهُ لِإِبْرَاهِيمَ، فَقَالَ: قَالَ عُمَرُ رَضِيَ اللهُ عَنْهُ: لَا نَدَعُ كِتَابَ اللَّهِ وَسُنَّةَ نَبِيِّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِقَوْلِ امْرَأَةٍ، لَا نَدْرِي أَحَفِظَتْ أَمْ نَسِيَتْ. وَكَانَ عُمَرُ يَجْعَلُ لَهَا السُّكْنَى وَالنَّفَقَةَ، وَفِي رِوَايَةٍ قَالَتْ: طَلَّقَهَا زَوْجُهَا الْبَتَّةَ، فَخَاصَمَتْهُ فِي السُّكْنَى وَالنَّفَقَةِ، فَلَمْ يَجْعَلْ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُكْنَى وَلَا نَفَقَةً. قَالَتْ: وَأَمَرَنِي أَنْ أَعْتَدَّ فِي بَيْتِ ابْنِ أُمِّ مَكْتُومٍ. حسن صحيح. (م,د,ت,جه)', 'ഫാത്വിമതുബിൻത് ഖൈസ്(റ): നബി(സ)യുടെ കാലത്ത് എന്റെ ഭർത്താവ് എന്നെ മൂന്ന് ത്വലാഖ് ചൊല്ലി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിനക്ക് പാർപ്പിടവും ചെലവുമില്ല." മുഗീറ പറഞ്ഞു: ഞാനിത് ഇബ്റാഹീമിനോട് പറഞ്ഞു: അദ്ദേഹം പറഞ്ഞു: ഇതേക്കുറിച്ച് ഉമർ(റ) പറഞ്ഞു: നാം അല്ലാഹുവിന്റെ ഗ്രന്ഥമോ നമ്മുടെ നബി(സ)യുടെ ചര്യയോ ഒരു സ്ത്രീയുടെ വചനത്തിന് വേണ്ടി ഒഴിവാക്കുകയില്ല. നമുക്കറിയില്ല, അവൾ മനഃപാഠമാക്കിയതോ അതോ മറന്നതോ എന്ന്. ഉമർ(റ) അവൾക്കായി ചെലവും പാർപ്പിടവും നൽകുമായിരുന്നു. മറ്റൊരു നിവേദനത്തിൽ: ഫാത്വിമ(റ) പറഞ്ഞു: അവരുടെ ഭർത്താവ് അവരെ മുഴുവൻ ത്വലാഖും ചൊല്ലി. അപ്പോൾ അവർ അദ്ദേഹത്തോട് ചെലവിന്റെയും പാർപ്പിടത്തിന്റെയും കാര്യത്തിൽ തർക്കിച്ചു. അപ്പോൾ നബി(സ) അവർക്ക് പാർപ്പിടമോ ചെലവോ നൽകണമെന്ന് വിധിച്ചില്ല. അവർ പറഞ്ഞു: അവിടന്ന് എന്നോട് ഇബ്നു ഉമ്മുമക്തൂം(റ)വിന്റെ വീട്ടിൽ ഇദ്ദയിരിക്കാൻ കൽപിച്ചു. (മു,ദ,തു,ജ)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമതുബിൻത് ഖൈസ്(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 220, 221, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=3 and h.hadith_no=187), 1, 'وَفِي رِوَايَةٍ قَالَتْ: طَلَّقَهَا زَوْجُهَا الْبَتَّةَ، فَخَاصَمَتْهُ فِي السُّكْنَى وَالنَّفَقَةِ، فَلَمْ يَجْعَلْ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُكْنَى وَلَا نَفَقَةً. قَالَتْ: وَأَمَرَنِي أَنْ أَعْتَدَّ فِي بَيْتِ ابْنِ أُمِّ مَكْتُومٍ. حسن صحيح. (م,د,ت,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: ഫാത്വിമ(റ) പറഞ്ഞു: അവരുടെ ഭർത്താവ് അവരെ മുഴുവൻ ത്വലാഖും ചൊല്ലി. അപ്പോൾ അവർ അദ്ദേഹത്തോട് ചെലവിന്റെയും പാർപ്പിടത്തിന്റെയും കാര്യത്തിൽ തർക്കിച്ചു. അപ്പോൾ നബി(സ) അവർക്ക് പാർപ്പിടമോ ചെലവോ നൽകണമെന്ന് വിധിച്ചില്ല. അവർ പറഞ്ഞു: അവിടന്ന് എന്നോട് ഇബ്നു ഉമ്മുമക്തൂം(റ)വിന്റെ വീട്ടിൽ ഇദ്ദയിരിക്കാൻ കൽപിച്ചു. (മു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا: إِنَّ زَوْجَهَا طَلَّقَهَا ثَلَاثًا، فَلَمْ يَجْعَلْ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُكْنَى وَلَا نَفَقَةً، قَالَتْ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا حَلَلْتِ فَآذِنِينِي". فَآذَنْتُهُ، فَخَطَبَهَا مُعَاوِيَةُ وَأَبُو جَهْمٍ وَأُسَامَةُ بْنُ زَيْدٍ رَضِيَ اللهُ عَنْهُمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا مُعَاوِيَةُ فَرَجُلٌ تَرِبٌ لَا مَالَ لَهُ، وَأَمَّا أَبُو جَهْمٍ فَرَجُلٌ ضَرَّابٌ لِلنِّسَاءِ، وَلَكِنْ أُسَامَةُ بْنُ زَيْدٍ". فَقَالَتْ بِيَدِهَا هَكَذَا: أُسَامَةُ أُسَامَةُ. فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "طَاعَةُ اللَّهِ وَطَاعَةُ رَسُولِهِ خَيْرٌ لَكِ". [قَالَتْ]: فَتَزَوَّجْتُهُ فَاغْتَبَطْتُ. (م)', 'ഫാത്വിമതുബിൻത് ഖൈസ്(റ): അവരുടെ ഭർത്താവ് അവരെ മൂന്ന് ത്വലാഖും ചൊല്ലി. റസൂൽ(സ) അവർക്ക് പാർപ്പിടമോ ചെലവോ നിശ്ചയിച്ചില്ല. അവർ പറയുന്നു: റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "നിന്റെ ഇദ്ദ കഴിഞ്ഞാൽ എന്നെ അറിയിക്കണം." ഞാൻ അവിടത്തെ അറിയിച്ചു. അങ്ങനെ മുആവിയ(റ)വും അബൂജഹ്മ്(റ)വും ഉസാമതുബ്നു സൈദ്(റ)വും അവരെ വിവാഹാലോചന നടത്തി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "മുആവിയ ദരിദ്രനാണ്. അദ്ദേഹത്തിന് സമ്പത്തില്ല. അബൂജഹ്മാണെങ്കിൽ സ്ത്രീകളെ നന്നായി അടിക്കുന്നയാളുമാണ്. പക്ഷേ, ഉസാമതുബ്നു സൈദ് (നിങ്ങൾക്ക് പറ്റിയ ആളാണ്.)" അപ്പോൾ അവർ തന്റെ കൈകൊണ്ട് ഇപ്രകാരം പറഞ്ഞു: ഉസാമ, ഉസാമ (ഉസാമയെ വിവാഹം കഴിക്കാനാഗ്രഹിക്കുന്നില്ല.) അപ്പോൾ അവരോട് റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന് വഴിപ്പെടലും അവന്റെ റസൂലിനെ അനുസരിക്കലും ആണ് നിനക്ക് നല്ലത്." ഫാത്വിമ(റ) പറയുന്നു: അങ്ങനെ ഞാനദ്ദേഹത്തെ വിവാഹം കഴിക്കുകയും സന്തുഷ്ടയാവുകയും ചെയ്തു. (മു)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമതുബിൻത് ഖൈസ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'قَالَتْ', null, 221, 221, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ بْنِ السَّكَنِ الْأَنْصَارِيَّةِ رَضِيَ اللهُ عَنْهَا: أَنَّهَا طُلِّقَتْ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَمْ يَكُنْ لِلْمُطَلَّقَةِ عِدَّةٌ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ حِينَ طُلِّقَتْ أَسْمَاءُ بِالْعِدَّةِ لِلطَّلَاقِ، فَكَانَتْ أَوَّلَ مَنْ أُنْزِلَتْ فِيهَا الْعِدَّةُ لِلْمُطَلَّقَاتِ. (د)', 'അസ്മാഅ് ബിൻത് യസീദ്(റ): റസൂൽ(സ)യുടെ കാലത്ത് അവർ ത്വലാഖ് ചൊല്ലപ്പെട്ടു, ത്വലാഖ് ചൊല്ലപ്പെട്ടവൾക്കാണെങ്കിൽ അന്ന് ഇദ്ദയുണ്ടായിരുന്നില്ല. അങ്ങനെ അസ്മാഅ്(റ) ത്വലാഖ് ചൊല്ലപ്പെട്ടപ്പോൾ മഹോന്നതനായ അല്ലാഹു ത്വലാഖിനുള്ള ഇദ്ദയുടെ ആയത് ഇറക്കി. ത്വലാഖ് ചൊല്ലപ്പെട്ടവർക്കുള്ള ഇദ്ദയെക്കുറിച്ച് ആദ്യം ഇറക്കപ്പെട്ടത് അവരുടെ കാര്യത്തിലാണ്. (ദ)', 'أَسْمَاءَ بِنْتِ يَزِيدَ بْنِ السَّكَنِ الْأَنْصَارِيَّةِ', 'അസ്മാഅ് ബിൻത് യസീദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 221, 222, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنِ ابْنِ عَبَّاسٍ فِي قَوْلِهِ: {مَا نَنْسَخْ مِنْ آيَةٍ أَوْ نُنْسِهَا نَأْتِ بِخَيْرٍ مِنْهَا أَوْ مِثْلِهَا} [البقرة: ١٠٦] وَقَالَ: {وَإِذَا بَدَّلْنَا آيَةً مَكَانَ آيَةٍ وَاللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ} [النّحل: ١٠١] الْآيَةَ. وَقَالَ: {يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ وَعِنْدَهُ أُمُّ الْكِتَابِ} [الرّعد: ٣٩] فَأَوَّلُ مَا نُسِخَ مِنَ الْقُرْآنِ الْقِبْلَةُ. وَقَالَ: {وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ} [البقرة: ٢٢٨] وَقَالَ: {وَاللَّائِي يَئِسْنَ مِنَ الْمَحِيضِ مِنْ نِسَائِكُمْ إِنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَاثَةُ أَشْهُرٍ} [الطَّلَاق: ٤] فَنُسِخَ مِنْ ذَلِكَ، قَالَ تَعَالَى: {ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا} [الأحزاب: ٤٩]. (ن)', 'ഇബ്നുഅബ്വാസ്(റ): ''നാം വല്ല സൂക്തവും ദുർബ്വലപ്പെടുത്തുകയോ മറപ്പിക്കുകയോ ചെയ്താൽ അത് പോലുള്ളതോ അതിനേക്കാൾ നല്ലതോ നാം കൊണ്ടുവരും.'' (അൽബഖറ: 106) വീണ്ടും പറഞ്ഞു: ''നാം വല്ല ആയത്തും ഒരു ആയതിന്റെ സ്ഥാനത്ത് മാറ്റുകയാണെങ്കിൽ, അല്ലാഹു അവനിറക്കുന്നത് നന്നായി അറിയുന്നവനാണ്.'' (നഹ്ൽ: 101) വീണ്ടും പറഞ്ഞു: ''അല്ലാഹു അവൻ ഇഛിക്കുന്നത് സ്ഥിരപ്പെടുത്തുകയും അപ്രകാരം അവൻ ഇഛിക്കുന്നത് മായ്ച്ചുകളയുകയും ചെയ്യും. ഉമ്മുൽകിതാബ് അവന്റെയടുക്കലാണ്.'' (അൽറഅ്ദ്: 39) ഖുർആനിൽ നിന്ന് ആദ്യമായി ദുർബ്വലപ്പെടുത്തപ്പെട്ടത് ഖിബ്ലയാണ്. വീണ്ടും പറഞ്ഞു: ''ത്വലാഖ് ചൊല്ലപ്പെട്ട സ്ത്രീകൾ മൂന്ന് ആർത്തവശുദ്ധികൾ വരെ കാത്തിരിക്കണം.'' (അൽബഖറ: 228) വീണ്ടും പറഞ്ഞു: ''നിങ്ങളുടെ സ്ത്രീകളിൽ നിന്ന് ആർത്തവം പ്രതീക്ഷയില്ലാത്തവർ, (അവരുടെ കാര്യത്തിൽ) നിങ്ങൾ സംശയിക്കുന്നുവെങ്കിൽ, അവരുടെ ഇദ്ദ മൂന്ന് മാസമാണ്.'' (ത്വലാഖ്: 4) ഇപ്പറഞ്ഞതിൽനിന്ന് ശേഷം വരുന്നത് ദുർബ്വലപ്പെടുത്തപ്പെട്ടു. അല്ലാഹു പറയുന്നു: ''(ഓ, വിശ്വാസികളെ, നിങ്ങൾ വിശ്വാസിനികളെ വിവാഹം കഴിക്കുകയും...) പിന്നീട് നിങ്ങൾ അവരുമായി ബന്ധത്തിലേർപ്പെടുംമുമ്പേ അവരെ ത്വലാഖ് ചൊല്ലുകയും ചെയ്താൽ നിങ്ങൾ എണ്ണിക്കണക്കാക്കുന്ന ഇദ്ദ ആചരിക്കേണ്ട ബാധ്യത അവർക്കില്ല.'' (അഹ്സാബ്: 49) (ന)', 'ابْنِ عَبَّاسٍ فِي قَوْلِهِ', 'ഇബ്നുഅബ്വാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الأحزاب: ٤٩', null, 222, 222, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُ قَالَ: لَا تُفْسِدُوا عَلَيْنَا سُنَّةَ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عِدَّةُ أُمِّ الْوَلَدِ أَرْبَعَةُ أَشْهُرٍ وَعَشْرًا. (د,جه)', 'അംറുബ്നുൽ ആസ്(റ): നബി(സ)യുടെ ചര്യ നിങ്ങൾ ഞങ്ങൾക്ക് മേൽ ദുശിപ്പിക്കരുത്. കുഞ്ഞിന്റെ മാതാവിന്റെ (ഉമ്മുവലദിന്റെ) ഇദ്ദ നാല് മാസവും പത്ത് ദിവസവുമാണ്. (ദ,ജ)', 'عَمْرِو بْنِ الْعَاصِ', 'അംറുബ്നുൽ ആസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 222, 222, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُ قَالَ: لَا تُلَبِّسُوا عَلَيْنَا سُنَّةَ نَبِيِّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عِدَّةُ الْمُتَوَفَّى عَنْهَا أَرْبَعَةُ أَشْهُرٍ وَعَشْرٌ، يَعْنِي أُمَّ الْوَلَدِ. (د,جه)', 'അംറുബ്നുൽ ആസ്(റ): ഞങ്ങളുടെ നബി(സ)യുടെ ചര്യയെ നിങ്ങൾ ഞങ്ങൾക്ക് മേൽ സംശയത്തിലാക്കരുത്, (തന്റെ ഭർത്താവ്..) മരണപ്പെട്ടവളുടെ ഇദ്ദ നാല് മാസവും പത്ത് ദിവസവുമാണ്. ഉമ്മുവലദിനെയാണദ്ദേഹമുദ്ദേശിക്കുന്നത്. (ദ,ജ)', 'عَمْرِو بْنِ الْعَاصِ', 'അംറുബ്നുൽ ആസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 222, 222, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ فَاطِمَةَ بِنْتِ أَبِي حُبَيْشٍ رَضِيَ اللهُ عَنْهَا: أَنَّهَا أَتَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَشَكَتْ إِلَيْهِ الدَّمَ، فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا ذَلِكِ عِرْقٌ، فَانْظُرِي إِذَا أَتَاكِ قُرْؤُكِ فَلَا تُصَلِّي، فَإِذَا مَرَّ قُرْؤُكِ فَلْتَطَهَّرِي، ثُمَّ صَلِّي مَا بَيْنَ الْقُرْءِ إِلَى الْقُرْءِ". (ن)', 'ഫാത്വിമതുബിൻത് അബൂ ഹുബൈശ്(റ): അവർ റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് രക്തത്തെക്കുറിച്ച് ആവലാതി പറഞ്ഞു. റസൂൽ(സ) അവരോട് പറഞ്ഞു: "നിശ്ചയം അത് രക്തവാഹിനിയാണ്. ആർത്തവം വരുന്നത് വരെ നീ നോക്കുക. അപ്പോൾ നീ നിസ്കരിക്കരുത്. ആർത്തവം കഴിഞ്ഞ് കടന്നാൽ നീ ശുദ്ധിയാവുക. പിന്നീട് രണ്ട് ആർത്തവങ്ങൾക്കിടയിലുള്ള സമയങ്ങളിൽ നീ നമസ്കരിക്കുക." (ന)', 'فَاطِمَةَ بِنْتِ أَبِي حُبَيْشٍ', 'ഫാത്വിമതുബിൻത് അബൂ ഹുബൈശ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 223, 223, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَيُّ الذَّنْبِ أَعْظَمُ؟ قَالَ: "أَنْ تَجْعَلَ لِلَّهِ نِدًّا وَهُوَ خَلَقَكَ". قَالَ: فَقُلْتُ: ثُمَّ أَيٌّ؟ قَالَ: "أَنْ تَقْتُلَ وَلَدَكَ مَخَافَةَ أَنْ يَأْكُلَ مَعَكَ". قَالَ: قُلْتُ: ثُمَّ أَيٌّ؟ قَالَ: "أَنْ تُزَانِيَ حَلِيلَةَ جَارِكَ". قَالَ: وَأَنْزَلَ اللَّهُ تَعَالَى تَصْدِيقَ قَوْلِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ} [الفرقان: ٦٨] الْآيَةَ. (ق,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഏത് പാപമാണ് ഏറ്റവും ഭയങ്കരം? അവിടന്ന് പറഞ്ഞു: "അല്ലാഹുവാണ് നിന്നെ സൃഷ്ടിച്ചതെന്നിരിക്കെ നീ അവന് പങ്കുകാരനെയുണ്ടാക്കൽ" നിവേദകൻ പറയുന്നു: ഞാൻ പറഞ്ഞു: പിന്നീടേതാണ്? അവിടന്ന് പറഞ്ഞു: "നിന്റെ കൂടെ ഭക്ഷിക്കുന്നത് ഭയന്ന് നിന്റെ കുട്ടിയെ നീ കൊലചെയ്യൽ." നിവേദകൻ പറയുന്നു: ഞാൻ ചോദിച്ചു: പിന്നീടേതാണ്? അവിടന്നരുളി: "നിന്റെ അയൽവാസിയുടെ ഭാര്യയെ വ്യഭിചരിക്കൽ." നിവേദകൻ പറയുന്നു: നബി(സ)യുടെ വാക്ക് സത്യമാക്കിക്കൊണ്ട് അല്ലാഹു ഖുർആനിറക്കി: ''അല്ലാഹുവിന്റെ കൂടെ മറ്റൊരു ദൈവത്തോട് പ്രാർത്ഥിക്കാത്തവരും, അല്ലാഹു നിഷിദ്ധമാക്കിയ ഒരാളെയും അവകാശമില്ലാതെ കൊല ചെയ്യാത്തവരും വ്യഭിചാരം ചെയ്യാത്തവരുമാണവർ.'' (അൽഫുർഖാൻ: 68) (ബു,മു,ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], 'الفرقان: ٦٨', null, 223, 223, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَتْ مِسْكِينَةٌ لِبَعْضِ الْأَنْصَارِ، فَقَالَتْ: إِنَّ سَيِّدِي يُكْرِهُنِي عَلَى الْبِغَاءِ، فَنَزَلَ فِي ذَلِكَ {وَلَا تُكْرِهُوا فَتَيَاتِكُمْ عَلَى الْبِغَاءِ} [النور: ٣٣]. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഒരു അൻസാരിയുടെ പരിചാരിക വന്നുകൊണ്ട് പറഞ്ഞു: തീർച്ചയായും എന്റെ യജമാനൻ എന്നെ വേശ്യാവൃത്തിക്ക് നിർബന്ധിക്കുന്നു. അപ്പോൾ ആ വിഷയത്തിൽ ''നിങ്ങൾ നിങ്ങളുടെ (പരിചാരികകളായ) യുവതികളെ വേശ്യാവൃത്തിക്ക് നിർബന്ധിക്കരുത്'' (അന്നൂർ: 33) എന്ന സൂക്തമിറങ്ങി. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], 'النور: ٣٣', null, 223, 223, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ سُلَيْمَانَ بْنِ طَرْخَانَ التَّيْمِيِّ: {وَمَنْ يُكْرِهْهُنَّ فَإِنَّ اللَّهَ مِنْ بَعْدِ إِكْرَاهِهِنَّ غَفُورٌ رَحِيمٌ} [النور: ٣٣] قَالَ: قَالَ سَعِيدُ بْنُ أَبِي الْحَسَنِ: غَفُورٌ لَهُنَّ: الْمُكْرَهَاتِ. (د)', 'സുലൈമാനുബ്നു ത്വർഖാനിത്തൈമി(റ): ''ആരെങ്കിലും അവരെ (വേശ്യാവൃത്തിക്ക്) നിർബന്ധിക്കുന്നുവെങ്കിൽ, അവർ നിർബന്ധിതരായി തെറ്റുചെയ്തതിനു ശേഷം തീർച്ചയായും അല്ലാഹു നന്നായി പൊറുക്കുന്നവനും കൂടുതൽ കരുണചെയ്യുന്നവനുമാണ്.'' (അന്നൂർ: 33) നിവേദകൻ പറയുന്നു: സഈദുബ്നു അബിൽ ഹസൻ(റ) പറഞ്ഞു: അത്തരത്തിൽ നിർബന്ധിക്കപ്പെട്ട സ്ത്രീകൾക്ക് (അല്ലാഹു) പൊറുത്ത് കൊടുക്കുക തന്നെ ചെയ്യും. (ദ)', 'سُلَيْمَانَ بْنِ طَرْخَانَ التَّيْمِيِّ', 'സുലൈമാനുബ്നു ത്വർഖാനിത്തൈമി(റ)', null, null, array['د']::text[], array['ദ']::text[], 'النور: ٣٣', null, 223, 224, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَفْضَلُ دِينَارٍ يُنْفِقُهُ الرَّجُلُ دِينَارٌ يُنْفِقُهُ عَلَى عِيَالِهِ، وَدِينَارٌ يُنْفِقُهُ الرَّجُلُ عَلَى دَابَّتِهِ فِي سَبِيلِ اللَّهِ، وَدِينَارٌ يُنْفِقُهُ عَلَى أَصْحَابِهِ فِي سَبِيلِ اللَّهِ". قَالَ أَبُو قِلَابَةَ: وَبَدَأَ بِالْعِيَالِ. ثُمَّ قَالَ أَبُو قِلَابَةَ: وَأَيُّ رَجُلٍ أَعْظَمُ أَجْرًا مِنْ رَجُلٍ يُنْفِقُ عَلَى عِيَالٍ صِغَارٍ يُعِفُّهُمْ، أَوْ يَنْفَعُهُمُ اللَّهُ بِهِ وَيُغْنِيهِمْ. (م)', 'സൗബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ ചെലവഴിക്കുന്ന ഏറ്റവും ശ്രേഷ്ഠമായ ദീനാർ, അവൻ തന്റെ കുടുംബത്തിന് ചെലവഴിക്കുന്ന ദീനാറാണ്, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ തന്റെ മൃഗത്തിനായി ചെലവഴിക്കുന്ന ദീനാറുമാണ്, തന്റെ അനുചരർക്കായി അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ചെലവഴിക്കുന്ന ദീനാറുമാണ്." അബൂഖിലാബ പറയുന്നു: അവിടന്ന് കുടുംബക്കാരെക്കൊണ്ട് തുടങ്ങുകയുണ്ടായി. പിന്നീട് അബൂഖിലാബ പറയുന്നു: തന്റെ ചെറിയ കുടുംബാംഗങ്ങൾക്ക് ചെലവഴിക്കുകയും അങ്ങനെ അവരെ അല്ലാഹു ചാരിത്രശുദ്ധിയുള്ളവരാക്കുകയും അഥവാ, അവനെക്കൊണ്ട് അല്ലാഹു അവരെ സഹായിക്കുകയും അവരെ ഐശ്വര്യമാക്കുകയും ചെയ്യുന്ന, ഒരാളേക്കാൾ ഏറ്റവും വലിയ പ്രതിഫലമുള്ള ആരാണുള്ളത്. (മു)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 224, 224, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ أَبِي مَسْعُودٍ الْبَدْرِيِّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْمُسْلِمَ إِذَا أَنْفَقَ عَلَى أَهْلِهِ نَفَقَةً – وَهُوَ يَحْتَسِبُهَا – كَانَتْ لَهُ صَدَقَةً". (م)', 'അബൂമസ്ഊദിനിൽ ബദരി(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം, ഒരു മുസ്ലിം തന്റെ വീട്ടുകാർക്കായി ചെലവഴിച്ചാൽ - അതിൽനിന്ന് പ്രതിഫലം ആഗ്രഹിച്ചുകൊണ്ട് - അത് അവന് ഒരു ദാനമായി ഭവിക്കുന്നതാണ്." (മു)', 'أَبِي مَسْعُودٍ الْبَدْرِيِّ', 'അബൂമസ്ഊദിനിൽ ബദരി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 224, 224, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "السَّاعِي عَلَى الْأَرْمَلَةِ وَالْمِسْكِينِ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ أَوِ الْقَائِمِ اللَّيْلَ، الصَّائِمِ النَّهَارَ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വിധവകൾക്കും ദരിദ്രർക്കുമായി അത്യധ്വാനം ചെയ്തവൻ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്തവനെപ്പോലെയാണ്, അല്ലെങ്കിൽ പകൽ നോമ്പെടുത്ത് രാത്രി നിന്ന് നമസ്കരിക്കുന്നവനെപ്പോലെയാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 224, 224, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَبِيعُ نَخْلَ بَنِي النَّضِيرِ، وَيَحْبِسُ لِأَهْلِهِ قُوتَ سَنَتِهِمْ. (خ)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): നബി(സ) ബനുന്നളീറിന്റെ ഈത്തപ്പന വിൽക്കുകയും തന്റെ വീട്ടുകാർക്കായി അവരുടെ ഒരു വർഷത്തെ ഭക്ഷണം പിടിച്ച് വെക്കുകയും ചെയ്യുമായിരുന്നു. (ബു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 224, 224, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَعْتَقَ رَجُلٌ مِنْ بَنِي عُذْرَةَ عَبْدًا لَهُ عَنْ دُبُرٍ، فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "أَلَكَ مَالٌ غَيْرُهُ". فَقَالَ: لَا، فَقَالَ: "مَنْ يَشْتَرِيهِ مِنِّي". فَاشْتَرَاهُ نُعَيْمُ بْنُ عَبْدِ اللَّهِ الْعَدَوِيُّ بِثَمَانِ مِائَةِ دِرْهَمٍ، فَجَاءَ بِهَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَفَعَهَا إِلَيْهِ، ثُمَّ قَالَ: "ابْدَأْ بِنَفْسِكَ فَتَصَدَّقْ عَلَيْهَا، فَإِنْ فَضَلَ شَيْءٌ فَلِأَهْلِكَ، فَإِنْ فَضَلَ عَنْ أَهْلِكَ شَيْءٌ فَلِذِي قَرَابَتِكَ، فَإِنْ فَضَلَ عَنْ ذِي قَرَابَتِكَ شَيْءٌ فَهَكَذَا وَهَكَذَا". يَقُولُ: فَبَيْنَ يَدَيْكَ، وَعَنْ يَمِينِكَ، وَعَنْ شِمَالِكَ. (م)', 'ജാബിർ(റ): ഞാൻ മരിച്ചതിനു ശേഷമേ നീ സ്വതന്ത്രനാവൂ എന്ന വ്യവസ്ഥയിൽ ബനൂഗുദ്റയിലെ ഒരാൾ തന്റെ അടിമയെ മോചിപ്പിച്ചു. അക്കാര്യം റസൂലുല്ലാഹി(സ)യുടെ അടുക്കലെത്തി. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിനക്ക് മറ്റുവല്ല സമ്പത്തുമുണ്ടോ?" അയാൾ പറഞ്ഞു: ഇല്ല. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "എന്നിൽ നിന്ന് ആര് അവനെ വാങ്ങും." അപ്പോൾ നുഐമുബ്നു അബ്ദില്ലാഹിൽ അദവീ 800 ദിർഹമിന് ആ അടിമയെ വാങ്ങി. അങ്ങനെ റസൂൽ(സ) അതുമായി വന്ന് അത് അദ്ദേഹത്തിന് നൽകി. എന്നിട്ട് പറഞ്ഞു: "നീ നിന്നിൽ നിന്ന് തുടങ്ങുക. നിനക്കായി അത് നീ ദാനം ചെയ്യുക. വല്ലതും ശേഷിച്ചാൽ അപ്പോൾ നിന്റെ വീട്ടുകാർക്ക് നൽകുക. ഇനിയും വല്ലതും ശേഷിച്ചാൽ അത് നിന്റെ കുടുംബബന്ധക്കാർക്കും നൽകുക. കുടുംബക്കാരിൽനിന്നും വല്ലതും ബാക്കിവന്നാൽ പിന്നെ ഇങ്ങനെയും ഇങ്ങനെയും നൽകുക." നിവേദകൻ പറയുന്നു: നിന്റെ മുമ്പിലുള്ളവർക്കും വലത് ഭാഗത്തുള്ളവർക്കും ഇടത് ഭാഗത്തുള്ളവർക്കും. (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 224, 225, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ خَيْثَمَةَ قَالَ: كُنَّا جُلُوسًا مَعَ عَبْدِ اللَّهِ بْنِ عَمْرٍو إِذْ جَاءَهُ قَهْرَمَانٌ لَهُ فَدَخَلَ، فَقَالَ: أَعْطَيْتَ الرَّقِيقَ قُوتَهُمْ؟ قَالَ: لَا، قَالَ: فَانْطَلِقْ فَأَعْطِهِمْ، وَقَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَفَى بِالْمَرْءِ إِثْمًا أَنْ يَحْبِسَ عَمَّنْ يَمْلِكُ قُوتَهُ". (م)', 'ഖൈസമ: ഞങ്ങൾ അബ്ദുല്ലാഹിബ്നു അംറ്(റ)വിന്റെയടുക്കൽ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ അദ്ദേഹത്തിന്റെ കലവറക്കാരൻ വന്ന് അകത്തുകടന്നു. അപ്പോൾ ഇബ്നു അംറ് ചോദിച്ചു: അടിമകൾക്ക് ഭക്ഷണം നൽകിയോ? അയാൾ പറഞ്ഞു: ഇല്ല. അദ്ദേഹം പറഞ്ഞു: പോകൂ. അവർക്ക് ഭക്ഷണം നൽകൂ. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "താൻ ഉടമയാക്കിയവർക്ക് അവരുടെ ഭക്ഷണം തടയൽ, ഒരാൾക്ക് പാപത്താൽ മതിയായതാണ്." (മു)', 'خَيْثَمَةَ قَالَ', 'ഖൈസമ', null, null, array['م']::text[], array['മു']::text[], null, null, 225, 225, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: جَاءَتْ هِنْدٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، وَاللَّهِ مَا كَانَ عَلَى ظَهْرِ الْأَرْضِ أَهْلُ خِبَاءٍ أَحَبَّ إِلَيَّ مِنْ أَنْ يُذِلَّهُمُ اللَّهُ مِنْ أَهْلِ خِبَائِكَ، وَمَا عَلَى ظَهْرِ الْأَرْضِ أَهْلُ خِبَاءٍ أَحَبَّ إِلَيَّ مِنْ أَنْ يُعِزَّهُمُ اللَّهُ مِنْ أَهْلِ خِبَائِكَ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَأَيْضًا، وَالَّذِي نَفْسِي بِيَدِهِ". ثُمَّ قَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ أَبَا سُفْيَانَ رَجُلٌ مُمْسِكٌ، فَهَلْ عَلَيَّ حَرَجٌ أَنْ أُنْفِقَ عَلَى عِيَالِهِ مِنْ مَالِهِ بِغَيْرِ إِذْنِهِ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا حَرَجَ عَلَيْكِ أَنْ تُنْفِقِي عَلَيْهِمْ بِالْمَعْرُوفِ". (م)', 'ആഇശ(റ): ഹിന്ദ്(റ) നബി(സ)യുടെ അടുത്തേക്ക് വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, അല്ലാഹുവാണ് സത്യം, അങ്ങയുടെ കുടുംബത്തേക്കാൾ, മഹോന്നതനായ അല്ലാഹു നിന്ദിക്കണമെന്ന് ഞാൻ നന്നായി ആഗ്രഹിച്ചിരുന്ന ഒരു കുടുംബവും ഭൂമുഖത്തുണ്ടായിരുന്നില്ല. (പക്ഷെ, ഇപ്പോൾ) അങ്ങയുടെ കുടുംബത്തേക്കാൾ, അല്ലാഹു ആദരിക്കണമെന്ന് ഞാൻ ഏറ്റവും ഇഷ്ടപ്പെടുന്ന ഒരു കുടുംബവും ഭൂമുഖത്തില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "എന്റെ ജീവൻ ആരുടെ കരങ്ങളിലാണോ അവൻ തന്നെ സത്യം, ഞാനും (അങ്ങിനെത്തന്നെ ചിന്തിച്ചിട്ടുണ്ട്.)" പിന്നീട് അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, അബൂസുഫ്യാൻ പിടിച്ച് വെച്ച് ചെലവഴിക്കുന്ന ഒരു മനുഷ്യനാണ്. അദ്ദേഹത്തിന്റെ സമ്മതമില്ലാതെ അദ്ദേഹത്തിന്റെ വീട്ടുകാർക്ക് അദ്ദേഹത്തിന്റെ മുതലിൽനിന്ന് ഞാൻ ചെലവഴിക്കുന്നത് തെറ്റാണോ? നബി(സ) പറഞ്ഞു: "അവരുടെ മേൽ നല്ല രീതിയിൽ ചെലവഴിക്കുന്നത് നിനക്ക് കുറ്റകരമല്ല." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 225, 226, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
