മറ്റൊരു നിവേദനം: അവൻ അവന്റെ ഉമ്മയുടെ അവിഹിത സന്തതിയാണ്, അവൾ അടിമയായാലും, സ്വതന്ത്രയായാലും. ഇത് ഇസ്ലാമിന്റെ ആദ്യകാലത്ത് ചേർക്കപ്പെട്ടതിനെക്കുറിച്ചാണ്. എന്നാൽ ഇസ്ലാമിനുമുമ്പ് ഓഹരിവെക്കപ്പെട്ടത്, അതുകഴിഞ്ഞുപോയി. (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 201, 201, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=3 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
